Status resolveTriggerIdByUnscopedName(const std::unordered_map<ID, CatalogManager::TriggerInfo>& trigger_cache,
                                      const std::string& trigger_name,
                                      ID& trigger_id_out,
                                      ErrorContext* ctx) {
    bool found = false;
    ID match{};
    for (const auto& [id, info] : trigger_cache)
    {
        if (!IdentifierUtils::namesMatch(trigger_name, false,
                                         info.trigger_name, info.name_is_delimited))
        {
            continue;
        }
        if (!found)
        {
            found = true;
            match = id;
            continue;
        }

        SET_ERROR_CONTEXT(
            ctx,
            Status::DUPLICATE_OBJECT,
            "NAME_COLLISION: trigger name resolves to multiple table parents; use table scope");
        return Status::DUPLICATE_OBJECT;
    }

    if (!found)
    {
        SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND, "Trigger does not exist");
        return Status::NOT_FOUND;
    }

    trigger_id_out = match;
    return Status::OK;
}

bool hasTriggerNameConflictInTable(
    const std::unordered_map<ID, CatalogManager::TriggerInfo>& trigger_cache,
    const std::unordered_multimap<ID, ID>& table_triggers,
    const ID& table_id,
    const std::string& trigger_name,
    bool trigger_name_is_delimited,
    const ID* exclude_trigger_id = nullptr) {
    auto range = table_triggers.equal_range(table_id);
    for (auto it = range.first; it != range.second; ++it)
    {
        if (exclude_trigger_id != nullptr && it->second == *exclude_trigger_id)
        {
            continue;
        }
        auto trigger_it = trigger_cache.find(it->second);
        if (trigger_it == trigger_cache.end())
        {
            continue;
        }

        if (IdentifierUtils::namesConflict(trigger_name,
                                           trigger_name_is_delimited,
                                           trigger_it->second.trigger_name,
                                           trigger_it->second.name_is_delimited))
        {
            return true;
        }
    }
    return false;
}

