    // Procedure record on disk (Phase 3 - Stored Code Tables)
    // NOTE: Functions and Procedures stored in same table
    struct ProcedureRecord
    {
        ID procedure_id;
        ID schema_id;
        char procedure_name[512];
        ID owner_id;                // Owner UUID reference
        uint8_t procedure_type;     // PROCEDURE vs FUNCTION
        uint8_t is_selectable;      // 1 if has SUSPEND (Firebird selectable procedures)
        uint8_t language;           // PSQL, SQL, UDR, etc.
        uint8_t sql_security;       // Phase 3.1: 0=DEFINER, 1=INVOKER (default)
        uint8_t name_is_delimited;  // 1 if quoted identifier
        uint8_t body_redacted;      // 1 if body was intentionally not stored
        uint8_t deterministic;      // Function determinism flag (0/1)
        uint8_t reserved;           // Alignment
        uint32_t parameter_count;
        ID return_type_oid;   // TOAST reference for return type definition
        ID body_oid;          // TOAST reference - procedure/function body
        ID bytecode_oid;      // TOAST reference - compiled SBLR bytecode
        uint64_t created_time;
        uint64_t last_modified_time;
        uint32_t is_valid;
        uint32_t padding;
    };

