    auto CatalogManager::createCollation(const CollationCatalogInfo &col_info, ErrorContext *ctx)
        -> Status
    {
        std::lock_guard<CatalogMutex> lock(mutex_);

        CollationRecord rec;
        memset(&rec, 0, sizeof(rec));

        rec.collation_id = col_info.collation_id;
        strncpy(rec.name, col_info.name.c_str(), sizeof(rec.name) - 1);
        rec.charset_id = col_info.charset_uuid;
        if (col_info.charset_id != 0)
        {
            ID resolved = resolveCharsetUuid(col_info.charset_id);
            if (isZeroUuidLocal(rec.charset_id) ||
                resolveCharsetId(rec.charset_id) != col_info.charset_id)
            {
                rec.charset_id = resolved;
            }
        }
        rec.collation_type = col_info.collation_type;
        rec.strength = col_info.strength;
        rec.pad_space = col_info.pad_space;
        rec.is_default = col_info.is_default;
        strncpy(rec.locale, col_info.locale, sizeof(rec.locale) - 1);
        rec.created_time = static_cast<uint64_t>(std::time(nullptr));
        rec.last_modified_time = rec.created_time;
        rec.is_valid = 1;

        auto matcher = [&col_info](const CollationRecord &existing)
        { return existing.is_valid && existing.collation_id == col_info.collation_id; };

        return updateRecordInHeapPage(collation_defs_table_page_, matcher, rec, ctx);
    }

    auto CatalogManager::updateCollation(uint32_t collation_id,
                                         const CollationCatalogInfo &col_info, ErrorContext *ctx)
        -> Status
    {
        std::lock_guard<CatalogMutex> lock(mutex_);

        // Step 1: Find existing collation record
        auto predicate = [collation_id](const CollationRecord &rec)
        { return rec.collation_id == collation_id && rec.is_valid; };

        auto result = findRecordInHeapPage<CollationRecord>(collation_defs_table_page_, predicate, ctx);
        if (result.status != Status::OK)
        {
            SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND, "Collation not found for update");
            return Status::NOT_FOUND;
        }

        // Step 2: Prepare updated record
        CollationRecord updated = result.record;

        // Update fields from col_info
        std::memset(updated.name, 0, sizeof(updated.name));
        std::memcpy(updated.name, col_info.name.c_str(),
                    std::min(col_info.name.size(), sizeof(updated.name) - 1));

        std::memset(updated.locale, 0, sizeof(updated.locale));
        std::memcpy(updated.locale, col_info.locale,
                    std::min(std::strlen(col_info.locale), sizeof(updated.locale) - 1));

        updated.charset_id = col_info.charset_uuid;
        if (col_info.charset_id != 0)
        {
            ID resolved = resolveCharsetUuid(col_info.charset_id);
            if (isZeroUuidLocal(updated.charset_id) ||
                resolveCharsetId(updated.charset_id) != col_info.charset_id)
            {
                updated.charset_id = resolved;
            }
        }
        updated.collation_type = col_info.collation_type;
        updated.strength = col_info.strength;
        updated.pad_space = col_info.pad_space;
        updated.is_default = col_info.is_default;
        updated.last_modified_time = static_cast<uint64_t>(std::time(nullptr));

        // Step 3: Update record in heap page using slot index (in-place update - Firebird MGA)
        Status status = updateRecordInHeapPage(collation_defs_table_page_, result.slot_index,
                                               updated, ctx);
        if (status != Status::OK)
        {
            return status;
        }

        DEBUG_LOG_DB("Updated collation: " << col_info.name << " (ID: " << collation_id << ")");
        return Status::OK;
    }

