// ============================================================================
// Foreign Key Disk Persistence (Phase D)
// ============================================================================

auto CatalogManager::readForeignKeyRecords(ErrorContext *ctx) -> Status
{
    std::lock_guard<std::mutex> lock(foreign_keys_cache_mutex_);

    if (foreign_keys_table_page_ == 0)
    {
        // Foreign keys table not initialized yet (old database format)
        return Status::OK;
    }

    BufferPool *bp = db_->buffer_pool();
    void *page_buffer;
    Status status = bp->pinPage(foreign_keys_table_page_, &page_buffer, ctx);
    if (status != Status::OK)
    {
        return status;
    }

    auto *heap = reinterpret_cast<CatalogHeapPage *>(page_buffer);
    uint32_t offset = sizeof(CatalogHeapPage);

    for (uint32_t i = 0; i < heap->record_count; i++)
    {
        auto *record = reinterpret_cast<ForeignKeyRecord *>(
            reinterpret_cast<uint8_t *>(page_buffer) + offset);

        if (record->is_valid)
        {
            ForeignKeyInfo fk_info;
            fk_info.fk_id = record->fk_id;
            fk_info.fk_name = std::string(record->fk_name);
            fk_info.child_table_id = record->child_table_id;
            fk_info.parent_table_id = record->parent_table_id;

            // Deserialize column names from comma-separated strings
            std::string child_cols_str(record->child_columns);
            std::string parent_cols_str(record->parent_columns);

            // Parse child columns
            size_t pos = 0;
            while (pos < child_cols_str.length())
            {
                size_t comma = child_cols_str.find(',', pos);
                if (comma == std::string::npos)
                {
                    fk_info.child_columns.push_back(child_cols_str.substr(pos));
                    break;
                }
                fk_info.child_columns.push_back(child_cols_str.substr(pos, comma - pos));
                pos = comma + 1;
            }

            // Parse parent columns
            pos = 0;
            while (pos < parent_cols_str.length())
            {
                size_t comma = parent_cols_str.find(',', pos);
                if (comma == std::string::npos)
                {
                    fk_info.parent_columns.push_back(parent_cols_str.substr(pos));
                    break;
                }
                fk_info.parent_columns.push_back(parent_cols_str.substr(pos, comma - pos));
                pos = comma + 1;
            }

            fk_info.on_delete = static_cast<FKAction>(record->on_delete);
            fk_info.on_update = static_cast<FKAction>(record->on_update);
            fk_info.match_type = static_cast<FKMatchType>(record->match_type);
            fk_info.is_enabled = record->is_enabled != 0;
            fk_info.created_time = record->created_time;

            // Store in cache
            foreign_keys_cache_[fk_info.fk_id] = fk_info;
            table_child_fks_.insert({fk_info.child_table_id, fk_info.fk_id});
            table_parent_fks_.insert({fk_info.parent_table_id, fk_info.fk_id});
        }

        offset += sizeof(ForeignKeyRecord);
    }

    bp->unpinPage(foreign_keys_table_page_, false, ctx);
    return Status::OK;
}

// =============================================================================
// Scheduler Job Operations (WS-4 Scheduler)
// =============================================================================

namespace {
    template <size_t N>
    void copyStringField(char (&dest)[N], const std::string& src) {
        std::strncpy(dest, src.c_str(), N - 1);
        dest[N - 1] = '\0';
    }

    uint64_t currentTimeMs() {
        return static_cast<uint64_t>(
            std::chrono::duration_cast<std::chrono::milliseconds>(
                std::chrono::system_clock::now().time_since_epoch()).count());
    }
}

auto CatalogManager::normalizeJobName(const std::string& name) -> std::string
{
    return IdentifierUtils::toUpper(name);
}

void CatalogManager::indexJobUnlocked(const JobInfo& job)
{
    job_name_index_[normalizeJobName(job.job_name)] = job.job_id;
    if (job.state == JobState::ENABLED)
    {
        job_due_index_.insert({job.next_run_time, job.job_id});
    }
}

void CatalogManager::unindexJobUnlocked(const JobInfo& job)
{
    auto name_key = normalizeJobName(job.job_name);
    auto name_it = job_name_index_.find(name_key);
    if (name_it != job_name_index_.end() && name_it->second == job.job_id)
    {
        job_name_index_.erase(name_it);
    }
    if (job.state == JobState::ENABLED)
    {
        auto range = job_due_index_.equal_range(job.next_run_time);
        for (auto it = range.first; it != range.second; ++it)
        {
            if (it->second == job.job_id)
            {
                job_due_index_.erase(it);
                break;
            }
        }
    }
}

void CatalogManager::indexJobRunUnlocked(const JobRunInfo& run)
{
    job_runs_cache_[run.job_run_id] = run;
    job_runs_by_job_.insert({run.job_id, run.job_run_id});
}

void CatalogManager::unindexJobRunUnlocked(const JobRunInfo& run)
{
    job_runs_cache_.erase(run.job_run_id);
    auto range = job_runs_by_job_.equal_range(run.job_id);
    for (auto it = range.first; it != range.second; ++it)
    {
        if (it->second == run.job_run_id)
        {
            job_runs_by_job_.erase(it);
            break;
        }
    }
}

auto CatalogManager::ensureJobCacheLoaded(ErrorContext* ctx) -> Status
{
    if (job_cache_loaded_)
    {
        return Status::OK;
    }

    std::vector<JobInfo> jobs;
    auto recover_scheduler_pages = [&]() -> Status {
        jobs_table_page_ = 0;
        job_runs_table_page_ = 0;
        job_dependencies_table_page_ = 0;
        job_secrets_table_page_ = 0;

        Status recover_status = allocateCatalogPage(jobs_table_page_, ctx);
        if (recover_status != Status::OK)
        {
            return recover_status;
        }
        recover_status = allocateCatalogPage(job_runs_table_page_, ctx);
        if (recover_status != Status::OK)
        {
            return recover_status;
        }
        recover_status = allocateCatalogPage(job_dependencies_table_page_, ctx);
        if (recover_status != Status::OK)
        {
            return recover_status;
        }
        recover_status = allocateCatalogPage(job_secrets_table_page_, ctx);
        if (recover_status != Status::OK)
        {
            return recover_status;
        }
        return writeCatalogRoot(ctx);
    };

    auto filter = [](const JobRecord& rec) {
        return rec.is_valid;
    };
    uint64_t xmin = 0;
    auto converter = [this, xmin, ctx](const JobRecord& rec, JobInfo& info) {
        info.job_id = rec.job_id;
        info.job_name = rec.job_name;
        info.description = rec.description;
        info.job_class = static_cast<JobClass>(rec.job_class);
        info.job_type = static_cast<JobType>(rec.job_type);
        info.job_sql.clear();
        info.bytecode.clear();
        info.source_dialect.clear();
        info.native_compiled_code.clear();
        if (!isZeroUuidLocal(rec.job_source_oid))
        {
            std::string source_storage;
            if (loadStringFromToast(rec.job_source_oid, xmin, source_storage, ctx) == Status::OK)
            {
                decodeStoredCodeSourceStorage(source_storage, info.job_sql, info.source_dialect);
            }
        }
        if (!isZeroUuidLocal(rec.job_exec_oid))
        {
            std::string exec_storage;
            if (loadStringFromToast(rec.job_exec_oid, xmin, exec_storage, ctx) == Status::OK)
            {
                decodeStoredCodeExecutionStorage(exec_storage,
                                                 info.bytecode,
                                                 info.native_compiled_code);
            }
        }
        info.procedure_uuid = rec.procedure_uuid;
        info.external_command = rec.external_command;
        info.schedule_kind = static_cast<ScheduleKind>(rec.schedule_kind);
        info.cron_expression = rec.cron_expression;
        info.interval_seconds = rec.interval_seconds;
        info.starts_at = rec.starts_at;
        info.ends_at = rec.ends_at;
        info.schedule_tz = rec.schedule_tz;
        info.has_measurement = rec.has_measurement != 0;
        info.measurement_options = rec.measurement_options;
        info.next_run_time = rec.next_run_time;
        info.on_completion = static_cast<JobOnCompletion>(rec.on_completion);
        info.partition_strategy = rec.partition_strategy;
        info.partition_shard_uuid = rec.partition_shard_uuid;
        info.partition_expression = rec.partition_expression;
        info.max_retries = rec.max_retries;
        info.retry_backoff_seconds = rec.retry_backoff_seconds;
        info.timeout_seconds = rec.timeout_seconds;
        info.created_by_user_uuid = rec.created_by_user_uuid;
        info.run_as_role_uuid = rec.run_as_role_uuid;
        info.created_at = rec.created_at;
        info.state = static_cast<JobState>(rec.state);
    };

    Status status = readRecordsToVector<JobRecord, JobInfo>(jobs_table_page_, jobs,
                                                           filter, converter, ctx);
    if (status != Status::OK && status != Status::NOT_FOUND)
    {
        const bool recoverable = status == Status::PAGE_CORRUPT ||
                                 status == Status::INVALID_ARGUMENT ||
                                 status == Status::DATA_CORRUPTED ||
                                 status == Status::INTERNAL_ERROR ||
                                 status == Status::IO_ERROR;
        if (recoverable)
        {
            Status recover_status = recover_scheduler_pages();
            if (recover_status != Status::OK)
            {
                return recover_status;
            }
            jobs.clear();
            status = readRecordsToVector<JobRecord, JobInfo>(jobs_table_page_, jobs,
                                                             filter, converter, ctx);
        }
    }
    if (status != Status::OK && status != Status::NOT_FOUND)
    {
        return status;
    }

    job_cache_.clear();
    job_name_index_.clear();
    job_due_index_.clear();
    for (const auto& job : jobs)
    {
        job_cache_[job.job_id] = job;
        indexJobUnlocked(job);
    }

    job_cache_loaded_ = true;
    return Status::OK;
}

auto CatalogManager::ensureJobRunsCacheLoaded(ErrorContext* ctx) -> Status
{
    if (job_runs_cache_loaded_)
    {
        return Status::OK;
    }

    std::vector<JobRunInfo> runs;
    auto recover_scheduler_pages = [&]() -> Status {
        jobs_table_page_ = 0;
        job_runs_table_page_ = 0;
        job_dependencies_table_page_ = 0;
        job_secrets_table_page_ = 0;

        Status recover_status = allocateCatalogPage(jobs_table_page_, ctx);
        if (recover_status != Status::OK)
        {
            return recover_status;
        }
        recover_status = allocateCatalogPage(job_runs_table_page_, ctx);
        if (recover_status != Status::OK)
        {
            return recover_status;
        }
        recover_status = allocateCatalogPage(job_dependencies_table_page_, ctx);
        if (recover_status != Status::OK)
        {
            return recover_status;
        }
        recover_status = allocateCatalogPage(job_secrets_table_page_, ctx);
        if (recover_status != Status::OK)
        {
            return recover_status;
        }
        return writeCatalogRoot(ctx);
    };

    auto filter = [](const JobRunRecord& rec) {
        return rec.is_valid;
    };
    uint64_t xmin = 0;
    auto converter = [this, xmin, ctx](const JobRunRecord& rec, JobRunInfo& info) {
        info.job_run_id = rec.job_run_id;
        info.job_id = rec.job_id;
        info.assigned_node_uuid = rec.assigned_node_uuid;
        info.shard_uuid = rec.shard_uuid;
        info.scheduled_time = rec.scheduled_time;
        info.started_at = rec.started_at;
        info.completed_at = rec.completed_at;
        info.state = static_cast<JobRunState>(rec.state);
        info.retry_count = rec.retry_count;
        info.result_message = rec.result_message;
        info.result_data.clear();
        if (!isZeroUuidLocal(rec.result_data_oid)) {
            std::string result_blob;
            if (loadStringFromToast(rec.result_data_oid, xmin, result_blob, ctx) == Status::OK) {
                info.result_data.assign(result_blob.begin(), result_blob.end());
            }
        }
        info.rows_affected = rec.rows_affected;
        info.error_code = rec.error_code;
    };

    Status status = readRecordsToVector<JobRunRecord, JobRunInfo>(job_runs_table_page_, runs,
                                                                 filter, converter, ctx);
    if (status != Status::OK && status != Status::NOT_FOUND)
    {
        const bool recoverable = status == Status::PAGE_CORRUPT ||
                                 status == Status::INVALID_ARGUMENT ||
                                 status == Status::DATA_CORRUPTED ||
                                 status == Status::INTERNAL_ERROR ||
                                 status == Status::IO_ERROR;
        if (recoverable)
        {
            Status recover_status = recover_scheduler_pages();
            if (recover_status != Status::OK)
            {
                return recover_status;
            }
            runs.clear();
            status = readRecordsToVector<JobRunRecord, JobRunInfo>(job_runs_table_page_, runs,
                                                                   filter, converter, ctx);
        }
    }
    if (status != Status::OK && status != Status::NOT_FOUND)
    {
        return status;
    }

    job_runs_cache_.clear();
    job_runs_by_job_.clear();
    for (const auto& run : runs)
    {
        indexJobRunUnlocked(run);
    }

    job_runs_cache_loaded_ = true;
    return Status::OK;
}

auto CatalogManager::createJob(const JobInfo& job_in, ID& job_id_out,
                              ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);

    const uint64_t created_time_ms =
        job_in.created_at == 0 ? currentTimeMs() : job_in.created_at;
    uint64_t next_run_time = job_in.next_run_time;
    if (next_run_time == 0)
    {
        if (job_in.schedule_kind == ScheduleKind::CRON && !job_in.cron_expression.empty())
        {
            next_run_time = detail::computeNextCronRunMsWithTimezone(
                job_in.cron_expression, created_time_ms, job_in.schedule_tz);
        }
        if (next_run_time == 0)
        {
            next_run_time = created_time_ms;
        }
    }

    JobRecord record{};
    record.job_id = generateUuidV7();
    copyStringField(record.job_name, job_in.job_name);
    copyStringField(record.description, job_in.description);
    record.job_class = static_cast<uint8_t>(job_in.job_class);
    record.job_type = static_cast<uint8_t>(job_in.job_type);
    record.schedule_kind = static_cast<uint8_t>(job_in.schedule_kind);
    record.on_completion = static_cast<uint8_t>(job_in.on_completion);
    record.state = static_cast<uint8_t>(job_in.state);
    uint64_t xmin = 0;
    const std::string source_storage =
        encodeStoredCodeSourceStorage(job_in.job_sql, job_in.source_dialect);
    if (!source_storage.empty())
    {
        Status source_status = storeStringInToast(source_storage, xmin, record.job_source_oid, ctx);
        if (source_status != Status::OK)
        {
            return source_status;
        }
    }
    const std::string exec_storage =
        encodeStoredCodeExecutionStorage(job_in.bytecode, job_in.native_compiled_code);
    if (!exec_storage.empty())
    {
        Status exec_status = storeStringInToast(exec_storage, xmin, record.job_exec_oid, ctx);
        if (exec_status != Status::OK)
        {
            return exec_status;
        }
    }
    record.procedure_uuid = job_in.procedure_uuid;
    copyStringField(record.external_command, job_in.external_command);
    copyStringField(record.cron_expression, job_in.cron_expression);
    record.interval_seconds = job_in.interval_seconds;
    record.starts_at = job_in.starts_at;
    record.ends_at = job_in.ends_at;
    copyStringField(record.schedule_tz, job_in.schedule_tz);
    record.has_measurement = job_in.has_measurement ? 1 : 0;
    copyStringField(record.measurement_options, job_in.measurement_options);
    record.next_run_time = next_run_time;
    copyStringField(record.partition_strategy, job_in.partition_strategy);
    record.partition_shard_uuid = job_in.partition_shard_uuid;
    copyStringField(record.partition_expression, job_in.partition_expression);
    record.max_retries = job_in.max_retries;
    record.retry_backoff_seconds = job_in.retry_backoff_seconds;
    record.timeout_seconds = job_in.timeout_seconds;
    record.created_by_user_uuid = job_in.created_by_user_uuid;
    record.run_as_role_uuid = job_in.run_as_role_uuid;
    record.created_at = created_time_ms;
    record.is_valid = 1;

    Status status = writeRecordToHeapPage(jobs_table_page_, record, ctx);
    if (status != Status::OK)
    {
        return status;
    }

    job_id_out = record.job_id;
    if (job_cache_loaded_)
    {
        JobInfo cached = job_in;
        cached.job_id = record.job_id;
        cached.next_run_time = record.next_run_time;
        cached.created_at = record.created_at;
        job_cache_[cached.job_id] = cached;
        indexJobUnlocked(cached);
    }
    return Status::OK;
}

auto CatalogManager::getJobByName(const std::string& job_name, JobInfo& job_out,
                                 ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    Status cache_status = ensureJobCacheLoaded(ctx);
    if (cache_status != Status::OK)
    {
        return cache_status;
    }
    auto name_key = normalizeJobName(job_name);
    auto it = job_name_index_.find(name_key);
    if (it != job_name_index_.end())
    {
        auto job_it = job_cache_.find(it->second);
        if (job_it != job_cache_.end())
        {
            job_out = job_it->second;
            return Status::OK;
        }
    }

    auto predicate = [&job_name](const JobRecord& rec) {
        return rec.is_valid && job_name == rec.job_name;
    };
    auto result = findRecordInHeapPage<JobRecord>(jobs_table_page_, predicate, ctx);
    if (result.status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND, "Job not found");
        return Status::NOT_FOUND;
    }

    job_out.job_id = result.record.job_id;
    job_out.job_name = result.record.job_name;
    job_out.description = result.record.description;
    job_out.job_class = static_cast<JobClass>(result.record.job_class);
    job_out.job_type = static_cast<JobType>(result.record.job_type);
    job_out.job_sql.clear();
    job_out.bytecode.clear();
    job_out.source_dialect.clear();
    job_out.native_compiled_code.clear();
    if (!isZeroUuidLocal(result.record.job_source_oid))
    {
        uint64_t xmin = 0;
        std::string source_storage;
        if (loadStringFromToast(result.record.job_source_oid, xmin, source_storage, ctx) == Status::OK)
        {
            decodeStoredCodeSourceStorage(source_storage,
                                          job_out.job_sql,
                                          job_out.source_dialect);
        }
    }
    if (!isZeroUuidLocal(result.record.job_exec_oid))
    {
        uint64_t xmin = 0;
        std::string exec_storage;
        if (loadStringFromToast(result.record.job_exec_oid, xmin, exec_storage, ctx) == Status::OK)
        {
            decodeStoredCodeExecutionStorage(exec_storage,
                                             job_out.bytecode,
                                             job_out.native_compiled_code);
        }
    }
    job_out.procedure_uuid = result.record.procedure_uuid;
    job_out.external_command = result.record.external_command;
    job_out.schedule_kind = static_cast<ScheduleKind>(result.record.schedule_kind);
    job_out.cron_expression = result.record.cron_expression;
    job_out.interval_seconds = result.record.interval_seconds;
    job_out.starts_at = result.record.starts_at;
    job_out.ends_at = result.record.ends_at;
    job_out.schedule_tz = result.record.schedule_tz;
    job_out.has_measurement = result.record.has_measurement != 0;
    job_out.measurement_options = result.record.measurement_options;
    job_out.next_run_time = result.record.next_run_time;
    job_out.on_completion = static_cast<JobOnCompletion>(result.record.on_completion);
    job_out.partition_strategy = result.record.partition_strategy;
    job_out.partition_shard_uuid = result.record.partition_shard_uuid;
    job_out.partition_expression = result.record.partition_expression;
    job_out.max_retries = result.record.max_retries;
    job_out.retry_backoff_seconds = result.record.retry_backoff_seconds;
    job_out.timeout_seconds = result.record.timeout_seconds;
    job_out.created_by_user_uuid = result.record.created_by_user_uuid;
    job_out.run_as_role_uuid = result.record.run_as_role_uuid;
    job_out.created_at = result.record.created_at;
    job_out.state = static_cast<JobState>(result.record.state);
    return Status::OK;
}

