auto CatalogManager::updateJob(const JobInfo& job_in, ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    auto predicate = [&job_in](const JobRecord& rec) {
        return rec.is_valid && rec.job_id == job_in.job_id;
    };
    auto found = findRecordInHeapPage<JobRecord>(jobs_table_page_, predicate, ctx);
    if (found.status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND, "Job not found");
        return Status::NOT_FOUND;
    }

    JobRecord updated = found.record;
    copyStringField(updated.job_name, job_in.job_name);
    copyStringField(updated.description, job_in.description);
    updated.job_class = static_cast<uint8_t>(job_in.job_class);
    updated.job_type = static_cast<uint8_t>(job_in.job_type);
    updated.job_source_oid = ID{};
    updated.job_exec_oid = ID{};
    uint64_t xmin = 0;
    const std::string source_storage =
        encodeStoredCodeSourceStorage(job_in.job_sql, job_in.source_dialect);
    if (!source_storage.empty())
    {
        Status source_status = storeStringInToast(source_storage, xmin, updated.job_source_oid, ctx);
        if (source_status != Status::OK)
        {
            return source_status;
        }
    }
    const std::string exec_storage =
        encodeStoredCodeExecutionStorage(job_in.bytecode, job_in.native_compiled_code);
    if (!exec_storage.empty())
    {
        Status exec_status = storeStringInToast(exec_storage, xmin, updated.job_exec_oid, ctx);
        if (exec_status != Status::OK)
        {
            return exec_status;
        }
    }
    updated.procedure_uuid = job_in.procedure_uuid;
    copyStringField(updated.external_command, job_in.external_command);
    updated.schedule_kind = static_cast<uint8_t>(job_in.schedule_kind);
    copyStringField(updated.cron_expression, job_in.cron_expression);
    updated.interval_seconds = job_in.interval_seconds;
    updated.starts_at = job_in.starts_at;
    updated.ends_at = job_in.ends_at;
    copyStringField(updated.schedule_tz, job_in.schedule_tz);
    updated.has_measurement = job_in.has_measurement ? 1 : 0;
    copyStringField(updated.measurement_options, job_in.measurement_options);
    updated.next_run_time = job_in.next_run_time;
    updated.on_completion = static_cast<uint8_t>(job_in.on_completion);
    copyStringField(updated.partition_strategy, job_in.partition_strategy);
    updated.partition_shard_uuid = job_in.partition_shard_uuid;
    copyStringField(updated.partition_expression, job_in.partition_expression);
    updated.max_retries = job_in.max_retries;
    updated.retry_backoff_seconds = job_in.retry_backoff_seconds;
    updated.timeout_seconds = job_in.timeout_seconds;
    updated.created_by_user_uuid = job_in.created_by_user_uuid;
    updated.run_as_role_uuid = job_in.run_as_role_uuid;
    updated.created_at = job_in.created_at;
    updated.state = static_cast<uint8_t>(job_in.state);

    Status status = updateRecordInHeapPage<JobRecord>(jobs_table_page_, predicate, updated, ctx);
    if (status == Status::OK && job_cache_loaded_)
    {
        auto it = job_cache_.find(job_in.job_id);
        if (it != job_cache_.end())
        {
            unindexJobUnlocked(it->second);
        }
        job_cache_[job_in.job_id] = job_in;
        indexJobUnlocked(job_in);
    }

    return status;
}

auto CatalogManager::deleteJob(const ID& job_id, bool keep_history,
                              ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    auto predicate = [&job_id](const JobRecord& rec) {
        return rec.is_valid && rec.job_id == job_id;
    };
    Status status = deleteRecordFromHeapPage<JobRecord>(jobs_table_page_, predicate, ctx);
    if (status != Status::OK)
    {
        return status;
    }

    auto dep_pred = [&job_id](const JobDependencyRecord& rec) {
        return rec.is_valid && rec.job_id == job_id;
    };
    deleteRecordFromHeapPage<JobDependencyRecord>(job_dependencies_table_page_, dep_pred, ctx);

    auto secret_pred = [&job_id](const JobSecretRecord& rec) {
        return rec.is_valid && rec.job_id == job_id;
    };
    deleteRecordFromHeapPage<JobSecretRecord>(job_secrets_table_page_, secret_pred, ctx);

    if (!keep_history)
    {
        auto run_pred = [&job_id](const JobRunRecord& rec) {
            return rec.is_valid && rec.job_id == job_id;
        };
        deleteRecordFromHeapPage<JobRunRecord>(job_runs_table_page_, run_pred, ctx);
    }

    if (job_cache_loaded_)
    {
        auto it = job_cache_.find(job_id);
        if (it != job_cache_.end())
        {
            unindexJobUnlocked(it->second);
            job_cache_.erase(it);
        }
    }
    if (job_runs_cache_loaded_ && !keep_history)
    {
        auto range = job_runs_by_job_.equal_range(job_id);
        for (auto it = range.first; it != range.second; )
        {
            job_runs_cache_.erase(it->second);
            it = job_runs_by_job_.erase(it);
        }
    }

    return Status::OK;
}

auto CatalogManager::listDueJobs(uint64_t now_ms, std::vector<JobInfo>& jobs_out,
                                ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    Status status = ensureJobCacheLoaded(ctx);
    if (status != Status::OK)
    {
        return status;
    }

    jobs_out.clear();
    auto end_it = job_due_index_.upper_bound(now_ms);
    for (auto it = job_due_index_.begin(); it != end_it; ++it)
    {
        auto job_it = job_cache_.find(it->second);
        if (job_it != job_cache_.end())
        {
            jobs_out.push_back(job_it->second);
        }
    }

    return Status::OK;
}

auto CatalogManager::listJobs(std::vector<JobInfo>& jobs_out,
                             ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    Status status = ensureJobCacheLoaded(ctx);
    if (status != Status::OK)
    {
        return status;
    }

    jobs_out.clear();
    jobs_out.reserve(job_cache_.size());
    for (const auto& entry : job_cache_)
    {
        jobs_out.push_back(entry.second);
    }

    return Status::OK;
}

auto CatalogManager::createJobRun(const JobRunInfo& run_in, ID& run_id_out,
                                 ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);

    JobRunRecord record{};
    record.job_run_id = generateUuidV7();
    record.job_id = run_in.job_id;
    record.assigned_node_uuid = run_in.assigned_node_uuid;
    record.shard_uuid = run_in.shard_uuid;
    record.scheduled_time = run_in.scheduled_time;
    record.started_at = run_in.started_at;
    record.completed_at = run_in.completed_at;
    record.state = static_cast<uint8_t>(run_in.state);
    record.retry_count = run_in.retry_count;
    record.rows_affected = run_in.rows_affected;
    record.error_code = run_in.error_code;
    record.result_data_oid = ID{};
    if (!run_in.result_data.empty())
    {
        std::string result_blob(run_in.result_data.begin(), run_in.result_data.end());
        uint64_t xmin = 0;
        Status toast_status = storeStringInToast(result_blob, xmin, record.result_data_oid, ctx);
        if (toast_status != Status::OK)
        {
            return toast_status;
        }
    }
    copyStringField(record.result_message, run_in.result_message);
    record.is_valid = 1;

    Status status = writeRecordToHeapPage(job_runs_table_page_, record, ctx);
    if (status != Status::OK)
    {
        return status;
    }

    run_id_out = record.job_run_id;
    if (job_runs_cache_loaded_)
    {
        JobRunInfo cached = run_in;
        cached.job_run_id = record.job_run_id;
        job_runs_cache_[cached.job_run_id] = cached;
        job_runs_by_job_.insert({cached.job_id, cached.job_run_id});
    }
    return Status::OK;
}

auto CatalogManager::updateJobRun(const JobRunInfo& run_in, ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    auto predicate = [&run_in](const JobRunRecord& rec) {
        return rec.is_valid && rec.job_run_id == run_in.job_run_id;
    };
    auto found = findRecordInHeapPage<JobRunRecord>(job_runs_table_page_, predicate, ctx);
    if (found.status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND, "Job run not found");
        return Status::NOT_FOUND;
    }

    JobRunRecord updated = found.record;
    updated.started_at = run_in.started_at;
    updated.completed_at = run_in.completed_at;
    updated.state = static_cast<uint8_t>(run_in.state);
    updated.retry_count = run_in.retry_count;
    updated.rows_affected = run_in.rows_affected;
    updated.error_code = run_in.error_code;
    if (!run_in.result_data.empty())
    {
        std::string result_blob(run_in.result_data.begin(), run_in.result_data.end());
        uint64_t xmin = 0;
        Status toast_status = storeStringInToast(result_blob, xmin, updated.result_data_oid, ctx);
        if (toast_status != Status::OK)
        {
            return toast_status;
        }
    }
    copyStringField(updated.result_message, run_in.result_message);

    Status status = updateRecordInHeapPage<JobRunRecord>(job_runs_table_page_, predicate, updated, ctx);
    if (status == Status::OK && job_runs_cache_loaded_)
    {
        auto it = job_runs_cache_.find(run_in.job_run_id);
        if (it != job_runs_cache_.end())
        {
            JobRunInfo cached = run_in;
            if (cached.result_data.empty())
            {
                cached.result_data = it->second.result_data;
            }
            it->second = std::move(cached);
        }
    }
    return status;
}

auto CatalogManager::getJobRun(const ID& run_id, JobRunInfo& run_out,
                              ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    Status status = ensureJobRunsCacheLoaded(ctx);
    if (status != Status::OK)
    {
        return status;
    }
    auto it = job_runs_cache_.find(run_id);
    if (it != job_runs_cache_.end())
    {
        run_out = it->second;
        return Status::OK;
    }

    auto predicate = [&run_id](const JobRunRecord& rec) {
        return rec.is_valid && rec.job_run_id == run_id;
    };
    auto found = findRecordInHeapPage<JobRunRecord>(job_runs_table_page_, predicate, ctx);
    if (found.status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND, "Job run not found");
        return Status::NOT_FOUND;
    }

    run_out.job_run_id = found.record.job_run_id;
    run_out.job_id = found.record.job_id;
    run_out.assigned_node_uuid = found.record.assigned_node_uuid;
    run_out.shard_uuid = found.record.shard_uuid;
    run_out.scheduled_time = found.record.scheduled_time;
    run_out.started_at = found.record.started_at;
    run_out.completed_at = found.record.completed_at;
    run_out.state = static_cast<JobRunState>(found.record.state);
    run_out.retry_count = found.record.retry_count;
    run_out.result_message = found.record.result_message;
    run_out.result_data.clear();
    if (!isZeroUuidLocal(found.record.result_data_oid))
    {
        std::string result_blob;
        uint64_t xmin = 0;
        if (loadStringFromToast(found.record.result_data_oid, xmin, result_blob, ctx) == Status::OK)
        {
            run_out.result_data.assign(result_blob.begin(), result_blob.end());
        }
    }
    run_out.rows_affected = found.record.rows_affected;
    run_out.error_code = found.record.error_code;
    return Status::OK;
}

auto CatalogManager::listJobRuns(const ID& job_id, std::vector<JobRunInfo>& runs_out,
                               ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    Status status = ensureJobRunsCacheLoaded(ctx);
    if (status != Status::OK)
    {
        return status;
    }

    runs_out.clear();
    auto range = job_runs_by_job_.equal_range(job_id);
    for (auto it = range.first; it != range.second; ++it)
    {
        auto run_it = job_runs_cache_.find(it->second);
        if (run_it != job_runs_cache_.end())
        {
            runs_out.push_back(run_it->second);
        }
    }

    return Status::OK;
}

auto CatalogManager::listJobRuns(std::vector<JobRunInfo>& runs_out,
                                ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    Status status = ensureJobRunsCacheLoaded(ctx);
    if (status != Status::OK)
    {
        return status;
    }

    runs_out.clear();
    runs_out.reserve(job_runs_cache_.size());
    for (const auto& entry : job_runs_cache_)
    {
        runs_out.push_back(entry.second);
    }

    return Status::OK;
}

auto CatalogManager::addJobDependencies(const ID& job_id,
                                       const std::vector<ID>& depends_on,
                                       ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    for (const auto& dep_id : depends_on)
    {
        JobDependencyRecord record{};
        record.job_id = job_id;
        record.depends_on_job_id = dep_id;
        record.created_time = currentTimeMs();
        record.is_valid = 1;
        Status status = writeRecordToHeapPage(job_dependencies_table_page_, record, ctx);
        if (status != Status::OK)
        {
            return status;
        }
    }
    return Status::OK;
}

auto CatalogManager::clearJobDependencies(const ID& job_id,
                                         ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    auto predicate = [&job_id](const JobDependencyRecord& rec) {
        return rec.is_valid && rec.job_id == job_id;
    };

    Status status = Status::OK;
    while (true) {
        status = deleteRecordFromHeapPage<JobDependencyRecord>(
            job_dependencies_table_page_, predicate, ctx);
        if (status == Status::NOT_FOUND) {
            return Status::OK;
        }
        if (status != Status::OK) {
            return status;
        }
    }
}

auto CatalogManager::listJobDependencies(const ID& job_id,
                                        std::vector<JobDependencyInfo>& deps_out,
                                        ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    auto filter = [&job_id](const JobDependencyRecord& rec) {
        return rec.is_valid && rec.job_id == job_id;
    };
    auto converter = [](const JobDependencyRecord& rec, JobDependencyInfo& info) {
        info.job_id = rec.job_id;
        info.depends_on_job_id = rec.depends_on_job_id;
        info.created_time = rec.created_time;
    };
    return readRecordsToVector<JobDependencyRecord, JobDependencyInfo>(
        job_dependencies_table_page_, deps_out, filter, converter, ctx);
}

auto CatalogManager::storeJobSecret(const ID& job_id,
                                    const std::string& secret_key,
                                    const std::string& secret_value,
                                    ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);

    if (secret_key.empty())
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "Secret key cannot be empty");
        return Status::INVALID_ARGUMENT;
    }

    EncryptionKeyManager* key_mgr = db_ ? db_->encryption_key_manager() : nullptr;
    if (!key_mgr)
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "Encryption key manager not available");
        return Status::INVALID_ARGUMENT;
    }

    std::vector<uint8_t> plaintext(secret_value.begin(), secret_value.end());
    std::vector<uint8_t> encrypted_blob;
    Status enc_status = key_mgr->encryptWithMasterKey(plaintext, encrypted_blob, ctx);
    if (enc_status != Status::OK)
    {
        return enc_status;
    }

    std::string encoded(reinterpret_cast<const char*>(encrypted_blob.data()), encrypted_blob.size());
    uint64_t xmin = 0;
    ID new_oid{};
    Status toast_status = storeStringInToast(encoded, xmin, new_oid, ctx);
    if (toast_status != Status::OK)
    {
        return toast_status;
    }

    auto predicate = [&](const JobSecretRecord& rec) {
        return rec.is_valid && rec.job_id == job_id && secret_key == rec.secret_key;
    };
    auto found = findRecordInHeapPage<JobSecretRecord>(job_secrets_table_page_, predicate, ctx);
    if (found.status == Status::OK)
    {
        JobSecretRecord updated = found.record;
        updated.secret_value_oid = new_oid;
        updated.created_time = currentTimeMs();
        return updateRecordInHeapPage<JobSecretRecord>(job_secrets_table_page_, predicate, updated, ctx);
    }

    JobSecretRecord record{};
    record.job_id = job_id;
    copyStringField(record.secret_key, secret_key);
    record.secret_value_oid = new_oid;
    record.created_time = currentTimeMs();
    record.is_valid = 1;
    return writeRecordToHeapPage(job_secrets_table_page_, record, ctx);
}

auto CatalogManager::getJobSecret(const ID& job_id,
                                  const std::string& secret_key,
                                  std::string& secret_value_out,
                                  ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    auto predicate = [&](const JobSecretRecord& rec) {
        return rec.is_valid && rec.job_id == job_id && secret_key == rec.secret_key;
    };
    auto found = findRecordInHeapPage<JobSecretRecord>(job_secrets_table_page_, predicate, ctx);
    if (found.status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND, "Job secret not found");
        return Status::NOT_FOUND;
    }

    std::string encoded;
    uint64_t xmin = 0;
    Status load_status = loadStringFromToast(found.record.secret_value_oid, xmin, encoded, ctx);
    if (load_status != Status::OK)
    {
        return load_status;
    }

    EncryptionKeyManager* key_mgr = db_ ? db_->encryption_key_manager() : nullptr;
    if (!key_mgr)
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "Encryption key manager not available");
        return Status::INVALID_ARGUMENT;
    }

    std::vector<uint8_t> encrypted_blob(encoded.begin(), encoded.end());
    std::vector<uint8_t> plaintext;
    Status dec_status = key_mgr->decryptWithMasterKey(encrypted_blob, plaintext, ctx);
    if (dec_status != Status::OK)
    {
        return dec_status;
    }

    secret_value_out.assign(reinterpret_cast<const char*>(plaintext.data()), plaintext.size());
    return Status::OK;
}

auto CatalogManager::deleteJobSecret(const ID& job_id,
                                     const std::string& secret_key,
                                     ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    auto predicate = [&](const JobSecretRecord& rec) {
        return rec.is_valid && rec.job_id == job_id && secret_key == rec.secret_key;
    };
    return deleteRecordFromHeapPage<JobSecretRecord>(job_secrets_table_page_, predicate, ctx);
}

// ============================================================================
// Security Operations (Phase 1.3 - Users, Roles, Groups)
// ============================================================================

// User operations

auto CatalogManager::createUser(const std::string& username, const std::string& password_hash,
                                const ID& default_schema_id, bool is_superuser,
                                ID& user_id_out, ErrorContext* ctx) -> Status
{
    std::unique_lock<CatalogMutex> lock(mutex_);

    // Validate username length
    Status status = UTF8Utils::validateStorageCapacity(username,
        CatalogConstants::MAX_IDENTIFIER_CHARS,
        CatalogConstants::MAX_IDENTIFIER_BYTES);
    if (status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, status, "Username too long or invalid UTF-8");
        return status;
    }

    // Check if username already exists
    UserInfo existing_user;
    SchemaInfo public_schema;
    bool need_public_schema = isZeroUuidLocal(default_schema_id);
    // Note: getUserByName also locks mutex, so we temporarily unlock here
    lock.unlock();
    status = getUserByName(username, existing_user, ctx);
    if (need_public_schema)
    {
        ErrorContext schema_ctx;
        Status schema_status = getSchema("users.public", public_schema, &schema_ctx);
        if (schema_status != Status::OK)
        {
            schema_status = getSchema("public", public_schema, &schema_ctx);
        }
        if (schema_status != Status::OK)
        {
            SET_ERROR_CONTEXT(ctx, schema_status, "Failed to resolve public schema");
            return schema_status;
        }
    }
    lock.lock();

    if (status == Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, Status::FILE_EXISTS, "User already exists");
        return Status::FILE_EXISTS;
    }

    // Generate new user ID
    user_id_out = generateUuidV7();

    // Create user record
    UserRecord user_rec;
    memset(&user_rec, 0, sizeof(UserRecord));
    user_rec.user_id = user_id_out;

    // Truncate username to fit in fixed buffer
    std::string truncated_username = UTF8Utils::truncateToBytes(username,
        sizeof(user_rec.username));
    strncpy(user_rec.username, truncated_username.c_str(),
            sizeof(user_rec.username) - 1);

    // Store password_hash in TOAST (Phase 1.4 - WP-1 TOAST Integration)
    uint64_t xmin = 0;  // Catalog operations use transaction 0 for visibility
    user_rec.password_hash_oid = ID{};
    user_rec.user_metadata_oid = ID{};

    if (!password_hash.empty())
    {
        status = storeStringInToast(password_hash, xmin, user_rec.password_hash_oid, ctx);
        if (status != Status::OK)
        {
            SET_ERROR_CONTEXT(ctx, status, "Failed to store password hash in TOAST");
            return status;
        }
    }
    user_rec.default_schema_id = need_public_schema ? public_schema.schema_id : default_schema_id;
    user_rec.is_active = 1;
    user_rec.is_superuser = is_superuser ? 1 : 0;
    user_rec.created_time = std::chrono::system_clock::now().time_since_epoch().count();
    user_rec.last_login_time = 0;
    user_rec.is_valid = 1;

    // Write to disk
    status = writeRecordToHeapPage(users_table_page_, user_rec, ctx);
    if (status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, status, "Failed to write user record");
        return status;
    }

    const std::string normalized_username = IdentifierUtils::toUpper(username);
    if (normalized_username != "SYSTEM" &&
        normalized_username != "SYSARCH")
    {
        // Persist bootstrap phase progression once a non-SYSTEM user exists.
        ErrorContext bootstrap_ctx;
        Status bootstrap_status = transitionBootstrapState(BootstrapState::UNINITIALIZED,
                                                           BootstrapState::INITIALIZED,
                                                           &bootstrap_ctx);
        if (bootstrap_status == Status::CONSTRAINT_VIOLATION)
        {
            (void)transitionBootstrapState(BootstrapState::INITIALIZED,
                                           BootstrapState::INITIALIZED,
                                           &bootstrap_ctx);
        }
    }

    DEBUG_LOG_DB("Created user: " << username << " (ID: " << user_id_out.toString() << ")");
    return Status::OK;
}

auto CatalogManager::ensureUserExists(const std::string& username, const std::string& password_hash,
                                      const ID& default_schema_id, bool is_superuser,
                                      ID& user_id_out, ErrorContext* ctx) -> Status
{
    std::unique_lock<CatalogMutex> lock(mutex_);

    Status status = UTF8Utils::validateStorageCapacity(username,
        CatalogConstants::MAX_IDENTIFIER_CHARS,
        CatalogConstants::MAX_IDENTIFIER_BYTES);
    if (status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, status, "Username too long or invalid UTF-8");
        return status;
    }

    auto predicate = [&username](const UserRecord& rec) {
        return rec.is_valid &&
            IdentifierUtils::namesMatch(username, false /*search_delimited*/,
                                        std::string(rec.username), false /*stored_delimited*/);
    };

    auto result = findRecordInHeapPage<UserRecord>(users_table_page_, predicate, ctx);
    if (result.status == Status::OK)
    {
        user_id_out = result.record.user_id;
        return Status::OK;
    }
    if (result.status != Status::NOT_FOUND)
    {
        SET_ERROR_CONTEXT(ctx, result.status, "User lookup failed");
        return result.status;
    }

    SchemaInfo public_schema;
    bool need_public_schema = isZeroUuidLocal(default_schema_id);
    lock.unlock();
    if (need_public_schema)
    {
        ErrorContext schema_ctx;
        Status schema_status = getSchema("users.public", public_schema, &schema_ctx);
        if (schema_status != Status::OK)
        {
            schema_status = getSchema("public", public_schema, &schema_ctx);
        }
        if (schema_status != Status::OK)
        {
            SET_ERROR_CONTEXT(ctx, schema_status, "Failed to resolve public schema");
            return schema_status;
        }
    }
    lock.lock();

    result = findRecordInHeapPage<UserRecord>(users_table_page_, predicate, ctx);
    if (result.status == Status::OK)
    {
        user_id_out = result.record.user_id;
        return Status::OK;
    }
    if (result.status != Status::NOT_FOUND)
    {
        SET_ERROR_CONTEXT(ctx, result.status, "User lookup failed");
        return result.status;
    }

    user_id_out = generateUuidV7();

    UserRecord user_rec;
    memset(&user_rec, 0, sizeof(UserRecord));
    user_rec.user_id = user_id_out;

    std::string truncated_username = UTF8Utils::truncateToBytes(username,
        sizeof(user_rec.username));
    strncpy(user_rec.username, truncated_username.c_str(),
            sizeof(user_rec.username) - 1);

    uint64_t xmin = 0;
    user_rec.password_hash_oid = ID{};
    user_rec.user_metadata_oid = ID{};
    if (!password_hash.empty())
    {
        status = storeStringInToast(password_hash, xmin, user_rec.password_hash_oid, ctx);
        if (status != Status::OK)
        {
            SET_ERROR_CONTEXT(ctx, status, "Failed to store password hash in TOAST");
            return status;
        }
    }
    user_rec.default_schema_id = need_public_schema ? public_schema.schema_id : default_schema_id;
    user_rec.is_active = 1;
    user_rec.is_superuser = is_superuser ? 1 : 0;
    user_rec.created_time = std::chrono::system_clock::now().time_since_epoch().count();
    user_rec.last_login_time = 0;
    user_rec.is_valid = 1;

    status = writeRecordToHeapPage(users_table_page_, user_rec, ctx);
    if (status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, status, "Failed to write user record");
        return status;
    }

    const std::string normalized_username = IdentifierUtils::toUpper(username);
    if (normalized_username != "SYSTEM" &&
        normalized_username != "SYSARCH")
    {
        ErrorContext bootstrap_ctx;
        Status bootstrap_status = transitionBootstrapState(BootstrapState::UNINITIALIZED,
                                                           BootstrapState::INITIALIZED,
                                                           &bootstrap_ctx);
        if (bootstrap_status == Status::CONSTRAINT_VIOLATION)
        {
            (void)transitionBootstrapState(BootstrapState::INITIALIZED,
                                           BootstrapState::INITIALIZED,
                                           &bootstrap_ctx);
        }
    }

    DEBUG_LOG_DB("Created user: " << username << " (ID: " << user_id_out.toString() << ")");
    return Status::OK;
}

auto CatalogManager::getUser(const ID& user_id, UserInfo& user_out,
                             ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);

    auto predicate = [&user_id](const UserRecord& rec) {
        return rec.is_valid && rec.user_id == user_id;
    };

    auto result = findRecordInHeapPage<UserRecord>(users_table_page_, predicate, ctx);
    if (result.status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, result.status, "User not found");
        return result.status;
    }

    // Convert to UserInfo
    user_out.user_id = result.record.user_id;
    user_out.username = std::string(result.record.username);

    // Load password_hash and user_metadata from TOAST (Phase 1.4 - WP-1 TOAST Integration)
    uint64_t xmin = 0;  // Catalog operations use transaction 0 for visibility
    user_out.password_hash = "";
    user_out.user_metadata = "";
    if (!isZeroUuidLocal(result.record.password_hash_oid))
    {
        Status load_status = loadStringFromToast(result.record.password_hash_oid, xmin,
                                                 user_out.password_hash, ctx);
        if (load_status != Status::OK)
        {
            SET_ERROR_CONTEXT(ctx, load_status, "Failed to load user password hash");
            return load_status;
        }
    }
    if (!isZeroUuidLocal(result.record.user_metadata_oid))
    {
        Status load_status = loadStringFromToast(result.record.user_metadata_oid, xmin,
                                                 user_out.user_metadata, ctx);
        if (load_status != Status::OK)
        {
            SET_ERROR_CONTEXT(ctx, load_status, "Failed to load user metadata");
            return load_status;
        }
    }

    user_out.default_schema_id = result.record.default_schema_id;
    user_out.is_active = result.record.is_active != 0;
    user_out.is_superuser = result.record.is_superuser != 0;
    user_out.created_time = result.record.created_time;
    user_out.last_login_time = result.record.last_login_time;

    return Status::OK;
}

