auto CatalogManager::updateUser(const ID& user_id, const std::string& password_hash,
                                const ID& default_schema_id, bool is_active, bool is_superuser,
                                ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);

    // Find the user record
    auto predicate = [&user_id](const UserRecord& rec) {
        return rec.is_valid && rec.user_id == user_id;
    };

    auto result = findRecordInHeapPage<UserRecord>(users_table_page_, predicate, ctx);
    if (result.status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, result.status, "User not found");
        return result.status;
    }

    // Update fields (Security Phase 3.0)
    UserRecord updated_rec = result.record;

    // Update password_hash in TOAST (Phase 1.4 - WP-1 TOAST Integration)
    uint64_t xmin = 0;  // Catalog operations use transaction 0 for visibility
    if (!password_hash.empty())
    {
        // Note: We don't delete the old TOAST record here because TOAST
        // handles garbage collection via transaction visibility.
        // Just store the new value and update the OID.
        Status toast_status = storeStringInToast(password_hash, xmin,
                                                  updated_rec.password_hash_oid, ctx);
        if (toast_status != Status::OK)
        {
            SET_ERROR_CONTEXT(ctx, toast_status, "Failed to store password hash in TOAST");
            return toast_status;
        }
    }

    updated_rec.default_schema_id = default_schema_id;
    updated_rec.is_active = is_active ? 1 : 0;
    updated_rec.is_superuser = is_superuser ? 1 : 0;

    // Write updated record
    Status status = updateRecordInHeapPage(users_table_page_, result.slot_index,
                                          updated_rec, ctx);
    if (status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, status, "Failed to update user record");
        return status;
    }

    return Status::OK;
}

auto CatalogManager::updateUserMetadata(const ID& user_id, const std::string& user_metadata,
                                        ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);

    auto predicate = [&user_id](const UserRecord& rec) {
        return rec.is_valid && rec.user_id == user_id;
    };

    auto result = findRecordInHeapPage<UserRecord>(users_table_page_, predicate, ctx);
    if (result.status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, result.status, "User not found");
        return result.status;
    }

    UserRecord updated_rec = result.record;
    if (user_metadata.empty())
    {
        updated_rec.user_metadata_oid = ID{};
    }
    else
    {
        uint64_t xmin = 0;
        Status toast_status = storeStringInToast(user_metadata, xmin, updated_rec.user_metadata_oid, ctx);
        if (toast_status != Status::OK)
        {
            SET_ERROR_CONTEXT(ctx, toast_status, "Failed to store user metadata in TOAST");
            return toast_status;
        }
    }

    Status status = updateRecordInHeapPage(users_table_page_, result.slot_index,
                                           updated_rec, ctx);
    if (status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, status, "Failed to update user metadata");
        return status;
    }

    return Status::OK;
}

auto CatalogManager::renameUser(const ID& user_id,
                                const std::string& new_username,
                                ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);

    Status status = UTF8Utils::validateStorageCapacity(new_username,
        CatalogConstants::MAX_IDENTIFIER_CHARS,
        CatalogConstants::MAX_IDENTIFIER_BYTES);
    if (status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, status, "Username too long or invalid UTF-8");
        return status;
    }

    auto duplicate_predicate = [&new_username, &user_id](const UserRecord& rec) {
        return rec.is_valid &&
               rec.user_id != user_id &&
               IdentifierUtils::namesMatch(new_username, false,
                                           std::string(rec.username), false);
    };
    auto duplicate = findRecordInHeapPage<UserRecord>(users_table_page_,
                                                      duplicate_predicate,
                                                      ctx);
    if (duplicate.status == Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, Status::FILE_EXISTS, "User already exists");
        return Status::FILE_EXISTS;
    }
    if (duplicate.status != Status::NOT_FOUND)
    {
        SET_ERROR_CONTEXT(ctx, duplicate.status, "User lookup failed");
        return duplicate.status;
    }

    auto predicate = [&user_id](const UserRecord& rec) {
        return rec.is_valid && rec.user_id == user_id;
    };
    auto result = findRecordInHeapPage<UserRecord>(users_table_page_, predicate, ctx);
    if (result.status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, result.status, "User not found");
        return result.status;
    }

    UserRecord updated_rec = result.record;
    std::memset(updated_rec.username, 0, sizeof(updated_rec.username));
    std::string truncated_username = UTF8Utils::truncateToBytes(new_username,
        sizeof(updated_rec.username));
    std::strncpy(updated_rec.username, truncated_username.c_str(),
                 sizeof(updated_rec.username) - 1);

    status = updateRecordInHeapPage(users_table_page_, result.slot_index, updated_rec, ctx);
    if (status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, status, "Failed to update user record");
        return status;
    }

    return Status::OK;
}

auto CatalogManager::deleteUser(const ID& user_id, bool cascade, ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);

    // Security Phase 3.0: CASCADE implementation
    if (cascade)
    {
        // CASCADE: Delete all dependent objects
        // 1. Revoke all role memberships
        std::vector<RoleMembershipInfo> role_memberships;
        Status status = getUserRoles(user_id, role_memberships, ctx);
        if (status == Status::OK)
        {
            for (const auto& membership : role_memberships)
            {
                revokeRole(membership.role_id, user_id, ctx);
                // Continue even if revoke fails
            }
        }

        // 2. Revoke all group memberships
        std::vector<ID> groups;
        status = getUserGroups(user_id, groups, ctx);
        if (status == Status::OK)
        {
            for (const auto& group_id : groups)
            {
                removeGroupMember(group_id, user_id, ctx);
                // Continue even if removal fails
            }
        }

        // 3. Delete all permissions granted to this user
        std::vector<PermissionInfo> permissions;
        status = getUserPermissions(user_id, permissions, ctx);
        if (status == Status::OK)
        {
            for (const auto& perm : permissions)
            {
                revokePermission(perm.object_id, perm.object_type, user_id,
                               GranteeType::USER, perm.privileges, ctx);
                // Continue even if revoke fails
            }
        }
    }
    else
    {
        // RESTRICT (default): Check for dependencies
        // Check if user has any role memberships
        std::vector<RoleMembershipInfo> role_memberships;
        Status status = getUserRoles(user_id, role_memberships, ctx);
        if (status == Status::OK && !role_memberships.empty())
        {
            SET_ERROR_CONTEXT(ctx, Status::CONSTRAINT_VIOLATION,
                            "User has role memberships (use CASCADE to drop)");
            return Status::CONSTRAINT_VIOLATION;
        }

        // Check if user has any group memberships
        std::vector<ID> groups;
        status = getUserGroups(user_id, groups, ctx);
        if (status == Status::OK && !groups.empty())
        {
            SET_ERROR_CONTEXT(ctx, Status::CONSTRAINT_VIOLATION,
                            "User has group memberships (use CASCADE to drop)");
            return Status::CONSTRAINT_VIOLATION;
        }

        // Check if user has any permissions
        std::vector<PermissionInfo> permissions;
        status = getUserPermissions(user_id, permissions, ctx);
        if (status == Status::OK && !permissions.empty())
        {
            SET_ERROR_CONTEXT(ctx, Status::CONSTRAINT_VIOLATION,
                            "User has permissions (use CASCADE to drop)");
            return Status::CONSTRAINT_VIOLATION;
        }
    }

    // Mark user as deleted (Firebird MGA style)
    auto predicate = [&user_id](const UserRecord& rec) {
        return rec.is_valid && rec.user_id == user_id;
    };

    Status status = deleteRecordFromHeapPage<UserRecord>(users_table_page_,
                                                          predicate, ctx);
    if (status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, status, "Failed to delete user");
        return status;
    }

    DEBUG_LOG_DB("Deleted user (ID: " << user_id.toString() << ")");
    return Status::OK;
}

auto CatalogManager::listUsers(std::vector<UserInfo>& users_out,
                               ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);

    users_out.clear();

    // Phase 1.4 - WP-1 TOAST Integration: Capture 'this' to load TOAST data
    uint64_t xmin = 0;  // Catalog operations use transaction 0 for visibility

    auto filter = [](const UserRecord& rec) { return rec.is_valid; };
    auto converter = [this, xmin, ctx](const UserRecord& rec, UserInfo& info) {
        info.user_id = rec.user_id;
        info.username = std::string(rec.username);

        // Load password_hash and user_metadata from TOAST
        info.password_hash = "";
        info.user_metadata = "";
        if (!isZeroUuidLocal(rec.password_hash_oid))
        {
            loadStringFromToast(rec.password_hash_oid, xmin, info.password_hash, ctx);
        }
        if (!isZeroUuidLocal(rec.user_metadata_oid))
        {
            loadStringFromToast(rec.user_metadata_oid, xmin, info.user_metadata, ctx);
        }

        info.default_schema_id = rec.default_schema_id;
        info.is_active = rec.is_active != 0;
        info.is_superuser = rec.is_superuser != 0;
        info.created_time = rec.created_time;
        info.last_login_time = rec.last_login_time;
    };

    return readRecordsToVector<UserRecord, UserInfo>(users_table_page_, users_out,
                                                     filter, converter, ctx);
}

auto CatalogManager::getBootstrapState(BootstrapState& state_out,
                                       ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);

    state_out = BootstrapState::UNINITIALIZED;

    // Persisted state lives in a reserved internal auth provider row. Avoid
    // detoasting arbitrary auth-provider payloads here because bootstrap/auth
    // probes run on the hot path before user login and must fail closed rather
    // than crash on stale TOAST rows.
    struct BootstrapProviderRow
    {
        ID provider_id;
        std::string provider_name;
        AuthProviderState provider_state;
        ID config_payload_oid;
    };
    std::vector<BootstrapProviderRow> providers;
    if (auth_provider_table_page_ != 0)
    {
        auto filter = [](const AuthProviderRecord& row) { return row.is_valid == 1; };
        auto converter = [](const AuthProviderRecord& row, BootstrapProviderRow& out) {
            out = BootstrapProviderRow{};
            out.provider_id = row.provider_id;
            out.provider_name = fixedNameFromBuffer(row.provider_name, sizeof(row.provider_name));
            out.provider_state = static_cast<AuthProviderState>(row.provider_state);
            out.config_payload_oid = row.config_payload_oid;
        };

        ErrorContext provider_ctx;
        Status provider_status = readRecordsToVector<AuthProviderRecord, BootstrapProviderRow>(
            auth_provider_table_page_, providers, filter, converter, &provider_ctx);
        if (provider_status != Status::OK && provider_status != Status::NOT_FOUND)
        {
            providers.clear();
        }
    }

    for (const auto& provider : providers)
    {
        if (IdentifierUtils::toUpper(provider.provider_name) !=
            IdentifierUtils::toUpper(kBootstrapStateProviderName))
        {
            continue;
        }

        if (provider.provider_state == AuthProviderState::DISABLED)
        {
            state_out = BootstrapState::LOCKED;
            return Status::OK;
        }

        break;
    }

    // Phase A/B distinction: initialized once any non-bootstrap-internal
    // principal exists.
    std::vector<std::string> usernames;
    auto filter = [](const UserRecord& rec) { return rec.is_valid != 0; };
    auto converter = [](const UserRecord& rec, std::string& username) {
        username = std::string(rec.username);
    };
    Status status = readRecordsToVector<UserRecord, std::string>(
        users_table_page_, usernames, filter, converter, ctx);
    if (status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, status, "Failed to read users for bootstrap state");
        return status;
    }

    for (const std::string& username : usernames)
    {
        const std::string normalized_username = IdentifierUtils::toUpper(username);
        if (normalized_username != "SYSTEM" &&
            normalized_username != "SYSARCH")
        {
            state_out = BootstrapState::INITIALIZED;
            return Status::OK;
        }
    }

    state_out = BootstrapState::UNINITIALIZED;
    return Status::OK;
}

auto CatalogManager::transitionBootstrapState(BootstrapState expected_state,
                                              BootstrapState new_state,
                                              ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);

    BootstrapState current_state = BootstrapState::UNINITIALIZED;
    Status status = getBootstrapState(current_state, ctx);
    if (status != Status::OK)
    {
        return status;
    }

    if (current_state != expected_state)
    {
        std::ostringstream oss;
        oss << "Bootstrap state transition rejected (expected="
            << bootstrapStateToString(expected_state)
            << ", actual=" << bootstrapStateToString(current_state) << ")";
        SET_ERROR_CONTEXT(ctx, Status::CONSTRAINT_VIOLATION, oss.str().c_str());
        return Status::CONSTRAINT_VIOLATION;
    }

    if (!isAllowedBootstrapTransition(expected_state, new_state))
    {
        std::ostringstream oss;
        oss << "Illegal bootstrap state transition (from="
            << bootstrapStateToString(expected_state)
            << ", to=" << bootstrapStateToString(new_state) << ")";
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, oss.str().c_str());
        return Status::INVALID_ARGUMENT;
    }

    AuthProviderCatalogInfo provider_info{};
    bool found = false;
    if (auth_provider_table_page_ != 0)
    {
        struct BootstrapProviderRow
        {
            ID provider_id;
            std::string provider_name;
            AuthProviderKind provider_kind;
            AuthProviderState provider_state;
            uint32_t priority_rank;
            uint32_t timeout_ms;
            uint32_t cache_ttl_ms;
            AuthProviderFailMode fail_mode;
            bool is_valid;
            uint64_t created_time;
            uint64_t last_modified_time;
        };

        std::vector<BootstrapProviderRow> providers;
        auto filter = [](const AuthProviderRecord& row) { return row.is_valid == 1; };
        auto converter = [](const AuthProviderRecord& row, BootstrapProviderRow& out) {
            out = BootstrapProviderRow{};
            out.provider_id = row.provider_id;
            out.provider_name = fixedNameFromBuffer(row.provider_name, sizeof(row.provider_name));
            out.provider_kind = static_cast<AuthProviderKind>(row.provider_kind);
            out.provider_state = static_cast<AuthProviderState>(row.provider_state);
            out.priority_rank = row.priority_rank;
            out.timeout_ms = row.timeout_ms;
            out.cache_ttl_ms = row.cache_ttl_ms;
            out.fail_mode = static_cast<AuthProviderFailMode>(row.fail_mode);
            out.is_valid = row.is_valid == 1;
            out.created_time = row.created_time;
            out.last_modified_time = row.last_modified_time;
        };

        ErrorContext provider_ctx;
        status = readRecordsToVector<AuthProviderRecord, BootstrapProviderRow>(
            auth_provider_table_page_, providers, filter, converter, &provider_ctx);
        if (status != Status::OK && status != Status::NOT_FOUND)
        {
            SET_ERROR_CONTEXT(ctx, status, "Failed to load bootstrap state record");
            return status;
        }

        for (const auto& provider : providers)
        {
            if (IdentifierUtils::toUpper(provider.provider_name) ==
                IdentifierUtils::toUpper(kBootstrapStateProviderName))
            {
                provider_info = AuthProviderCatalogInfo{};
                provider_info.provider_id = provider.provider_id;
                provider_info.provider_name = provider.provider_name;
                provider_info.provider_kind = provider.provider_kind;
                provider_info.provider_state = provider.provider_state;
                provider_info.priority_rank = provider.priority_rank;
                provider_info.timeout_ms = provider.timeout_ms;
                provider_info.cache_ttl_ms = provider.cache_ttl_ms;
                provider_info.fail_mode = provider.fail_mode;
                provider_info.is_valid = provider.is_valid;
                provider_info.created_time = provider.created_time;
                provider_info.last_modified_time = provider.last_modified_time;
                found = true;
                break;
            }
        }
    }

    if (!found)
    {
        provider_info = AuthProviderCatalogInfo{};
        provider_info.provider_id = generateUuidV7();
        provider_info.provider_name = kBootstrapStateProviderName;
        provider_info.provider_kind = AuthProviderKind::INTERNAL_SCRAM_SHA256;
        provider_info.priority_rank = 0;
        provider_info.timeout_ms = 0;
        provider_info.cache_ttl_ms = 0;
        provider_info.fail_mode = AuthProviderFailMode::HARD_FAIL;
        provider_info.is_valid = true;
    }

    provider_info.provider_state = (new_state == BootstrapState::LOCKED)
        ? AuthProviderState::DISABLED
        : AuthProviderState::ENABLED;
    provider_info.config_payload = "state=" + bootstrapStateToString(new_state) +
                                   "\nupdated=" + std::to_string(catalogNowTicks());

    status = upsertAuthProviderCatalogEntry(provider_info, ctx);
    if (status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, status, "Failed to persist bootstrap state record");
        return status;
    }

    return Status::OK;
}

auto CatalogManager::claimBootstrapWindow(ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);

    BootstrapState current_state = BootstrapState::UNINITIALIZED;
    Status status = getBootstrapState(current_state, ctx);
    if (status != Status::OK)
    {
        return status;
    }

    if (current_state != BootstrapState::UNINITIALIZED)
    {
        std::ostringstream oss;
        oss << "Bootstrap claim rejected (state=" << bootstrapStateToString(current_state) << ")";
        SET_ERROR_CONTEXT(ctx, Status::CONSTRAINT_VIOLATION, oss.str().c_str());
        return Status::CONSTRAINT_VIOLATION;
    }

    return transitionBootstrapState(BootstrapState::UNINITIALIZED,
                                    BootstrapState::LOCKED,
                                    ctx);
}

auto CatalogManager::releaseBootstrapWindow(ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);

    BootstrapState current_state = BootstrapState::UNINITIALIZED;
    Status status = getBootstrapState(current_state, ctx);
    if (status != Status::OK)
    {
        return status;
    }

    if (current_state != BootstrapState::LOCKED)
    {
        return Status::OK;
    }

    return transitionBootstrapState(BootstrapState::LOCKED,
                                    BootstrapState::UNINITIALIZED,
                                    ctx);
}

// Role operations

auto CatalogManager::createRole(const std::string& role_name, const ID& owner_id,
                                const ID& default_schema_id,
                                ID& role_id_out, ErrorContext* ctx) -> Status
{
    std::unique_lock<CatalogMutex> lock(mutex_);

    // Validate role name length
    Status status = UTF8Utils::validateStorageCapacity(role_name,
        CatalogConstants::MAX_IDENTIFIER_CHARS,
        CatalogConstants::MAX_IDENTIFIER_BYTES);
    if (status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, status, "Role name too long or invalid UTF-8");
        return status;
    }

    // Check if role already exists
    RoleInfo existing_role;
    CatalogManager::SchemaInfo public_schema;
    bool need_public_schema = isZeroUuidLocal(default_schema_id);
    lock.unlock();
    status = getRoleByName(role_name, existing_role, ctx);
    if (need_public_schema)
    {
        ErrorContext schema_ctx;
        Status schema_status = getSchema("users.public", public_schema, &schema_ctx);
        if (schema_status != Status::OK)
        {
            schema_status = getSchema("public", public_schema, &schema_ctx);
        }
        if (schema_status != Status::OK)
        {
            SET_ERROR_CONTEXT(ctx, schema_status, "Failed to resolve public schema");
            return schema_status;
        }
    }
    lock.lock();

    if (status == Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, Status::FILE_EXISTS, "Role already exists");
        return Status::FILE_EXISTS;
    }

    // Generate new role ID
    role_id_out = generateUuidV7();

    // Create role record
    RoleRecord role_rec;
    memset(&role_rec, 0, sizeof(RoleRecord));
    role_rec.role_id = role_id_out;

    // Truncate role name to fit in fixed buffer
    std::string truncated_name = UTF8Utils::truncateToBytes(role_name,
        sizeof(role_rec.role_name));
    strncpy(role_rec.role_name, truncated_name.c_str(),
            sizeof(role_rec.role_name) - 1);

    role_rec.owner_id = owner_id;
    role_rec.default_schema_id = need_public_schema ? public_schema.schema_id : default_schema_id;
    role_rec.role_metadata_oid = ID{};
    role_rec.is_active = 1;
    role_rec.created_time = std::chrono::system_clock::now().time_since_epoch().count();
    role_rec.last_modified_time = role_rec.created_time;
    role_rec.is_valid = 1;

    // Write to disk
    status = writeRecordToHeapPage(roles_table_page_, role_rec, ctx);
    if (status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, status, "Failed to write role record");
        return status;
    }

    DEBUG_LOG_DB("Created role: " << role_name << " (ID: " << role_id_out.toString() << ")");
    return Status::OK;
}

auto CatalogManager::getRole(const ID& role_id, RoleInfo& role_out,
                             ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);

    auto predicate = [&role_id](const RoleRecord& rec) {
        return rec.is_valid && rec.role_id == role_id;
    };

    auto result = findRecordInHeapPage<RoleRecord>(roles_table_page_, predicate, ctx);
    if (result.status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, result.status, "Role not found");
        return result.status;
    }

    // Convert to RoleInfo
    role_out.role_id = result.record.role_id;
    role_out.role_name = std::string(result.record.role_name);
    role_out.owner_id = result.record.owner_id;
    role_out.default_schema_id = result.record.default_schema_id;

    // Load role_metadata from TOAST (Phase 1.4 - WP-1 TOAST Integration)
    uint64_t xmin = 0;  // Catalog operations use transaction 0 for visibility
    role_out.role_metadata = "";
    if (!isZeroUuidLocal(result.record.role_metadata_oid))
    {
        loadStringFromToast(result.record.role_metadata_oid, xmin, role_out.role_metadata, ctx);
    }

    role_out.is_active = result.record.is_active != 0;
    role_out.created_time = result.record.created_time;
    role_out.last_modified_time = result.record.last_modified_time;

    return Status::OK;
}

auto CatalogManager::getRoleByName(const std::string& role_name, RoleInfo& role_out,
                                   ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);

    auto predicate = [&role_name](const RoleRecord& rec) {
        return rec.is_valid && (std::string(rec.role_name) == role_name);
    };

    auto result = findRecordInHeapPage<RoleRecord>(roles_table_page_, predicate, ctx);
    if (result.status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, result.status, "Role not found");
        return result.status;
    }

    // Convert to RoleInfo
    role_out.role_id = result.record.role_id;
    role_out.role_name = std::string(result.record.role_name);
    role_out.owner_id = result.record.owner_id;
    role_out.default_schema_id = result.record.default_schema_id;

    // Load role_metadata from TOAST (Phase 1.4 - WP-1 TOAST Integration)
    uint64_t xmin = 0;  // Catalog operations use transaction 0 for visibility
    role_out.role_metadata = "";
    if (!isZeroUuidLocal(result.record.role_metadata_oid))
    {
        loadStringFromToast(result.record.role_metadata_oid, xmin, role_out.role_metadata, ctx);
    }

    role_out.is_active = result.record.is_active != 0;
    role_out.created_time = result.record.created_time;
    role_out.last_modified_time = result.record.last_modified_time;

    return Status::OK;
}

auto CatalogManager::deleteRole(const ID& role_id, bool cascade, ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);

    // Security Phase 3.0: CASCADE implementation
    if (cascade)
    {
        // CASCADE: Delete all dependent objects
        // 1. Revoke role from all members
        std::vector<RoleMembershipInfo> members;
        Status status = getRoleMembers(role_id, members, ctx);
        if (status == Status::OK)
        {
            for (const auto& membership : members)
            {
                revokeRole(role_id, membership.user_id, ctx);
                // Continue even if revoke fails
            }
        }

        // 2. Delete all permissions granted to this role
        std::vector<PermissionInfo> permissions;
        status = getUserPermissions(role_id, permissions, ctx);  // Works for roles too
        if (status == Status::OK)
        {
            for (const auto& perm : permissions)
            {
                revokePermission(perm.object_id, perm.object_type, role_id,
                               GranteeType::ROLE, perm.privileges, ctx);
                // Continue even if revoke fails
            }
        }
    }
    else
    {
        // RESTRICT (default): Check for dependencies
        // Check if role has any members
        std::vector<RoleMembershipInfo> members;
        Status status = getRoleMembers(role_id, members, ctx);
        if (status == Status::OK && !members.empty())
        {
            SET_ERROR_CONTEXT(ctx, Status::CONSTRAINT_VIOLATION,
                            "Role has members (use CASCADE to drop)");
            return Status::CONSTRAINT_VIOLATION;
        }

        // Check if role has any permissions
        std::vector<PermissionInfo> permissions;
        status = getUserPermissions(role_id, permissions, ctx);
        if (status == Status::OK && !permissions.empty())
        {
            SET_ERROR_CONTEXT(ctx, Status::CONSTRAINT_VIOLATION,
                            "Role has permissions (use CASCADE to drop)");
            return Status::CONSTRAINT_VIOLATION;
        }
    }

    // Mark role as deleted (Firebird MGA style)
    auto predicate = [&role_id](const RoleRecord& rec) {
        return rec.is_valid && rec.role_id == role_id;
    };

    Status status = deleteRecordFromHeapPage<RoleRecord>(roles_table_page_,
                                                          predicate, ctx);
    if (status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, status, "Failed to delete role");
        return status;
    }

    DEBUG_LOG_DB("Deleted role (ID: " << role_id.toString() << ")");
    return Status::OK;
}

auto CatalogManager::listRoles(std::vector<RoleInfo>& roles_out,
                               ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);

    roles_out.clear();

    uint64_t xmin = 0;  // Catalog operations use transaction 0 for visibility

    auto filter = [](const RoleRecord& rec) { return rec.is_valid; };
    auto converter = [this, xmin, ctx](const RoleRecord& rec, RoleInfo& info) {
        info.role_id = rec.role_id;
        info.role_name = std::string(rec.role_name);
        info.owner_id = rec.owner_id;
        info.default_schema_id = rec.default_schema_id;
        info.role_metadata.clear();
        if (!isZeroUuidLocal(rec.role_metadata_oid))
        {
            loadStringFromToast(rec.role_metadata_oid, xmin, info.role_metadata, ctx);
        }
        info.is_active = rec.is_active != 0;
        info.created_time = rec.created_time;
        info.last_modified_time = rec.last_modified_time;
    };

    return readRecordsToVector<RoleRecord, RoleInfo>(roles_table_page_, roles_out,
                                                     filter, converter, ctx);
}

// Phase A CRUD: Update role metadata
auto CatalogManager::updateRole(const ID& role_id, const std::optional<std::string>& new_name,
                                const std::optional<ID>& new_owner_id,
                                const std::optional<std::string>& new_metadata,
                                const std::optional<ID>& new_default_schema_id,
                                const std::optional<bool>& is_active,
                                ErrorContext* ctx) -> Status
{
    std::unique_lock<CatalogMutex> lock(mutex_);

    // Find existing role
    RoleInfo existing;
    Status status = getRole(role_id, existing, ctx);
    if (status != Status::OK)
    {
        return status;
    }

    // Validate new name if provided
    if (new_name.has_value())
    {
        status = UTF8Utils::validateStorageCapacity(new_name.value(),
            CatalogConstants::MAX_IDENTIFIER_CHARS,
            CatalogConstants::MAX_IDENTIFIER_BYTES);
        if (status != Status::OK)
        {
            SET_ERROR_CONTEXT(ctx, status, "Role name too long or invalid UTF-8");
            return status;
        }

        // Check if new name conflicts with existing role
        if (new_name.value() != existing.role_name)
        {
            RoleInfo conflict;
            lock.unlock();
            Status conflict_check = getRoleByName(new_name.value(), conflict, ctx);
            lock.lock();
            if (conflict_check == Status::OK)
            {
                SET_ERROR_CONTEXT(ctx, Status::FILE_EXISTS, "Role name already exists");
                return Status::FILE_EXISTS;
            }
        }
    }

    // Update role record on disk
    BufferPool *bp = db_->buffer_pool();
    void *page_data;
    status = bp->pinPage(roles_table_page_, &page_data, ctx);
    if (status != Status::OK)
    {
        return status;
    }

    HeapPage heap_page(static_cast<uint8_t *>(page_data), db_->page_size());
    uint16_t item_count = heap_page.getItemCount();
    bool found = false;

    auto *mutable_page_data = static_cast<uint8_t *>(page_data);

    for (uint16_t i = 0; i < item_count; ++i)
    {
        const uint8_t *tuple_data;
        uint32_t tuple_size;

        if (heap_page.getTuple(i, &tuple_data, &tuple_size, ctx) == Status::OK)
        {
            if (tuple_size >= sizeof(TupleHeader) + sizeof(RoleRecord))
            {
                const ptrdiff_t offset = tuple_data - static_cast<const uint8_t *>(page_data);
                uint8_t *mutable_tuple_data = mutable_page_data + offset;

                auto *record =
                    reinterpret_cast<RoleRecord *>(mutable_tuple_data + sizeof(TupleHeader));

                if (record->role_id == role_id && record->is_valid == 1)
                {
                    // Apply updates
                    if (new_name.has_value())
                    {
                        std::string truncated = UTF8Utils::truncateToBytes(new_name.value(),
                            sizeof(record->role_name));
                        memset(record->role_name, 0, sizeof(record->role_name));
                        strncpy(record->role_name, truncated.c_str(),
                                sizeof(record->role_name) - 1);
                    }
                    if (new_owner_id.has_value())
                    {
                        record->owner_id = new_owner_id.value();
                    }
                    if (new_default_schema_id.has_value())
                    {
                        record->default_schema_id = new_default_schema_id.value();
                    }
                    if (is_active.has_value())
                    {
                        record->is_active = is_active.value() ? 1 : 0;
                    }
                    if (new_metadata.has_value())
                    {
                        ID old_oid = record->role_metadata_oid;
                        ID new_oid{};
                        uint64_t xmin = ConnectionContext::getCurrentTransactionId();
                        if (xmin == 0)
                        {
                            xmin = config::DEFAULT_INITIAL_XID;
                        }

                        Status toast_status = storeStringInToast(new_metadata.value(),
                                                                xmin, new_oid, ctx);
                        if (toast_status != Status::OK)
                        {
                            bp->unpinPage(roles_table_page_, false, ctx);
                            return toast_status;
                        }

                        if (!isZeroUuidLocal(old_oid) && policy_toast_manager_)
                        {
                            policy_toast_manager_->deleteToastValue(old_oid, xmin, ctx);
                        }
                        record->role_metadata_oid = new_oid;
                    }
                    record->last_modified_time = std::chrono::system_clock::now().time_since_epoch().count();
                    found = true;
                    break;
                }
            }
        }
    }

    bp->unpinPage(roles_table_page_, found, ctx);

    if (!found)
    {
        SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND, "Role not found on disk");
        return Status::NOT_FOUND;
    }

    return Status::OK;
}

// Role membership operations

auto CatalogManager::grantRole(const ID& role_id, const ID& user_id, const ID& granted_by,
                               bool with_admin_option, ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);

    // Check if membership already exists
    auto predicate = [&role_id, &user_id](const RoleMembershipRecord& rec) {
        return rec.is_valid && rec.role_id == role_id && rec.user_id == user_id;
    };

    auto result = findRecordInHeapPage<RoleMembershipRecord>(
        role_memberships_table_page_, predicate, ctx);
    if (result.status == Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, Status::FILE_EXISTS, "Role membership already exists");
        return Status::FILE_EXISTS;
    }

    // P2-15: Role cycle detection - prevent A → B → C → A grants
    // Check if granting role_id to user_id would create a cycle
    // A cycle exists if user_id is already (transitively) a member of role_id
    // i.e., if role_id can reach user_id through existing memberships
    {
        std::unordered_set<ID, IDHash> visited;
        std::queue<ID> to_process;

        // Start from role_id and see if we can reach user_id
        to_process.push(role_id);
        visited.insert(role_id);

        while (!to_process.empty())
        {
            ID current = to_process.front();
            to_process.pop();

            // Get all roles that 'current' is a member of (current's parent roles)
            auto role_filter = [&current](const RoleMembershipRecord& rec) {
                return rec.is_valid && rec.user_id == current;
            };

            auto converter = [](const RoleMembershipRecord& rec, RoleMembershipInfo& info) {
                info.membership_id = rec.membership_id;
                info.user_id = rec.user_id;
                info.role_id = rec.role_id;
                info.granted_by = rec.granted_by;
                info.with_admin_option = rec.with_admin_option != 0;
                info.granted_time = rec.granted_time;
            };

            std::vector<RoleMembershipInfo> memberships;
            readRecordsToVector<RoleMembershipRecord, RoleMembershipInfo>(
                role_memberships_table_page_, memberships, role_filter, converter, ctx);

            for (const auto& m : memberships)
            {
                // Check if we've found the target (user_id)
                if (m.role_id == user_id)
                {
                    SET_ERROR_CONTEXT(ctx, Status::CONSTRAINT_VIOLATION,
                        "Role grant would create a cycle");
                    return Status::CONSTRAINT_VIOLATION;
                }

                if (visited.find(m.role_id) == visited.end())
                {
                    visited.insert(m.role_id);
                    to_process.push(m.role_id);
                }
            }
        }
    }

    // Create membership record
    RoleMembershipRecord membership_rec;
    memset(&membership_rec, 0, sizeof(RoleMembershipRecord));
    membership_rec.membership_id = generateUuidV7();
    membership_rec.user_id = user_id;
    membership_rec.role_id = role_id;
    membership_rec.granted_by = granted_by;
    membership_rec.with_admin_option = with_admin_option ? 1 : 0;
    membership_rec.granted_time = std::chrono::system_clock::now().time_since_epoch().count();
    membership_rec.is_valid = 1;

    // Write to disk
    Status status = writeRecordToHeapPage(role_memberships_table_page_, membership_rec, ctx);
    if (status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, status, "Failed to write role membership record");
        return status;
    }

    uint64_t epoch = 0;
    Status epoch_status = bumpSecurityPolicyEpoch(epoch, ctx);
    if (epoch_status != Status::OK)
    {
        return epoch_status;
    }

    if (db_ && db_->permission_cache())
    {
        db_->permission_cache()->invalidateUser(user_id);
    }

    DEBUG_LOG_DB("Granted role " << role_id.toString() << " to user " << user_id.toString());
    return Status::OK;
}

auto CatalogManager::revokeRole(const ID& role_id, const ID& user_id,
                                ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);

    // Find and delete membership
    auto predicate = [&role_id, &user_id](const RoleMembershipRecord& rec) {
        return rec.is_valid && rec.role_id == role_id && rec.user_id == user_id;
    };

    Status status = deleteRecordFromHeapPage<RoleMembershipRecord>(
        role_memberships_table_page_, predicate, ctx);
    if (status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, status, "Failed to revoke role membership");
        return status;
    }

    uint64_t epoch = 0;
    Status epoch_status = bumpSecurityPolicyEpoch(epoch, ctx);
    if (epoch_status != Status::OK)
    {
        return epoch_status;
    }

    if (db_ && db_->permission_cache())
    {
        db_->permission_cache()->invalidateUser(user_id);
    }

    DEBUG_LOG_DB("Revoked role " << role_id.toString() << " from user " << user_id.toString());
    return Status::OK;
}

