auto CatalogManager::grantDefaultPrivilege(const ID& schema_id,
                                           const ID& grantor_id,
                                           PermissionObjectType object_type,
                                           const ID& grantee_id,
                                           GranteeType grantee_type,
                                           uint32_t privileges,
                                           bool grant_option,
                                           ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);

    if (default_privileges_table_page_ == 0)
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "Default privileges table not initialized");
        return Status::INVALID_ARGUMENT;
    }

    auto predicate = [&](const DefaultPrivilegeRecord& rec) {
        return rec.is_valid &&
               rec.schema_id == schema_id &&
               rec.grantor_id == grantor_id &&
               rec.object_type == static_cast<uint8_t>(object_type) &&
               rec.grantee_id == grantee_id &&
               rec.grantee_type == static_cast<uint8_t>(grantee_type);
    };

    auto result = findRecordInHeapPage<DefaultPrivilegeRecord>(default_privileges_table_page_, predicate, ctx);
    if (result.status == Status::OK)
    {
        DefaultPrivilegeRecord updated = result.record;
        updated.privileges |= privileges;
        if (grant_option)
        {
            updated.grant_option = 1;
        }

        Status status = updateRecordInHeapPage(default_privileges_table_page_, result.slot_index,
                                               updated, ctx);
        if (status != Status::OK)
        {
            SET_ERROR_CONTEXT(ctx, status, "Failed to update default privileges record");
        }
        return status;
    }

    DefaultPrivilegeRecord record;
    memset(&record, 0, sizeof(DefaultPrivilegeRecord));
    record.default_privilege_id = generateUuidV7();
    record.schema_id = schema_id;
    record.grantor_id = grantor_id;
    record.object_type = static_cast<uint8_t>(object_type);
    record.grantee_id = grantee_id;
    record.grantee_type = static_cast<uint8_t>(grantee_type);
    record.privileges = privileges;
    record.grant_option = grant_option ? 1 : 0;
    record.created_time = std::chrono::system_clock::now().time_since_epoch().count();
    record.is_valid = 1;

    Status status = writeRecordToHeapPage(default_privileges_table_page_, record, ctx);
    if (status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, status, "Failed to write default privileges record");
    }
    return status;
}

auto CatalogManager::revokeDefaultPrivilege(const ID& schema_id,
                                            const ID& grantor_id,
                                            PermissionObjectType object_type,
                                            const ID& grantee_id,
                                            GranteeType grantee_type,
                                            uint32_t privileges,
                                            ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);

    auto predicate = [&](const DefaultPrivilegeRecord& rec) {
        return rec.is_valid &&
               rec.schema_id == schema_id &&
               rec.grantor_id == grantor_id &&
               rec.object_type == static_cast<uint8_t>(object_type) &&
               rec.grantee_id == grantee_id &&
               rec.grantee_type == static_cast<uint8_t>(grantee_type);
    };

    auto result = findRecordInHeapPage<DefaultPrivilegeRecord>(default_privileges_table_page_, predicate, ctx);
    if (result.status != Status::OK)
    {
        return Status::OK;
    }

    DefaultPrivilegeRecord updated = result.record;
    updated.privileges &= ~privileges;
    if (updated.privileges == 0)
    {
        return deleteRecordFromHeapPage<DefaultPrivilegeRecord>(default_privileges_table_page_,
                                                               predicate, ctx);
    }

    return updateRecordInHeapPage(default_privileges_table_page_, result.slot_index, updated, ctx);
}

auto CatalogManager::listDefaultPrivileges(const ID& schema_id,
                                           const ID& grantor_id,
                                           PermissionObjectType object_type,
                                           std::vector<DefaultPrivilegeInfo>& defaults_out,
                                           ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);

    defaults_out.clear();

    auto filter = [&](const DefaultPrivilegeRecord& rec) {
        return rec.is_valid &&
               rec.schema_id == schema_id &&
               rec.grantor_id == grantor_id &&
               rec.object_type == static_cast<uint8_t>(object_type);
    };

    auto converter = [](const DefaultPrivilegeRecord& rec, DefaultPrivilegeInfo& info) {
        info.default_privilege_id = rec.default_privilege_id;
        info.schema_id = rec.schema_id;
        info.grantor_id = rec.grantor_id;
        info.object_type = static_cast<PermissionObjectType>(rec.object_type);
        info.grantee_id = rec.grantee_id;
        info.grantee_type = static_cast<GranteeType>(rec.grantee_type);
        info.privileges = rec.privileges;
        info.grant_option = rec.grant_option != 0;
        info.created_time = rec.created_time;
    };

    return readRecordsToVector<DefaultPrivilegeRecord, DefaultPrivilegeInfo>(
        default_privileges_table_page_, defaults_out, filter, converter, ctx);
}

auto CatalogManager::applyDefaultPrivileges(const ID& schema_id,
                                            PermissionObjectType object_type,
                                            const ID& object_id,
                                            const ID& grantor_id,
                                            ErrorContext* ctx) -> Status
{
    std::vector<DefaultPrivilegeInfo> defaults;
    Status status = listDefaultPrivileges(schema_id, grantor_id, object_type, defaults, ctx);
    if (status != Status::OK)
    {
        return status;
    }

    for (const auto& def : defaults)
    {
        Status grant_status = grantPermission(object_id, object_type,
                                             def.grantee_id, def.grantee_type,
                                             def.privileges, def.grant_option,
                                             def.grantor_id, ctx);
        if (grant_status != Status::OK)
        {
            return grant_status;
        }
    }

    return Status::OK;
}

// ============================================================================
// Security Phase 3.3: Column-Level Permission Operations
// ============================================================================

auto CatalogManager::grantColumnPermission(const ID& table_id, const std::string& column_name,
                                          const ID& grantee_id, GranteeType grantee_type,
                                          uint32_t privileges, bool grant_option,
                                          const ID& grantor_id, ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);

    // Check if permission already exists for this column - if so, merge privileges
    auto predicate = [&](const ColumnPermissionRecord& rec) {
        return rec.is_valid &&
               rec.table_id == table_id &&
               std::strcmp(rec.column_name, column_name.c_str()) == 0 &&
               rec.grantee_id == grantee_id &&
               rec.grantee_type == static_cast<uint8_t>(grantee_type);
    };

    auto result = findRecordInHeapPage<ColumnPermissionRecord>(column_permissions_table_page_, predicate, ctx);

    if (result.status == Status::OK)
    {
        // Update existing permission - merge privileges
        ColumnPermissionRecord updated_rec = result.record;
        updated_rec.privileges |= privileges;  // OR the privileges together
        if (grant_option) {
            updated_rec.grant_option = 1;
        }

        Status status = updateRecordInHeapPage(column_permissions_table_page_, result.slot_index,
                                              updated_rec, ctx);
        if (status != Status::OK)
        {
            SET_ERROR_CONTEXT(ctx, status, "Failed to update column permission record");
            return status;
        }

        uint64_t epoch = 0;
        Status epoch_status = bumpSecurityPolicyEpoch(epoch, ctx);
        if (epoch_status != Status::OK)
        {
            return epoch_status;
        }
        uint64_t table_epoch = 0;
        Status table_status = bumpTablePolicyEpoch(table_id, table_epoch, ctx);
        if (table_status != Status::OK)
        {
            return table_status;
        }

        DEBUG_LOG_DB("Updated column permission on table " << table_id.toString()
                    << ", column: " << column_name);
        return Status::OK;
    }

    // Create new column permission record
    ColumnPermissionRecord col_perm_rec;
    memset(&col_perm_rec, 0, sizeof(ColumnPermissionRecord));
    col_perm_rec.permission_id = generateUuidV7();
    col_perm_rec.table_id = table_id;
    strncpy(col_perm_rec.column_name, column_name.c_str(), 127);
    col_perm_rec.column_name[127] = '\0';  // Ensure null termination
    col_perm_rec.grantee_id = grantee_id;
    col_perm_rec.grantee_type = static_cast<uint8_t>(grantee_type);
    col_perm_rec.privileges = privileges;
    col_perm_rec.grant_option = grant_option ? 1 : 0;
    col_perm_rec.grantor_id = grantor_id;
    col_perm_rec.created_time = std::chrono::system_clock::now().time_since_epoch().count();
    col_perm_rec.is_valid = 1;

    // Write to disk
    Status status = writeRecordToHeapPage(column_permissions_table_page_, col_perm_rec, ctx);
    if (status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, status, "Failed to write column permission record");
        return status;
    }

    uint64_t epoch = 0;
    Status epoch_status = bumpSecurityPolicyEpoch(epoch, ctx);
    if (epoch_status != Status::OK)
    {
        return epoch_status;
    }
    uint64_t table_epoch = 0;
    Status table_status = bumpTablePolicyEpoch(table_id, table_epoch, ctx);
    if (table_status != Status::OK)
    {
        return table_status;
    }

    DEBUG_LOG_DB("Granted column permission on table " << table_id.toString()
                << ", column: " << column_name);
    return Status::OK;
}

auto CatalogManager::revokeColumnPermission(const ID& table_id, const std::string& column_name,
                                           const ID& grantee_id, GranteeType grantee_type,
                                           uint32_t privileges, ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);

    // Find column permission record
    auto predicate = [&](const ColumnPermissionRecord& rec) {
        return rec.is_valid &&
               rec.table_id == table_id &&
               std::strcmp(rec.column_name, column_name.c_str()) == 0 &&
               rec.grantee_id == grantee_id &&
               rec.grantee_type == static_cast<uint8_t>(grantee_type);
    };

    auto result = findRecordInHeapPage<ColumnPermissionRecord>(column_permissions_table_page_, predicate, ctx);
    if (result.status != Status::OK)
    {
        // Permission not found - not an error, just return OK
        return Status::OK;
    }

    // Remove specified privileges (AND with inverse)
    ColumnPermissionRecord updated_rec = result.record;
    updated_rec.privileges &= ~privileges;  // Clear the specified privilege bits

    // If no privileges remain, mark as deleted (MGA soft delete)
    if (updated_rec.privileges == 0)
    {
        updated_rec.is_valid = 0;
    }

    Status status = updateRecordInHeapPage(column_permissions_table_page_, result.slot_index,
                                          updated_rec, ctx);
    if (status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, status, "Failed to revoke column permission");
        return status;
    }

    uint64_t epoch = 0;
    Status epoch_status = bumpSecurityPolicyEpoch(epoch, ctx);
    if (epoch_status != Status::OK)
    {
        return epoch_status;
    }
    uint64_t table_epoch = 0;
    Status table_status = bumpTablePolicyEpoch(table_id, table_epoch, ctx);
    if (table_status != Status::OK)
    {
        return table_status;
    }

    DEBUG_LOG_DB("Revoked column permission on table " << table_id.toString()
                << ", column: " << column_name);
    return Status::OK;
}

auto CatalogManager::hasColumnPermission(const ID& user_id, const ID& table_id,
                                        const std::string& column_name, Privilege privilege,
                                        bool& has_perm_out, ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);

    has_perm_out = false;

    // IMPORTANT: Check table-level permission first
    // If user has table-level privilege, they have access to all columns
    bool has_table_perm = false;
    Status status = hasPermission(user_id, table_id, PermissionObjectType::TABLE,
                                 privilege, has_table_perm, ctx);
    if (status != Status::OK) {
        return status;
    }

    if (has_table_perm) {
        has_perm_out = true;
        return Status::OK;
    }

    // Check column-level permission
    uint32_t required_priv = static_cast<uint32_t>(privilege);

    // Check user's direct column permissions
    auto user_predicate = [&](const ColumnPermissionRecord& rec) {
        return rec.is_valid &&
               rec.table_id == table_id &&
               std::strcmp(rec.column_name, column_name.c_str()) == 0 &&
               rec.grantee_id == user_id &&
               rec.grantee_type == static_cast<uint8_t>(GranteeType::USER) &&
               (rec.privileges & required_priv) != 0;
    };

    auto result = findRecordInHeapPage<ColumnPermissionRecord>(
        column_permissions_table_page_, user_predicate, ctx);

    if (result.status == Status::OK) {
        has_perm_out = true;
        return Status::OK;
    }

    // WP-3 PERM-1: Check role memberships for column permissions
    std::vector<ID> effective_roles;
    status = getEffectiveRoles(user_id, effective_roles, ctx);
    if (status == Status::OK)
    {
        for (const auto& role_id : effective_roles)
        {
            auto role_predicate = [&](const ColumnPermissionRecord& rec) {
                return rec.is_valid &&
                       rec.table_id == table_id &&
                       std::strcmp(rec.column_name, column_name.c_str()) == 0 &&
                       rec.grantee_id == role_id &&
                       rec.grantee_type == static_cast<uint8_t>(GranteeType::ROLE) &&
                       (rec.privileges & required_priv) != 0;
            };

            result = findRecordInHeapPage<ColumnPermissionRecord>(
                column_permissions_table_page_, role_predicate, ctx);
            if (result.status == Status::OK)
            {
                has_perm_out = true;
                return Status::OK;
            }
        }
    }

    // WP-3 PERM-1: Check group memberships for column permissions
    std::vector<ID> effective_groups;
    status = getEffectiveGroups(user_id, effective_groups, ctx);
    if (status == Status::OK)
    {
        for (const auto& group_id : effective_groups)
        {
            auto group_predicate = [&](const ColumnPermissionRecord& rec) {
                return rec.is_valid &&
                       rec.table_id == table_id &&
                       std::strcmp(rec.column_name, column_name.c_str()) == 0 &&
                       rec.grantee_id == group_id &&
                       rec.grantee_type == static_cast<uint8_t>(GranteeType::GROUP) &&
                       (rec.privileges & required_priv) != 0;
            };

            result = findRecordInHeapPage<ColumnPermissionRecord>(
                column_permissions_table_page_, group_predicate, ctx);
            if (result.status == Status::OK)
            {
                has_perm_out = true;
                return Status::OK;
            }
        }
    }

    return Status::OK;
}

auto CatalogManager::getAccessibleColumns(const ID& user_id, const ID& table_id,
                                         Privilege privilege, std::vector<std::string>& columns_out,
                                         ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);

    columns_out.clear();

    // Check if user has table-level permission
    bool has_table_perm = false;
    Status status = hasPermission(user_id, table_id, PermissionObjectType::TABLE,
                                 privilege, has_table_perm, ctx);
    if (status != Status::OK) {
        return status;
    }

    // If user has table-level permission, return empty vector
    // Empty vector signals "all columns accessible" to avoid loading all column names
    if (has_table_perm) {
        return Status::OK;
    }

    if (column_permissions_table_page_ == 0)
    {
        return Status::OK;
    }

    // Collect columns with specific privileges
    uint32_t required_priv = static_cast<uint32_t>(privilege);
    std::unordered_set<std::string> visible_columns;

    auto collect_columns_for_grantee =
        [&](GranteeType grantee_type, const ID* grantee_id) -> Status
    {
        std::vector<std::string> granted_columns;
        auto filter = [&](const ColumnPermissionRecord& rec) {
            if (!rec.is_valid ||
                rec.table_id != table_id ||
                rec.grantee_type != static_cast<uint8_t>(grantee_type) ||
                (rec.privileges & required_priv) == 0)
            {
                return false;
            }

            if (grantee_type == GranteeType::PUBLIC)
            {
                return true;
            }

            return grantee_id != nullptr && rec.grantee_id == *grantee_id;
        };

        auto converter = [](const ColumnPermissionRecord& rec, std::string& col_name) {
            col_name = std::string(rec.column_name);
        };

        Status read_status = readRecordsToVector<ColumnPermissionRecord, std::string>(
            column_permissions_table_page_, granted_columns, filter, converter, ctx);
        if (read_status != Status::OK)
        {
            return read_status;
        }

        for (const auto& col_name : granted_columns)
        {
            if (visible_columns.insert(col_name).second)
            {
                columns_out.push_back(col_name);
            }
        }

        return Status::OK;
    };

    Status collect_status = collect_columns_for_grantee(GranteeType::USER, &user_id);
    if (collect_status != Status::OK)
    {
        return collect_status;
    }

    collect_status = collect_columns_for_grantee(GranteeType::PUBLIC, nullptr);
    if (collect_status != Status::OK)
    {
        return collect_status;
    }

    std::vector<ID> effective_roles;
    status = getEffectiveRoles(user_id, effective_roles, ctx);
    if (status != Status::OK)
    {
        return status;
    }
    for (const auto& role_id : effective_roles)
    {
        collect_status = collect_columns_for_grantee(GranteeType::ROLE, &role_id);
        if (collect_status != Status::OK)
        {
            return collect_status;
        }
    }

    std::vector<ID> effective_groups;
    status = getEffectiveGroups(user_id, effective_groups, ctx);
    if (status != Status::OK)
    {
        return status;
    }
    for (const auto& group_id : effective_groups)
    {
        collect_status = collect_columns_for_grantee(GranteeType::GROUP, &group_id);
        if (collect_status != Status::OK)
        {
            return collect_status;
        }
    }

    std::sort(columns_out.begin(), columns_out.end());
    return Status::OK;
}

auto CatalogManager::getColumnPermissions(const ID& table_id,
                                         std::vector<ColumnPermissionInfo>& perms_out,
                                         ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);

    perms_out.clear();

    auto filter = [&](const ColumnPermissionRecord& rec) {
        return rec.is_valid && rec.table_id == table_id;
    };

    auto converter = [](const ColumnPermissionRecord& rec, ColumnPermissionInfo& info) {
        info.permission_id = rec.permission_id;
        info.table_id = rec.table_id;
        info.column_name = std::string(rec.column_name);
        info.grantee_id = rec.grantee_id;
        info.grantee_type = static_cast<GranteeType>(rec.grantee_type);
        info.privileges = rec.privileges;
        info.grant_option = rec.grant_option != 0;
        info.grantor_id = rec.grantor_id;
        info.created_time = rec.created_time;
    };

    return readRecordsToVector<ColumnPermissionRecord, ColumnPermissionInfo>(
        column_permissions_table_page_, perms_out, filter, converter, ctx);
}

// ============================================================================
// Security Phase 3.4: Row-Level Security Policy Operations
// ============================================================================

auto CatalogManager::createPolicy(const ID& table_id, const std::string& policy_name,
                                 PolicyType type, const std::vector<std::string>& roles,
                                 const std::string& using_expr, const std::string& with_check_expr,
                                 ID& policy_id_out, ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);

    // Check if policy with this name already exists on this table
    auto predicate = [&](const PolicyRecord& rec) {
        return rec.is_valid &&
               rec.table_id == table_id &&
               std::strcmp(rec.policy_name, policy_name.c_str()) == 0;
    };

    auto result = findRecordInHeapPage<PolicyRecord>(policies_table_page_, predicate, ctx);
    if (result.status == Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, Status::FILE_EXISTS,
                         ("Policy '" + policy_name + "' already exists on table").c_str());
        return Status::FILE_EXISTS;
    }

    // Create new policy record
    PolicyRecord policy_rec;
    memset(&policy_rec, 0, sizeof(PolicyRecord));
    policy_rec.policy_id = generateUuidV7();
    policy_rec.table_id = table_id;
    strncpy(policy_rec.policy_name, policy_name.c_str(), 63);
    policy_rec.policy_name[63] = '\0';  // Ensure null termination
    policy_rec.policy_type = static_cast<uint8_t>(type);
    policy_rec.is_enabled = 1;
    policy_rec.created_time = std::chrono::system_clock::now().time_since_epoch().count();
    policy_rec.modified_time = policy_rec.created_time;
    policy_rec.is_valid = 1;

    // Store expressions in TOAST (Phase 1.4 - WP-1 TOAST Integration)
    uint64_t xmin = 0;  // Catalog operations use transaction 0 for visibility
    Status toast_status;

    // Store roles array in TOAST if non-empty
    policy_rec.roles_oid = ID{};
    if (!roles.empty())
    {
        // Serialize roles as comma-separated string
        std::string roles_str;
        for (size_t i = 0; i < roles.size(); ++i)
        {
            if (i > 0) roles_str += ",";
            roles_str += roles[i];
        }
        // Store roles_str in TOAST
        toast_status = storeStringInToast(roles_str, xmin, policy_rec.roles_oid, ctx);
        if (toast_status != Status::OK)
        {
            SET_ERROR_CONTEXT(ctx, toast_status, "Failed to store policy roles in TOAST");
            return toast_status;
        }
    }

    // Store USING expression
    toast_status = storeStringInToast(using_expr, xmin, policy_rec.using_expr_oid, ctx);
    if (toast_status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, toast_status, "Failed to store USING expression");
        return toast_status;
    }

    // Store WITH CHECK expression
    toast_status = storeStringInToast(with_check_expr, xmin, policy_rec.with_check_expr_oid, ctx);
    if (toast_status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, toast_status, "Failed to store WITH CHECK expression");
        return toast_status;
    }

    // Write to disk
    Status status = writeRecordToHeapPage(policies_table_page_, policy_rec, ctx);
    if (status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, status, "Failed to write policy record");
        return status;
    }

    // Cache policy in memory with expressions (Phase 3.4.6)
    {
        std::lock_guard<std::mutex> cache_lock(policy_cache_mutex_);

        PolicyInfo policy_info;
        policy_info.policy_id = policy_rec.policy_id;
        policy_info.table_id = policy_rec.table_id;
        policy_info.policy_name = policy_name;
        policy_info.policy_type = type;

        // Phase 3 Polish: Convert role names to UUIDs
        policy_info.role_ids.clear();
        for (const auto& role_name : roles)
        {
            RoleInfo role;
            if (getRoleByName(role_name, role, ctx) == Status::OK)
            {
                policy_info.role_ids.push_back(role.role_id);
            }
            // If role doesn't exist, skip it (could warn)
        }

        policy_info.using_expr = using_expr;        // Store actual expression string
        policy_info.with_check_expr = with_check_expr;  // Store actual expression string
        policy_info.is_enabled = true;
        policy_info.created_time = policy_rec.created_time;
        policy_info.modified_time = policy_rec.modified_time;

        policy_cache_[policy_info.policy_id] = policy_info;
    }

    policy_id_out = policy_rec.policy_id;
    DEBUG_LOG_DB("Created policy '" << policy_name << "' on table " << table_id.toString());

    uint64_t epoch = 0;
    Status epoch_status = bumpSecurityPolicyEpoch(epoch, ctx);
    if (epoch_status != Status::OK)
    {
        return epoch_status;
    }
    uint64_t table_epoch = 0;
    Status table_status = bumpTablePolicyEpoch(table_id, table_epoch, ctx);
    if (table_status != Status::OK)
    {
        return table_status;
    }

    return Status::OK;
}

auto CatalogManager::dropPolicy(const ID& table_id, const std::string& policy_name,
                               ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);

    // Find policy record
    auto predicate = [&](const PolicyRecord& rec) {
        return rec.is_valid &&
               rec.table_id == table_id &&
               std::strcmp(rec.policy_name, policy_name.c_str()) == 0;
    };

    auto result = findRecordInHeapPage<PolicyRecord>(policies_table_page_, predicate, ctx);
    if (result.status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND,
                         ("Policy '" + policy_name + "' not found on table").c_str());
        return Status::NOT_FOUND;
    }

    // Phase 3.4.8: Delete TOAST data for expressions before soft-deleting the policy
    uint64_t xmax = ConnectionContext::getCurrentTransactionId();
    if (xmax == 0)
    {
        xmax = config::DEFAULT_INITIAL_XID;
    }

    // Delete USING expression from TOAST if it exists
    if (!isZeroUuidLocal(result.record.using_expr_oid) && policy_toast_manager_)
    {
        Status toast_status = policy_toast_manager_->deleteToastValue(
            result.record.using_expr_oid, xmax, ctx);
        if (toast_status != Status::OK)
        {
            DEBUG_LOG_DB("Warning: Failed to delete USING expression TOAST data for policy: " << policy_name);
            // Non-fatal - continue with policy deletion
        }
    }

    // Delete WITH CHECK expression from TOAST if it exists
    if (!isZeroUuidLocal(result.record.with_check_expr_oid) && policy_toast_manager_)
    {
        Status toast_status = policy_toast_manager_->deleteToastValue(
            result.record.with_check_expr_oid, xmax, ctx);
        if (toast_status != Status::OK)
        {
            DEBUG_LOG_DB("Warning: Failed to delete WITH CHECK expression TOAST data for policy: " << policy_name);
            // Non-fatal - continue with policy deletion
        }
    }

    // Mark as invalid (soft delete - MGA pattern)
    PolicyRecord updated_rec = result.record;
    updated_rec.is_valid = 0;

    Status status = updateRecordInHeapPage(policies_table_page_, result.slot_index,
                                          updated_rec, ctx);
    if (status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, status, "Failed to delete policy record");
        return status;
    }

    // Remove from cache (Phase 3.4.6)
    {
        std::lock_guard<std::mutex> cache_lock(policy_cache_mutex_);
        policy_cache_.erase(result.record.policy_id);
    }

    DEBUG_LOG_DB("Dropped policy '" << policy_name << "' from table " << table_id.toString());

    uint64_t epoch = 0;
    Status epoch_status = bumpSecurityPolicyEpoch(epoch, ctx);
    if (epoch_status != Status::OK)
    {
        return epoch_status;
    }
    uint64_t table_epoch = 0;
    Status table_status = bumpTablePolicyEpoch(table_id, table_epoch, ctx);
    if (table_status != Status::OK)
    {
        return table_status;
    }

    return Status::OK;
}

auto CatalogManager::alterPolicy(const ID& table_id, const std::string& policy_name,
                                int is_enabled, const std::string& using_expr,
                                const std::string& with_check_expr,
                                ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);

    // Find policy record
    auto predicate = [&](const PolicyRecord& rec) {
        return rec.is_valid &&
               rec.table_id == table_id &&
               std::strcmp(rec.policy_name, policy_name.c_str()) == 0;
    };

    auto result = findRecordInHeapPage<PolicyRecord>(policies_table_page_, predicate, ctx);
    if (result.status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND,
                         ("Policy '" + policy_name + "' not found on table").c_str());
        return Status::NOT_FOUND;
    }

    // Update the record
    PolicyRecord updated_rec = result.record;
    bool modified = false;

    // Update enabled status if specified (-1 means don't change)
    if (is_enabled >= 0)
    {
        updated_rec.is_enabled = is_enabled ? 1 : 0;
        modified = true;
    }

    // Update USING expression if specified (non-empty)
    if (!using_expr.empty())
    {
        uint64_t xmin = ConnectionContext::getCurrentTransactionId();
        if (xmin == 0)
        {
            xmin = config::DEFAULT_INITIAL_XID;
        }

        // Delete old expression if exists
        if (!isZeroUuidLocal(updated_rec.using_expr_oid) && policy_toast_manager_)
        {
            policy_toast_manager_->deleteToastValue(updated_rec.using_expr_oid, xmin, ctx);
        }

        // Store new expression
        Status toast_status = storeStringInToast(using_expr, xmin, updated_rec.using_expr_oid, ctx);
        if (toast_status != Status::OK)
        {
            SET_ERROR_CONTEXT(ctx, toast_status, "Failed to store USING expression");
            return toast_status;
        }
        modified = true;
    }

    // Update WITH CHECK expression if specified (non-empty)
    if (!with_check_expr.empty())
    {
        uint64_t xmin = ConnectionContext::getCurrentTransactionId();
        if (xmin == 0)
        {
            xmin = config::DEFAULT_INITIAL_XID;
        }

        // Delete old expression if exists
        if (!isZeroUuidLocal(updated_rec.with_check_expr_oid) && policy_toast_manager_)
        {
            policy_toast_manager_->deleteToastValue(updated_rec.with_check_expr_oid, xmin, ctx);
        }

        // Store new expression
        Status toast_status = storeStringInToast(with_check_expr, xmin, updated_rec.with_check_expr_oid, ctx);
        if (toast_status != Status::OK)
        {
            SET_ERROR_CONTEXT(ctx, toast_status, "Failed to store WITH CHECK expression");
            return toast_status;
        }
        modified = true;
    }

    if (!modified)
    {
        return Status::OK;  // Nothing to change
    }

    // Update modified time
    updated_rec.modified_time = std::chrono::system_clock::now().time_since_epoch().count();

    // Write updated record
    Status status = updateRecordInHeapPage(policies_table_page_, result.slot_index,
                                          updated_rec, ctx);
    if (status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, status, "Failed to update policy record");
        return status;
    }

    // Update cache (Phase 3.4.6)
    {
        std::lock_guard<std::mutex> cache_lock(policy_cache_mutex_);

        auto it = policy_cache_.find(result.record.policy_id);
        if (it != policy_cache_.end())
        {
            if (is_enabled >= 0)
            {
                it->second.is_enabled = (is_enabled != 0);
            }
            if (!using_expr.empty())
            {
                it->second.using_expr = using_expr;
            }
            if (!with_check_expr.empty())
            {
                it->second.with_check_expr = with_check_expr;
            }
            it->second.modified_time = updated_rec.modified_time;
        }
    }

    DEBUG_LOG_DB("Altered policy '" << policy_name << "' on table " << table_id.toString());

    uint64_t epoch = 0;
    Status epoch_status = bumpSecurityPolicyEpoch(epoch, ctx);
    if (epoch_status != Status::OK)
    {
        return epoch_status;
    }
    uint64_t table_epoch = 0;
    Status table_status = bumpTablePolicyEpoch(table_id, table_epoch, ctx);
    if (table_status != Status::OK)
    {
        return table_status;
    }

    return Status::OK;
}

auto CatalogManager::getPolicy(const ID& table_id, const std::string& policy_name,
                              PolicyInfo& policy_out, ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);

    // Find policy record on disk
    auto predicate = [&](const PolicyRecord& rec) {
        return rec.is_valid &&
               rec.table_id == table_id &&
               std::strcmp(rec.policy_name, policy_name.c_str()) == 0;
    };

    auto result = findRecordInHeapPage<PolicyRecord>(policies_table_page_, predicate, ctx);
    if (result.status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND,
                         ("Policy '" + policy_name + "' not found").c_str());
        return Status::NOT_FOUND;
    }

    // Check cache for full policy info with expressions (Phase 3.4.6)
    {
        std::lock_guard<std::mutex> cache_lock(policy_cache_mutex_);
        auto cache_it = policy_cache_.find(result.record.policy_id);
        if (cache_it != policy_cache_.end())
        {
            // Return cached policy with expressions
            policy_out = cache_it->second;
            return Status::OK;
        }
    }

    // Policy not in cache - load from TOAST (Phase 3.4.8)
    // Convert record to PolicyInfo
    policy_out.policy_id = result.record.policy_id;
    policy_out.table_id = result.record.table_id;
    policy_out.policy_name = std::string(result.record.policy_name);
    policy_out.policy_type = static_cast<PolicyType>(result.record.policy_type);
    policy_out.is_enabled = result.record.is_enabled != 0;
    policy_out.created_time = result.record.created_time;
    policy_out.modified_time = result.record.modified_time;

    // Load expressions from TOAST if available (Phase 3.4.8)
    uint64_t xmin = ConnectionContext::getCurrentTransactionId();
    if (xmin == 0)
    {
        xmin = config::DEFAULT_INITIAL_XID;
    }

    // Load USING expression
    Status load_status = loadStringFromToast(result.record.using_expr_oid, xmin,
                                            policy_out.using_expr, ctx);
    if (load_status != Status::OK && load_status != Status::NOT_FOUND)
    {
        DEBUG_LOG_DB("Failed to load USING expression from TOAST for policy: " << policy_name);
        // Non-fatal - continue with empty expression
        policy_out.using_expr = "";
    }

    // Load WITH CHECK expression
    load_status = loadStringFromToast(result.record.with_check_expr_oid, xmin,
                                     policy_out.with_check_expr, ctx);
    if (load_status != Status::OK && load_status != Status::NOT_FOUND)
    {
        DEBUG_LOG_DB("Failed to load WITH CHECK expression from TOAST for policy: " << policy_name);
        // Non-fatal - continue with empty expression
        policy_out.with_check_expr = "";
    }

    policy_out.role_ids.clear();
    if (!isZeroUuidLocal(result.record.roles_oid))
    {
        std::string roles_str;
        Status roles_status = loadStringFromToast(result.record.roles_oid, xmin, roles_str, ctx);
        if (roles_status == Status::OK && !roles_str.empty())
        {
            std::istringstream iss(roles_str);
            std::string role_name;
            while (std::getline(iss, role_name, ','))
            {
                if (role_name.empty())
                {
                    continue;
                }
                RoleInfo role;
                if (getRoleByName(role_name, role, ctx) == Status::OK)
                {
                    policy_out.role_ids.push_back(role.role_id);
                }
            }
        }
    }

    // Cache the loaded policy for future access
    {
        std::lock_guard<std::mutex> cache_lock(policy_cache_mutex_);
        policy_cache_[policy_out.policy_id] = policy_out;
    }

    return Status::OK;
}

auto CatalogManager::getTablePolicies(const ID& table_id, PolicyType type,
                                     std::vector<PolicyInfo>& policies_out,
                                     ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);

    policies_out.clear();

    auto filter = [&](const PolicyRecord& rec) {
        if (!rec.is_valid || rec.table_id != table_id)
            return false;

        // If type is ALL, return all policies
        // Otherwise, match specific type or ALL type policies
        if (type == PolicyType::ALL)
            return true;

        return rec.policy_type == static_cast<uint8_t>(type) ||
               rec.policy_type == static_cast<uint8_t>(PolicyType::ALL);
    };

    uint64_t xmin = ConnectionContext::getCurrentTransactionId();
    if (xmin == 0)
    {
        xmin = config::DEFAULT_INITIAL_XID;
    }

    auto converter = [this, xmin, ctx](const PolicyRecord& rec, PolicyInfo& info) {
        info.policy_id = rec.policy_id;
        info.table_id = rec.table_id;
        info.policy_name = std::string(rec.policy_name);
        info.policy_type = static_cast<PolicyType>(rec.policy_type);
        info.is_enabled = rec.is_valid != 0;
        info.created_time = rec.created_time;
        info.modified_time = rec.modified_time;

        // Try to load from cache with expressions (Phase 3.4.6)
        {
            std::lock_guard<std::mutex> cache_lock(policy_cache_mutex_);
            auto cache_it = policy_cache_.find(rec.policy_id);
            if (cache_it != policy_cache_.end())
            {
                // Use cached policy with expressions (Phase 3 Polish: role_ids)
                info.role_ids = cache_it->second.role_ids;
                info.using_expr = cache_it->second.using_expr;
                info.with_check_expr = cache_it->second.with_check_expr;
                return;
            }
        }

        // Cache miss - no expressions available (Phase 3 Polish: role_ids)
        info.role_ids.clear();
        info.using_expr.clear();
        info.with_check_expr.clear();

        if (!isZeroUuidLocal(rec.using_expr_oid))
        {
            loadStringFromToast(rec.using_expr_oid, xmin, info.using_expr, ctx);
        }
        if (!isZeroUuidLocal(rec.with_check_expr_oid))
        {
            loadStringFromToast(rec.with_check_expr_oid, xmin, info.with_check_expr, ctx);
        }

        if (!isZeroUuidLocal(rec.roles_oid))
        {
            std::string roles_str;
            if (loadStringFromToast(rec.roles_oid, xmin, roles_str, ctx) == Status::OK)
            {
                std::istringstream iss(roles_str);
                std::string role_name;
                while (std::getline(iss, role_name, ','))
                {
                    if (role_name.empty())
                    {
                        continue;
                    }
                    RoleInfo role;
                    if (getRoleByName(role_name, role, ctx) == Status::OK)
                    {
                        info.role_ids.push_back(role.role_id);
                    }
                }
            }
        }

        {
            std::lock_guard<std::mutex> cache_lock(policy_cache_mutex_);
            policy_cache_[info.policy_id] = info;
        }
    };

    return readRecordsToVector<PolicyRecord, PolicyInfo>(
        policies_table_page_, policies_out, filter, converter, ctx);
}

auto CatalogManager::getPoliciesForUser(const ID& table_id, const ID& user_id,
                                       PolicyType type, std::vector<PolicyInfo>& policies_out,
                                       ErrorContext* ctx) -> Status
{
    // First get all policies for the table
    std::vector<PolicyInfo> all_policies;
    Status status = getTablePolicies(table_id, type, all_policies, ctx);
    if (status != Status::OK)
        return status;

    // WP-3 PERM-3: Filter policies by user roles
    // Get effective roles for the user
    std::vector<ID> effective_roles;
    {
        std::lock_guard<CatalogMutex> lock(mutex_);
        getEffectiveRoles(user_id, effective_roles, ctx);
    }

    policies_out.clear();

    for (const auto& policy : all_policies)
    {
        // Policy with empty roles applies to all users
        if (policy.role_ids.empty())
        {
            policies_out.push_back(policy);
            continue;
        }

        // Check if user or any of their roles matches a policy role
        bool applies = false;
        for (const auto& policy_role : policy.role_ids)
        {
            // Check direct user match (policy can target specific users by ID)
            if (policy_role == user_id)
            {
                applies = true;
                break;
            }

            // Check role membership
            for (const auto& user_role : effective_roles)
            {
                if (policy_role == user_role)
                {
                    applies = true;
                    break;
                }
            }
            if (applies)
                break;
        }

        if (applies)
        {
            policies_out.push_back(policy);
        }
    }

    return Status::OK;
}

// Test helper: Clear policy cache to force TOAST loading (Phase 3.4.8)
void CatalogManager::clearPolicyCache()
{
    std::lock_guard<std::mutex> lock(policy_cache_mutex_);
    policy_cache_.clear();
    DEBUG_LOG_DB("Policy cache cleared (test helper)");
}

auto CatalogManager::setTableRLS(const ID& table_id, bool enabled, bool forced,
                                ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);

    // Find table record
    auto predicate = [&](const TableRecord& rec) {
        return rec.is_valid && rec.table_id == table_id;
    };

    auto result = findRecordInHeapPage<TableRecord>(tables_table_page_, predicate, ctx);
    if (result.status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND, "Table not found");
        return Status::NOT_FOUND;
    }

    // Update RLS flags
    TableRecord updated_rec = result.record;
    updated_rec.rls_enabled = enabled ? 1 : 0;
    updated_rec.rls_forced = forced ? 1 : 0;

    Status status = updateRecordInHeapPage(tables_table_page_, result.slot_index,
                                          updated_rec, ctx);
    if (status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, status, "Failed to update table RLS settings");
        return status;
    }

    auto table_it = table_cache_.find(table_id);
    if (table_it != table_cache_.end())
    {
        table_it->second.rls_enabled = enabled;
        table_it->second.rls_forced = forced;
    }

    uint64_t epoch = 0;
    Status epoch_status = bumpSecurityPolicyEpoch(epoch, ctx);
    if (epoch_status != Status::OK)
    {
        return epoch_status;
    }
    uint64_t table_epoch = 0;
    Status table_status = bumpTablePolicyEpoch(table_id, table_epoch, ctx);
    if (table_status != Status::OK)
    {
        return table_status;
    }

    DEBUG_LOG_DB("Set RLS on table " << table_id.toString()
                << " - enabled: " << enabled << ", forced: " << forced);
    return Status::OK;
}

auto CatalogManager::getTableRLS(const ID& table_id, bool& enabled_out, bool& forced_out,
                                ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);

    // Find table record
    auto predicate = [&](const TableRecord& rec) {
        return rec.is_valid && rec.table_id == table_id;
    };

    auto result = findRecordInHeapPage<TableRecord>(tables_table_page_, predicate, ctx);
    if (result.status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND, "Table not found");
        return Status::NOT_FOUND;
    }

    enabled_out = result.record.rls_enabled != 0;
    forced_out = result.record.rls_forced != 0;

    return Status::OK;
}

// ============================================================================
// Security Phase 3.1: SQL Object Permissions
// ============================================================================

auto CatalogManager::grantObjectPermission(const ID& object_id, ObjectType object_type,
                                          const ID& grantee_id, GranteeType grantee_type,
                                          uint32_t permissions, bool grant_option,
                                          ID& permission_id_out, ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);

    // Check if permission already exists for this object+grantee combination
    auto predicate = [&](const ObjectPermissionRecord& rec) {
        return rec.is_valid &&
               rec.object_id == object_id &&
               rec.grantee_id == grantee_id;
    };

    auto result = findRecordInHeapPage<ObjectPermissionRecord>(object_permissions_table_page_, predicate, ctx);
    if (result.status == Status::OK)
    {
        // Permission exists - update it (OR the permissions together)
        ObjectPermissionRecord updated_rec = result.record;
        updated_rec.permissions |= permissions;  // Add new permissions
        updated_rec.grant_option = grant_option ? 1 : 0;
        updated_rec.created_time = std::chrono::system_clock::now().time_since_epoch().count();

        Status status = updateRecordInHeapPage(object_permissions_table_page_, result.slot_index,
                                              updated_rec, ctx);
        if (status != Status::OK)
        {
            SET_ERROR_CONTEXT(ctx, status, "Failed to update object permission");
            return status;
        }

        permission_id_out = updated_rec.permission_id;

        // Update cache
        {
            std::lock_guard<std::mutex> cache_lock(object_permissions_cache_mutex_);
            auto& perms = object_permissions_cache_[object_id];
            for (auto& perm : perms)
            {
                if (perm.grantee_id == grantee_id)
                {
                    perm.permissions = updated_rec.permissions;
                    perm.grant_option = grant_option;
                    perm.created_time = updated_rec.created_time;
                    break;
                }
            }
        }

        uint64_t epoch = 0;
        Status epoch_status = bumpSecurityPolicyEpoch(epoch, ctx);
        if (epoch_status != Status::OK)
        {
            return epoch_status;
        }
        if (object_type == ObjectType::TABLE)
        {
            uint64_t table_epoch = 0;
            Status table_status = bumpTablePolicyEpoch(object_id, table_epoch, ctx);
            if (table_status != Status::OK)
            {
                return table_status;
            }
        }

        DEBUG_LOG_DB("Updated object permission for object " << object_id.toString());
        return Status::OK;
    }

    // Create new permission record
    ObjectPermissionRecord perm_rec;
    memset(&perm_rec, 0, sizeof(ObjectPermissionRecord));
    perm_rec.permission_id = generateUuidV7();
    perm_rec.object_id = object_id;
    perm_rec.object_type = static_cast<uint8_t>(object_type);
    perm_rec.grantee_id = grantee_id;
    perm_rec.grantee_type = static_cast<uint8_t>(grantee_type);
    perm_rec.permissions = permissions;
    perm_rec.grant_option = grant_option ? 1 : 0;

    // Get grantor from connection context
    ConnectionContext* conn_ctx = ConnectionContext::getCurrent();
    if (conn_ctx)
    {
        perm_rec.grantor_id = conn_ctx->getCurrentUserId();
    }
    else
    {
        perm_rec.grantor_id = getSystemUserIdUnlocked(ctx);
        if (isZeroUuidLocal(perm_rec.grantor_id))
        {
            return ctx ? ctx->code : Status::PAGE_CORRUPT;
        }
    }

    perm_rec.created_time = std::chrono::system_clock::now().time_since_epoch().count();
    perm_rec.is_valid = 1;

    // Write to disk
    Status status = writeRecordToHeapPage(object_permissions_table_page_, perm_rec, ctx);
    if (status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, status, "Failed to write object permission record");
        return status;
    }

    // Cache permission
    {
        std::lock_guard<std::mutex> cache_lock(object_permissions_cache_mutex_);

        ObjectPermissionInfo perm_info;
        perm_info.permission_id = perm_rec.permission_id;
        perm_info.object_id = object_id;
        perm_info.object_type = object_type;
        perm_info.grantee_id = grantee_id;
        perm_info.grantee_type = grantee_type;
        perm_info.permissions = permissions;
        perm_info.grant_option = grant_option;
        perm_info.grantor_id = perm_rec.grantor_id;
        perm_info.created_time = perm_rec.created_time;

        object_permissions_cache_[object_id].push_back(perm_info);
    }

    {
        uint64_t epoch = 0;
        Status epoch_status = bumpSecurityPolicyEpoch(epoch, ctx);
        if (epoch_status != Status::OK)
        {
            return epoch_status;
        }
        if (object_type == ObjectType::TABLE)
        {
            uint64_t table_epoch = 0;
            Status table_status = bumpTablePolicyEpoch(object_id, table_epoch, ctx);
            if (table_status != Status::OK)
            {
                return table_status;
            }
        }
    }

    permission_id_out = perm_rec.permission_id;
    DEBUG_LOG_DB("Granted object permission on object " << object_id.toString());
    return Status::OK;
}

auto CatalogManager::revokeObjectPermission(const ID& object_id, const ID& grantee_id,
                                           ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);

    // Find permission record
    auto predicate = [&](const ObjectPermissionRecord& rec) {
        return rec.is_valid &&
               rec.object_id == object_id &&
               rec.grantee_id == grantee_id;
    };

    auto result = findRecordInHeapPage<ObjectPermissionRecord>(object_permissions_table_page_, predicate, ctx);
    if (result.status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND, "Object permission not found");
        return Status::NOT_FOUND;
    }

    // Mark as invalid (soft delete - MGA pattern)
    ObjectPermissionRecord updated_rec = result.record;
    updated_rec.is_valid = 0;

    Status status = updateRecordInHeapPage(object_permissions_table_page_, result.slot_index,
                                          updated_rec, ctx);
    if (status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, status, "Failed to revoke object permission");
        return status;
    }

    // Remove from cache
    {
        std::lock_guard<std::mutex> cache_lock(object_permissions_cache_mutex_);
        auto& perms = object_permissions_cache_[object_id];
        perms.erase(
            std::remove_if(perms.begin(), perms.end(),
                          [&](const ObjectPermissionInfo& p) { return p.grantee_id == grantee_id; }),
            perms.end());
    }

    uint64_t epoch = 0;
    Status epoch_status = bumpSecurityPolicyEpoch(epoch, ctx);
    if (epoch_status != Status::OK)
    {
        return epoch_status;
    }
    {
        uint64_t table_epoch = 0;
        Status table_status = bumpTablePolicyEpoch(object_id, table_epoch, ctx);
        if (table_status != Status::OK)
        {
            return table_status;
        }
    }

    DEBUG_LOG_DB("Revoked object permission on object " << object_id.toString());
    return Status::OK;
}

auto CatalogManager::hasObjectPermission(const ID& object_id, const ID& user_id,
                                        uint32_t required_permissions,
                                        ErrorContext* ctx) -> bool
{
    // WP-3 PERM-2: Get effective roles and groups for user (before acquiring locks)
    std::vector<ID> effective_roles;
    std::vector<ID> effective_groups;
    {
        std::lock_guard<CatalogMutex> lock(mutex_);
        getEffectiveRoles(user_id, effective_roles, ctx);
        getEffectiveGroups(user_id, effective_groups, ctx);
    }

    // Helper to check permissions in a list
    auto checkPermsInList = [&](const std::vector<ObjectPermissionInfo>& perms) -> bool {
        for (const auto& perm : perms)
        {
            // Check if permission grants required access
            if ((perm.permissions & required_permissions) != required_permissions)
                continue;

            // Direct user permission
            if (perm.grantee_type == GranteeType::USER && perm.grantee_id == user_id)
            {
                return true;
            }

            // PUBLIC permission
            if (perm.grantee_type == GranteeType::PUBLIC)
            {
                return true;
            }

            // WP-3 PERM-2: Role-based permission
            if (perm.grantee_type == GranteeType::ROLE)
            {
                for (const auto& role_id : effective_roles)
                {
                    if (perm.grantee_id == role_id)
                    {
                        return true;
                    }
                }
            }

            // WP-3 PERM-2: Group-based permission
            if (perm.grantee_type == GranteeType::GROUP)
            {
                for (const auto& group_id : effective_groups)
                {
                    if (perm.grantee_id == group_id)
                    {
                        return true;
                    }
                }
            }
        }
        return false;
    };

    // Check cache first
    {
        std::lock_guard<std::mutex> cache_lock(object_permissions_cache_mutex_);
        auto it = object_permissions_cache_.find(object_id);
        if (it != object_permissions_cache_.end())
        {
            return checkPermsInList(it->second);
        }
    }

    // Cache miss - load from disk
    std::lock_guard<CatalogMutex> lock(mutex_);

    auto predicate = [&](const ObjectPermissionRecord& rec) {
        return rec.is_valid && rec.object_id == object_id;
    };

    std::vector<ObjectPermissionInfo> perms;
    auto converter = [](const ObjectPermissionRecord& rec, ObjectPermissionInfo& info) {
        info.permission_id = rec.permission_id;
        info.object_id = rec.object_id;
        info.object_type = static_cast<ObjectType>(rec.object_type);
        info.grantee_id = rec.grantee_id;
        info.grantee_type = static_cast<GranteeType>(rec.grantee_type);
        info.permissions = rec.permissions;
        info.grant_option = rec.grant_option != 0;
        info.grantor_id = rec.grantor_id;
        info.created_time = rec.created_time;
    };

    auto filter = predicate;
    Status status = readRecordsToVector<ObjectPermissionRecord, ObjectPermissionInfo>(
        object_permissions_table_page_, perms, filter, converter, ctx);

    if (status == Status::OK && !perms.empty())
    {
        // Populate cache
        {
            std::lock_guard<std::mutex> cache_lock(object_permissions_cache_mutex_);
            object_permissions_cache_[object_id] = perms;
        }

        return checkPermsInList(perms);
    }

    return false;
}

auto CatalogManager::getObjectPermissions(const ID& object_id,
                                         std::vector<ObjectPermissionInfo>& perms_out,
                                         ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);

    perms_out.clear();

    auto filter = [&](const ObjectPermissionRecord& rec) {
        return rec.is_valid && rec.object_id == object_id;
    };

    auto converter = [](const ObjectPermissionRecord& rec, ObjectPermissionInfo& info) {
        info.permission_id = rec.permission_id;
        info.object_id = rec.object_id;
        info.object_type = static_cast<ObjectType>(rec.object_type);
        info.grantee_id = rec.grantee_id;
        info.grantee_type = static_cast<GranteeType>(rec.grantee_type);
        info.permissions = rec.permissions;
        info.grant_option = rec.grant_option != 0;
        info.grantor_id = rec.grantor_id;
        info.created_time = rec.created_time;
    };

    return readRecordsToVector<ObjectPermissionRecord, ObjectPermissionInfo>(
        object_permissions_table_page_, perms_out, filter, converter, ctx);
}

// ================================================================================================
// Foreign Key Constraints (ALPHA Phase A - FK Constraints)
// ================================================================================================

auto CatalogManager::createForeignKey(const std::string& fk_name,
                                     const ID& child_table_id,
                                     const ID& parent_table_id,
                                     const std::vector<std::string>& child_columns,
                                     const std::vector<std::string>& parent_columns,
                                     FKAction on_delete,
                                     FKAction on_update,
                                     FKMatchType match_type,
                                     ID& fk_id_out,
                                     bool is_deferrable,
                                     bool initially_deferred,
                                     ErrorContext* ctx) -> Status
{
    // Acquire ALL locks in consistent order to prevent deadlock with dropTable
    // Must use same lock order as dropTable: mutex_, sequence_cache_mutex_, trigger_mutex_,
    // foreign_keys_cache_mutex_, constraints_cache_mutex_, dependency_cache_mutex_
    std::scoped_lock lock(mutex_, sequence_cache_mutex_, trigger_mutex_,
                         foreign_keys_cache_mutex_, constraints_cache_mutex_, dependency_cache_mutex_);

    // Validate inputs
    if (fk_name.empty())
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "Foreign key name cannot be empty");
        return Status::INVALID_ARGUMENT;
    }

    if (child_columns.empty() || parent_columns.empty())
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "Foreign key must have at least one column");
        return Status::INVALID_ARGUMENT;
    }

    if (child_columns.size() != parent_columns.size())
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "Foreign key child and parent column counts must match");
        return Status::INVALID_ARGUMENT;
    }

    // Generate FK ID
    fk_id_out = generateUuidV7();

    // Create FK info
    ForeignKeyInfo fk_info;
    fk_info.fk_id = fk_id_out;
    fk_info.fk_name = fk_name;
    fk_info.child_table_id = child_table_id;
    fk_info.parent_table_id = parent_table_id;
    fk_info.child_columns = child_columns;
    fk_info.parent_columns = parent_columns;
    fk_info.on_delete = on_delete;
    fk_info.on_update = on_update;
    fk_info.match_type = match_type;
    fk_info.is_enabled = true;
    fk_info.is_deferrable = is_deferrable;  // ALPHA Phase 1 - Deferred constraints
    fk_info.initially_deferred = initially_deferred;  // ALPHA Phase 1 - Deferred constraints
    fk_info.created_time = std::chrono::system_clock::now().time_since_epoch().count();

    // Store in cache
    foreign_keys_cache_[fk_id_out] = fk_info;
    table_child_fks_.insert({child_table_id, fk_id_out});
    table_parent_fks_.insert({parent_table_id, fk_id_out});

    // Phase 2: Create dependency links
    // FK is owned by child table (child-side dependency - auto-drop)
    // Use internal version - locks already held
    ID child_dep_id;
    Status dep_status = createDependencyInternal(
        fk_id_out, ObjectType::CONSTRAINT,  // FK is dependent
        child_table_id, ObjectType::TABLE,   // On child table
        DependencyType::AUTO,                // Auto-drop when child table dropped
        child_dep_id,
        ctx
    );
    if (dep_status != Status::OK) {
        // Rollback cache changes
        foreign_keys_cache_.erase(fk_id_out);
        table_child_fks_.erase(child_table_id);
        table_parent_fks_.erase(parent_table_id);
        SET_ERROR_CONTEXT(ctx, dep_status, "Failed to create child dependency for foreign key");
        return dep_status;
    }

    // FK references parent table (parent-side dependency - blocks drop)
    // Use internal version - locks already held
    ID parent_dep_id;
    dep_status = createDependencyInternal(
        fk_id_out, ObjectType::CONSTRAINT,   // FK is dependent
        parent_table_id, ObjectType::TABLE,  // On parent table
        DependencyType::NORMAL,              // Blocks parent table drop
        parent_dep_id,
        ctx
    );
    if (dep_status != Status::OK) {
        // Rollback both dependency and cache changes
        // Use internal version - locks already held
        deleteDependencyInternal(child_dep_id, ctx);
        foreign_keys_cache_.erase(fk_id_out);
        auto child_range = table_child_fks_.equal_range(child_table_id);
        for (auto it = child_range.first; it != child_range.second; ) {
            if (it->second == fk_id_out)
                it = table_child_fks_.erase(it);
            else
                ++it;
        }
        auto parent_range = table_parent_fks_.equal_range(parent_table_id);
        for (auto it = parent_range.first; it != parent_range.second; ) {
            if (it->second == fk_id_out)
                it = table_parent_fks_.erase(it);
            else
                ++it;
        }
        SET_ERROR_CONTEXT(ctx, dep_status, "Failed to create parent dependency for foreign key");
        return dep_status;
    }

    // Store dependency IDs in FK info for cleanup
    fk_info.child_dependency_id = child_dep_id;
    fk_info.parent_dependency_id = parent_dep_id;
    foreign_keys_cache_[fk_id_out] = fk_info;  // Update with dependency IDs

    // Phase D: Persist to disk
    if (foreign_keys_table_page_ != 0)
    {
        ForeignKeyRecord fk_rec;
        memset(&fk_rec, 0, sizeof(ForeignKeyRecord));

        fk_rec.fk_id = fk_id_out;
        strncpy(fk_rec.fk_name, fk_name.c_str(), sizeof(fk_rec.fk_name) - 1);
        fk_rec.child_table_id = child_table_id;
        fk_rec.parent_table_id = parent_table_id;

        // Serialize column vectors to comma-separated strings
        std::string child_cols_str;
        for (size_t i = 0; i < child_columns.size(); ++i)
        {
            if (i > 0) child_cols_str += ",";
            child_cols_str += child_columns[i];
        }
        strncpy(fk_rec.child_columns, child_cols_str.c_str(), sizeof(fk_rec.child_columns) - 1);

        std::string parent_cols_str;
        for (size_t i = 0; i < parent_columns.size(); ++i)
        {
            if (i > 0) parent_cols_str += ",";
            parent_cols_str += parent_columns[i];
        }
        strncpy(fk_rec.parent_columns, parent_cols_str.c_str(), sizeof(fk_rec.parent_columns) - 1);

        fk_rec.on_delete = static_cast<uint8_t>(on_delete);
        fk_rec.on_update = static_cast<uint8_t>(on_update);
        fk_rec.match_type = static_cast<uint8_t>(match_type);
        fk_rec.is_enabled = 1;
        fk_rec.created_time = fk_info.created_time;
        fk_rec.is_valid = 1;

        Status status = writeRecordToHeapPage(foreign_keys_table_page_, fk_rec, ctx);
        if (status != Status::OK)
        {
            // Rollback dependencies first
            // Use internal version - locks already held
            deleteDependencyInternal(child_dep_id, ctx);
            deleteDependencyInternal(parent_dep_id, ctx);

            // Rollback cache changes
            foreign_keys_cache_.erase(fk_id_out);
            auto child_range = table_child_fks_.equal_range(child_table_id);
            for (auto it = child_range.first; it != child_range.second; )
            {
                if (it->second == fk_id_out)
                    it = table_child_fks_.erase(it);
                else
                    ++it;
            }
            auto parent_range = table_parent_fks_.equal_range(parent_table_id);
            for (auto it = parent_range.first; it != parent_range.second; )
            {
                if (it->second == fk_id_out)
                    it = table_parent_fks_.erase(it);
                else
                    ++it;
            }

            SET_ERROR_CONTEXT(ctx, status, "Failed to write foreign key record");
            return status;
        }
    }

    return Status::OK;
}

auto CatalogManager::getForeignKeysForTable(const ID& table_id,
                                           std::vector<ForeignKeyInfo>& fks_out,
                                           ErrorContext* ctx) -> Status
{
    std::lock_guard<std::mutex> lock(foreign_keys_cache_mutex_);

    fks_out.clear();

    // Find all FKs where this table is the child
    auto range = table_child_fks_.equal_range(table_id);
    for (auto it = range.first; it != range.second; ++it)
    {
        auto fk_it = foreign_keys_cache_.find(it->second);
        if (fk_it != foreign_keys_cache_.end())
        {
            fks_out.push_back(fk_it->second);
        }
    }

    return Status::OK;
}

auto CatalogManager::getReferencingForeignKeys(const ID& table_id,
                                              std::vector<ForeignKeyInfo>& fks_out,
                                              ErrorContext* ctx) -> Status
{
    std::lock_guard<std::mutex> lock(foreign_keys_cache_mutex_);

    fks_out.clear();

    // Find all FKs where this table is the parent (referenced table)
    auto range = table_parent_fks_.equal_range(table_id);
    for (auto it = range.first; it != range.second; ++it)
    {
        auto fk_it = foreign_keys_cache_.find(it->second);
        if (fk_it != foreign_keys_cache_.end())
        {
            fks_out.push_back(fk_it->second);
        }
    }

    return Status::OK;
}

auto CatalogManager::getForeignKey(const ID& fk_id,
                                  ForeignKeyInfo& fk_out,
                                  ErrorContext* ctx) -> Status
{
    std::lock_guard<std::mutex> lock(foreign_keys_cache_mutex_);

    auto it = foreign_keys_cache_.find(fk_id);
    if (it == foreign_keys_cache_.end())
    {
        SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND, "Foreign key not found");
        return Status::NOT_FOUND;
    }

    fk_out = it->second;
    return Status::OK;
}

// Internal helper (assumes foreign_keys_cache_mutex_ and dependency_cache_mutex_ already held)
auto CatalogManager::dropForeignKeyInternal(const ID& fk_id,
                                             ErrorContext* ctx) -> Status
{
    // NO LOCK - caller must hold foreign_keys_cache_mutex_ and dependency_cache_mutex_

    auto it = foreign_keys_cache_.find(fk_id);
    if (it == foreign_keys_cache_.end())
    {
        SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND, "Foreign key not found");
        return Status::NOT_FOUND;
    }

    const ForeignKeyInfo& fk = it->second;

    // Phase 2: Delete dependency links using stored IDs (use internal version)
    if (fk.child_dependency_id != ID{}) {
        deleteDependencyInternal(fk.child_dependency_id, ctx);
    }
    if (fk.parent_dependency_id != ID{}) {
        deleteDependencyInternal(fk.parent_dependency_id, ctx);
    }

    // Remove from index maps
    auto child_range = table_child_fks_.equal_range(fk.child_table_id);
    for (auto child_it = child_range.first; child_it != child_range.second; )
    {
        if (child_it->second == fk_id)
        {
            child_it = table_child_fks_.erase(child_it);
        }
        else
        {
            ++child_it;
        }
    }

    auto parent_range = table_parent_fks_.equal_range(fk.parent_table_id);
    for (auto parent_it = parent_range.first; parent_it != parent_range.second; )
    {
        if (parent_it->second == fk_id)
        {
            parent_it = table_parent_fks_.erase(parent_it);
        }
        else
        {
            ++parent_it;
        }
    }

    // Remove from cache
    foreign_keys_cache_.erase(it);

    // Phase D: Mark as invalid on disk
    if (foreign_keys_table_page_ != 0)
    {
        auto predicate = [&fk_id](const ForeignKeyRecord& rec) {
            return rec.is_valid && rec.fk_id == fk_id;
        };

        auto result = findRecordInHeapPage<ForeignKeyRecord>(foreign_keys_table_page_, predicate, ctx);
        if (result.status == Status::OK)
        {
            ForeignKeyRecord updated_rec = result.record;
            updated_rec.is_valid = 0;

            Status status = updateRecordInHeapPage(foreign_keys_table_page_, predicate, updated_rec, ctx);
            if (status != Status::OK)
            {
                SET_ERROR_CONTEXT(ctx, status, "Failed to mark foreign key as invalid on disk");
                return status;
            }
        }
    }

    return Status::OK;
}

auto CatalogManager::dropForeignKey(const ID& fk_id,
                                   ErrorContext* ctx) -> Status
{
    std::scoped_lock lock(foreign_keys_cache_mutex_, dependency_cache_mutex_);
    return dropForeignKeyInternal(fk_id, ctx);
}

auto CatalogManager::setForeignKeyEnabled(const ID& fk_id, bool enabled,
                                         ErrorContext* ctx) -> Status
{
    std::lock_guard<std::mutex> lock(foreign_keys_cache_mutex_);

    auto it = foreign_keys_cache_.find(fk_id);
    if (it == foreign_keys_cache_.end())
    {
        SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND, "Foreign key not found");
        return Status::NOT_FOUND;
    }

    it->second.is_enabled = enabled;

    // Phase D: Update disk
    if (foreign_keys_table_page_ != 0)
    {
        auto predicate = [&fk_id](const ForeignKeyRecord& rec) {
            return rec.is_valid && rec.fk_id == fk_id;
        };

        auto result = findRecordInHeapPage<ForeignKeyRecord>(foreign_keys_table_page_, predicate, ctx);
        if (result.status == Status::OK)
        {
            ForeignKeyRecord updated_rec = result.record;
            updated_rec.is_enabled = enabled ? 1 : 0;

            Status status = updateRecordInHeapPage(foreign_keys_table_page_, predicate, updated_rec, ctx);
            if (status != Status::OK)
            {
                SET_ERROR_CONTEXT(ctx, status, "Failed to update foreign key enabled status on disk");
                return status;
            }
        }
    }

    return Status::OK;
}

// ============================================================================
// Domain dependency checking (Domain CRUD now in DomainManager)
// ============================================================================

// WP-2 CAT-M7: Find columns using a specific domain for DROP DOMAIN dependency check
auto CatalogManager::findColumnsByDomain(const ID& domain_id,
                                         std::vector<std::pair<ID, std::string>>& table_column_out,
                                         ErrorContext* ctx) -> Status
{
    // Note: This function must not hold mutex_ when calling getColumns()
    // since getColumns() also takes mutex_
    table_column_out.clear();

    // Get list of all table IDs first (with lock)
    std::vector<ID> table_ids;
    {
        std::lock_guard<CatalogMutex> lock(mutex_);
        for (const auto& [table_id, table_info] : table_cache_)
        {
            table_ids.push_back(table_id);
        }
    }

    // Iterate through all tables (without holding mutex_)
    for (const auto& table_id : table_ids)
    {
        // Get columns for this table
        std::vector<ColumnInfo> columns;
        Status status = getColumns(table_id, columns, ctx);
        if (status != Status::OK)
        {
            continue;  // Skip tables we can't read
        }

        // Check each column for domain usage
        for (const auto& col : columns)
        {
            if (col.domain_id == domain_id)
            {
                table_column_out.push_back({table_id, col.column_name});
            }
        }
    }

    return Status::OK;
}

auto CatalogManager::findChildDomains(const ID& domain_id,
                                      std::vector<DomainInfo>& child_domains_out,
                                      ErrorContext* ctx) -> Status
{
    child_domains_out.clear();

    if (!db_ || !db_->domain_manager())
    {
        return Status::OK;
    }

    std::vector<DomainInfo> domains;
    Status status = db_->domain_manager()->listDomains(ID{}, domains, ctx);
    if (status != Status::OK)
    {
        return status;
    }

    for (const auto& domain : domains)
    {
        if (domain.parent_domain_id == domain_id)
        {
            child_domains_out.push_back(domain);
        }
    }

    return Status::OK;
}

auto CatalogManager::listDomains(const ID& schema_id,
                                 std::vector<DomainInfo>& domains_out,
                                 ErrorContext* ctx) -> Status
{
    domains_out.clear();

    if (!db_ || !db_->domain_manager())
    {
        return Status::OK;
    }

    return db_->domain_manager()->listDomains(schema_id, domains_out, ctx);
}

// Domain lookup wrapper - delegates to DomainManager
auto CatalogManager::getDomainByName(const ID& schema_id, const std::string& domain_name,
                                     DomainInfo& info_out, ErrorContext* ctx) -> Status
{
    return db_->domain_manager()->getDomain(schema_id, domain_name, info_out, ctx);
}

auto CatalogManager::getDomainById(const ID& domain_id,
                                   DomainInfo& info_out, ErrorContext* ctx) -> Status
{
    return db_->domain_manager()->getDomain(domain_id, info_out, ctx);
}

// ============================================================================
// UDR CRUD Operations (Phase A - Catalog Cleanup)
// ============================================================================

auto CatalogManager::createUDR(const ID& schema_id, const std::string& udr_name,
                               const std::string& library_path, const std::string& entry_point,
                               UDRType udr_type, const std::string& signature,
                               ID& udr_id_out, ErrorContext* ctx) -> Status
{
    std::unique_lock<CatalogMutex> lock(mutex_);

    // Validate schema exists
    if (schema_cache_.find(schema_id) == schema_cache_.end())
    {
        SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND, "Schema not found");
        return Status::NOT_FOUND;
    }

    // Validate UDR name
    Status status = UTF8Utils::validateStorageCapacity(udr_name,
        CatalogConstants::MAX_IDENTIFIER_CHARS, CatalogConstants::MAX_IDENTIFIER_BYTES);
    if (status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, status, "UDR name too long or invalid UTF-8");
        return status;
    }

    // Check if UDR already exists
    UDRInfo existing;
    lock.unlock();
    status = getUDRByName(schema_id, udr_name, existing, ctx);
    lock.lock();
    if (status == Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, Status::FILE_EXISTS, "UDR already exists");
        return Status::FILE_EXISTS;
    }

    // Generate new UDR ID
    udr_id_out = generateUuidV7();

    // Create UDR record
    UDRRecord udr_rec;
    memset(&udr_rec, 0, sizeof(UDRRecord));
    udr_rec.udr_id = udr_id_out;
    udr_rec.schema_id = schema_id;

    std::string truncated = UTF8Utils::truncateToBytes(udr_name, sizeof(udr_rec.udr_name));
    strncpy(udr_rec.udr_name, truncated.c_str(), sizeof(udr_rec.udr_name) - 1);

    truncated = UTF8Utils::truncateToBytes(library_path, sizeof(udr_rec.library_path));
    strncpy(udr_rec.library_path, truncated.c_str(), sizeof(udr_rec.library_path) - 1);

    truncated = UTF8Utils::truncateToBytes(entry_point, sizeof(udr_rec.entry_point));
    strncpy(udr_rec.entry_point, truncated.c_str(), sizeof(udr_rec.entry_point) - 1);

    udr_rec.owner_id = getSystemUserIdUnlocked(ctx);
    if (isZeroUuidLocal(udr_rec.owner_id))
    {
        return ctx ? ctx->code : Status::PAGE_CORRUPT;
    }
    udr_rec.udr_type = static_cast<uint8_t>(udr_type);
    udr_rec.created_time = std::chrono::system_clock::now().time_since_epoch().count();
    udr_rec.last_modified_time = udr_rec.created_time;
    udr_rec.is_valid = 1;

    // Store signature in TOAST
    uint64_t xmin = 0;
    if (!signature.empty())
    {
        status = storeStringInToast(signature, xmin, udr_rec.signature_oid, ctx);
        if (status != Status::OK) return status;
    }

    // Write to disk
    status = writeRecordToHeapPage(udr_table_page_, udr_rec, ctx);
    if (status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, status, "Failed to write UDR record");
        return status;
    }

    return Status::OK;
}

auto CatalogManager::getUDR(const ID& udr_id, UDRInfo& info_out, ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);

    auto predicate = [&udr_id](const UDRRecord& rec) {
        return rec.udr_id == udr_id && rec.is_valid == 1;
    };

    auto result = findRecordInHeapPage<UDRRecord>(udr_table_page_, predicate, ctx);
    if (result.status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND, "UDR not found");
        return Status::NOT_FOUND;
    }

    info_out.udr_id = result.record.udr_id;
    info_out.schema_id = result.record.schema_id;
    info_out.udr_name = std::string(result.record.udr_name);
    info_out.name_is_delimited = result.record.name_is_delimited != 0;
    info_out.owner_id = result.record.owner_id;
    info_out.library_path = std::string(result.record.library_path);
    info_out.entry_point = std::string(result.record.entry_point);
    info_out.udr_type = static_cast<UDRType>(result.record.udr_type);
    info_out.created_time = result.record.created_time;
    info_out.last_modified_time = result.record.last_modified_time;

    uint64_t xmin = 0;
    if (!isZeroUuidLocal(result.record.signature_oid))
    {
        loadStringFromToast(result.record.signature_oid, xmin, info_out.signature, ctx);
    }

    return Status::OK;
}

auto CatalogManager::getUDRByName(const ID& schema_id, const std::string& udr_name,
                                  UDRInfo& info_out, ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);

    auto predicate = [&schema_id, &udr_name](const UDRRecord& rec) {
        return rec.schema_id == schema_id &&
               IdentifierUtils::namesMatch(udr_name, false /*search_delimited*/,
                                           rec.udr_name,
                                           rec.name_is_delimited != 0) &&
               rec.is_valid == 1;
    };

    auto result = findRecordInHeapPage<UDRRecord>(udr_table_page_, predicate, ctx);
    if (result.status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND, "UDR not found");
        return Status::NOT_FOUND;
    }

    info_out.udr_id = result.record.udr_id;
    info_out.schema_id = result.record.schema_id;
    info_out.udr_name = std::string(result.record.udr_name);
    info_out.name_is_delimited = result.record.name_is_delimited != 0;
    info_out.owner_id = result.record.owner_id;
    info_out.library_path = std::string(result.record.library_path);
    info_out.entry_point = std::string(result.record.entry_point);
    info_out.udr_type = static_cast<UDRType>(result.record.udr_type);
    info_out.created_time = result.record.created_time;
    info_out.last_modified_time = result.record.last_modified_time;

    uint64_t xmin = 0;
    if (!isZeroUuidLocal(result.record.signature_oid))
    {
        loadStringFromToast(result.record.signature_oid, xmin, info_out.signature, ctx);
    }

    return Status::OK;
}

auto CatalogManager::updateUDR(const ID& udr_id,
                               const std::optional<std::string>& new_library_path,
                               const std::optional<std::string>& new_entry_point,
                               const std::optional<std::string>& new_signature,
                               ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);

    BufferPool *bp = db_->buffer_pool();
    void *page_data;
    Status status = bp->pinPage(udr_table_page_, &page_data, ctx);
    if (status != Status::OK) return status;

    HeapPage heap_page(static_cast<uint8_t *>(page_data), db_->page_size());
    uint16_t item_count = heap_page.getItemCount();
    bool found = false;
    auto *mutable_page_data = static_cast<uint8_t *>(page_data);

    for (uint16_t i = 0; i < item_count; ++i)
    {
        const uint8_t *tuple_data;
        uint32_t tuple_size;
        if (heap_page.getTuple(i, &tuple_data, &tuple_size, ctx) == Status::OK)
        {
            if (tuple_size >= sizeof(TupleHeader) + sizeof(UDRRecord))
            {
                const ptrdiff_t offset = tuple_data - static_cast<const uint8_t *>(page_data);
                auto *record = reinterpret_cast<UDRRecord *>(
                    mutable_page_data + offset + sizeof(TupleHeader));

                if (record->udr_id == udr_id && record->is_valid == 1)
                {
                    if (new_library_path.has_value())
                    {
                        std::string truncated = UTF8Utils::truncateToBytes(
                            new_library_path.value(), sizeof(record->library_path));
                        memset(record->library_path, 0, sizeof(record->library_path));
                        strncpy(record->library_path, truncated.c_str(),
                                sizeof(record->library_path) - 1);
                    }
                    if (new_entry_point.has_value())
                    {
                        std::string truncated = UTF8Utils::truncateToBytes(
                            new_entry_point.value(), sizeof(record->entry_point));
                        memset(record->entry_point, 0, sizeof(record->entry_point));
                        strncpy(record->entry_point, truncated.c_str(),
                                sizeof(record->entry_point) - 1);
                    }
                    if (new_signature.has_value())
                    {
                        uint64_t xmin = 0;
                        storeStringInToast(new_signature.value(), xmin, record->signature_oid, ctx);
                    }
                    record->last_modified_time = std::chrono::system_clock::now().time_since_epoch().count();
                    found = true;
                    break;
                }
            }
        }
    }

    bp->unpinPage(udr_table_page_, found, ctx);
    return found ? Status::OK : Status::NOT_FOUND;
}

auto CatalogManager::dropUDR(const ID& udr_id, bool cascade, ErrorContext* ctx) -> Status
{
    UDRInfo existing;
    Status status = getUDR(udr_id, existing, ctx);
    if (status != Status::OK) {
        return status;
    }

    std::vector<DependencyInfo> deps;
    status = getDependents(udr_id, deps, ctx);
    if (status != Status::OK) {
        return status;
    }

    if (!deps.empty()) {
        std::vector<DependencyName> resolved;
        resolveDependencyNames(deps, resolved, ctx);
        std::string error_msg = buildDependencyErrorMessage(
            existing.udr_name, ObjectType::UDR, resolved);
        SET_ERROR_CONTEXT(ctx, Status::CONSTRAINT_VIOLATION, error_msg.c_str());
        return Status::CONSTRAINT_VIOLATION;
    }

    std::lock_guard<CatalogMutex> lock(mutex_);

    BufferPool *bp = db_->buffer_pool();
    void *page_data;
    status = bp->pinPage(udr_table_page_, &page_data, ctx);
    if (status != Status::OK) return status;

    HeapPage heap_page(static_cast<uint8_t *>(page_data), db_->page_size());
    uint16_t item_count = heap_page.getItemCount();
    bool found = false;
    auto *mutable_page_data = static_cast<uint8_t *>(page_data);

    for (uint16_t i = 0; i < item_count; ++i)
    {
        const uint8_t *tuple_data;
        uint32_t tuple_size;
        if (heap_page.getTuple(i, &tuple_data, &tuple_size, ctx) == Status::OK)
        {
            if (tuple_size >= sizeof(TupleHeader) + sizeof(UDRRecord))
            {
                const ptrdiff_t offset = tuple_data - static_cast<const uint8_t *>(page_data);
                auto *record = reinterpret_cast<UDRRecord *>(
                    mutable_page_data + offset + sizeof(TupleHeader));

                if (record->udr_id == udr_id && record->is_valid == 1)
                {
                    record->is_valid = 0;
                    found = true;
                    break;
                }
            }
        }
    }

    bp->unpinPage(udr_table_page_, found, ctx);
    if (!found) {
        SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND, "UDR not found");
        return Status::NOT_FOUND;
    }

    status = clearDependenciesFor(udr_id, ctx);
    if (status != Status::OK) {
        LOG_ERROR(CATALOG, "Failed to clear dependencies for UDR");
    }

    return Status::OK;
}

auto CatalogManager::listUDRs(const ID& schema_id, std::vector<UDRInfo>& udrs_out,
                              ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    udrs_out.clear();

    auto filter = [&schema_id](const UDRRecord& rec) {
        return rec.schema_id == schema_id && rec.is_valid == 1;
    };
    auto converter = [this, ctx](const UDRRecord& rec, UDRInfo& info) {
        info.udr_id = rec.udr_id;
        info.schema_id = rec.schema_id;
        info.udr_name = std::string(rec.udr_name);
        info.name_is_delimited = rec.name_is_delimited != 0;
        info.owner_id = rec.owner_id;
        info.library_path = std::string(rec.library_path);
        info.entry_point = std::string(rec.entry_point);
        info.udr_type = static_cast<UDRType>(rec.udr_type);
        info.created_time = rec.created_time;
        info.last_modified_time = rec.last_modified_time;
        uint64_t xmin = 0;
        if (!isZeroUuidLocal(rec.signature_oid))
            loadStringFromToast(rec.signature_oid, xmin, info.signature, ctx);
    };

    return readRecordsToVector<UDRRecord, UDRInfo>(udr_table_page_, udrs_out, filter, converter, ctx);
}

// ============================================================================
// Package CRUD Operations (Phase A - Catalog Cleanup)
// ============================================================================

auto CatalogManager::createPackage(const ID& schema_id, const std::string& package_name,
                                   const std::string& package_header, const std::string& package_body,
                                   ID& package_id_out, ErrorContext* ctx) -> Status
{
    std::unique_lock<CatalogMutex> lock(mutex_);

    if (schema_cache_.find(schema_id) == schema_cache_.end())
    {
        SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND, "Schema not found");
        return Status::NOT_FOUND;
    }

    Status status = UTF8Utils::validateStorageCapacity(package_name,
        CatalogConstants::MAX_IDENTIFIER_CHARS, CatalogConstants::MAX_IDENTIFIER_BYTES);
    if (status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, status, "Package name too long or invalid UTF-8");
        return status;
    }

    PackageInfo existing;
    lock.unlock();
    status = getPackageByName(schema_id, package_name, existing, ctx);
    lock.lock();
    if (status == Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, Status::FILE_EXISTS, "Package already exists");
        return Status::FILE_EXISTS;
    }

    package_id_out = generateUuidV7();

    PackageRecord pkg_rec;
    memset(&pkg_rec, 0, sizeof(PackageRecord));
    pkg_rec.package_id = package_id_out;
    pkg_rec.schema_id = schema_id;

    std::string truncated = UTF8Utils::truncateToBytes(package_name, sizeof(pkg_rec.package_name));
    strncpy(pkg_rec.package_name, truncated.c_str(), sizeof(pkg_rec.package_name) - 1);

    pkg_rec.owner_id = getSystemUserIdUnlocked(ctx);
    if (isZeroUuidLocal(pkg_rec.owner_id))
    {
        return ctx ? ctx->code : Status::PAGE_CORRUPT;
    }
    pkg_rec.created_time = std::chrono::system_clock::now().time_since_epoch().count();
    pkg_rec.last_modified_time = pkg_rec.created_time;
    pkg_rec.is_valid = 1;

    uint64_t xmin = 0;
    if (!package_header.empty())
    {
        status = storeStringInToast(package_header, xmin, pkg_rec.package_header_oid, ctx);
        if (status != Status::OK) return status;
    }
    if (!package_body.empty())
    {
        status = storeStringInToast(package_body, xmin, pkg_rec.package_body_oid, ctx);
        if (status != Status::OK) return status;
    }

    status = writeRecordToHeapPage(packages_table_page_, pkg_rec, ctx);
    if (status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, status, "Failed to write package record");
        return status;
    }

    return Status::OK;
}

auto CatalogManager::getPackage(const ID& package_id, PackageInfo& info_out, ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);

    auto predicate = [&package_id](const PackageRecord& rec) {
        return rec.package_id == package_id && rec.is_valid == 1;
    };

    auto result = findRecordInHeapPage<PackageRecord>(packages_table_page_, predicate, ctx);
    if (result.status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND, "Package not found");
        return Status::NOT_FOUND;
    }

    info_out.package_id = result.record.package_id;
    info_out.schema_id = result.record.schema_id;
    info_out.package_name = std::string(result.record.package_name);
    info_out.name_is_delimited = result.record.name_is_delimited != 0;
    info_out.owner_id = result.record.owner_id;
    info_out.created_time = result.record.created_time;
    info_out.last_modified_time = result.record.last_modified_time;

    uint64_t xmin = 0;
    if (!isZeroUuidLocal(result.record.package_header_oid))
        loadStringFromToast(result.record.package_header_oid, xmin, info_out.package_header, ctx);
    if (!isZeroUuidLocal(result.record.package_body_oid))
        loadStringFromToast(result.record.package_body_oid, xmin, info_out.package_body, ctx);

    return Status::OK;
}

auto CatalogManager::getPackageByName(const ID& schema_id, const std::string& package_name,
                                      PackageInfo& info_out, ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);

    auto predicate = [&schema_id, &package_name](const PackageRecord& rec) {
        return rec.schema_id == schema_id &&
               IdentifierUtils::namesMatch(package_name, false /*search_delimited*/,
                                           rec.package_name,
                                           rec.name_is_delimited != 0) &&
               rec.is_valid == 1;
    };

    auto result = findRecordInHeapPage<PackageRecord>(packages_table_page_, predicate, ctx);
    if (result.status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND, "Package not found");
        return Status::NOT_FOUND;
    }

    info_out.package_id = result.record.package_id;
    info_out.schema_id = result.record.schema_id;
    info_out.package_name = std::string(result.record.package_name);
    info_out.name_is_delimited = result.record.name_is_delimited != 0;
    info_out.owner_id = result.record.owner_id;
    info_out.created_time = result.record.created_time;
    info_out.last_modified_time = result.record.last_modified_time;

    uint64_t xmin = 0;
    if (!isZeroUuidLocal(result.record.package_header_oid))
        loadStringFromToast(result.record.package_header_oid, xmin, info_out.package_header, ctx);
    if (!isZeroUuidLocal(result.record.package_body_oid))
        loadStringFromToast(result.record.package_body_oid, xmin, info_out.package_body, ctx);

    return Status::OK;
}

auto CatalogManager::updatePackage(const ID& package_id,
                                   const std::optional<std::string>& new_header,
                                   const std::optional<std::string>& new_body,
                                   ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);

    BufferPool *bp = db_->buffer_pool();
    void *page_data;
    Status status = bp->pinPage(packages_table_page_, &page_data, ctx);
    if (status != Status::OK) return status;

    HeapPage heap_page(static_cast<uint8_t *>(page_data), db_->page_size());
    uint16_t item_count = heap_page.getItemCount();
    bool found = false;
    auto *mutable_page_data = static_cast<uint8_t *>(page_data);

    for (uint16_t i = 0; i < item_count; ++i)
    {
        const uint8_t *tuple_data;
        uint32_t tuple_size;
        if (heap_page.getTuple(i, &tuple_data, &tuple_size, ctx) == Status::OK)
        {
            if (tuple_size >= sizeof(TupleHeader) + sizeof(PackageRecord))
            {
                const ptrdiff_t offset = tuple_data - static_cast<const uint8_t *>(page_data);
                auto *record = reinterpret_cast<PackageRecord *>(
                    mutable_page_data + offset + sizeof(TupleHeader));

                if (record->package_id == package_id && record->is_valid == 1)
                {
                    uint64_t xmin = 0;
                    if (new_header.has_value())
                        storeStringInToast(new_header.value(), xmin, record->package_header_oid, ctx);
                    if (new_body.has_value())
                        storeStringInToast(new_body.value(), xmin, record->package_body_oid, ctx);
                    record->last_modified_time = std::chrono::system_clock::now().time_since_epoch().count();
                    found = true;
                    break;
                }
            }
        }
    }

    bp->unpinPage(packages_table_page_, found, ctx);
    return found ? Status::OK : Status::NOT_FOUND;
}

auto CatalogManager::dropPackage(const ID& package_id, bool cascade, ErrorContext* ctx) -> Status
{
    PackageInfo existing;
    Status status = getPackage(package_id, existing, ctx);
    if (status != Status::OK) {
        return status;
    }

    std::vector<DependencyInfo> deps;
    status = getDependents(package_id, deps, ctx);
    if (status != Status::OK) {
        return status;
    }

    if (!deps.empty()) {
        std::vector<DependencyName> resolved;
        resolveDependencyNames(deps, resolved, ctx);
        std::string error_msg = buildDependencyErrorMessage(
            existing.package_name, ObjectType::PACKAGE, resolved);
        SET_ERROR_CONTEXT(ctx, Status::CONSTRAINT_VIOLATION, error_msg.c_str());
        return Status::CONSTRAINT_VIOLATION;
    }

    std::lock_guard<CatalogMutex> lock(mutex_);

    BufferPool *bp = db_->buffer_pool();
    void *page_data;
    status = bp->pinPage(packages_table_page_, &page_data, ctx);
    if (status != Status::OK) return status;

    HeapPage heap_page(static_cast<uint8_t *>(page_data), db_->page_size());
    uint16_t item_count = heap_page.getItemCount();
    bool found = false;
    auto *mutable_page_data = static_cast<uint8_t *>(page_data);

    for (uint16_t i = 0; i < item_count; ++i)
    {
        const uint8_t *tuple_data;
        uint32_t tuple_size;
        if (heap_page.getTuple(i, &tuple_data, &tuple_size, ctx) == Status::OK)
        {
            if (tuple_size >= sizeof(TupleHeader) + sizeof(PackageRecord))
            {
                const ptrdiff_t offset = tuple_data - static_cast<const uint8_t *>(page_data);
                auto *record = reinterpret_cast<PackageRecord *>(
                    mutable_page_data + offset + sizeof(TupleHeader));

                if (record->package_id == package_id && record->is_valid == 1)
                {
                    record->is_valid = 0;
                    found = true;
                    break;
                }
            }
        }
    }

    bp->unpinPage(packages_table_page_, found, ctx);
    if (!found) {
        SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND, "Package not found");
        return Status::NOT_FOUND;
    }

    status = clearDependenciesFor(package_id, ctx);
    if (status != Status::OK) {
        LOG_ERROR(CATALOG, "Failed to clear dependencies for package");
    }

    return Status::OK;
}

