// ============================================================================
// Exception CRUD Operations (Phase 3 - Stored Code Tables)
// ============================================================================

Status CatalogManager::createException(const ID& schema_id, const std::string& name,
                                       const std::string& message, ID& exception_id_out,
                                       ErrorContext* ctx)
{
    std::lock_guard<CatalogMutex> lock(mutex_);

    if (schema_cache_.find(schema_id) == schema_cache_.end())
    {
        SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND, "Schema not found");
        return Status::NOT_FOUND;
    }

    exception_id_out = generateUuidV7();

    ExceptionRecord rec{};
    rec.exception_id = exception_id_out;
    rec.schema_id = schema_id;
    std::string truncated = UTF8Utils::truncateToBytes(name, sizeof(rec.name));
    strncpy(rec.name, truncated.c_str(), sizeof(rec.name) - 1);
    rec.owner_id = getSystemUserIdUnlocked(ctx);
    if (isZeroUuidLocal(rec.owner_id))
    {
        return ctx ? ctx->code : Status::PAGE_CORRUPT;
    }
    rec.created_time = std::chrono::system_clock::now().time_since_epoch().count();
    rec.last_modified_time = rec.created_time;
    rec.is_valid = 1;
    rec.name_is_delimited = 0;

    // Store message in TOAST
    if (!message.empty()) {
        uint64_t xmin = 0;
        Status st = storeStringInToast(message, xmin, rec.message_oid, ctx);
        if (st != Status::OK) return st;
    }

    Status st = writeRecordToHeapPage(exceptions_table_page_, rec, ctx);
    if (st != Status::OK) {
        SET_ERROR_CONTEXT(ctx, st, "Failed to write exception record");
        return st;
    }

    exception_cache_[exception_id_out] = {
        rec.exception_id,
        rec.schema_id,
        std::string(rec.name),
        rec.name_is_delimited != 0,
        message,
        rec.owner_id,
        rec.created_time,
        rec.last_modified_time,
        true
    };

    return Status::OK;
}

Status CatalogManager::getException(const ID& exception_id, ExceptionInfo& info_out,
                                    ErrorContext* ctx)
{
    std::lock_guard<CatalogMutex> lock(mutex_);

    auto it = exception_cache_.find(exception_id);
    if (it != exception_cache_.end()) {
        info_out = it->second;
        return Status::OK;
    }

    auto predicate = [&exception_id](const ExceptionRecord& rec) {
        return rec.exception_id == exception_id && rec.is_valid == 1;
    };

    auto result = findRecordInHeapPage<ExceptionRecord>(exceptions_table_page_, predicate, ctx);
    if (result.status != Status::OK) {
        SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND, "Exception not found");
        return Status::NOT_FOUND;
    }

    ExceptionInfo info{};
    info.exception_id = result.record.exception_id;
    info.schema_id = result.record.schema_id;
    info.name = std::string(result.record.name);
    info.name_is_delimited = result.record.name_is_delimited != 0;
    info.owner_id = result.record.owner_id;
    info.created_time = result.record.created_time;
    info.last_modified_time = result.record.last_modified_time;
    info.is_valid = (result.record.is_valid == 1);
    if (!isZeroUuidLocal(result.record.message_oid)) {
        uint64_t xmin = 0;
        loadStringFromToast(result.record.message_oid, xmin, info.message, ctx);
    }

    exception_cache_[exception_id] = info;
    info_out = info;
    return Status::OK;
}

Status CatalogManager::getExceptionByName(const ID& schema_id, const std::string& name,
                                          ExceptionInfo& info_out, ErrorContext* ctx)
{
    std::lock_guard<CatalogMutex> lock(mutex_);

    auto predicate = [&schema_id, &name](const ExceptionRecord& rec) {
        return rec.schema_id == schema_id &&
               IdentifierUtils::namesMatch(name, false /*search_delimited*/,
                                           rec.name,
                                           rec.name_is_delimited != 0) &&
               rec.is_valid == 1;
    };

    auto result = findRecordInHeapPage<ExceptionRecord>(exceptions_table_page_, predicate, ctx);
    if (result.status != Status::OK) {
        SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND, "Exception not found");
        return Status::NOT_FOUND;
    }

    return getException(result.record.exception_id, info_out, ctx);
}

Status CatalogManager::dropException(const ID& exception_id, bool /*cascade*/, ErrorContext* ctx)
{
    ExceptionInfo existing;
    Status status = getException(exception_id, existing, ctx);
    if (status != Status::OK) {
        return status;
    }

    std::vector<DependencyInfo> deps;
    status = getDependents(exception_id, deps, ctx);
    if (status != Status::OK) {
        return status;
    }

    if (!deps.empty()) {
        std::vector<DependencyName> resolved;
        resolveDependencyNames(deps, resolved, ctx);
        std::string error_msg = buildDependencyErrorMessage(
            existing.name, ObjectType::EXCEPTION, resolved);
        SET_ERROR_CONTEXT(ctx, Status::CONSTRAINT_VIOLATION, error_msg.c_str());
        return Status::CONSTRAINT_VIOLATION;
    }

    std::lock_guard<CatalogMutex> lock(mutex_);

    BufferPool* bp = db_->buffer_pool();
    void* page_data;
    status = bp->pinPage(exceptions_table_page_, &page_data, ctx);
    if (status != Status::OK) return status;

    HeapPage heap_page(static_cast<uint8_t*>(page_data), db_->page_size());
    uint16_t item_count = heap_page.getItemCount();
    bool found = false;
    auto* mutable_page_data = static_cast<uint8_t*>(page_data);

    for (uint16_t i = 0; i < item_count; ++i)
    {
        const uint8_t* tuple_data;
        uint32_t tuple_size;
        if (heap_page.getTuple(i, &tuple_data, &tuple_size, ctx) == Status::OK)
        {
            if (tuple_size >= sizeof(TupleHeader) + sizeof(ExceptionRecord))
            {
                const ptrdiff_t offset = tuple_data - static_cast<const uint8_t*>(page_data);
                auto* record = reinterpret_cast<ExceptionRecord*>(mutable_page_data + offset + sizeof(TupleHeader));

                if (record->exception_id == exception_id && record->is_valid == 1)
                {
                    record->is_valid = 0;
                    found = true;
                    break;
                }
            }
        }
    }

    bp->unpinPage(exceptions_table_page_, found, ctx);

    if (!found) {
        SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND, "Exception not found");
        return Status::NOT_FOUND;
    }

    exception_cache_.erase(exception_id);
    status = clearDependenciesFor(exception_id, ctx);
    if (status != Status::OK) {
        LOG_ERROR(CATALOG, "Failed to clear dependencies for exception");
    }
    return Status::OK;
}

Status CatalogManager::listExceptions(const ID& schema_id, std::vector<ExceptionInfo>& exceptions_out,
                                      ErrorContext* ctx)
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    exceptions_out.clear();

    auto filter = [&schema_id](const ExceptionRecord& rec) {
        return rec.schema_id == schema_id && rec.is_valid == 1;
    };
    auto converter = [this, ctx](const ExceptionRecord& rec, ExceptionInfo& info) {
        info.exception_id = rec.exception_id;
        info.schema_id = rec.schema_id;
        info.name = std::string(rec.name);
        info.name_is_delimited = rec.name_is_delimited != 0;
        info.owner_id = rec.owner_id;
        info.created_time = rec.created_time;
        info.last_modified_time = rec.last_modified_time;
        info.is_valid = (rec.is_valid == 1);
        if (!isZeroUuidLocal(rec.message_oid)) {
            uint64_t xmin = 0;
            loadStringFromToast(rec.message_oid, xmin, info.message, ctx);
        }
    };

    return readRecordsToVector<ExceptionRecord, ExceptionInfo>(exceptions_table_page_, exceptions_out,
                                                               filter, converter, ctx);
}

// Unified object lookup
Status CatalogManager::lookupObject(const ID& schema_id, const std::string& name,
                                    ObjectLookup& out, ErrorContext* ctx)
{
    // Try function
    {
        std::lock_guard<std::mutex> lock(psql_mutex_);
        for (const auto& [func_name, fn] : functions_) {
            if (fn.schema_id != schema_id) {
                continue;
            }
            if (IdentifierUtils::namesMatch(name, false /*search_delimited*/,
                                            fn.name, fn.name_is_delimited)) {
                out.object_id = fn.function_id;
                out.type = ObjectType::FUNCTION;
                out.schema_id = fn.schema_id;
                out.name = fn.name;
                return Status::OK;
            }
        }
    }

    // Procedure
    {
        std::lock_guard<std::mutex> lock(psql_mutex_);
        for (const auto& [proc_name, pr] : procedures_) {
            if (pr.schema_id != schema_id) {
                continue;
            }
            if (IdentifierUtils::namesMatch(name, false /*search_delimited*/,
                                            pr.name, pr.name_is_delimited)) {
                out.object_id = pr.procedure_id;
                out.type = ObjectType::PROCEDURE;
                out.schema_id = pr.schema_id;
                out.name = pr.name;
                return Status::OK;
            }
        }
    }

    // Package
    PackageInfo pkg;
    if (getPackageByName(schema_id, name, pkg, ctx) == Status::OK) {
        out.object_id = pkg.package_id;
        out.type = ObjectType::PACKAGE;
        out.schema_id = schema_id;
        out.name = name;
        return Status::OK;
    }

    // UDR
    UDRInfo ui;
    if (getUDRByName(schema_id, name, ui, ctx) == Status::OK) {
        out.object_id = ui.udr_id;
        out.type = ObjectType::UDR;
        out.schema_id = schema_id;
        out.name = name;
        return Status::OK;
    }

    // Exception
    ExceptionInfo ex;
    if (getExceptionByName(schema_id, name, ex, ctx) == Status::OK) {
        out.object_id = ex.exception_id;
        out.type = ObjectType::EXCEPTION;
        out.schema_id = schema_id;
        out.name = name;
        return Status::OK;
    }

    // Sequence
    ID seq_id;
    if (getSequenceIdByName(schema_id, name, seq_id, ctx) == Status::OK) {
        out.object_id = seq_id;
        out.type = ObjectType::SEQUENCE;
        out.schema_id = schema_id;
        out.name = name;
        return Status::OK;
    }

    return Status::NOT_FOUND;
}

// ============================================================================
// Canonical Type Catalog CRUD Operations (CAT-010)
// ============================================================================

auto CatalogManager::upsertTypeCatalogEntry(const TypeCatalogInfo& info,
                                            ID& type_id_out,
                                            ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);

    if (isZeroUuidLocal(info.schema_id))
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "type.schema_uuid is required");
        return Status::INVALID_ARGUMENT;
    }
    if (info.type_name.empty())
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "type.type_name is required");
        return Status::INVALID_ARGUMENT;
    }

    Status status = UTF8Utils::validateStorageCapacity(
        info.type_name, CatalogConstants::MAX_IDENTIFIER_CHARS, CatalogConstants::MAX_IDENTIFIER_BYTES, ctx);
    if (status != Status::OK)
    {
        return status;
    }

    ID type_id = info.type_id;
    if (isZeroUuidLocal(type_id))
    {
        type_id = generateUuidV7();
    }
    type_id_out = type_id;

    const std::string name_folded = canonicalIdentifierForLookup(info.type_name);
    auto unique_predicate = [&info, &name_folded, &type_id](const TypeRecord& rec) {
        if (rec.is_valid != 1 || rec.schema_id != info.schema_id || rec.type_id == type_id)
        {
            return false;
        }
        return canonicalIdentifierForLookup(fixedNameFromBuffer(rec.type_name, sizeof(rec.type_name))) ==
               name_folded;
    };
    auto collision = findRecordInHeapPage<TypeRecord>(type_table_page_, unique_predicate, ctx);
    if (collision.status == Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, Status::CONSTRAINT_VIOLATION,
                          "UNIQUE(type.schema_uuid,type.type_name) violated");
        return Status::CONSTRAINT_VIOLATION;
    }
    if (collision.status != Status::NOT_FOUND)
    {
        return collision.status;
    }

    const uint64_t now = catalogNowTicks();
    TypeRecord rec{};
    rec.type_id = type_id;
    rec.schema_id = info.schema_id;
    std::string truncated = UTF8Utils::truncateToBytes(info.type_name, sizeof(rec.type_name));
    strncpy(rec.type_name, truncated.c_str(), sizeof(rec.type_name) - 1);
    rec.type_kind = static_cast<uint8_t>(info.type_kind);
    rec.base_type_id = info.base_type_id;
    rec.element_type_id = info.element_type_id;
    rec.key_type_id = info.key_type_id;
    rec.value_type_id = info.value_type_id;
    rec.range_subtype_id = info.range_subtype_id;
    rec.is_system = info.is_system ? 1 : 0;
    rec.system_origin = info.system_origin;
    rec.last_modified_time = (info.last_modified_time == 0) ? now : info.last_modified_time;
    rec.is_valid = info.is_valid ? 1 : 0;

    auto existing_predicate = [&type_id](const TypeRecord& row) {
        return row.type_id == type_id && row.is_valid == 1;
    };
    auto existing = findRecordInHeapPage<TypeRecord>(type_table_page_, existing_predicate, ctx);
    if (existing.status == Status::OK)
    {
        rec.created_time = existing.record.created_time;
    }
    else if (existing.status == Status::NOT_FOUND)
    {
        rec.created_time = (info.created_time == 0) ? now : info.created_time;
    }
    else
    {
        return existing.status;
    }

    auto matcher = [&type_id](const TypeRecord& row) {
        return row.type_id == type_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(type_table_page_, matcher, rec, ctx);
}

