auto CatalogManager::listTypeCatalogEntries(const ID& schema_id,
                                            std::vector<TypeCatalogInfo>& types_out,
                                            ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    types_out.clear();

    const bool filter_by_schema = !isZeroUuidLocal(schema_id);
    auto filter = [&schema_id, filter_by_schema](const TypeRecord& rec) {
        if (rec.is_valid != 1)
        {
            return false;
        }
        return !filter_by_schema || rec.schema_id == schema_id;
    };
    auto converter = [](const TypeRecord& rec, TypeCatalogInfo& info) {
        info.type_id = rec.type_id;
        info.schema_id = rec.schema_id;
        info.type_name = fixedNameFromBuffer(rec.type_name, sizeof(rec.type_name));
        info.type_kind = static_cast<TypeKind>(rec.type_kind);
        info.base_type_id = rec.base_type_id;
        info.element_type_id = rec.element_type_id;
        info.key_type_id = rec.key_type_id;
        info.value_type_id = rec.value_type_id;
        info.range_subtype_id = rec.range_subtype_id;
        info.is_system = rec.is_system != 0;
        info.system_origin = rec.system_origin;
        info.created_time = rec.created_time;
        info.last_modified_time = rec.last_modified_time;
        info.is_valid = rec.is_valid == 1;
    };
    return readRecordsToVector<TypeRecord, TypeCatalogInfo>(type_table_page_, types_out, filter, converter, ctx);
}

