auto CatalogManager::upsertTypeIo(const TypeIoInfo& info, ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);

    if (isZeroUuidLocal(info.type_id))
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "type_io.type_uuid is required");
        return Status::INVALID_ARGUMENT;
    }
    if (isZeroUuidLocal(info.input_fn_id) || isZeroUuidLocal(info.output_fn_id))
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT,
                          "type_io requires input_fn_uuid and output_fn_uuid");
        return Status::INVALID_ARGUMENT;
    }

    auto type_predicate = [&info](const TypeRecord& rec) {
        return rec.type_id == info.type_id && rec.is_valid == 1;
    };
    auto type_row = findRecordInHeapPage<TypeRecord>(type_table_page_, type_predicate, ctx);
    if (type_row.status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND, "Referenced type_uuid not found");
        return Status::NOT_FOUND;
    }

    const uint64_t now = catalogNowTicks();
    TypeIoRecord rec{};
    rec.type_id = info.type_id;
    rec.input_fn_id = info.input_fn_id;
    rec.output_fn_id = info.output_fn_id;
    rec.binary_input_fn_id = info.binary_input_fn_id;
    rec.binary_output_fn_id = info.binary_output_fn_id;
    rec.is_valid = info.is_valid ? 1 : 0;
    rec.last_modified_time = (info.last_modified_time == 0) ? now : info.last_modified_time;

    auto existing_predicate = [&info](const TypeIoRecord& row) {
        return row.type_id == info.type_id && row.is_valid == 1;
    };
    auto existing = findRecordInHeapPage<TypeIoRecord>(type_io_table_page_, existing_predicate, ctx);
    if (existing.status == Status::OK)
    {
        rec.created_time = existing.record.created_time;
    }
    else if (existing.status == Status::NOT_FOUND)
    {
        rec.created_time = (info.created_time == 0) ? now : info.created_time;
    }
    else
    {
        return existing.status;
    }

    auto matcher = [&info](const TypeIoRecord& row) {
        return row.type_id == info.type_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(type_io_table_page_, matcher, rec, ctx);
}

