auto CatalogManager::upsertTypeCast(const TypeCastInfo& info, ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);

    if (isZeroUuidLocal(info.source_type_id) || isZeroUuidLocal(info.target_type_id))
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT,
                          "type_cast requires source_type_uuid and target_type_uuid");
        return Status::INVALID_ARGUMENT;
    }
    uint8_t cast_kind_raw = static_cast<uint8_t>(info.cast_kind);
    if (cast_kind_raw > static_cast<uint8_t>(TypeCastKind::BINARY_COMPATIBLE))
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "Invalid type_cast.cast_kind");
        return Status::INVALID_ARGUMENT;
    }

    auto source_predicate = [&info](const TypeRecord& rec) {
        return rec.type_id == info.source_type_id && rec.is_valid == 1;
    };
    auto target_predicate = [&info](const TypeRecord& rec) {
        return rec.type_id == info.target_type_id && rec.is_valid == 1;
    };
    if (findRecordInHeapPage<TypeRecord>(type_table_page_, source_predicate, ctx).status != Status::OK ||
        findRecordInHeapPage<TypeRecord>(type_table_page_, target_predicate, ctx).status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND, "Referenced source or target type not found");
        return Status::NOT_FOUND;
    }

    const uint64_t now = catalogNowTicks();
    TypeCastRecord rec{};
    rec.source_type_id = info.source_type_id;
    rec.target_type_id = info.target_type_id;
    rec.cast_kind = cast_kind_raw;
    rec.is_lossy = info.is_lossy ? 1 : 0;
    rec.cast_fn_id = info.cast_fn_id;
    rec.is_valid = info.is_valid ? 1 : 0;
    rec.last_modified_time = (info.last_modified_time == 0) ? now : info.last_modified_time;

    auto existing_predicate = [&info](const TypeCastRecord& row) {
        return row.source_type_id == info.source_type_id &&
               row.target_type_id == info.target_type_id &&
               row.cast_kind == static_cast<uint8_t>(info.cast_kind) &&
               row.is_valid == 1;
    };
    auto existing = findRecordInHeapPage<TypeCastRecord>(type_casts_table_page_, existing_predicate, ctx);
    if (existing.status == Status::OK)
    {
        rec.created_time = existing.record.created_time;
    }
    else if (existing.status == Status::NOT_FOUND)
    {
        rec.created_time = (info.created_time == 0) ? now : info.created_time;
    }
    else
    {
        return existing.status;
    }

    auto matcher = [&info](const TypeCastRecord& row) {
        return row.source_type_id == info.source_type_id &&
               row.target_type_id == info.target_type_id &&
               row.cast_kind == static_cast<uint8_t>(info.cast_kind) &&
               row.is_valid == 1;
    };
    return updateRecordInHeapPage(type_casts_table_page_, matcher, rec, ctx);
}

auto CatalogManager::getTypeCast(const ID& source_type_id,
                                 const ID& target_type_id,
                                 TypeCastKind cast_kind,
                                 TypeCastInfo& info_out,
                                 ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    auto predicate = [&source_type_id, &target_type_id, cast_kind](const TypeCastRecord& rec) {
        return rec.source_type_id == source_type_id &&
               rec.target_type_id == target_type_id &&
               rec.cast_kind == static_cast<uint8_t>(cast_kind) &&
               rec.is_valid == 1;
    };
    auto result = findRecordInHeapPage<TypeCastRecord>(type_casts_table_page_, predicate, ctx);
    if (result.status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND, "Type cast not found");
        return Status::NOT_FOUND;
    }

    const TypeCastRecord& rec = result.record;
    info_out.source_type_id = rec.source_type_id;
    info_out.target_type_id = rec.target_type_id;
    info_out.cast_kind = static_cast<TypeCastKind>(rec.cast_kind);
    info_out.cast_fn_id = rec.cast_fn_id;
    info_out.is_lossy = rec.is_lossy != 0;
    info_out.created_time = rec.created_time;
    info_out.last_modified_time = rec.last_modified_time;
    info_out.is_valid = rec.is_valid == 1;
    return Status::OK;
}

