auto CatalogManager::upsertTypeTransform(const TypeTransformInfo& info,
                                         ID& transform_id_out,
                                         ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);

    if (isZeroUuidLocal(info.type_id) || isZeroUuidLocal(info.language_id))
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT,
                          "type_transform requires type_uuid and language_uuid");
        return Status::INVALID_ARGUMENT;
    }
    if (isZeroUuidLocal(info.from_sql_proc_id) && isZeroUuidLocal(info.to_sql_proc_id))
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT,
                          "type_transform requires from_sql_proc_uuid or to_sql_proc_uuid");
        return Status::INVALID_ARGUMENT;
    }

    ID transform_id = info.transform_id;
    if (isZeroUuidLocal(transform_id))
    {
        transform_id = generateUuidV7();
    }
    transform_id_out = transform_id;

    auto type_predicate = [&info](const TypeRecord& rec) {
        return rec.type_id == info.type_id && rec.is_valid == 1;
    };
    if (findRecordInHeapPage<TypeRecord>(type_table_page_, type_predicate, ctx).status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND, "Referenced type_uuid not found");
        return Status::NOT_FOUND;
    }

    auto unique_predicate = [&info, &transform_id](const TypeTransformRecord& rec) {
        return rec.is_valid == 1 && rec.type_id == info.type_id &&
               rec.language_id == info.language_id && rec.transform_id != transform_id;
    };
    auto collision = findRecordInHeapPage<TypeTransformRecord>(type_transforms_table_page_, unique_predicate, ctx);
    if (collision.status == Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, Status::CONSTRAINT_VIOLATION,
                          "UNIQUE(type_uuid,language_uuid) violated for type_transform");
        return Status::CONSTRAINT_VIOLATION;
    }
    if (collision.status != Status::NOT_FOUND)
    {
        return collision.status;
    }

    const uint64_t now = catalogNowTicks();
    TypeTransformRecord rec{};
    rec.transform_id = transform_id;
    rec.type_id = info.type_id;
    rec.language_id = info.language_id;
    rec.from_sql_proc_id = info.from_sql_proc_id;
    rec.to_sql_proc_id = info.to_sql_proc_id;
    rec.is_valid = info.is_valid ? 1 : 0;
    rec.last_modified_time = (info.last_modified_time == 0) ? now : info.last_modified_time;

    auto existing_predicate = [&transform_id](const TypeTransformRecord& row) {
        return row.transform_id == transform_id && row.is_valid == 1;
    };
    auto existing = findRecordInHeapPage<TypeTransformRecord>(type_transforms_table_page_, existing_predicate, ctx);
    if (existing.status == Status::OK)
    {
        rec.created_time = existing.record.created_time;
    }
    else if (existing.status == Status::NOT_FOUND)
    {
        rec.created_time = (info.created_time == 0) ? now : info.created_time;
    }
    else
    {
        return existing.status;
    }

    auto matcher = [&transform_id](const TypeTransformRecord& row) {
        return row.transform_id == transform_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(type_transforms_table_page_, matcher, rec, ctx);
}

