auto CatalogManager::upsertEncodingConversion(const EncodingConversionInfo& info,
                                              ID& conversion_id_out,
                                              ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);

    if (info.conversion_name.empty())
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "encoding_conversion.conversion_name is required");
        return Status::INVALID_ARGUMENT;
    }
    if (isZeroUuidLocal(info.source_charset_id) || isZeroUuidLocal(info.target_charset_id) ||
        isZeroUuidLocal(info.conversion_proc_id))
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT,
                          "encoding_conversion source/target charset and conversion_proc are required");
        return Status::INVALID_ARGUMENT;
    }

    Status status = UTF8Utils::validateStorageCapacity(
        info.conversion_name,
        CatalogConstants::MAX_IDENTIFIER_CHARS,
        CatalogConstants::MAX_IDENTIFIER_BYTES,
        ctx);
    if (status != Status::OK)
    {
        return status;
    }

    ID conversion_id = info.conversion_id;
    if (isZeroUuidLocal(conversion_id))
    {
        conversion_id = generateUuidV7();
    }
    conversion_id_out = conversion_id;

    const std::string name_folded = canonicalIdentifierForLookup(info.conversion_name);
    auto name_predicate = [&name_folded, &conversion_id](const EncodingConversionRecord& rec) {
        if (rec.is_valid != 1 || rec.conversion_id == conversion_id)
        {
            return false;
        }
        return canonicalIdentifierForLookup(
            fixedNameFromBuffer(rec.conversion_name, sizeof(rec.conversion_name))) == name_folded;
    };
    auto name_collision = findRecordInHeapPage<EncodingConversionRecord>(
        encoding_conversions_table_page_, name_predicate, ctx);
    if (name_collision.status == Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, Status::CONSTRAINT_VIOLATION,
                          "UNIQUE(encoding_conversion.conversion_name) violated");
        return Status::CONSTRAINT_VIOLATION;
    }
    if (name_collision.status != Status::NOT_FOUND)
    {
        return name_collision.status;
    }

    if (info.is_default)
    {
        auto default_predicate = [&info, &conversion_id](const EncodingConversionRecord& rec) {
            return rec.is_valid == 1 && rec.is_default == 1 &&
                   rec.source_charset_id == info.source_charset_id &&
                   rec.target_charset_id == info.target_charset_id &&
                   rec.conversion_id != conversion_id;
        };
        auto default_collision = findRecordInHeapPage<EncodingConversionRecord>(
            encoding_conversions_table_page_, default_predicate, ctx);
        if (default_collision.status == Status::OK)
        {
            SET_ERROR_CONTEXT(ctx, Status::CONSTRAINT_VIOLATION,
                              "Duplicate default encoding conversion for source/target pair");
            return Status::CONSTRAINT_VIOLATION;
        }
        if (default_collision.status != Status::NOT_FOUND)
        {
            return default_collision.status;
        }
    }

    const uint64_t now = catalogNowTicks();
    EncodingConversionRecord rec{};
    rec.conversion_id = conversion_id;
    std::string truncated = UTF8Utils::truncateToBytes(info.conversion_name, sizeof(rec.conversion_name));
    strncpy(rec.conversion_name, truncated.c_str(), sizeof(rec.conversion_name) - 1);
    rec.source_charset_id = info.source_charset_id;
    rec.target_charset_id = info.target_charset_id;
    rec.conversion_proc_id = info.conversion_proc_id;
    rec.is_default = info.is_default ? 1 : 0;
    rec.is_system = info.is_system ? 1 : 0;
    rec.is_valid = info.is_valid ? 1 : 0;
    rec.last_modified_time = (info.last_modified_time == 0) ? now : info.last_modified_time;

    auto existing_predicate = [&conversion_id](const EncodingConversionRecord& row) {
        return row.conversion_id == conversion_id && row.is_valid == 1;
    };
    auto existing = findRecordInHeapPage<EncodingConversionRecord>(
        encoding_conversions_table_page_, existing_predicate, ctx);
    if (existing.status == Status::OK)
    {
        rec.created_time = existing.record.created_time;
    }
    else if (existing.status == Status::NOT_FOUND)
    {
        rec.created_time = (info.created_time == 0) ? now : info.created_time;
    }
    else
    {
        return existing.status;
    }

    auto matcher = [&conversion_id](const EncodingConversionRecord& row) {
        return row.conversion_id == conversion_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(encoding_conversions_table_page_, matcher, rec, ctx);
}

