auto CatalogManager::upsertDomainParamKey(const DomainParamKeyCatalogInfo& info,
                                          ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (info.param_key_id == 0)
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "domain_param_key.param_key_id is required");
        return Status::INVALID_ARGUMENT;
    }
    if (info.param_name.empty())
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "domain_param_key.param_name is required");
        return Status::INVALID_ARGUMENT;
    }
    if (!isKnownDomainParamType(info.param_type))
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "domain_param_key.param_type is invalid");
        return Status::INVALID_ARGUMENT;
    }

    Status status = UTF8Utils::validateStorageCapacity(
        info.param_name, CatalogConstants::MAX_IDENTIFIER_CHARS, CatalogConstants::MAX_IDENTIFIER_BYTES, ctx);
    if (status != Status::OK)
    {
        return status;
    }

    const std::string folded_name = canonicalIdentifierForLookup(info.param_name);
    auto duplicate_name = [&folded_name, &info](const DomainParamKeyRecord& rec) {
        if (rec.is_valid != 1 || rec.param_key_id == info.param_key_id)
        {
            return false;
        }
        return canonicalIdentifierForLookup(fixedNameFromBuffer(rec.param_name, sizeof(rec.param_name))) ==
               folded_name;
    };
    auto name_collision = findRecordInHeapPage<DomainParamKeyRecord>(
        domain_param_keys_table_page_, duplicate_name, ctx);
    if (name_collision.status == Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, Status::CONSTRAINT_VIOLATION,
                          "UNIQUE(domain_param_key.param_name) violated");
        return Status::CONSTRAINT_VIOLATION;
    }
    if (name_collision.status != Status::NOT_FOUND)
    {
        return name_collision.status;
    }

    const uint64_t now = catalogNowTicks();
    DomainParamKeyRecord rec{};
    rec.param_key_id = info.param_key_id;
    rec.param_type = static_cast<uint8_t>(info.param_type);
    std::string truncated = UTF8Utils::truncateToBytes(info.param_name, sizeof(rec.param_name));
    strncpy(rec.param_name, truncated.c_str(), sizeof(rec.param_name) - 1);
    rec.is_valid = info.is_valid ? 1 : 0;
    rec.last_modified_time = (info.last_modified_time == 0) ? now : info.last_modified_time;

    auto existing_predicate = [&info](const DomainParamKeyRecord& row) {
        return row.param_key_id == info.param_key_id && row.is_valid == 1;
    };
    auto existing = findRecordInHeapPage<DomainParamKeyRecord>(
        domain_param_keys_table_page_, existing_predicate, ctx);
    if (existing.status == Status::OK)
    {
        rec.created_time = existing.record.created_time;
    }
    else if (existing.status == Status::NOT_FOUND)
    {
        rec.created_time = (info.created_time == 0) ? now : info.created_time;
    }
    else
    {
        return existing.status;
    }

    auto matcher = [&info](const DomainParamKeyRecord& row) {
        return row.param_key_id == info.param_key_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(domain_param_keys_table_page_, matcher, rec, ctx);
}

auto CatalogManager::getDomainParamKey(uint16_t param_key_id,
                                       DomainParamKeyCatalogInfo& info_out,
                                       ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    auto predicate = [param_key_id](const DomainParamKeyRecord& rec) {
        return rec.param_key_id == param_key_id && rec.is_valid == 1;
    };
    auto result = findRecordInHeapPage<DomainParamKeyRecord>(domain_param_keys_table_page_, predicate, ctx);
    if (result.status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND, "Domain parameter key not found");
        return Status::NOT_FOUND;
    }

    info_out = DomainParamKeyCatalogInfo{};
    info_out.param_key_id = result.record.param_key_id;
    info_out.param_name = fixedNameFromBuffer(result.record.param_name, sizeof(result.record.param_name));
    info_out.param_type = static_cast<DomainParamType>(result.record.param_type);
    if (!isKnownDomainParamType(info_out.param_type))
    {
        SET_ERROR_CONTEXT(ctx, Status::PAGE_CORRUPT, "Invalid domain_param_key.param_type");
        return Status::PAGE_CORRUPT;
    }
    info_out.is_valid = result.record.is_valid == 1;
    info_out.created_time = result.record.created_time;
    info_out.last_modified_time = result.record.last_modified_time;
    return Status::OK;
}

auto CatalogManager::getDomainParamKeyByName(const std::string& param_name,
                                             DomainParamKeyCatalogInfo& info_out,
                                             ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    const std::string folded_name = canonicalIdentifierForLookup(param_name);
    auto predicate = [&folded_name](const DomainParamKeyRecord& rec) {
        if (rec.is_valid != 1)
        {
            return false;
        }
        return canonicalIdentifierForLookup(fixedNameFromBuffer(rec.param_name, sizeof(rec.param_name))) ==
               folded_name;
    };
    auto result = findRecordInHeapPage<DomainParamKeyRecord>(domain_param_keys_table_page_, predicate, ctx);
    if (result.status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND, "Domain parameter key not found by name");
        return Status::NOT_FOUND;
    }

    info_out = DomainParamKeyCatalogInfo{};
    info_out.param_key_id = result.record.param_key_id;
    info_out.param_name = fixedNameFromBuffer(result.record.param_name, sizeof(result.record.param_name));
    info_out.param_type = static_cast<DomainParamType>(result.record.param_type);
    if (!isKnownDomainParamType(info_out.param_type))
    {
        SET_ERROR_CONTEXT(ctx, Status::PAGE_CORRUPT, "Invalid domain_param_key.param_type");
        return Status::PAGE_CORRUPT;
    }
    info_out.is_valid = result.record.is_valid == 1;
    info_out.created_time = result.record.created_time;
    info_out.last_modified_time = result.record.last_modified_time;
    return Status::OK;
}

