auto CatalogManager::upsertDomainParameter(const DomainParameterCatalogInfo& info,
                                           ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    Status status = validateDomainParameterValueContract(info, ctx);
    if (status != Status::OK)
    {
        return status;
    }

    DomainInfo domain{};
    if (getDomainById(info.domain_id, domain, ctx) != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND, "Referenced domain_uuid not found");
        return Status::NOT_FOUND;
    }

    auto key_predicate = [&info](const DomainParamKeyRecord& rec) {
        return rec.param_key_id == info.param_key_id && rec.is_valid == 1;
    };
    auto key_row = findRecordInHeapPage<DomainParamKeyRecord>(domain_param_keys_table_page_, key_predicate, ctx);
    if (key_row.status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND, "Referenced param_key_id not found");
        return Status::NOT_FOUND;
    }
    if (key_row.record.param_type != static_cast<uint8_t>(info.param_type))
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT,
                          "domain_parameter.param_type does not match domain_param_key.param_type");
        return Status::INVALID_ARGUMENT;
    }

    DomainParameterRecord rec{};
    rec.domain_id = info.domain_id;
    rec.param_key_id = info.param_key_id;
    rec.param_type = static_cast<uint8_t>(info.param_type);
    rec.is_valid = info.is_valid ? 1 : 0;

    if (info.val_u32.has_value())
    {
        rec.val_u32 = info.val_u32.value();
    }
    if (info.val_i32.has_value())
    {
        rec.val_i32 = info.val_i32.value();
    }
    if (info.val_u64.has_value())
    {
        rec.val_u64 = info.val_u64.value();
    }
    if (info.val_i64.has_value())
    {
        rec.val_i64 = info.val_i64.value();
    }
    if (info.val_u8.has_value())
    {
        rec.val_u8 = info.val_u8.value();
    }
    if (info.val_bool.has_value())
    {
        rec.val_bool = info.val_bool.value() ? 1 : 0;
    }
    if (!isZeroUuidLocal(info.val_uuid))
    {
        rec.val_uuid = info.val_uuid;
    }
    if (info.val_enum.has_value())
    {
        rec.val_enum = info.val_enum.value();
    }
    if (info.val_f32.has_value())
    {
        rec.val_f32 = info.val_f32.value();
    }
    if (info.val_f64.has_value())
    {
        rec.val_f64 = info.val_f64.value();
    }
    if (info.val_string.has_value())
    {
        uint64_t xmin = 0;
        status = storeStringInToast(info.val_string.value(), xmin, rec.val_string_oid, ctx);
        if (status != Status::OK)
        {
            return status;
        }
    }

    const uint64_t now = catalogNowTicks();
    rec.last_modified_time = (info.last_modified_time == 0) ? now : info.last_modified_time;

    auto existing_predicate = [&info](const DomainParameterRecord& row) {
        return row.domain_id == info.domain_id &&
               row.param_key_id == info.param_key_id &&
               row.is_valid == 1;
    };
    auto existing = findRecordInHeapPage<DomainParameterRecord>(
        domain_parameters_table_page_, existing_predicate, ctx);
    if (existing.status == Status::OK)
    {
        rec.created_time = existing.record.created_time;
    }
    else if (existing.status == Status::NOT_FOUND)
    {
        rec.created_time = (info.created_time == 0) ? now : info.created_time;
    }
    else
    {
        return existing.status;
    }

    auto matcher = [&info](const DomainParameterRecord& row) {
        return row.domain_id == info.domain_id &&
               row.param_key_id == info.param_key_id &&
               row.is_valid == 1;
    };
    return updateRecordInHeapPage(domain_parameters_table_page_, matcher, rec, ctx);
}

auto CatalogManager::getDomainParameter(const ID& domain_id,
                                        uint16_t param_key_id,
                                        DomainParameterCatalogInfo& info_out,
                                        ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    auto predicate = [&domain_id, param_key_id](const DomainParameterRecord& rec) {
        return rec.domain_id == domain_id && rec.param_key_id == param_key_id && rec.is_valid == 1;
    };
    auto result = findRecordInHeapPage<DomainParameterRecord>(domain_parameters_table_page_, predicate, ctx);
    if (result.status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND, "Domain parameter not found");
        return Status::NOT_FOUND;
    }

    info_out = DomainParameterCatalogInfo{};
    info_out.domain_id = result.record.domain_id;
    info_out.param_key_id = result.record.param_key_id;
    info_out.param_type = static_cast<DomainParamType>(result.record.param_type);
    info_out.val_uuid = result.record.val_uuid;
    info_out.is_valid = result.record.is_valid == 1;
    info_out.created_time = result.record.created_time;
    info_out.last_modified_time = result.record.last_modified_time;

    using DPT = DomainParamType;
    switch (info_out.param_type)
    {
        case DPT::U32:
            info_out.val_u32 = result.record.val_u32;
            break;
        case DPT::I32:
            info_out.val_i32 = result.record.val_i32;
            break;
        case DPT::U64:
            info_out.val_u64 = result.record.val_u64;
            break;
        case DPT::I64:
            info_out.val_i64 = result.record.val_i64;
            break;
        case DPT::U8:
            info_out.val_u8 = result.record.val_u8;
            break;
        case DPT::BOOL:
            info_out.val_bool = result.record.val_bool != 0;
            break;
        case DPT::STRING:
            if (!isZeroUuidLocal(result.record.val_string_oid))
            {
                uint64_t xmin = 0;
                std::string str;
                Status load_status = loadStringFromToast(result.record.val_string_oid, xmin, str, ctx);
                if (load_status != Status::OK)
                {
                    return load_status;
                }
                info_out.val_string = std::move(str);
            }
            break;
        case DPT::UUID:
            break;
        case DPT::ENUM_VALUE:
            info_out.val_enum = result.record.val_enum;
            break;
        case DPT::F32:
            info_out.val_f32 = result.record.val_f32;
            break;
        case DPT::F64:
            info_out.val_f64 = result.record.val_f64;
            break;
        default:
            SET_ERROR_CONTEXT(ctx, Status::PAGE_CORRUPT, "Invalid domain_parameter.param_type");
            return Status::PAGE_CORRUPT;
    }

    return Status::OK;
}

auto CatalogManager::listDomainParameters(const ID& domain_id,
                                          std::vector<DomainParameterCatalogInfo>& rows_out,
                                          ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    rows_out.clear();
    auto filter = [&domain_id](const DomainParameterRecord& rec) {
        return rec.is_valid == 1 && rec.domain_id == domain_id;
    };
    auto converter = [this, ctx](const DomainParameterRecord& rec, DomainParameterCatalogInfo& info) {
        info = DomainParameterCatalogInfo{};
        info.domain_id = rec.domain_id;
        info.param_key_id = rec.param_key_id;
        info.param_type = static_cast<DomainParamType>(rec.param_type);
        info.val_uuid = rec.val_uuid;
        info.is_valid = rec.is_valid == 1;
        info.created_time = rec.created_time;
        info.last_modified_time = rec.last_modified_time;

        using DPT = DomainParamType;
        switch (info.param_type)
        {
            case DPT::U32:
                info.val_u32 = rec.val_u32;
                break;
            case DPT::I32:
                info.val_i32 = rec.val_i32;
                break;
            case DPT::U64:
                info.val_u64 = rec.val_u64;
                break;
            case DPT::I64:
                info.val_i64 = rec.val_i64;
                break;
            case DPT::U8:
                info.val_u8 = rec.val_u8;
                break;
            case DPT::BOOL:
                info.val_bool = rec.val_bool != 0;
                break;
            case DPT::STRING:
                if (!isZeroUuidLocal(rec.val_string_oid))
                {
                    uint64_t xmin = 0;
                    std::string str;
                    if (loadStringFromToast(rec.val_string_oid, xmin, str, ctx) == Status::OK)
                    {
                        info.val_string = std::move(str);
                    }
                }
                break;
            case DPT::UUID:
                break;
            case DPT::ENUM_VALUE:
                info.val_enum = rec.val_enum;
                break;
            case DPT::F32:
                info.val_f32 = rec.val_f32;
                break;
            case DPT::F64:
                info.val_f64 = rec.val_f64;
                break;
            default:
                break;
        }
    };
    return readRecordsToVector<DomainParameterRecord, DomainParameterCatalogInfo>(
        domain_parameters_table_page_, rows_out, filter, converter, ctx);
}

