auto CatalogManager::upsertDomainConstraintCatalogEntry(const DomainConstraintCatalogInfo& info,
                                                        ID& constraint_id_out,
                                                        ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.domain_id))
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "domain_constraint.domain_uuid is required");
        return Status::INVALID_ARGUMENT;
    }
    if (!isValidDomainConstraintKind(info.constraint_kind))
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "domain_constraint.constraint_kind is invalid");
        return Status::INVALID_ARGUMENT;
    }
    if (info.constraint_expr_sblr.empty())
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "domain_constraint.constraint_expr_sblr is required");
        return Status::INVALID_ARGUMENT;
    }
    DomainInfo domain{};
    if (getDomainById(info.domain_id, domain, ctx) != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND, "Referenced domain_uuid not found");
        return Status::NOT_FOUND;
    }

    ID constraint_id = info.constraint_id;
    if (isZeroUuidLocal(constraint_id))
    {
        constraint_id = generateUuidV7();
    }
    constraint_id_out = constraint_id;

    DomainConstraintCatalogRecord rec{};
    rec.constraint_id = constraint_id;
    rec.domain_id = info.domain_id;
    rec.constraint_kind = static_cast<uint8_t>(info.constraint_kind);
    rec.is_valid = info.is_valid ? 1 : 0;

    uint64_t xmin = 0;
    Status status = storeStringInToast(info.constraint_expr_sblr, xmin, rec.constraint_expr_oid, ctx);
    if (status != Status::OK)
    {
        return status;
    }

    const uint64_t now = catalogNowTicks();
    rec.last_modified_time = (info.last_modified_time == 0) ? now : info.last_modified_time;

    auto existing_predicate = [&constraint_id](const DomainConstraintCatalogRecord& row) {
        return row.constraint_id == constraint_id && row.is_valid == 1;
    };
    auto existing = findRecordInHeapPage<DomainConstraintCatalogRecord>(
        domain_constraints_table_page_, existing_predicate, ctx);
    if (existing.status == Status::OK)
    {
        rec.created_time = existing.record.created_time;
    }
    else if (existing.status == Status::NOT_FOUND)
    {
        rec.created_time = (info.created_time == 0) ? now : info.created_time;
    }
    else
    {
        return existing.status;
    }

    auto matcher = [&constraint_id](const DomainConstraintCatalogRecord& row) {
        return row.constraint_id == constraint_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(domain_constraints_table_page_, matcher, rec, ctx);
}

