auto CatalogManager::upsertDomainValidationCatalogEntry(const DomainValidationCatalogInfo& info,
                                                        ID& validation_id_out,
                                                        ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.domain_id))
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "domain_validation.domain_uuid is required");
        return Status::INVALID_ARGUMENT;
    }
    if (!isValidDomainValidationKind(info.validation_kind))
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "domain_validation.validation_kind is invalid");
        return Status::INVALID_ARGUMENT;
    }
    if (info.validation_expr_sblr.empty())
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "domain_validation.validation_expr_sblr is required");
        return Status::INVALID_ARGUMENT;
    }
    DomainInfo domain{};
    if (getDomainById(info.domain_id, domain, ctx) != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND, "Referenced domain_uuid not found");
        return Status::NOT_FOUND;
    }

    ID validation_id = info.validation_id;
    if (isZeroUuidLocal(validation_id))
    {
        validation_id = generateUuidV7();
    }
    validation_id_out = validation_id;

    DomainValidationCatalogRecord rec{};
    rec.validation_id = validation_id;
    rec.domain_id = info.domain_id;
    rec.validation_kind = static_cast<uint8_t>(info.validation_kind);
    rec.is_valid = info.is_valid ? 1 : 0;

    uint64_t xmin = 0;
    Status status = storeStringInToast(info.validation_expr_sblr, xmin, rec.validation_expr_oid, ctx);
    if (status != Status::OK)
    {
        return status;
    }

    const uint64_t now = catalogNowTicks();
    rec.last_modified_time = (info.last_modified_time == 0) ? now : info.last_modified_time;
    auto existing_predicate = [&validation_id](const DomainValidationCatalogRecord& row) {
        return row.validation_id == validation_id && row.is_valid == 1;
    };
    auto existing = findRecordInHeapPage<DomainValidationCatalogRecord>(
        domain_validation_table_page_, existing_predicate, ctx);
    if (existing.status == Status::OK)
    {
        rec.created_time = existing.record.created_time;
    }
    else if (existing.status == Status::NOT_FOUND)
    {
        rec.created_time = (info.created_time == 0) ? now : info.created_time;
    }
    else
    {
        return existing.status;
    }

    auto matcher = [&validation_id](const DomainValidationCatalogRecord& row) {
        return row.validation_id == validation_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(domain_validation_table_page_, matcher, rec, ctx);
}

