// ============================================================================
// Canonical Charset/Collation Extension Catalog CRUD Operations (CAT-012)
// ============================================================================

auto CatalogManager::upsertCharsetAliasCatalogEntry(const CharsetAliasCatalogInfo& info,
                                                    ID& alias_id_out,
                                                    ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.charset_id))
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "charset_alias.charset_uuid is required");
        return Status::INVALID_ARGUMENT;
    }
    if (isZeroUuidLocal(info.bundle_id))
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "charset_alias.bundle_uuid is required");
        return Status::INVALID_ARGUMENT;
    }
    if (info.alias_name.empty())
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "charset_alias.alias_name is required");
        return Status::INVALID_ARGUMENT;
    }

    std::string normalized_name = info.normalized_name.empty()
        ? canonicalIdentifierForLookup(info.alias_name)
        : canonicalIdentifierForLookup(info.normalized_name);
    if (normalized_name.empty())
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT,
                          "charset_alias.normalized_name resolved to empty value");
        return Status::INVALID_ARGUMENT;
    }

    Status status = UTF8Utils::validateStorageCapacity(
        info.alias_name, CatalogConstants::MAX_IDENTIFIER_CHARS, CatalogConstants::MAX_IDENTIFIER_BYTES, ctx);
    if (status != Status::OK)
    {
        return status;
    }
    status = UTF8Utils::validateStorageCapacity(
        normalized_name, CatalogConstants::MAX_IDENTIFIER_CHARS, CatalogConstants::MAX_IDENTIFIER_BYTES, ctx);
    if (status != Status::OK)
    {
        return status;
    }

    auto charset_predicate = [&info](const CharsetRecord& rec) {
        return rec.is_valid == 1 && rec.charset_id == info.charset_id;
    };
    auto charset_row = findRecordInHeapPage<CharsetRecord>(charsets_table_page_, charset_predicate, ctx);
    if (charset_row.status != Status::OK)
    {
        if (charset_row.status == Status::NOT_FOUND)
        {
            SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND, "Referenced charset_uuid not found");
            return Status::NOT_FOUND;
        }
        return charset_row.status;
    }

    ID alias_id = info.alias_id;
    if (isZeroUuidLocal(alias_id))
    {
        alias_id = generateUuidV7();
    }
    alias_id_out = alias_id;

    auto duplicate_predicate = [&normalized_name, &alias_id](const CharsetAliasRecord& rec) {
        if (rec.is_valid != 1 || rec.alias_id == alias_id)
        {
            return false;
        }
        return canonicalIdentifierForLookup(
            fixedNameFromBuffer(rec.normalized_name, sizeof(rec.normalized_name))) == normalized_name;
    };
    auto duplicate = findRecordInHeapPage<CharsetAliasRecord>(
        charset_aliases_table_page_, duplicate_predicate, ctx);
    if (duplicate.status == Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, Status::CONSTRAINT_VIOLATION,
                          "UNIQUE(charset_alias.normalized_name) violated");
        return Status::CONSTRAINT_VIOLATION;
    }
    if (duplicate.status != Status::NOT_FOUND)
    {
        return duplicate.status;
    }

    const uint64_t now = catalogNowTicks();
    CharsetAliasRecord rec{};
    rec.alias_id = alias_id;
    rec.charset_id = info.charset_id;
    rec.bundle_id = info.bundle_id;
    rec.is_valid = info.is_valid ? 1 : 0;

    std::string alias_truncated = UTF8Utils::truncateToBytes(info.alias_name, sizeof(rec.alias_name));
    std::string normalized_truncated = UTF8Utils::truncateToBytes(normalized_name, sizeof(rec.normalized_name));
    std::strncpy(rec.alias_name, alias_truncated.c_str(), sizeof(rec.alias_name) - 1);
    std::strncpy(rec.normalized_name, normalized_truncated.c_str(), sizeof(rec.normalized_name) - 1);

    rec.last_modified_time = (info.last_modified_time == 0) ? now : info.last_modified_time;
    auto existing_predicate = [&alias_id](const CharsetAliasRecord& row) {
        return row.alias_id == alias_id && row.is_valid == 1;
    };
    auto existing = findRecordInHeapPage<CharsetAliasRecord>(
        charset_aliases_table_page_, existing_predicate, ctx);
    if (existing.status == Status::OK)
    {
        rec.created_time = existing.record.created_time;
    }
    else if (existing.status == Status::NOT_FOUND)
    {
        rec.created_time = (info.created_time == 0) ? now : info.created_time;
    }
    else
    {
        return existing.status;
    }

    auto matcher = [&alias_id](const CharsetAliasRecord& row) {
        return row.alias_id == alias_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(charset_aliases_table_page_, matcher, rec, ctx);
}

