auto CatalogManager::getCharsetAliasCatalogEntryByNormalizedName(
    const std::string& normalized_name,
    CharsetAliasCatalogInfo& info_out,
    ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    const std::string folded_name = canonicalIdentifierForLookup(normalized_name);
    auto predicate = [&folded_name](const CharsetAliasRecord& rec) {
        if (rec.is_valid != 1)
        {
            return false;
        }
        return canonicalIdentifierForLookup(
            fixedNameFromBuffer(rec.normalized_name, sizeof(rec.normalized_name))) == folded_name;
    };
    auto result = findRecordInHeapPage<CharsetAliasRecord>(charset_aliases_table_page_, predicate, ctx);
    if (result.status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND, "Charset alias not found by normalized name");
        return Status::NOT_FOUND;
    }

    info_out = CharsetAliasCatalogInfo{};
    info_out.alias_id = result.record.alias_id;
    info_out.charset_id = result.record.charset_id;
    info_out.bundle_id = result.record.bundle_id;
    info_out.alias_name = fixedNameFromBuffer(result.record.alias_name, sizeof(result.record.alias_name));
    info_out.normalized_name =
        fixedNameFromBuffer(result.record.normalized_name, sizeof(result.record.normalized_name));
    info_out.is_valid = result.record.is_valid == 1;
    info_out.created_time = result.record.created_time;
    info_out.last_modified_time = result.record.last_modified_time;
    return Status::OK;
}

