auto CatalogManager::upsertCollationTailoringCatalogEntry(const CollationTailoringCatalogInfo& info,
                                                          ID& tailoring_id_out,
                                                          ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (info.collation_id == 0)
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "collation_tailoring.collation_id is required");
        return Status::INVALID_ARGUMENT;
    }
    if (isZeroUuidLocal(info.bundle_id))
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "collation_tailoring.bundle_uuid is required");
        return Status::INVALID_ARGUMENT;
    }
    if (!isValidCollationTailoringKind(info.tailoring_kind))
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT,
                          "collation_tailoring.tailoring_kind is invalid");
        return Status::INVALID_ARGUMENT;
    }
    const bool has_json = info.tailoring_json.has_value() && !info.tailoring_json.value().empty();
    const bool has_blob = info.tailoring_blob.has_value() && !info.tailoring_blob.value().empty();
    if (!has_json && !has_blob)
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT,
                          "collation_tailoring requires tailoring_json and/or tailoring_blob");
        return Status::INVALID_ARGUMENT;
    }
    if (info.tailoring_hash.empty())
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "collation_tailoring.tailoring_hash is required");
        return Status::INVALID_ARGUMENT;
    }
    Status status = UTF8Utils::validateStorageCapacity(
        info.tailoring_hash, 64, 65, ctx);
    if (status != Status::OK)
    {
        return status;
    }

    auto collation_predicate = [&info](const CollationRecord& rec) {
        return rec.is_valid == 1 && rec.collation_id == info.collation_id;
    };
    auto collation_row = findRecordInHeapPage<CollationRecord>(
        collation_defs_table_page_, collation_predicate, ctx);
    if (collation_row.status != Status::OK)
    {
        if (collation_row.status == Status::NOT_FOUND)
        {
            SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND, "Referenced collation_id not found");
            return Status::NOT_FOUND;
        }
        return collation_row.status;
    }

    ID tailoring_id = info.tailoring_id;
    if (isZeroUuidLocal(tailoring_id))
    {
        tailoring_id = generateUuidV7();
    }
    tailoring_id_out = tailoring_id;

    const std::string folded_hash = canonicalIdentifierForLookup(info.tailoring_hash);
    auto duplicate_predicate = [&info, &tailoring_id, &folded_hash](const CollationTailoringRecord& rec) {
        if (rec.is_valid != 1 || rec.tailoring_id == tailoring_id)
        {
            return false;
        }
        if (rec.collation_id != info.collation_id)
        {
            return false;
        }
        if (rec.tailoring_kind != static_cast<uint8_t>(info.tailoring_kind))
        {
            return false;
        }
        return canonicalIdentifierForLookup(
            fixedNameFromBuffer(rec.tailoring_hash, sizeof(rec.tailoring_hash))) == folded_hash;
    };
    auto duplicate = findRecordInHeapPage<CollationTailoringRecord>(
        collation_tailoring_table_page_, duplicate_predicate, ctx);
    if (duplicate.status == Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, Status::CONSTRAINT_VIOLATION,
                          "UNIQUE(collation_id, tailoring_kind, tailoring_hash) violated");
        return Status::CONSTRAINT_VIOLATION;
    }
    if (duplicate.status != Status::NOT_FOUND)
    {
        return duplicate.status;
    }

    const uint64_t now = catalogNowTicks();
    CollationTailoringRecord rec{};
    rec.tailoring_id = tailoring_id;
    rec.collation_id = info.collation_id;
    rec.tailoring_kind = static_cast<uint8_t>(info.tailoring_kind);
    rec.bundle_id = info.bundle_id;
    rec.is_valid = info.is_valid ? 1 : 0;
    std::string hash_truncated = UTF8Utils::truncateToBytes(info.tailoring_hash, sizeof(rec.tailoring_hash));
    std::strncpy(rec.tailoring_hash, hash_truncated.c_str(), sizeof(rec.tailoring_hash) - 1);

    uint64_t xmin = 0;
    if (has_json)
    {
        status = storeStringInToast(info.tailoring_json.value(), xmin, rec.tailoring_json_oid, ctx);
        if (status != Status::OK)
        {
            return status;
        }
    }
    if (has_blob)
    {
        status = storeStringInToast(info.tailoring_blob.value(), xmin, rec.tailoring_blob_oid, ctx);
        if (status != Status::OK)
        {
            return status;
        }
    }

    rec.last_modified_time = (info.last_modified_time == 0) ? now : info.last_modified_time;
    auto existing_predicate = [&tailoring_id](const CollationTailoringRecord& row) {
        return row.tailoring_id == tailoring_id && row.is_valid == 1;
    };
    auto existing = findRecordInHeapPage<CollationTailoringRecord>(
        collation_tailoring_table_page_, existing_predicate, ctx);
    if (existing.status == Status::OK)
    {
        rec.created_time = existing.record.created_time;
    }
    else if (existing.status == Status::NOT_FOUND)
    {
        rec.created_time = (info.created_time == 0) ? now : info.created_time;
    }
    else
    {
        return existing.status;
    }

    auto matcher = [&tailoring_id](const CollationTailoringRecord& row) {
        return row.tailoring_id == tailoring_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(collation_tailoring_table_page_, matcher, rec, ctx);
}

auto CatalogManager::getCollationTailoringCatalogEntry(const ID& tailoring_id,
                                                       CollationTailoringCatalogInfo& info_out,
                                                       ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    auto predicate = [&tailoring_id](const CollationTailoringRecord& rec) {
        return rec.tailoring_id == tailoring_id && rec.is_valid == 1;
    };
    auto result = findRecordInHeapPage<CollationTailoringRecord>(
        collation_tailoring_table_page_, predicate, ctx);
    if (result.status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND, "Collation tailoring not found");
        return Status::NOT_FOUND;
    }

    info_out = CollationTailoringCatalogInfo{};
    info_out.tailoring_id = result.record.tailoring_id;
    info_out.collation_id = result.record.collation_id;
    info_out.bundle_id = result.record.bundle_id;
    info_out.tailoring_kind = static_cast<CollationTailoringKind>(result.record.tailoring_kind);
    if (!isValidCollationTailoringKind(info_out.tailoring_kind))
    {
        SET_ERROR_CONTEXT(ctx, Status::PAGE_CORRUPT, "Invalid collation_tailoring.tailoring_kind");
        return Status::PAGE_CORRUPT;
    }
    info_out.tailoring_hash =
        fixedNameFromBuffer(result.record.tailoring_hash, sizeof(result.record.tailoring_hash));
    info_out.is_valid = result.record.is_valid == 1;
    info_out.created_time = result.record.created_time;
    info_out.last_modified_time = result.record.last_modified_time;

    uint64_t xmin = 0;
    if (!isZeroUuidLocal(result.record.tailoring_json_oid))
    {
        std::string json;
        Status load_status = loadStringFromToast(result.record.tailoring_json_oid, xmin, json, ctx);
        if (load_status != Status::OK)
        {
            return load_status;
        }
        info_out.tailoring_json = std::move(json);
    }
    if (!isZeroUuidLocal(result.record.tailoring_blob_oid))
    {
        std::string blob;
        Status load_status = loadStringFromToast(result.record.tailoring_blob_oid, xmin, blob, ctx);
        if (load_status != Status::OK)
        {
            return load_status;
        }
        info_out.tailoring_blob = std::move(blob);
    }
    return Status::OK;
}

auto CatalogManager::listCollationTailoringCatalogEntries(
    uint32_t collation_id,
    std::vector<CollationTailoringCatalogInfo>& rows_out,
    ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    rows_out.clear();
    auto filter = [collation_id](const CollationTailoringRecord& rec) {
        if (rec.is_valid != 1)
        {
            return false;
        }
        return collation_id == 0 || rec.collation_id == collation_id;
    };
    auto converter = [this, ctx](const CollationTailoringRecord& rec, CollationTailoringCatalogInfo& info) {
        info = CollationTailoringCatalogInfo{};
        info.tailoring_id = rec.tailoring_id;
        info.collation_id = rec.collation_id;
        info.bundle_id = rec.bundle_id;
        info.tailoring_kind = static_cast<CollationTailoringKind>(rec.tailoring_kind);
        info.tailoring_hash = fixedNameFromBuffer(rec.tailoring_hash, sizeof(rec.tailoring_hash));
        info.is_valid = rec.is_valid == 1;
        info.created_time = rec.created_time;
        info.last_modified_time = rec.last_modified_time;

        uint64_t xmin = 0;
        if (!isZeroUuidLocal(rec.tailoring_json_oid))
        {
            std::string json;
            if (loadStringFromToast(rec.tailoring_json_oid, xmin, json, ctx) == Status::OK)
            {
                info.tailoring_json = std::move(json);
            }
        }
        if (!isZeroUuidLocal(rec.tailoring_blob_oid))
        {
            std::string blob;
            if (loadStringFromToast(rec.tailoring_blob_oid, xmin, blob, ctx) == Status::OK)
            {
                info.tailoring_blob = std::move(blob);
            }
        }
    };
    return readRecordsToVector<CollationTailoringRecord, CollationTailoringCatalogInfo>(
        collation_tailoring_table_page_, rows_out, filter, converter, ctx);
}

auto CatalogManager::deleteCollationTailoringCatalogEntry(const ID& tailoring_id,
                                                          ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    auto predicate = [&tailoring_id](const CollationTailoringRecord& rec) {
        return rec.tailoring_id == tailoring_id && rec.is_valid == 1;
    };
    auto result = findRecordInHeapPage<CollationTailoringRecord>(
        collation_tailoring_table_page_, predicate, ctx);
    if (result.status != Status::OK)
    {
        return Status::NOT_FOUND;
    }

    CollationTailoringRecord updated = result.record;
    updated.is_valid = 0;
    updated.last_modified_time = catalogNowTicks();
    return updateRecordInHeapPage(collation_tailoring_table_page_, result.slot_index, updated, ctx);
}

