// Canonical Resource/Timezone Extension Catalog CRUD Operations (CAT-013)
// ============================================================================

auto CatalogManager::upsertResourceBundleCatalogEntry(const ResourceBundleCatalogInfo& info,
                                                      ID& bundle_id_out,
                                                      ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (!isValidResourceBundleKind(info.bundle_kind))
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "resource_bundle.bundle_kind is invalid");
        return Status::INVALID_ARGUMENT;
    }
    if (info.bundle_name.empty())
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "resource_bundle.bundle_name is required");
        return Status::INVALID_ARGUMENT;
    }
    if (info.bundle_version.empty())
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "resource_bundle.bundle_version is required");
        return Status::INVALID_ARGUMENT;
    }
    if (info.content_hash.empty())
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "resource_bundle.content_hash is required");
        return Status::INVALID_ARGUMENT;
    }

    Status status = UTF8Utils::validateStorageCapacity(info.bundle_name, 128, 128, ctx);
    if (status != Status::OK)
    {
        return status;
    }
    status = UTF8Utils::validateStorageCapacity(info.bundle_version, 128, 128, ctx);
    if (status != Status::OK)
    {
        return status;
    }
    status = UTF8Utils::validateStorageCapacity(info.source_uri, 512, 512, ctx);
    if (status != Status::OK)
    {
        return status;
    }
    status = UTF8Utils::validateStorageCapacity(info.content_hash, 64, 65, ctx);
    if (status != Status::OK)
    {
        return status;
    }

    ID bundle_id = info.bundle_id;
    if (isZeroUuidLocal(bundle_id))
    {
        bundle_id = generateUuidV7();
    }
    bundle_id_out = bundle_id;

    const std::string kind_name = std::to_string(static_cast<uint8_t>(info.bundle_kind));
    const std::string folded_name = canonicalIdentifierForLookup(info.bundle_name);
    const std::string folded_version = canonicalIdentifierForLookup(info.bundle_version);
    const std::string folded_hash = canonicalIdentifierForLookup(info.content_hash);
    auto duplicate_predicate =
        [&kind_name, &folded_name, &folded_version, &folded_hash, &bundle_id](const ResourceBundleRecord& rec) {
            if (rec.is_valid != 1 || rec.bundle_id == bundle_id)
            {
                return false;
            }
            if (std::to_string(rec.bundle_kind) != kind_name)
            {
                return false;
            }
            if (canonicalIdentifierForLookup(fixedNameFromBuffer(rec.bundle_name, sizeof(rec.bundle_name))) !=
                folded_name)
            {
                return false;
            }
            if (canonicalIdentifierForLookup(
                    fixedNameFromBuffer(rec.bundle_version, sizeof(rec.bundle_version))) != folded_version)
            {
                return false;
            }
            return canonicalIdentifierForLookup(
                       fixedNameFromBuffer(rec.content_hash, sizeof(rec.content_hash))) == folded_hash;
        };
    auto duplicate = findRecordInHeapPage<ResourceBundleRecord>(
        resource_bundles_table_page_, duplicate_predicate, ctx);
    if (duplicate.status == Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, Status::CONSTRAINT_VIOLATION,
                          "UNIQUE(bundle_kind,bundle_name,bundle_version,content_hash) violated");
        return Status::CONSTRAINT_VIOLATION;
    }
    if (duplicate.status != Status::NOT_FOUND)
    {
        return duplicate.status;
    }

    if (info.is_active)
    {
        auto active_conflict_predicate = [&bundle_id, &info](const ResourceBundleRecord& rec) {
            return rec.is_valid == 1 &&
                   rec.is_active == 1 &&
                   rec.bundle_kind == static_cast<uint8_t>(info.bundle_kind) &&
                   rec.bundle_id != bundle_id;
        };
        auto active_conflict = findRecordInHeapPage<ResourceBundleRecord>(
            resource_bundles_table_page_, active_conflict_predicate, ctx);
        if (active_conflict.status == Status::OK)
        {
            SET_ERROR_CONTEXT(ctx, Status::CONSTRAINT_VIOLATION,
                              "Only one active resource bundle is allowed per bundle_kind");
            return Status::CONSTRAINT_VIOLATION;
        }
        if (active_conflict.status != Status::NOT_FOUND)
        {
            return active_conflict.status;
        }
    }

    const uint64_t now = catalogNowTicks();
    ResourceBundleRecord rec{};
    rec.bundle_id = bundle_id;
    rec.bundle_kind = static_cast<uint8_t>(info.bundle_kind);
    rec.is_active = info.is_active ? 1 : 0;
    rec.is_valid = info.is_valid ? 1 : 0;

    std::string truncated_name = UTF8Utils::truncateToBytes(info.bundle_name, sizeof(rec.bundle_name));
    std::strncpy(rec.bundle_name, truncated_name.c_str(), sizeof(rec.bundle_name) - 1);
    std::string truncated_version = UTF8Utils::truncateToBytes(info.bundle_version, sizeof(rec.bundle_version));
    std::strncpy(rec.bundle_version, truncated_version.c_str(), sizeof(rec.bundle_version) - 1);
    std::string truncated_uri = UTF8Utils::truncateToBytes(info.source_uri, sizeof(rec.source_uri));
    std::strncpy(rec.source_uri, truncated_uri.c_str(), sizeof(rec.source_uri) - 1);
    std::string truncated_hash = UTF8Utils::truncateToBytes(info.content_hash, sizeof(rec.content_hash));
    std::strncpy(rec.content_hash, truncated_hash.c_str(), sizeof(rec.content_hash) - 1);

    uint64_t xmin = 0;
    if (!info.manifest_json.empty())
    {
        status = storeStringInToast(info.manifest_json, xmin, rec.manifest_json_oid, ctx);
        if (status != Status::OK)
        {
            return status;
        }
    }

    rec.last_modified_time = (info.last_modified_time == 0) ? now : info.last_modified_time;
    auto existing_predicate = [&bundle_id](const ResourceBundleRecord& row) {
        return row.bundle_id == bundle_id && row.is_valid == 1;
    };
    auto existing = findRecordInHeapPage<ResourceBundleRecord>(
        resource_bundles_table_page_, existing_predicate, ctx);
    if (existing.status == Status::OK)
    {
        rec.created_time = existing.record.created_time;
        if (info.activated_time != 0)
        {
            rec.activated_time = info.activated_time;
        }
        else if (info.is_active)
        {
            rec.activated_time =
                (existing.record.activated_time != 0) ? existing.record.activated_time : now;
        }
        else
        {
            rec.activated_time = 0;
        }
    }
    else if (existing.status == Status::NOT_FOUND)
    {
        rec.created_time = (info.created_time == 0) ? now : info.created_time;
        if (info.activated_time != 0)
        {
            rec.activated_time = info.activated_time;
        }
        else if (info.is_active)
        {
            rec.activated_time = now;
        }
        else
        {
            rec.activated_time = 0;
        }
    }
    else
    {
        return existing.status;
    }

    auto matcher = [&bundle_id](const ResourceBundleRecord& row) {
        return row.bundle_id == bundle_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(resource_bundles_table_page_, matcher, rec, ctx);
}

auto CatalogManager::getResourceBundleCatalogEntry(const ID& bundle_id,
                                                   ResourceBundleCatalogInfo& info_out,
                                                   ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    auto predicate = [&bundle_id](const ResourceBundleRecord& rec) {
        return rec.bundle_id == bundle_id && rec.is_valid == 1;
    };
    auto result = findRecordInHeapPage<ResourceBundleRecord>(resource_bundles_table_page_, predicate, ctx);
    if (result.status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND, "Resource bundle not found");
        return Status::NOT_FOUND;
    }

    info_out = ResourceBundleCatalogInfo{};
    info_out.bundle_id = result.record.bundle_id;
    info_out.bundle_kind = static_cast<ResourceBundleKind>(result.record.bundle_kind);
    if (!isValidResourceBundleKind(info_out.bundle_kind))
    {
        SET_ERROR_CONTEXT(ctx, Status::PAGE_CORRUPT, "Invalid resource_bundle.bundle_kind");
        return Status::PAGE_CORRUPT;
    }
    info_out.bundle_name = fixedNameFromBuffer(result.record.bundle_name, sizeof(result.record.bundle_name));
    info_out.bundle_version =
        fixedNameFromBuffer(result.record.bundle_version, sizeof(result.record.bundle_version));
    info_out.source_uri = fixedNameFromBuffer(result.record.source_uri, sizeof(result.record.source_uri));
    info_out.content_hash = fixedNameFromBuffer(result.record.content_hash, sizeof(result.record.content_hash));
    info_out.is_active = result.record.is_active == 1;
    info_out.is_valid = result.record.is_valid == 1;
    info_out.created_time = result.record.created_time;
    info_out.activated_time = result.record.activated_time;
    info_out.last_modified_time = result.record.last_modified_time;

    uint64_t xmin = 0;
    if (!isZeroUuidLocal(result.record.manifest_json_oid))
    {
        Status load_status =
            loadStringFromToast(result.record.manifest_json_oid, xmin, info_out.manifest_json, ctx);
        if (load_status != Status::OK)
        {
            return load_status;
        }
    }
    return Status::OK;
}

auto CatalogManager::getActiveResourceBundleByKind(ResourceBundleKind kind,
                                                   ResourceBundleCatalogInfo& info_out,
                                                   ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (!isValidResourceBundleKind(kind))
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "resource_bundle.bundle_kind is invalid");
        return Status::INVALID_ARGUMENT;
    }
    auto predicate = [kind](const ResourceBundleRecord& rec) {
        return rec.is_valid == 1 && rec.is_active == 1 &&
               rec.bundle_kind == static_cast<uint8_t>(kind);
    };
    auto result = findRecordInHeapPage<ResourceBundleRecord>(resource_bundles_table_page_, predicate, ctx);
    if (result.status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND, "Active resource bundle not found");
        return Status::NOT_FOUND;
    }

    info_out = ResourceBundleCatalogInfo{};
    info_out.bundle_id = result.record.bundle_id;
    info_out.bundle_kind = static_cast<ResourceBundleKind>(result.record.bundle_kind);
    info_out.bundle_name = fixedNameFromBuffer(result.record.bundle_name, sizeof(result.record.bundle_name));
    info_out.bundle_version =
        fixedNameFromBuffer(result.record.bundle_version, sizeof(result.record.bundle_version));
    info_out.source_uri = fixedNameFromBuffer(result.record.source_uri, sizeof(result.record.source_uri));
    info_out.content_hash = fixedNameFromBuffer(result.record.content_hash, sizeof(result.record.content_hash));
    info_out.is_active = true;
    info_out.is_valid = result.record.is_valid == 1;
    info_out.created_time = result.record.created_time;
    info_out.activated_time = result.record.activated_time;
    info_out.last_modified_time = result.record.last_modified_time;

    uint64_t xmin = 0;
    if (!isZeroUuidLocal(result.record.manifest_json_oid))
    {
        Status load_status =
            loadStringFromToast(result.record.manifest_json_oid, xmin, info_out.manifest_json, ctx);
        if (load_status != Status::OK)
        {
            return load_status;
        }
    }
    return Status::OK;
}

auto CatalogManager::listResourceBundleCatalogEntries(ResourceBundleKind kind_filter,
                                                      std::vector<ResourceBundleCatalogInfo>& rows_out,
                                                      ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (kind_filter != ResourceBundleKind::UNSPECIFIED &&
        !isValidResourceBundleKind(kind_filter))
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "resource_bundle.bundle_kind filter is invalid");
        return Status::INVALID_ARGUMENT;
    }

    rows_out.clear();
    auto filter = [kind_filter](const ResourceBundleRecord& rec) {
        if (rec.is_valid != 1)
        {
            return false;
        }
        return kind_filter == ResourceBundleKind::UNSPECIFIED ||
               rec.bundle_kind == static_cast<uint8_t>(kind_filter);
    };
    auto converter = [this, ctx](const ResourceBundleRecord& rec, ResourceBundleCatalogInfo& info) {
        info = ResourceBundleCatalogInfo{};
        info.bundle_id = rec.bundle_id;
        info.bundle_kind = static_cast<ResourceBundleKind>(rec.bundle_kind);
        info.bundle_name = fixedNameFromBuffer(rec.bundle_name, sizeof(rec.bundle_name));
        info.bundle_version = fixedNameFromBuffer(rec.bundle_version, sizeof(rec.bundle_version));
        info.source_uri = fixedNameFromBuffer(rec.source_uri, sizeof(rec.source_uri));
        info.content_hash = fixedNameFromBuffer(rec.content_hash, sizeof(rec.content_hash));
        info.is_active = rec.is_active == 1;
        info.is_valid = rec.is_valid == 1;
        info.created_time = rec.created_time;
        info.activated_time = rec.activated_time;
        info.last_modified_time = rec.last_modified_time;

        uint64_t xmin = 0;
        if (!isZeroUuidLocal(rec.manifest_json_oid))
        {
            std::string manifest;
            if (loadStringFromToast(rec.manifest_json_oid, xmin, manifest, ctx) == Status::OK)
            {
                info.manifest_json = std::move(manifest);
            }
        }
    };
    return readRecordsToVector<ResourceBundleRecord, ResourceBundleCatalogInfo>(
        resource_bundles_table_page_, rows_out, filter, converter, ctx);
}

auto CatalogManager::deleteResourceBundleCatalogEntry(const ID& bundle_id,
                                                      ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    auto predicate = [&bundle_id](const ResourceBundleRecord& rec) {
        return rec.bundle_id == bundle_id && rec.is_valid == 1;
    };
    auto result = findRecordInHeapPage<ResourceBundleRecord>(resource_bundles_table_page_, predicate, ctx);
    if (result.status != Status::OK)
    {
        return Status::NOT_FOUND;
    }

    ResourceBundleRecord updated = result.record;
    updated.is_valid = 0;
    updated.is_active = 0;
    updated.last_modified_time = catalogNowTicks();
    return updateRecordInHeapPage(resource_bundles_table_page_, result.slot_index, updated, ctx);
}

auto CatalogManager::upsertResourceArtifactCatalogEntry(const ResourceArtifactCatalogInfo& info,
                                                        ID& artifact_id_out,
                                                        ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.bundle_id))
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "resource_artifact.bundle_uuid is required");
        return Status::INVALID_ARGUMENT;
    }
    if (!isValidResourceArtifactKind(info.artifact_kind))
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "resource_artifact.artifact_kind is invalid");
        return Status::INVALID_ARGUMENT;
    }
    if (info.artifact_path.empty())
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "resource_artifact.artifact_path is required");
        return Status::INVALID_ARGUMENT;
    }
    if (info.content_blob.empty())
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "resource_artifact.content_blob is required");
        return Status::INVALID_ARGUMENT;
    }
    if (info.content_hash.empty())
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "resource_artifact.content_hash is required");
        return Status::INVALID_ARGUMENT;
    }

    uint64_t content_size_bytes = info.content_size_bytes;
    if (content_size_bytes == 0)
    {
        content_size_bytes = static_cast<uint64_t>(info.content_blob.size());
    }
    if (content_size_bytes != static_cast<uint64_t>(info.content_blob.size()))
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT,
                          "resource_artifact.content_size_bytes must match content_blob size");
        return Status::INVALID_ARGUMENT;
    }

    Status status = UTF8Utils::validateStorageCapacity(info.artifact_path, 512, 512, ctx);
    if (status != Status::OK)
    {
        return status;
    }
    status = UTF8Utils::validateStorageCapacity(info.content_hash, 64, 65, ctx);
    if (status != Status::OK)
    {
        return status;
    }

    auto bundle_predicate = [&info](const ResourceBundleRecord& rec) {
        return rec.bundle_id == info.bundle_id && rec.is_valid == 1;
    };
    auto bundle_row = findRecordInHeapPage<ResourceBundleRecord>(
        resource_bundles_table_page_, bundle_predicate, ctx);
    if (bundle_row.status != Status::OK)
    {
        if (bundle_row.status == Status::NOT_FOUND)
        {
            SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND, "Referenced bundle_uuid not found");
            return Status::NOT_FOUND;
        }
        return bundle_row.status;
    }

    ID artifact_id = info.artifact_id;
    if (isZeroUuidLocal(artifact_id))
    {
        artifact_id = generateUuidV7();
    }
    artifact_id_out = artifact_id;

    auto duplicate_predicate = [&info, &artifact_id](const ResourceArtifactRecord& rec) {
        if (rec.is_valid != 1 || rec.bundle_id != info.bundle_id || rec.artifact_id == artifact_id)
        {
            return false;
        }
        return fixedNameFromBuffer(rec.artifact_path, sizeof(rec.artifact_path)) == info.artifact_path;
    };
    auto duplicate = findRecordInHeapPage<ResourceArtifactRecord>(
        resource_artifacts_table_page_, duplicate_predicate, ctx);
    if (duplicate.status == Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, Status::CONSTRAINT_VIOLATION,
                          "UNIQUE(resource_artifact.bundle_uuid, artifact_path) violated");
        return Status::CONSTRAINT_VIOLATION;
    }
    if (duplicate.status != Status::NOT_FOUND)
    {
        return duplicate.status;
    }

    const uint64_t now = catalogNowTicks();
    ResourceArtifactRecord rec{};
    rec.artifact_id = artifact_id;
    rec.bundle_id = info.bundle_id;
    rec.artifact_kind = static_cast<uint8_t>(info.artifact_kind);
    rec.is_valid = info.is_valid ? 1 : 0;
    std::string path = UTF8Utils::truncateToBytes(info.artifact_path, sizeof(rec.artifact_path));
    std::strncpy(rec.artifact_path, path.c_str(), sizeof(rec.artifact_path) - 1);
    std::string hash = UTF8Utils::truncateToBytes(info.content_hash, sizeof(rec.content_hash));
    std::strncpy(rec.content_hash, hash.c_str(), sizeof(rec.content_hash) - 1);
    rec.content_size_bytes = content_size_bytes;

    uint64_t xmin = 0;
    status = storeStringInToast(info.content_blob, xmin, rec.content_blob_oid, ctx);
    if (status != Status::OK)
    {
        return status;
    }

    rec.last_modified_time = (info.last_modified_time == 0) ? now : info.last_modified_time;
    auto existing_predicate = [&artifact_id](const ResourceArtifactRecord& row) {
        return row.artifact_id == artifact_id && row.is_valid == 1;
    };
    auto existing = findRecordInHeapPage<ResourceArtifactRecord>(
        resource_artifacts_table_page_, existing_predicate, ctx);
    if (existing.status == Status::OK)
    {
        rec.created_time = existing.record.created_time;
    }
    else if (existing.status == Status::NOT_FOUND)
    {
        rec.created_time = (info.created_time == 0) ? now : info.created_time;
    }
    else
    {
        return existing.status;
    }

    auto matcher = [&artifact_id](const ResourceArtifactRecord& row) {
        return row.artifact_id == artifact_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(resource_artifacts_table_page_, matcher, rec, ctx);
}

auto CatalogManager::getResourceArtifactCatalogEntry(const ID& artifact_id,
                                                     ResourceArtifactCatalogInfo& info_out,
                                                     ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    auto predicate = [&artifact_id](const ResourceArtifactRecord& rec) {
        return rec.artifact_id == artifact_id && rec.is_valid == 1;
    };
    auto result = findRecordInHeapPage<ResourceArtifactRecord>(resource_artifacts_table_page_, predicate, ctx);
    if (result.status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND, "Resource artifact not found");
        return Status::NOT_FOUND;
    }

    info_out = ResourceArtifactCatalogInfo{};
    info_out.artifact_id = result.record.artifact_id;
    info_out.bundle_id = result.record.bundle_id;
    info_out.artifact_kind = static_cast<ResourceArtifactKind>(result.record.artifact_kind);
    if (!isValidResourceArtifactKind(info_out.artifact_kind))
    {
        SET_ERROR_CONTEXT(ctx, Status::PAGE_CORRUPT, "Invalid resource_artifact.artifact_kind");
        return Status::PAGE_CORRUPT;
    }
    info_out.artifact_path =
        fixedNameFromBuffer(result.record.artifact_path, sizeof(result.record.artifact_path));
    info_out.content_hash = fixedNameFromBuffer(result.record.content_hash, sizeof(result.record.content_hash));
    info_out.content_size_bytes = result.record.content_size_bytes;
    info_out.is_valid = result.record.is_valid == 1;
    info_out.created_time = result.record.created_time;
    info_out.last_modified_time = result.record.last_modified_time;

    uint64_t xmin = 0;
    Status load_status =
        loadStringFromToast(result.record.content_blob_oid, xmin, info_out.content_blob, ctx);
    if (load_status != Status::OK)
    {
        return load_status;
    }
    return Status::OK;
}

auto CatalogManager::listResourceArtifactCatalogEntries(const ID& bundle_id,
                                                        std::vector<ResourceArtifactCatalogInfo>& rows_out,
                                                        ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    rows_out.clear();
    auto filter = [&bundle_id](const ResourceArtifactRecord& rec) {
        if (rec.is_valid != 1)
        {
            return false;
        }
        return isZeroUuidLocal(bundle_id) || rec.bundle_id == bundle_id;
    };
    auto converter = [this, ctx](const ResourceArtifactRecord& rec, ResourceArtifactCatalogInfo& info) {
        info = ResourceArtifactCatalogInfo{};
        info.artifact_id = rec.artifact_id;
        info.bundle_id = rec.bundle_id;
        info.artifact_kind = static_cast<ResourceArtifactKind>(rec.artifact_kind);
        info.artifact_path = fixedNameFromBuffer(rec.artifact_path, sizeof(rec.artifact_path));
        info.content_hash = fixedNameFromBuffer(rec.content_hash, sizeof(rec.content_hash));
        info.content_size_bytes = rec.content_size_bytes;
        info.is_valid = rec.is_valid == 1;
        info.created_time = rec.created_time;
        info.last_modified_time = rec.last_modified_time;

        uint64_t xmin = 0;
        std::string blob;
        if (loadStringFromToast(rec.content_blob_oid, xmin, blob, ctx) == Status::OK)
        {
            info.content_blob = std::move(blob);
        }
    };
    return readRecordsToVector<ResourceArtifactRecord, ResourceArtifactCatalogInfo>(
        resource_artifacts_table_page_, rows_out, filter, converter, ctx);
}

