auto CatalogManager::upsertTimezoneTransitionCatalogEntry(const TimezoneTransitionCatalogInfo& info,
                                                          ID& transition_id_out,
                                                          ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.timezone_id))
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "timezone_transition.timezone_uuid is required");
        return Status::INVALID_ARGUMENT;
    }
    if (isZeroUuidLocal(info.bundle_id))
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "timezone_transition.bundle_uuid is required");
        return Status::INVALID_ARGUMENT;
    }
    if (info.abbreviation.empty())
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "timezone_transition.abbr is required");
        return Status::INVALID_ARGUMENT;
    }
    Status status = UTF8Utils::validateStorageCapacity(info.abbreviation, 64, 64, ctx);
    if (status != Status::OK)
    {
        return status;
    }

    auto timezone_predicate = [&info](const TimezoneRecord& rec) {
        return rec.timezone_id == info.timezone_id && rec.is_valid == 1;
    };
    auto timezone_row = findRecordInHeapPage<TimezoneRecord>(timezones_table_page_, timezone_predicate, ctx);
    if (timezone_row.status != Status::OK)
    {
        if (timezone_row.status == Status::NOT_FOUND)
        {
            SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND, "Referenced timezone_uuid not found");
            return Status::NOT_FOUND;
        }
        return timezone_row.status;
    }

    auto bundle_predicate = [&info](const ResourceBundleRecord& rec) {
        return rec.bundle_id == info.bundle_id && rec.is_valid == 1;
    };
    auto bundle_row = findRecordInHeapPage<ResourceBundleRecord>(
        resource_bundles_table_page_, bundle_predicate, ctx);
    if (bundle_row.status != Status::OK)
    {
        if (bundle_row.status == Status::NOT_FOUND)
        {
            SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND, "Referenced bundle_uuid not found");
            return Status::NOT_FOUND;
        }
        return bundle_row.status;
    }

    ID transition_id = info.transition_id;
    if (isZeroUuidLocal(transition_id))
    {
        transition_id = generateUuidV7();
    }
    transition_id_out = transition_id;

    auto seq_duplicate_predicate = [&info, &transition_id](const TimezoneTransitionRecord& rec) {
        return rec.is_valid == 1 &&
               rec.transition_id != transition_id &&
               rec.timezone_id == info.timezone_id &&
               rec.sequence_no == info.sequence_no;
    };
    auto seq_duplicate = findRecordInHeapPage<TimezoneTransitionRecord>(
        timezone_transitions_table_page_, seq_duplicate_predicate, ctx);
    if (seq_duplicate.status == Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, Status::CONSTRAINT_VIOLATION,
                          "UNIQUE(timezone_uuid, sequence_no) violated");
        return Status::CONSTRAINT_VIOLATION;
    }
    if (seq_duplicate.status != Status::NOT_FOUND)
    {
        return seq_duplicate.status;
    }

    const std::string abbr_folded = canonicalIdentifierForLookup(info.abbreviation);
    auto full_duplicate_predicate =
        [&info, &transition_id, &abbr_folded](const TimezoneTransitionRecord& rec) {
            if (rec.is_valid != 1 || rec.transition_id == transition_id || rec.timezone_id != info.timezone_id)
            {
                return false;
            }
            if (rec.effective_utc_epoch != info.effective_utc_epoch ||
                rec.utc_offset_seconds != info.utc_offset_seconds ||
                (rec.is_dst != 0) != info.is_dst)
            {
                return false;
            }
            return canonicalIdentifierForLookup(
                       fixedNameFromBuffer(rec.abbreviation, sizeof(rec.abbreviation))) == abbr_folded;
        };
    auto full_duplicate = findRecordInHeapPage<TimezoneTransitionRecord>(
        timezone_transitions_table_page_, full_duplicate_predicate, ctx);
    if (full_duplicate.status == Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, Status::CONSTRAINT_VIOLATION,
                          "UNIQUE(timezone_uuid, effective_utc_epoch, utc_offset_seconds, is_dst, abbr) violated");
        return Status::CONSTRAINT_VIOLATION;
    }
    if (full_duplicate.status != Status::NOT_FOUND)
    {
        return full_duplicate.status;
    }

    const uint64_t now = catalogNowTicks();
    TimezoneTransitionRecord rec{};
    rec.transition_id = transition_id;
    rec.timezone_id = info.timezone_id;
    rec.bundle_id = info.bundle_id;
    rec.effective_utc_epoch = info.effective_utc_epoch;
    rec.utc_offset_seconds = info.utc_offset_seconds;
    rec.is_dst = info.is_dst ? 1 : 0;
    std::string abbr = UTF8Utils::truncateToBytes(info.abbreviation, sizeof(rec.abbreviation));
    std::strncpy(rec.abbreviation, abbr.c_str(), sizeof(rec.abbreviation) - 1);
    rec.sequence_no = info.sequence_no;
    rec.is_valid = info.is_valid ? 1 : 0;
    rec.last_modified_time = (info.last_modified_time == 0) ? now : info.last_modified_time;

    auto existing_predicate = [&transition_id](const TimezoneTransitionRecord& row) {
        return row.transition_id == transition_id && row.is_valid == 1;
    };
    auto existing = findRecordInHeapPage<TimezoneTransitionRecord>(
        timezone_transitions_table_page_, existing_predicate, ctx);
    if (existing.status == Status::OK)
    {
        rec.created_time = existing.record.created_time;
    }
    else if (existing.status == Status::NOT_FOUND)
    {
        rec.created_time = (info.created_time == 0) ? now : info.created_time;
    }
    else
    {
        return existing.status;
    }

    auto matcher = [&transition_id](const TimezoneTransitionRecord& row) {
        return row.transition_id == transition_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(timezone_transitions_table_page_, matcher, rec, ctx);
}

