auto CatalogManager::getReservedWordCatalogEntryByWord(const std::string& word,
                                                       EmulationEngine parser_scope,
                                                       ReservedWordCatalogInfo& info_out,
                                                       ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (word.empty())
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "reserved_words.word is required");
        return Status::INVALID_ARGUMENT;
    }
    if (!isValidEmulationEngine(parser_scope))
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "reserved_words.parser_scope is invalid");
        return Status::INVALID_ARGUMENT;
    }
    const std::string folded_word = canonicalIdentifierForLookup(word);
    auto predicate = [&folded_word, parser_scope](const ReservedWordRecord& rec) {
        if (rec.is_valid != 1 || rec.parser_scope != static_cast<uint8_t>(parser_scope))
        {
            return false;
        }
        return canonicalIdentifierForLookup(fixedNameFromBuffer(rec.word, sizeof(rec.word))) == folded_word;
    };
    auto result = findRecordInHeapPage<ReservedWordRecord>(reserved_words_table_page_, predicate, ctx);
    if (result.status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND, "reserved_words row not found");
        return Status::NOT_FOUND;
    }
    info_out = ReservedWordCatalogInfo{};
    info_out.reserved_word_id = result.record.reserved_word_id;
    info_out.word = fixedNameFromBuffer(result.record.word, sizeof(result.record.word));
    info_out.parser_scope = static_cast<EmulationEngine>(result.record.parser_scope);
    if (!isValidEmulationEngine(info_out.parser_scope))
    {
        SET_ERROR_CONTEXT(ctx, Status::PAGE_CORRUPT, "Invalid reserved_words.parser_scope");
        return Status::PAGE_CORRUPT;
    }
    info_out.is_reserved = result.record.is_reserved != 0;
    info_out.is_keyword = result.record.is_keyword != 0;
    info_out.last_updated_txid = result.record.last_updated_txid;
    info_out.is_valid = result.record.is_valid == 1;
    info_out.created_time = result.record.created_time;
    info_out.last_modified_time = result.record.last_modified_time;
    return Status::OK;
}

auto CatalogManager::listReservedWordCatalogEntries(
    EmulationEngine parser_scope_filter,
    std::vector<ReservedWordCatalogInfo>& rows_out,
    ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    rows_out.clear();
    if (parser_scope_filter != EmulationEngine::UNSPECIFIED &&
        !isValidEmulationEngine(parser_scope_filter))
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "reserved_words.parser_scope filter is invalid");
        return Status::INVALID_ARGUMENT;
    }
    auto filter = [parser_scope_filter](const ReservedWordRecord& rec) {
        if (rec.is_valid != 1)
        {
            return false;
        }
        return parser_scope_filter == EmulationEngine::UNSPECIFIED ||
               rec.parser_scope == static_cast<uint8_t>(parser_scope_filter);
    };
    auto converter = [](const ReservedWordRecord& rec, ReservedWordCatalogInfo& info) {
        info = ReservedWordCatalogInfo{};
        info.reserved_word_id = rec.reserved_word_id;
        info.word = fixedNameFromBuffer(rec.word, sizeof(rec.word));
        info.parser_scope = static_cast<EmulationEngine>(rec.parser_scope);
        info.is_reserved = rec.is_reserved != 0;
        info.is_keyword = rec.is_keyword != 0;
        info.last_updated_txid = rec.last_updated_txid;
        info.is_valid = rec.is_valid == 1;
        info.created_time = rec.created_time;
        info.last_modified_time = rec.last_modified_time;
    };
    return readRecordsToVector<ReservedWordRecord, ReservedWordCatalogInfo>(
        reserved_words_table_page_, rows_out, filter, converter, ctx);
}

auto CatalogManager::deleteReservedWordCatalogEntry(const ID& reserved_word_id,
                                                    ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    auto predicate = [&reserved_word_id](const ReservedWordRecord& rec) {
        return rec.reserved_word_id == reserved_word_id && rec.is_valid == 1;
    };
    auto result = findRecordInHeapPage<ReservedWordRecord>(reserved_words_table_page_, predicate, ctx);
    if (result.status != Status::OK)
    {
        return Status::NOT_FOUND;
    }

    ReservedWordRecord updated = result.record;
    updated.is_valid = 0;
    updated.last_modified_time = catalogNowTicks();
    return updateRecordInHeapPage(reserved_words_table_page_, result.slot_index, updated, ctx);
}

auto CatalogManager::upsertEmulationProfileCatalogEntry(const EmulationProfileCatalogInfo& info,
                                                        ID& emulation_profile_id_out,
                                                        ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (!isValidEmulationEngine(info.engine))
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "emulation_profile.engine is invalid");
        return Status::INVALID_ARGUMENT;
    }
    if (info.enabled)
    {
        if (!isValidStorageProfile(info.storage_profile))
        {
            SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "emulation_profile.storage_profile is required");
            return Status::INVALID_ARGUMENT;
        }
        if (info.requested_engine_version.empty())
        {
            SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT,
                              "emulation_profile.requested_engine_version is required when enabled");
            return Status::INVALID_ARGUMENT;
        }
    }
    if (!info.requested_engine_version.empty())
    {
        Status status = UTF8Utils::validateStorageCapacity(info.requested_engine_version, 64, 63, ctx);
        if (status != Status::OK)
        {
            return status;
        }
    }

    ID emulation_profile_id = info.emulation_profile_id;
    if (isZeroUuidLocal(emulation_profile_id))
    {
        emulation_profile_id = generateUuidV7();
    }
    emulation_profile_id_out = emulation_profile_id;

    auto duplicate_predicate = [&emulation_profile_id, &info](const EmulationProfileRecord& rec) {
        return rec.is_valid == 1 &&
               rec.emulation_profile_id != emulation_profile_id &&
               rec.engine == static_cast<uint8_t>(info.engine);
    };
    auto duplicate = findRecordInHeapPage<EmulationProfileRecord>(
        emulation_profile_table_page_, duplicate_predicate, ctx);
    if (duplicate.status == Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, Status::CONSTRAINT_VIOLATION, "UNIQUE(emulation_profile.engine) violated");
        return Status::CONSTRAINT_VIOLATION;
    }
    if (duplicate.status != Status::NOT_FOUND)
    {
        return duplicate.status;
    }

    const uint64_t now = catalogNowTicks();
    EmulationProfileRecord rec{};
    rec.emulation_profile_id = emulation_profile_id;
    rec.engine = static_cast<uint8_t>(info.engine);
    rec.enabled = info.enabled ? 1 : 0;
    rec.storage_profile = isValidStorageProfile(info.storage_profile)
        ? static_cast<uint8_t>(info.storage_profile)
        : static_cast<uint8_t>(StorageProfile::RELATIONAL);
    rec.is_valid = info.is_valid ? 1 : 0;
    if (!info.requested_engine_version.empty())
    {
        std::string version =
            UTF8Utils::truncateToBytes(info.requested_engine_version, sizeof(rec.requested_engine_version));
        std::strncpy(rec.requested_engine_version, version.c_str(), sizeof(rec.requested_engine_version) - 1);
    }
    rec.installed_txid = info.installed_txid;
    rec.last_modified_txid = info.last_modified_txid;
    rec.config_flags = info.config_flags;
    rec.last_modified_time = (info.last_modified_time == 0) ? now : info.last_modified_time;

    auto existing_predicate = [&emulation_profile_id](const EmulationProfileRecord& row) {
        return row.emulation_profile_id == emulation_profile_id && row.is_valid == 1;
    };
    auto existing = findRecordInHeapPage<EmulationProfileRecord>(
        emulation_profile_table_page_, existing_predicate, ctx);
    if (existing.status == Status::OK)
    {
        rec.created_time = existing.record.created_time;
    }
    else if (existing.status == Status::NOT_FOUND)
    {
        rec.created_time = (info.created_time == 0) ? now : info.created_time;
    }
    else
    {
        return existing.status;
    }

    auto matcher = [&emulation_profile_id](const EmulationProfileRecord& row) {
        return row.emulation_profile_id == emulation_profile_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(emulation_profile_table_page_, matcher, rec, ctx);
}

