auto CatalogManager::upsertParserProfileCatalogEntry(const ParserProfileCatalogInfo& info,
                                                     ID& parser_profile_id_out,
                                                     ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (info.profile_name.empty())
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "parser_profile.profile_name is required");
        return Status::INVALID_ARGUMENT;
    }
    if (!isValidEmulationEngine(info.parser_engine))
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "parser_profile.parser_engine is invalid");
        return Status::INVALID_ARGUMENT;
    }
    if (info.is_native && info.parser_engine != EmulationEngine::NATIVE)
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT,
                          "parser_profile.is_native requires parser_engine=NATIVE");
        return Status::INVALID_ARGUMENT;
    }
    if (info.profile_hash.empty())
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "parser_profile.profile_hash is required");
        return Status::INVALID_ARGUMENT;
    }

    Status status = UTF8Utils::validateStorageCapacity(info.profile_name, 128, 127, ctx);
    if (status != Status::OK)
    {
        return status;
    }
    status = UTF8Utils::validateStorageCapacity(info.profile_hash, 64, 64, ctx);
    if (status != Status::OK)
    {
        return status;
    }

    const std::string folded_name = canonicalIdentifierForLookup(info.profile_name);
    const std::string folded_hash = canonicalIdentifierForLookup(info.profile_hash);

    ID parser_profile_id = info.parser_profile_id;
    if (isZeroUuidLocal(parser_profile_id))
    {
        parser_profile_id = generateUuidV7();
    }
    parser_profile_id_out = parser_profile_id;

    auto duplicate_name_predicate = [&folded_name, &parser_profile_id](const ParserProfileRecord& rec) {
        if (rec.is_valid != 1 || rec.parser_profile_id == parser_profile_id)
        {
            return false;
        }
        return canonicalIdentifierForLookup(
            fixedNameFromBuffer(rec.profile_name, sizeof(rec.profile_name))) == folded_name;
    };
    auto duplicate_name = findRecordInHeapPage<ParserProfileRecord>(
        parser_profiles_table_page_, duplicate_name_predicate, ctx);
    if (duplicate_name.status == Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, Status::CONSTRAINT_VIOLATION, "UNIQUE(parser_profile.profile_name) violated");
        return Status::CONSTRAINT_VIOLATION;
    }
    if (duplicate_name.status != Status::NOT_FOUND)
    {
        return duplicate_name.status;
    }

    auto duplicate_version_predicate = [&info, &parser_profile_id](const ParserProfileRecord& rec) {
        return rec.is_valid == 1 &&
               rec.parser_profile_id != parser_profile_id &&
               rec.parser_engine == static_cast<uint8_t>(info.parser_engine) &&
               rec.version_major == info.version_major &&
               rec.version_minor == info.version_minor;
    };
    auto duplicate_version = findRecordInHeapPage<ParserProfileRecord>(
        parser_profiles_table_page_, duplicate_version_predicate, ctx);
    if (duplicate_version.status == Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, Status::CONSTRAINT_VIOLATION,
                          "UNIQUE(parser_engine, version_major, version_minor) violated");
        return Status::CONSTRAINT_VIOLATION;
    }
    if (duplicate_version.status != Status::NOT_FOUND)
    {
        return duplicate_version.status;
    }

    if (info.is_default)
    {
        auto default_conflict_predicate = [&info, &parser_profile_id](const ParserProfileRecord& rec) {
            return rec.is_valid == 1 &&
                   rec.parser_profile_id != parser_profile_id &&
                   rec.parser_engine == static_cast<uint8_t>(info.parser_engine) &&
                   rec.is_default == 1;
        };
        auto default_conflict = findRecordInHeapPage<ParserProfileRecord>(
            parser_profiles_table_page_, default_conflict_predicate, ctx);
        if (default_conflict.status == Status::OK)
        {
            SET_ERROR_CONTEXT(ctx, Status::CONSTRAINT_VIOLATION,
                              "Only one default parser profile is allowed per parser_engine");
            return Status::CONSTRAINT_VIOLATION;
        }
        if (default_conflict.status != Status::NOT_FOUND)
        {
            return default_conflict.status;
        }
    }

    if (!isZeroUuidLocal(info.base_profile_id))
    {
        auto base_predicate = [&info](const ParserProfileRecord& rec) {
            return rec.is_valid == 1 && rec.parser_profile_id == info.base_profile_id;
        };
        auto base_row = findRecordInHeapPage<ParserProfileRecord>(
            parser_profiles_table_page_, base_predicate, ctx);
        if (base_row.status != Status::OK)
        {
            if (base_row.status == Status::NOT_FOUND)
            {
                SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND, "parser_profile.base_profile_uuid not found");
                return Status::NOT_FOUND;
            }
            return base_row.status;
        }
        if (base_row.record.parser_engine != static_cast<uint8_t>(info.parser_engine))
        {
            SET_ERROR_CONTEXT(ctx, Status::CONSTRAINT_VIOLATION,
                              "base_profile_uuid must reference the same parser_engine");
            return Status::CONSTRAINT_VIOLATION;
        }
    }

    const uint64_t now = catalogNowTicks();
    ParserProfileRecord rec{};
    rec.parser_profile_id = parser_profile_id;
    rec.parser_engine = static_cast<uint8_t>(info.parser_engine);
    rec.is_native = info.is_native ? 1 : 0;
    rec.is_default = info.is_default ? 1 : 0;
    rec.is_enabled = info.is_enabled ? 1 : 0;
    rec.is_valid = info.is_valid ? 1 : 0;
    rec.version_major = info.version_major;
    rec.version_minor = info.version_minor;
    std::string stored_profile_name = UTF8Utils::truncateToBytes(info.profile_name, sizeof(rec.profile_name));
    std::strncpy(rec.profile_name, stored_profile_name.c_str(), sizeof(rec.profile_name) - 1);
    std::string stored_hash = UTF8Utils::truncateToBytes(folded_hash, sizeof(rec.profile_hash));
    std::strncpy(rec.profile_hash, stored_hash.c_str(), sizeof(rec.profile_hash) - 1);
    rec.base_profile_id = info.base_profile_id;
    rec.last_modified_time = (info.last_modified_time == 0) ? now : info.last_modified_time;

    auto existing_predicate = [&parser_profile_id](const ParserProfileRecord& row) {
        return row.parser_profile_id == parser_profile_id && row.is_valid == 1;
    };
    auto existing = findRecordInHeapPage<ParserProfileRecord>(
        parser_profiles_table_page_, existing_predicate, ctx);
    if (existing.status == Status::OK)
    {
        rec.created_time = existing.record.created_time;
    }
    else if (existing.status == Status::NOT_FOUND)
    {
        rec.created_time = (info.created_time == 0) ? now : info.created_time;
    }
    else
    {
        return existing.status;
    }

    auto matcher = [&parser_profile_id](const ParserProfileRecord& row) {
        return row.parser_profile_id == parser_profile_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(parser_profiles_table_page_, matcher, rec, ctx);
}

