auto CatalogManager::listParserCapabilityCatalogEntries(
    const ID& parser_profile_id,
    const std::string& feature_family,
    std::vector<ParserCapabilityCatalogInfo>& rows_out,
    ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    rows_out.clear();
    const std::string family_filter = canonicalIdentifierForLookup(feature_family);
    auto filter = [&parser_profile_id, &family_filter](const ParserCapabilityRecord& rec) {
        if (rec.is_valid != 1)
        {
            return false;
        }
        if (!isZeroUuidLocal(parser_profile_id) && rec.parser_profile_id != parser_profile_id)
        {
            return false;
        }
        if (!family_filter.empty())
        {
            return canonicalIdentifierForLookup(
                       fixedNameFromBuffer(rec.feature_family, sizeof(rec.feature_family))) == family_filter;
        }
        return true;
    };
    auto converter = [this, ctx](const ParserCapabilityRecord& rec, ParserCapabilityCatalogInfo& info) {
        info = ParserCapabilityCatalogInfo{};
        info.parser_capability_id = rec.parser_capability_id;
        info.parser_profile_id = rec.parser_profile_id;
        info.feature_family = fixedNameFromBuffer(rec.feature_family, sizeof(rec.feature_family));
        info.feature_key = fixedNameFromBuffer(rec.feature_key, sizeof(rec.feature_key));
        info.capability_action = static_cast<ParserCapabilityAction>(rec.capability_action);
        info.parser_transform_id = rec.parser_transform_id;
        info.reject_code = fixedNameFromBuffer(rec.reject_code, sizeof(rec.reject_code));
        info.precedence_rank = rec.precedence_rank;
        info.is_enabled = rec.is_enabled != 0;
        info.is_valid = rec.is_valid == 1;
        info.created_time = rec.created_time;
        info.last_modified_time = rec.last_modified_time;
        if (!isZeroUuidLocal(rec.notes_oid))
        {
            uint64_t xmin = 0;
            std::string notes;
            if (loadStringFromToast(rec.notes_oid, xmin, notes, ctx) == Status::OK)
            {
                info.notes = std::move(notes);
            }
        }
    };
    return readRecordsToVector<ParserCapabilityRecord, ParserCapabilityCatalogInfo>(
        parser_capability_entries_table_page_, rows_out, filter, converter, ctx);
}

