auto CatalogManager::upsertParserErrorMapCatalogEntry(const ParserErrorMapCatalogInfo& info,
                                                      ID& parser_error_map_id_out,
                                                      ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.parser_profile_id))
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "parser_error_map_entry.parser_profile_uuid is required");
        return Status::INVALID_ARGUMENT;
    }
    if (info.reject_code.empty() || info.dialect_sqlstate.empty() || info.dialect_error_code.empty() ||
        info.message_template.empty())
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT,
                          "parser_error_map_entry reject_code/sqlstate/error_code/message are required");
        return Status::INVALID_ARGUMENT;
    }
    if (!isValidParserErrorSeverity(info.error_severity))
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "parser_error_map_entry.error_severity is invalid");
        return Status::INVALID_ARGUMENT;
    }

    Status status = UTF8Utils::validateStorageCapacity(info.reject_code, 64, 63, ctx);
    if (status != Status::OK)
    {
        return status;
    }
    status = UTF8Utils::validateStorageCapacity(info.dialect_sqlstate, 32, 31, ctx);
    if (status != Status::OK)
    {
        return status;
    }
    status = UTF8Utils::validateStorageCapacity(info.dialect_error_code, 64, 63, ctx);
    if (status != Status::OK)
    {
        return status;
    }

    auto profile_predicate = [&info](const ParserProfileRecord& rec) {
        return rec.is_valid == 1 && rec.parser_profile_id == info.parser_profile_id;
    };
    auto profile_row = findRecordInHeapPage<ParserProfileRecord>(parser_profiles_table_page_, profile_predicate, ctx);
    if (profile_row.status != Status::OK)
    {
        if (profile_row.status == Status::NOT_FOUND)
        {
            SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND, "Referenced parser_profile_uuid not found");
            return Status::NOT_FOUND;
        }
        return profile_row.status;
    }

    ID parser_error_map_id = info.parser_error_map_id;
    if (isZeroUuidLocal(parser_error_map_id))
    {
        parser_error_map_id = generateUuidV7();
    }
    parser_error_map_id_out = parser_error_map_id;

    const std::string folded_reject_code = canonicalIdentifierForLookup(info.reject_code);
    auto duplicate_predicate = [&info, &folded_reject_code, &parser_error_map_id](
                                   const ParserErrorMapRecord& rec) {
        if (rec.is_valid != 1 || rec.parser_error_map_id == parser_error_map_id)
        {
            return false;
        }
        if (rec.parser_profile_id != info.parser_profile_id)
        {
            return false;
        }
        return canonicalIdentifierForLookup(
            fixedNameFromBuffer(rec.reject_code, sizeof(rec.reject_code))) == folded_reject_code;
    };
    auto duplicate = findRecordInHeapPage<ParserErrorMapRecord>(
        parser_error_map_entries_table_page_, duplicate_predicate, ctx);
    if (duplicate.status == Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, Status::CONSTRAINT_VIOLATION,
                          "UNIQUE(parser_profile_uuid, reject_code) violated");
        return Status::CONSTRAINT_VIOLATION;
    }
    if (duplicate.status != Status::NOT_FOUND)
    {
        return duplicate.status;
    }

    const uint64_t now = catalogNowTicks();
    ParserErrorMapRecord rec{};
    rec.parser_error_map_id = parser_error_map_id;
    rec.parser_profile_id = info.parser_profile_id;
    std::string reject_code = UTF8Utils::truncateToBytes(folded_reject_code, sizeof(rec.reject_code));
    std::string sqlstate = UTF8Utils::truncateToBytes(info.dialect_sqlstate, sizeof(rec.dialect_sqlstate));
    std::string dialect_error_code =
        UTF8Utils::truncateToBytes(info.dialect_error_code, sizeof(rec.dialect_error_code));
    std::strncpy(rec.reject_code, reject_code.c_str(), sizeof(rec.reject_code) - 1);
    std::strncpy(rec.dialect_sqlstate, sqlstate.c_str(), sizeof(rec.dialect_sqlstate) - 1);
    std::strncpy(rec.dialect_error_code, dialect_error_code.c_str(), sizeof(rec.dialect_error_code) - 1);
    rec.error_severity = static_cast<uint8_t>(info.error_severity);
    rec.is_retryable = info.is_retryable ? 1 : 0;
    rec.is_enabled = info.is_enabled ? 1 : 0;
    rec.is_valid = info.is_valid ? 1 : 0;
    rec.last_modified_time = (info.last_modified_time == 0) ? now : info.last_modified_time;

    uint64_t xmin = 0;
    status = storeStringInToast(info.message_template, xmin, rec.message_template_oid, ctx);
    if (status != Status::OK)
    {
        return status;
    }
    if (info.hint_template.has_value() && !info.hint_template.value().empty())
    {
        status = storeStringInToast(info.hint_template.value(), xmin, rec.hint_template_oid, ctx);
        if (status != Status::OK)
        {
            return status;
        }
    }

    auto existing_predicate = [&parser_error_map_id](const ParserErrorMapRecord& row) {
        return row.parser_error_map_id == parser_error_map_id && row.is_valid == 1;
    };
    auto existing = findRecordInHeapPage<ParserErrorMapRecord>(
        parser_error_map_entries_table_page_, existing_predicate, ctx);
    if (existing.status == Status::OK)
    {
        rec.created_time = existing.record.created_time;
    }
    else if (existing.status == Status::NOT_FOUND)
    {
        rec.created_time = (info.created_time == 0) ? now : info.created_time;
    }
    else
    {
        return existing.status;
    }

    auto matcher = [&parser_error_map_id](const ParserErrorMapRecord& row) {
        return row.parser_error_map_id == parser_error_map_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(parser_error_map_entries_table_page_, matcher, rec, ctx);
}

