auto CatalogManager::upsertParserFeaturePrecedenceCatalogEntry(
    const ParserFeaturePrecedenceCatalogInfo& info,
    ID& parser_feature_precedence_id_out,
    ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.parser_profile_id))
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT,
                          "parser_feature_precedence.parser_profile_uuid is required");
        return Status::INVALID_ARGUMENT;
    }
    if (info.feature_family.empty() || info.feature_key.empty())
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT,
                          "parser_feature_precedence.feature_family and feature_key are required");
        return Status::INVALID_ARGUMENT;
    }
    if (!isValidParserPrecedenceTiebreak(info.precedence_tiebreak))
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT,
                          "parser_feature_precedence.precedence_tiebreak is invalid");
        return Status::INVALID_ARGUMENT;
    }

    Status status = UTF8Utils::validateStorageCapacity(info.feature_family, 128, 127, ctx);
    if (status != Status::OK)
    {
        return status;
    }
    status = UTF8Utils::validateStorageCapacity(info.feature_key, 128, 127, ctx);
    if (status != Status::OK)
    {
        return status;
    }

    auto profile_predicate = [&info](const ParserProfileRecord& rec) {
        return rec.is_valid == 1 && rec.parser_profile_id == info.parser_profile_id;
    };
    auto profile_row = findRecordInHeapPage<ParserProfileRecord>(parser_profiles_table_page_, profile_predicate, ctx);
    if (profile_row.status != Status::OK)
    {
        if (profile_row.status == Status::NOT_FOUND)
        {
            SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND, "Referenced parser_profile_uuid not found");
            return Status::NOT_FOUND;
        }
        return profile_row.status;
    }

    ID parser_feature_precedence_id = info.parser_feature_precedence_id;
    if (isZeroUuidLocal(parser_feature_precedence_id))
    {
        parser_feature_precedence_id = generateUuidV7();
    }
    parser_feature_precedence_id_out = parser_feature_precedence_id;

    const std::string folded_family = canonicalIdentifierForLookup(info.feature_family);
    const std::string folded_key = canonicalIdentifierForLookup(info.feature_key);

    auto duplicate_key_predicate = [&info, &folded_family, &folded_key, &parser_feature_precedence_id](
                                       const ParserFeaturePrecedenceRecord& rec) {
        if (rec.is_valid != 1 || rec.parser_feature_precedence_id == parser_feature_precedence_id)
        {
            return false;
        }
        if (rec.parser_profile_id != info.parser_profile_id)
        {
            return false;
        }
        const std::string rec_family =
            canonicalIdentifierForLookup(fixedNameFromBuffer(rec.feature_family, sizeof(rec.feature_family)));
        const std::string rec_key =
            canonicalIdentifierForLookup(fixedNameFromBuffer(rec.feature_key, sizeof(rec.feature_key)));
        return rec_family == folded_family && rec_key == folded_key;
    };
    auto duplicate_key = findRecordInHeapPage<ParserFeaturePrecedenceRecord>(
        parser_feature_precedence_table_page_, duplicate_key_predicate, ctx);
    if (duplicate_key.status == Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, Status::CONSTRAINT_VIOLATION,
                          "UNIQUE(parser_profile_uuid, feature_family, feature_key) violated");
        return Status::CONSTRAINT_VIOLATION;
    }
    if (duplicate_key.status != Status::NOT_FOUND)
    {
        return duplicate_key.status;
    }

    auto duplicate_rank_predicate = [&info, &folded_family, &parser_feature_precedence_id](
                                        const ParserFeaturePrecedenceRecord& rec) {
        if (rec.is_valid != 1 || rec.parser_feature_precedence_id == parser_feature_precedence_id)
        {
            return false;
        }
        if (rec.parser_profile_id != info.parser_profile_id || rec.precedence_rank != info.precedence_rank)
        {
            return false;
        }
        return canonicalIdentifierForLookup(
                   fixedNameFromBuffer(rec.feature_family, sizeof(rec.feature_family))) == folded_family;
    };
    auto duplicate_rank = findRecordInHeapPage<ParserFeaturePrecedenceRecord>(
        parser_feature_precedence_table_page_, duplicate_rank_predicate, ctx);
    if (duplicate_rank.status == Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, Status::CONSTRAINT_VIOLATION,
                          "UNIQUE(parser_profile_uuid, feature_family, precedence_rank) violated");
        return Status::CONSTRAINT_VIOLATION;
    }
    if (duplicate_rank.status != Status::NOT_FOUND)
    {
        return duplicate_rank.status;
    }

    const uint64_t now = catalogNowTicks();
    ParserFeaturePrecedenceRecord rec{};
    rec.parser_feature_precedence_id = parser_feature_precedence_id;
    rec.parser_profile_id = info.parser_profile_id;
    std::string feature_family = UTF8Utils::truncateToBytes(folded_family, sizeof(rec.feature_family));
    std::string feature_key = UTF8Utils::truncateToBytes(folded_key, sizeof(rec.feature_key));
    std::strncpy(rec.feature_family, feature_family.c_str(), sizeof(rec.feature_family) - 1);
    std::strncpy(rec.feature_key, feature_key.c_str(), sizeof(rec.feature_key) - 1);
    rec.precedence_rank = info.precedence_rank;
    rec.precedence_tiebreak = static_cast<uint8_t>(info.precedence_tiebreak);
    rec.is_terminal = info.is_terminal ? 1 : 0;
    rec.is_enabled = info.is_enabled ? 1 : 0;
    rec.is_valid = info.is_valid ? 1 : 0;
    rec.last_modified_time = (info.last_modified_time == 0) ? now : info.last_modified_time;

    auto existing_predicate = [&parser_feature_precedence_id](const ParserFeaturePrecedenceRecord& row) {
        return row.parser_feature_precedence_id == parser_feature_precedence_id && row.is_valid == 1;
    };
    auto existing = findRecordInHeapPage<ParserFeaturePrecedenceRecord>(
        parser_feature_precedence_table_page_, existing_predicate, ctx);
    if (existing.status == Status::OK)
    {
        rec.created_time = existing.record.created_time;
    }
    else if (existing.status == Status::NOT_FOUND)
    {
        rec.created_time = (info.created_time == 0) ? now : info.created_time;
    }
    else
    {
        return existing.status;
    }

    auto matcher = [&parser_feature_precedence_id](const ParserFeaturePrecedenceRecord& row) {
        return row.parser_feature_precedence_id == parser_feature_precedence_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(parser_feature_precedence_table_page_, matcher, rec, ctx);
}

auto CatalogManager::getParserFeaturePrecedenceCatalogEntry(
    const ID& parser_feature_precedence_id,
    ParserFeaturePrecedenceCatalogInfo& info_out,
    ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    auto predicate = [&parser_feature_precedence_id](const ParserFeaturePrecedenceRecord& rec) {
        return rec.parser_feature_precedence_id == parser_feature_precedence_id && rec.is_valid == 1;
    };
    auto result = findRecordInHeapPage<ParserFeaturePrecedenceRecord>(
        parser_feature_precedence_table_page_, predicate, ctx);
    if (result.status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND, "parser_feature_precedence row not found");
        return Status::NOT_FOUND;
    }

    info_out = ParserFeaturePrecedenceCatalogInfo{};
    info_out.parser_feature_precedence_id = result.record.parser_feature_precedence_id;
    info_out.parser_profile_id = result.record.parser_profile_id;
    info_out.feature_family =
        fixedNameFromBuffer(result.record.feature_family, sizeof(result.record.feature_family));
    info_out.feature_key =
        fixedNameFromBuffer(result.record.feature_key, sizeof(result.record.feature_key));
    info_out.precedence_rank = result.record.precedence_rank;
    info_out.precedence_tiebreak =
        static_cast<ParserPrecedenceTiebreak>(result.record.precedence_tiebreak);
    if (!isValidParserPrecedenceTiebreak(info_out.precedence_tiebreak))
    {
        SET_ERROR_CONTEXT(ctx, Status::PAGE_CORRUPT,
                          "Invalid parser_feature_precedence.precedence_tiebreak");
        return Status::PAGE_CORRUPT;
    }
    info_out.is_terminal = result.record.is_terminal != 0;
    info_out.is_enabled = result.record.is_enabled != 0;
    info_out.is_valid = result.record.is_valid == 1;
    info_out.created_time = result.record.created_time;
    info_out.last_modified_time = result.record.last_modified_time;
    return Status::OK;
}

auto CatalogManager::listParserFeaturePrecedenceCatalogEntries(
    const ID& parser_profile_id,
    const std::string& feature_family,
    std::vector<ParserFeaturePrecedenceCatalogInfo>& rows_out,
    ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    rows_out.clear();
    const std::string family_filter = canonicalIdentifierForLookup(feature_family);
    auto filter = [&parser_profile_id, &family_filter](const ParserFeaturePrecedenceRecord& rec) {
        if (rec.is_valid != 1)
        {
            return false;
        }
        if (!isZeroUuidLocal(parser_profile_id) && rec.parser_profile_id != parser_profile_id)
        {
            return false;
        }
        if (!family_filter.empty())
        {
            return canonicalIdentifierForLookup(
                       fixedNameFromBuffer(rec.feature_family, sizeof(rec.feature_family))) == family_filter;
        }
        return true;
    };
    auto converter = [](const ParserFeaturePrecedenceRecord& rec, ParserFeaturePrecedenceCatalogInfo& info) {
        info = ParserFeaturePrecedenceCatalogInfo{};
        info.parser_feature_precedence_id = rec.parser_feature_precedence_id;
        info.parser_profile_id = rec.parser_profile_id;
        info.feature_family = fixedNameFromBuffer(rec.feature_family, sizeof(rec.feature_family));
        info.feature_key = fixedNameFromBuffer(rec.feature_key, sizeof(rec.feature_key));
        info.precedence_rank = rec.precedence_rank;
        info.precedence_tiebreak = static_cast<ParserPrecedenceTiebreak>(rec.precedence_tiebreak);
        info.is_terminal = rec.is_terminal != 0;
        info.is_enabled = rec.is_enabled != 0;
        info.is_valid = rec.is_valid == 1;
        info.created_time = rec.created_time;
        info.last_modified_time = rec.last_modified_time;
    };
    Status status = readRecordsToVector<ParserFeaturePrecedenceRecord, ParserFeaturePrecedenceCatalogInfo>(
        parser_feature_precedence_table_page_, rows_out, filter, converter, ctx);
    if (status != Status::OK)
    {
        return status;
    }
    std::sort(rows_out.begin(), rows_out.end(),
              [](const ParserFeaturePrecedenceCatalogInfo& lhs,
                 const ParserFeaturePrecedenceCatalogInfo& rhs) {
                  if (lhs.precedence_rank != rhs.precedence_rank)
                  {
                      return lhs.precedence_rank < rhs.precedence_rank;
                  }
                  const std::string lhs_key = canonicalIdentifierForLookup(lhs.feature_key);
                  const std::string rhs_key = canonicalIdentifierForLookup(rhs.feature_key);
                  if (lhs_key != rhs_key)
                  {
                      return lhs_key < rhs_key;
                  }
                  return lhs.parser_feature_precedence_id.bytes <
                         rhs.parser_feature_precedence_id.bytes;
              });
    return Status::OK;
}

auto CatalogManager::deleteParserFeaturePrecedenceCatalogEntry(
    const ID& parser_feature_precedence_id,
    ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    auto predicate = [&parser_feature_precedence_id](const ParserFeaturePrecedenceRecord& rec) {
        return rec.parser_feature_precedence_id == parser_feature_precedence_id && rec.is_valid == 1;
    };
    auto result = findRecordInHeapPage<ParserFeaturePrecedenceRecord>(
        parser_feature_precedence_table_page_, predicate, ctx);
    if (result.status != Status::OK)
    {
        return Status::NOT_FOUND;
    }
    ParserFeaturePrecedenceRecord updated = result.record;
    updated.is_valid = 0;
    updated.last_modified_time = catalogNowTicks();
    return updateRecordInHeapPage(parser_feature_precedence_table_page_, result.slot_index, updated, ctx);
}

