// Canonical index metadata extension catalog CRUD operations (CAT-016)
// ============================================================================

auto CatalogManager::upsertIndexAccessMethodCatalogEntry(const IndexAccessMethodCatalogInfo& info,
                                                         ID& access_method_id_out,
                                                         ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (info.method_name.empty())
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "index_access_method.method_name is required");
        return Status::INVALID_ARGUMENT;
    }
    if (info.index_type_name.empty())
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "index_access_method.index_type_name is required");
        return Status::INVALID_ARGUMENT;
    }
    Status status = UTF8Utils::validateStorageCapacity(info.method_name, 128, 127, ctx);
    if (status != Status::OK)
    {
        return status;
    }
    status = UTF8Utils::validateStorageCapacity(info.index_type_name, 64, 63, ctx);
    if (status != Status::OK)
    {
        return status;
    }
    const std::string folded_method_name = canonicalIdentifierForLookup(info.method_name);
    const std::string folded_index_type = canonicalIdentifierForLookup(info.index_type_name);
    if (!isValidCanonicalIndexTypeName(folded_index_type))
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "index_access_method.index_type_name is invalid");
        return Status::INVALID_ARGUMENT;
    }
    if (!isZeroUuidLocal(info.handler_udr_id))
    {
        auto udr_predicate = [&info](const UDRRecord& rec) {
            return rec.is_valid == 1 && rec.udr_id == info.handler_udr_id;
        };
        auto udr_result = findRecordInHeapPage<UDRRecord>(udr_table_page_, udr_predicate, ctx);
        if (udr_result.status != Status::OK)
        {
            SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND, "index_access_method.handler_udr_uuid not found");
            return Status::NOT_FOUND;
        }
    }

    ID access_method_id = info.access_method_id;
    if (isZeroUuidLocal(access_method_id))
    {
        access_method_id = generateUuidV7();
    }
    access_method_id_out = access_method_id;

    auto duplicate_predicate = [&access_method_id, &folded_method_name](const IndexAccessMethodRecord& rec) {
        if (rec.is_valid != 1 || rec.access_method_id == access_method_id)
        {
            return false;
        }
        return canonicalIdentifierForLookup(
            fixedNameFromBuffer(rec.method_name, sizeof(rec.method_name))) == folded_method_name;
    };
    auto duplicate = findRecordInHeapPage<IndexAccessMethodRecord>(
        index_access_methods_table_page_, duplicate_predicate, ctx);
    if (duplicate.status == Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, Status::CONSTRAINT_VIOLATION,
                          "UNIQUE(index_access_method.method_name) violated");
        return Status::CONSTRAINT_VIOLATION;
    }
    if (duplicate.status != Status::NOT_FOUND)
    {
        return duplicate.status;
    }

    const uint64_t now = catalogNowTicks();
    IndexAccessMethodRecord rec{};
    rec.access_method_id = access_method_id;
    std::string method_name = UTF8Utils::truncateToBytes(folded_method_name, sizeof(rec.method_name));
    std::strncpy(rec.method_name, method_name.c_str(), sizeof(rec.method_name) - 1);
    std::string index_type_name = UTF8Utils::truncateToBytes(folded_index_type, sizeof(rec.index_type_name));
    std::strncpy(rec.index_type_name, index_type_name.c_str(), sizeof(rec.index_type_name) - 1);
    rec.handler_udr_id = info.handler_udr_id;
    rec.supports_unique = info.supports_unique ? 1 : 0;
    rec.supports_multicolumn = info.supports_multicolumn ? 1 : 0;
    rec.supports_include = info.supports_include ? 1 : 0;
    rec.supports_partial = info.supports_partial ? 1 : 0;
    rec.supports_order = info.supports_order ? 1 : 0;
    rec.supports_nulls_order = info.supports_nulls_order ? 1 : 0;
    rec.supports_concurrent = info.supports_concurrent ? 1 : 0;
    rec.default_fillfactor = info.default_fillfactor;
    rec.is_system = info.is_system ? 1 : 0;
    rec.is_valid = info.is_valid ? 1 : 0;
    rec.last_modified_time = (info.last_modified_time == 0) ? now : info.last_modified_time;

    auto existing_predicate = [&access_method_id](const IndexAccessMethodRecord& row) {
        return row.access_method_id == access_method_id && row.is_valid == 1;
    };
    auto existing = findRecordInHeapPage<IndexAccessMethodRecord>(
        index_access_methods_table_page_, existing_predicate, ctx);
    if (existing.status == Status::OK)
    {
        rec.created_time = existing.record.created_time;
    }
    else if (existing.status == Status::NOT_FOUND)
    {
        rec.created_time = (info.created_time == 0) ? now : info.created_time;
    }
    else
    {
        return existing.status;
    }

    auto matcher = [&access_method_id](const IndexAccessMethodRecord& row) {
        return row.access_method_id == access_method_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(index_access_methods_table_page_, matcher, rec, ctx);
}

