auto CatalogManager::upsertIndexOpclassCatalogEntry(const IndexOpclassCatalogInfo& info,
                                                    ID& opclass_id_out,
                                                    ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (info.opclass_name.empty())
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "index_opclass.name is required");
        return Status::INVALID_ARGUMENT;
    }
    if (info.index_type_name.empty())
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "index_opclass.index_type is required");
        return Status::INVALID_ARGUMENT;
    }
    if (isZeroUuidLocal(info.input_type_id) || isZeroUuidLocal(info.owner_schema_id))
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT,
                          "index_opclass.input_type_uuid and owner_schema_uuid are required");
        return Status::INVALID_ARGUMENT;
    }
    Status status = UTF8Utils::validateStorageCapacity(info.opclass_name, 128, 127, ctx);
    if (status != Status::OK)
    {
        return status;
    }
    status = UTF8Utils::validateStorageCapacity(info.index_type_name, 64, 63, ctx);
    if (status != Status::OK)
    {
        return status;
    }
    const std::string folded_name = canonicalIdentifierForLookup(info.opclass_name);
    const std::string folded_type = canonicalIdentifierForLookup(info.index_type_name);
    if (!isValidCanonicalIndexTypeName(folded_type))
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "index_opclass.index_type is invalid");
        return Status::INVALID_ARGUMENT;
    }

    auto schema_predicate = [&info](const SchemaRecord& rec) {
        return rec.is_valid == 1 && rec.schema_id == info.owner_schema_id;
    };
    auto schema_row = findRecordInHeapPage<SchemaRecord>(schemas_table_page_, schema_predicate, ctx);
    if (schema_row.status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND, "index_opclass.owner_schema_uuid not found");
        return Status::NOT_FOUND;
    }

    auto type_predicate = [&info](const TypeRecord& rec) {
        return rec.is_valid == 1 && rec.type_id == info.input_type_id;
    };
    auto type_row = findRecordInHeapPage<TypeRecord>(type_table_page_, type_predicate, ctx);
    if (type_row.status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND, "index_opclass.input_type_uuid not found");
        return Status::NOT_FOUND;
    }

    ID opclass_id = info.opclass_id;
    if (isZeroUuidLocal(opclass_id))
    {
        opclass_id = generateUuidV7();
    }
    opclass_id_out = opclass_id;

    auto duplicate_predicate = [&opclass_id, &folded_name, &folded_type, &info](const IndexOpclassRecord& rec) {
        if (rec.is_valid != 1 || rec.opclass_id == opclass_id || rec.owner_schema_id != info.owner_schema_id)
        {
            return false;
        }
        const std::string rec_name =
            canonicalIdentifierForLookup(fixedNameFromBuffer(rec.opclass_name, sizeof(rec.opclass_name)));
        const std::string rec_type =
            canonicalIdentifierForLookup(fixedNameFromBuffer(rec.index_type_name, sizeof(rec.index_type_name)));
        return rec_name == folded_name && rec_type == folded_type;
    };
    auto duplicate = findRecordInHeapPage<IndexOpclassRecord>(
        index_opclass_table_page_, duplicate_predicate, ctx);
    if (duplicate.status == Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, Status::CONSTRAINT_VIOLATION,
                          "UNIQUE(index_opclass.name, index_type, owner_schema_uuid) violated");
        return Status::CONSTRAINT_VIOLATION;
    }
    if (duplicate.status != Status::NOT_FOUND)
    {
        return duplicate.status;
    }

    const uint64_t now = catalogNowTicks();
    IndexOpclassRecord rec{};
    rec.opclass_id = opclass_id;
    std::string opclass_name = UTF8Utils::truncateToBytes(folded_name, sizeof(rec.opclass_name));
    std::strncpy(rec.opclass_name, opclass_name.c_str(), sizeof(rec.opclass_name) - 1);
    std::string index_type_name = UTF8Utils::truncateToBytes(folded_type, sizeof(rec.index_type_name));
    std::strncpy(rec.index_type_name, index_type_name.c_str(), sizeof(rec.index_type_name) - 1);
    rec.input_type_id = info.input_type_id;
    rec.collation_id = info.collation_id;
    rec.owner_schema_id = info.owner_schema_id;
    rec.is_valid = info.is_valid ? 1 : 0;
    rec.last_modified_time = (info.last_modified_time == 0) ? now : info.last_modified_time;

    auto existing_predicate = [&opclass_id](const IndexOpclassRecord& row) {
        return row.opclass_id == opclass_id && row.is_valid == 1;
    };
    auto existing = findRecordInHeapPage<IndexOpclassRecord>(
        index_opclass_table_page_, existing_predicate, ctx);
    if (existing.status == Status::OK)
    {
        rec.created_time = existing.record.created_time;
    }
    else if (existing.status == Status::NOT_FOUND)
    {
        rec.created_time = (info.created_time == 0) ? now : info.created_time;
    }
    else
    {
        return existing.status;
    }

    auto matcher = [&opclass_id](const IndexOpclassRecord& row) {
        return row.opclass_id == opclass_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(index_opclass_table_page_, matcher, rec, ctx);
}

