auto CatalogManager::listIndexMaintenanceDeltaCatalogEntries(
    const ID& maintenance_id,
    std::vector<IndexMaintenanceDeltaCatalogInfo>& rows_out,
    ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    rows_out.clear();
    auto filter = [&maintenance_id](const IndexMaintenanceDeltaRecord& rec) {
        if (rec.is_valid != 1)
        {
            return false;
        }
        return isZeroUuidLocal(maintenance_id) || rec.maintenance_id == maintenance_id;
    };
    auto converter = [](const IndexMaintenanceDeltaRecord& rec, IndexMaintenanceDeltaCatalogInfo& info) {
        info = IndexMaintenanceDeltaCatalogInfo{};
        info.maintenance_delta_id = rec.maintenance_delta_id;
        info.maintenance_id = rec.maintenance_id;
        info.delta_id = rec.delta_id;
        info.delta_op = static_cast<IndexDeltaOp>(rec.delta_op);
        info.tid_gpid = rec.tid_gpid;
        info.tid_slot = rec.tid_slot;
        info.commit_txid = rec.commit_txid;
        info.is_valid = rec.is_valid == 1;
        info.created_time = rec.created_time;
    };
    Status status = readRecordsToVector<IndexMaintenanceDeltaRecord, IndexMaintenanceDeltaCatalogInfo>(
        index_maintenance_deltas_table_page_, rows_out, filter, converter, ctx);
    if (status != Status::OK)
    {
        return status;
    }
    std::sort(rows_out.begin(), rows_out.end(),
              [](const IndexMaintenanceDeltaCatalogInfo& lhs,
                 const IndexMaintenanceDeltaCatalogInfo& rhs) {
                  return lhs.delta_id < rhs.delta_id;
              });
    return Status::OK;
}

