auto CatalogManager::upsertIndexBuildDeltaCatalogEntry(const IndexBuildDeltaCatalogInfo& info,
                                                       ID& build_delta_id_out,
                                                       ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.index_id) || info.delta_id == 0)
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT,
                          "index_build_delta.index_uuid and delta_id are required");
        return Status::INVALID_ARGUMENT;
    }
    if (!isValidIndexDeltaOp(info.delta_op))
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "index_build_delta.delta_op is invalid");
        return Status::INVALID_ARGUMENT;
    }
    if ((info.delta_op == IndexDeltaOp::INSERT || info.delta_op == IndexDeltaOp::UPDATE) &&
        isZeroUuidLocal(info.key_bytes_id))
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT,
                          "index_build_delta.key_bytes is required for insert/update");
        return Status::INVALID_ARGUMENT;
    }

    auto index_predicate = [&info](const IndexRecord& rec) {
        return rec.is_valid == 1 && rec.index_id == info.index_id;
    };
    auto index_result = findRecordInHeapPage<IndexRecord>(indexes_table_page_, index_predicate, ctx);
    if (index_result.status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND, "index_build_delta.index_uuid not found");
        return Status::NOT_FOUND;
    }

    ID build_delta_id = info.build_delta_id;
    if (isZeroUuidLocal(build_delta_id))
    {
        build_delta_id = generateUuidV7();
    }
    build_delta_id_out = build_delta_id;

    auto duplicate_predicate = [&info, &build_delta_id](const IndexBuildDeltaRecord& rec) {
        return rec.is_valid == 1 &&
               rec.build_delta_id != build_delta_id &&
               rec.index_id == info.index_id &&
               rec.delta_id == info.delta_id;
    };
    auto duplicate = findRecordInHeapPage<IndexBuildDeltaRecord>(
        index_build_deltas_table_page_, duplicate_predicate, ctx);
    if (duplicate.status == Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, Status::CONSTRAINT_VIOLATION,
                          "UNIQUE(index_build_delta.index_uuid, delta_id) violated");
        return Status::CONSTRAINT_VIOLATION;
    }
    if (duplicate.status != Status::NOT_FOUND)
    {
        return duplicate.status;
    }

    IndexBuildDeltaRecord rec{};
    rec.build_delta_id = build_delta_id;
    rec.index_id = info.index_id;
    rec.delta_id = info.delta_id;
    rec.delta_op = static_cast<uint8_t>(info.delta_op);
    rec.tid_gpid = info.tid_gpid;
    rec.tid_slot = info.tid_slot;
    rec.key_bytes_oid = info.key_bytes_id;
    rec.created_txid = info.created_txid;
    rec.is_valid = info.is_valid ? 1 : 0;
    rec.created_time = (info.created_time == 0) ? catalogNowTicks() : info.created_time;

    auto matcher = [&build_delta_id](const IndexBuildDeltaRecord& row) {
        return row.build_delta_id == build_delta_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(index_build_deltas_table_page_, matcher, rec, ctx);
}

