auto CatalogManager::upsertIndexStorageCatalogEntry(const IndexStorageCatalogInfo& info,
                                                    ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.index_id))
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "index_storage.index_uuid is required");
        return Status::INVALID_ARGUMENT;
    }
    if (index_cache_.find(info.index_id) == index_cache_.end())
    {
        SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND, "index_storage.index_uuid not found");
        return Status::NOT_FOUND;
    }
    if (!isZeroUuidLocal(info.filespace_id) && resolveTablespaceId(info.filespace_id) == 0)
    {
        SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND, "index_storage.filespace_uuid not found");
        return Status::NOT_FOUND;
    }
    if (info.bytes_used > info.bytes_allocated)
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT,
                          "index_storage.bytes_used cannot exceed bytes_allocated");
        return Status::INVALID_ARGUMENT;
    }
    if (info.fragmentation_ratio < 0.0f || info.fragmentation_ratio > 1.0f)
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT,
                          "index_storage.fragmentation_ratio must be in [0,1]");
        return Status::INVALID_ARGUMENT;
    }

    const uint64_t now = catalogNowTicks();
    IndexStorageRecord rec{};
    rec.index_id = info.index_id;
    rec.page_count = info.page_count;
    rec.bytes_used = info.bytes_used;
    rec.bytes_allocated = info.bytes_allocated;
    rec.fragmentation_ratio = info.fragmentation_ratio;
    rec.filespace_id = info.filespace_id;
    rec.is_valid = info.is_valid ? 1 : 0;
    rec.last_modified_time = (info.last_modified_time == 0) ? now : info.last_modified_time;

    auto existing_predicate = [&info](const IndexStorageRecord& row) {
        return row.index_id == info.index_id && row.is_valid == 1;
    };
    auto existing = findRecordInHeapPage<IndexStorageRecord>(index_storage_table_page_, existing_predicate, ctx);
    if (existing.status == Status::OK)
    {
        rec.created_time = existing.record.created_time;
    }
    else if (existing.status == Status::NOT_FOUND)
    {
        rec.created_time = (info.created_time == 0) ? now : info.created_time;
    }
    else
    {
        return existing.status;
    }

    auto matcher = [&info](const IndexStorageRecord& row) {
        return row.index_id == info.index_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(index_storage_table_page_, matcher, rec, ctx);
}

