    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "index_health.diagnostic_status is invalid");
        return Status::INVALID_ARGUMENT;
    }

    const uint64_t now = catalogNowTicks();
    IndexHealthRecord rec{};
    rec.index_id = info.index_id;
    rec.last_light_scan_txid = info.last_light_scan_txid;
    rec.last_light_scan_time = info.last_light_scan_time;
    rec.light_status = static_cast<uint8_t>(info.light_status);
