    rec.last_diag_scan_time = info.last_diag_scan_time;
    rec.diagnostic_status = static_cast<uint8_t>(info.diagnostic_status);
    rec.diagnostic_error_count = info.diagnostic_error_count;
    rec.checksum_errors = info.checksum_errors;
    rec.order_errors = info.order_errors;
    rec.pointer_errors = info.pointer_errors;
    rec.orphan_pages = info.orphan_pages;
    rec.duplicate_keys = info.duplicate_keys;
    rec.in_memory_errors = info.in_memory_errors;
    rec.pages_scanned = info.pages_scanned;
    rec.bytes_scanned = info.bytes_scanned;
