auto CatalogManager::getIndexHealthCatalogEntry(const ID& index_id,
                                                IndexHealthCatalogInfo& info_out,
                                                ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    auto predicate = [&index_id](const IndexHealthRecord& rec) {
        return rec.index_id == index_id && rec.is_valid == 1;
    };
    auto result = findRecordInHeapPage<IndexHealthRecord>(index_health_table_page_, predicate, ctx);
    if (result.status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND, "index_health row not found");
        return Status::NOT_FOUND;
    }
    if (!isValidIndexLightHealthStatus(static_cast<IndexHealthStatus>(result.record.light_status)))
    {
        SET_ERROR_CONTEXT(ctx, Status::PAGE_CORRUPT, "index_health.light_status is invalid on disk");
        return Status::PAGE_CORRUPT;
    }
    if (!isValidIndexHealthStatus(static_cast<IndexHealthStatus>(result.record.diagnostic_status)))
    {
        SET_ERROR_CONTEXT(ctx, Status::PAGE_CORRUPT, "index_health.diagnostic_status is invalid on disk");
        return Status::PAGE_CORRUPT;
    }

    info_out = IndexHealthCatalogInfo{};
    info_out.index_id = result.record.index_id;
    info_out.last_light_scan_txid = result.record.last_light_scan_txid;
    info_out.last_light_scan_time = result.record.last_light_scan_time;
    info_out.light_status = static_cast<IndexHealthStatus>(result.record.light_status);
    info_out.light_error_count = result.record.light_error_count;
    info_out.last_diag_scan_txid = result.record.last_diag_scan_txid;
    info_out.last_diag_scan_time = result.record.last_diag_scan_time;
    info_out.diagnostic_status = static_cast<IndexHealthStatus>(result.record.diagnostic_status);
    info_out.diagnostic_error_count = result.record.diagnostic_error_count;
    info_out.checksum_errors = result.record.checksum_errors;
    info_out.order_errors = result.record.order_errors;
    info_out.pointer_errors = result.record.pointer_errors;
    info_out.orphan_pages = result.record.orphan_pages;
    info_out.duplicate_keys = result.record.duplicate_keys;
    info_out.in_memory_errors = result.record.in_memory_errors;
    info_out.pages_scanned = result.record.pages_scanned;
    info_out.bytes_scanned = result.record.bytes_scanned;
    info_out.is_valid = result.record.is_valid == 1;
    info_out.created_time = result.record.created_time;
    info_out.last_modified_time = result.record.last_modified_time;
    return Status::OK;
}

auto CatalogManager::listIndexHealthCatalogEntries(std::vector<IndexHealthCatalogInfo>& rows_out,
                                                   ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    rows_out.clear();
    auto filter = [](const IndexHealthRecord& rec) {
        return rec.is_valid == 1;
    };
    auto converter = [](const IndexHealthRecord& rec, IndexHealthCatalogInfo& info) {
        info = IndexHealthCatalogInfo{};
        info.index_id = rec.index_id;
        info.last_light_scan_txid = rec.last_light_scan_txid;
        info.last_light_scan_time = rec.last_light_scan_time;
        info.light_status = static_cast<IndexHealthStatus>(rec.light_status);
        info.light_error_count = rec.light_error_count;
        info.last_diag_scan_txid = rec.last_diag_scan_txid;
        info.last_diag_scan_time = rec.last_diag_scan_time;
        info.diagnostic_status = static_cast<IndexHealthStatus>(rec.diagnostic_status);
        info.diagnostic_error_count = rec.diagnostic_error_count;
        info.checksum_errors = rec.checksum_errors;
        info.order_errors = rec.order_errors;
        info.pointer_errors = rec.pointer_errors;
        info.orphan_pages = rec.orphan_pages;
        info.duplicate_keys = rec.duplicate_keys;
        info.in_memory_errors = rec.in_memory_errors;
        info.pages_scanned = rec.pages_scanned;
        info.bytes_scanned = rec.bytes_scanned;
        info.is_valid = rec.is_valid == 1;
        info.created_time = rec.created_time;
        info.last_modified_time = rec.last_modified_time;
    };
    Status status = readRecordsToVector<IndexHealthRecord, IndexHealthCatalogInfo>(
        index_health_table_page_, rows_out, filter, converter, ctx);
    if (status != Status::OK)
    {
        return status;
    }
    for (const auto& row : rows_out)
    {
        if (!isValidIndexLightHealthStatus(row.light_status) ||
            !isValidIndexHealthStatus(row.diagnostic_status))
        {
            SET_ERROR_CONTEXT(ctx, Status::PAGE_CORRUPT, "index_health status value is invalid");
            return Status::PAGE_CORRUPT;
        }
    }
    return Status::OK;
}

auto CatalogManager::deleteIndexHealthCatalogEntry(const ID& index_id,
                                                   ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    auto predicate = [&index_id](const IndexHealthRecord& rec) {
        return rec.index_id == index_id && rec.is_valid == 1;
    };
    auto result = findRecordInHeapPage<IndexHealthRecord>(index_health_table_page_, predicate, ctx);
    if (result.status != Status::OK)
    {
        return Status::NOT_FOUND;
    }
    IndexHealthRecord updated = result.record;
    updated.is_valid = 0;
    updated.last_modified_time = catalogNowTicks();
    return updateRecordInHeapPage(index_health_table_page_, result.slot_index, updated, ctx);
}

