auto CatalogManager::upsertFilespaceStatsCatalogEntry(const FilespaceStatsCatalogInfo& info,
                                                      ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (info.filespace_id > 0xFFFFu)
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "filespace_stats.filespace_id out of range");
        return Status::INVALID_ARGUMENT;
    }
    if (info.filespace_id != 0 &&
        tablespace_cache_.find(static_cast<uint16_t>(info.filespace_id)) == tablespace_cache_.end())
    {
        SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND, "filespace_stats.filespace_id not found");
        return Status::NOT_FOUND;
    }
    if (info.free_pages > info.total_pages)
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT,
                          "filespace_stats.free_pages cannot exceed total_pages");
        return Status::INVALID_ARGUMENT;
    }
    if (info.dirty_pages > info.total_pages)
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT,
                          "filespace_stats.dirty_pages cannot exceed total_pages");
        return Status::INVALID_ARGUMENT;
    }

    const uint64_t now = catalogNowTicks();
    FilespaceStatsRecord rec{};
    rec.filespace_id = info.filespace_id;
    rec.total_pages = info.total_pages;
    rec.free_pages = info.free_pages;
    rec.dirty_pages = info.dirty_pages;
    rec.read_iops = info.read_iops;
    rec.write_iops = info.write_iops;
    rec.last_scan_txid = info.last_scan_txid;
    rec.is_valid = info.is_valid ? 1 : 0;
    rec.last_modified_time = (info.last_modified_time == 0) ? now : info.last_modified_time;

    auto existing_predicate = [id = info.filespace_id](const FilespaceStatsRecord& row) {
        return row.filespace_id == id && row.is_valid == 1;
    };
    auto existing = findRecordInHeapPage<FilespaceStatsRecord>(
        filespace_stats_table_page_, existing_predicate, ctx);
    if (existing.status == Status::OK)
    {
        rec.created_time = existing.record.created_time;
    }
    else if (existing.status == Status::NOT_FOUND)
    {
        rec.created_time = (info.created_time == 0) ? now : info.created_time;
    }
    else
    {
        return existing.status;
    }

    auto matcher = [id = info.filespace_id](const FilespaceStatsRecord& row) {
        return row.filespace_id == id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(filespace_stats_table_page_, matcher, rec, ctx);
}

