auto CatalogManager::upsertLobCatalogEntry(const LobCatalogInfo& info,
                                           ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.lob_id))
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "lob.lob_uuid is required");
        return Status::INVALID_ARGUMENT;
    }
    if (isZeroUuidLocal(info.database_id))
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "lob.database_uuid is required");
        return Status::INVALID_ARGUMENT;
    }
    if (isZeroUuidLocal(info.owner_id))
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "lob.owner_uuid is required");
        return Status::INVALID_ARGUMENT;
    }
    if (info.is_encrypted && isZeroUuidLocal(info.encryption_key_id))
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT,
                          "lob.encryption_key_uuid required when is_encrypted=true");
        return Status::INVALID_ARGUMENT;
    }

    const uint64_t now = catalogNowTicks();
    LobCatalogRecord rec{};
    rec.lob_id = info.lob_id;
    rec.database_id = info.database_id;
    rec.owner_id = info.owner_id;
    rec.data_length = info.data_length;
    rec.page_count = info.page_count;
    rec.has_checksum = info.has_checksum ? 1 : 0;
    rec.is_encrypted = info.is_encrypted ? 1 : 0;
    rec.is_valid = info.is_valid ? 1 : 0;
    rec.checksum = info.has_checksum ? info.checksum : 0;
    rec.encryption_key_id = info.encryption_key_id;
    rec.last_modified_time = (info.last_modified_time == 0) ? now : info.last_modified_time;

    auto existing_predicate = [&info](const LobCatalogRecord& row) {
        return row.lob_id == info.lob_id && row.is_valid == 1;
    };
    auto existing = findRecordInHeapPage<LobCatalogRecord>(lob_table_page_, existing_predicate, ctx);
    if (existing.status == Status::OK)
    {
        rec.created_time = existing.record.created_time;
    }
    else if (existing.status == Status::NOT_FOUND)
    {
        rec.created_time = (info.created_time == 0) ? now : info.created_time;
    }
    else
    {
        return existing.status;
    }

    auto matcher = [&info](const LobCatalogRecord& row) {
        return row.lob_id == info.lob_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(lob_table_page_, matcher, rec, ctx);
}

