auto CatalogManager::upsertLobPageCatalogEntry(const LobPageCatalogInfo& info,
                                               ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.lob_page_id))
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "lob_page.lob_page_uuid is required");
        return Status::INVALID_ARGUMENT;
    }
    if (isZeroUuidLocal(info.lob_id))
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "lob_page.lob_uuid is required");
        return Status::INVALID_ARGUMENT;
    }
    if (info.page_gpid == 0)
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "lob_page.page_gpid is required");
        return Status::INVALID_ARGUMENT;
    }
    const uint32_t max_chunk = static_cast<uint32_t>(db_->page_size() > sizeof(PageHeader)
        ? db_->page_size() - sizeof(PageHeader)
        : 0);
    if (info.chunk_bytes > max_chunk)
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT,
                          "lob_page.chunk_bytes exceeds max payload for configured page size");
        return Status::INVALID_ARGUMENT;
    }

    auto lob_predicate = [&info](const LobCatalogRecord& rec) {
        return rec.lob_id == info.lob_id && rec.is_valid == 1;
    };
    auto lob_row = findRecordInHeapPage<LobCatalogRecord>(lob_table_page_, lob_predicate, ctx);
    if (lob_row.status != Status::OK)
    {
        if (lob_row.status == Status::NOT_FOUND)
        {
            SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND, "lob_page.lob_uuid not found");
            return Status::NOT_FOUND;
        }
        return lob_row.status;
    }

    auto duplicate_predicate = [&info](const LobPageCatalogRecord& rec) {
        return rec.is_valid == 1 &&
               rec.lob_page_id != info.lob_page_id &&
               rec.lob_id == info.lob_id &&
               rec.page_index == info.page_index;
    };
    auto duplicate = findRecordInHeapPage<LobPageCatalogRecord>(
        lob_page_table_page_, duplicate_predicate, ctx);
    if (duplicate.status == Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, Status::CONSTRAINT_VIOLATION,
                          "UNIQUE(lob_uuid, page_index) violated");
        return Status::CONSTRAINT_VIOLATION;
    }
    if (duplicate.status != Status::NOT_FOUND)
    {
        return duplicate.status;
    }

    const uint64_t now = catalogNowTicks();
    LobPageCatalogRecord rec{};
    rec.lob_page_id = info.lob_page_id;
    rec.lob_id = info.lob_id;
    rec.page_index = info.page_index;
    rec.chunk_bytes = info.chunk_bytes;
    rec.page_gpid = info.page_gpid;
    rec.has_checksum = info.has_checksum ? 1 : 0;
    rec.is_valid = info.is_valid ? 1 : 0;
    rec.checksum = info.has_checksum ? info.checksum : 0;
    rec.last_modified_time = (info.last_modified_time == 0) ? now : info.last_modified_time;

    auto existing_predicate = [&info](const LobPageCatalogRecord& row) {
        return row.lob_page_id == info.lob_page_id && row.is_valid == 1;
    };
    auto existing = findRecordInHeapPage<LobPageCatalogRecord>(
        lob_page_table_page_, existing_predicate, ctx);
    if (existing.status == Status::OK)
    {
        rec.created_time = existing.record.created_time;
    }
    else if (existing.status == Status::NOT_FOUND)
    {
        rec.created_time = (info.created_time == 0) ? now : info.created_time;
    }
    else
    {
        return existing.status;
    }

    auto matcher = [&info](const LobPageCatalogRecord& row) {
        return row.lob_page_id == info.lob_page_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(lob_page_table_page_, matcher, rec, ctx);
}

