    info_out.last_modified_time = result.record.last_modified_time;
    if (!isZeroUuidLocal(result.record.config_oid))
    {
        uint64_t xmin = 0;
        Status status = loadStringFromToast(result.record.config_oid, xmin, info_out.config_json, ctx);
        if (status != Status::OK)
        {
            return status;
        }
    }
