auto CatalogManager::upsertCertRegistryCatalogEntry(const CertRegistryCatalogInfo& info,
                                                    ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.cert_id) ||
        isZeroUuidLocal(info.public_key_id) ||
        isZeroUuidLocal(info.cert_der_id))
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "cert_registry required UUID is missing");
        return Status::INVALID_ARGUMENT;
    }
    if (!isValidCertKind(info.cert_kind) || !isValidCertStatus(info.status))
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "cert_registry enum value is invalid");
        return Status::INVALID_ARGUMENT;
    }
    if (info.not_before == 0 || info.not_after == 0 || info.not_before > info.not_after)
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "cert_registry validity window is invalid");
        return Status::INVALID_ARGUMENT;
    }
    if (info.signature_algorithm.empty())
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "cert_registry.signature_algorithm is required");
        return Status::INVALID_ARGUMENT;
    }
    if (info.status == CertStatus::REVOKED && !info.has_revoked_time)
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT,
                          "cert_registry.revoked_time required when status=REVOKED");
        return Status::INVALID_ARGUMENT;
    }

    ErrorContext local_ctx;
    Status status = UTF8Utils::validateStorageCapacity(
        info.signature_algorithm, sizeof(CertRegistryRecord{}.signature_algorithm),
        sizeof(CertRegistryRecord{}.signature_algorithm), &local_ctx);
    if (status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, status, "cert_registry.signature_algorithm too long");
        return status;
    }

    auto same_thumbprint = [&info](const CertRegistryRecord& row) {
        return row.is_valid == 1 &&
               row.cert_id != info.cert_id &&
               std::memcmp(row.thumbprint_sha256, info.thumbprint_sha256.data(), 32) == 0;
    };
    auto duplicate = findRecordInHeapPage<CertRegistryRecord>(cert_registry_table_page_, same_thumbprint, ctx);
    if (duplicate.status == Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, Status::CONSTRAINT_VIOLATION, "UNIQUE(thumbprint_sha256) violated");
        return Status::CONSTRAINT_VIOLATION;
    }
    if (duplicate.status != Status::NOT_FOUND)
    {
        return duplicate.status;
    }

    CertRegistryRecord rec{};
    rec.cert_id = info.cert_id;
    rec.cert_kind = static_cast<uint8_t>(info.cert_kind);
    rec.status = static_cast<uint8_t>(info.status);
    rec.has_cert_pem = isZeroUuidLocal(info.cert_pem_id) ? 0 : 1;
    rec.has_revoked_time = info.has_revoked_time ? 1 : 0;
    rec.is_valid = info.is_valid ? 1 : 0;
    rec.not_before = info.not_before;
    rec.not_after = info.not_after;
    rec.public_key_id = info.public_key_id;
    rec.cert_der_id = info.cert_der_id;
    rec.cert_pem_id = info.cert_pem_id;
    rec.created_time = (info.created_time == 0) ? catalogNowTicks() : info.created_time;
    rec.revoked_time = info.has_revoked_time ? info.revoked_time : 0;
    std::memcpy(rec.thumbprint_sha256, info.thumbprint_sha256.data(), 32);
    std::strncpy(rec.signature_algorithm,
                 UTF8Utils::truncateToBytes(info.signature_algorithm, sizeof(rec.signature_algorithm)).c_str(),
                 sizeof(rec.signature_algorithm) - 1);

    uint64_t xmin = 0;
    if (!info.subject_name.empty())
    {
        status = storeStringInToast(info.subject_name, xmin, rec.subject_name_oid, ctx);
        if (status != Status::OK) return status;
    }
    if (!info.issuer_name.empty())
    {
        status = storeStringInToast(info.issuer_name, xmin, rec.issuer_name_oid, ctx);
        if (status != Status::OK) return status;
    }
    if (!info.serial_number.empty())
    {
        status = storeStringInToast(info.serial_number, xmin, rec.serial_number_oid, ctx);
        if (status != Status::OK) return status;
    }

    auto existing_predicate = [&info](const CertRegistryRecord& row) {
        return row.cert_id == info.cert_id && row.is_valid == 1;
    };
    auto existing = findRecordInHeapPage<CertRegistryRecord>(cert_registry_table_page_, existing_predicate, ctx);
    if (existing.status == Status::OK)
    {
        rec.created_time = existing.record.created_time;
    }
    else if (existing.status != Status::NOT_FOUND)
    {
        return existing.status;
    }

    auto matcher = [&info](const CertRegistryRecord& row) {
        return row.cert_id == info.cert_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(cert_registry_table_page_, matcher, rec, ctx);
}

auto CatalogManager::getCertRegistryCatalogEntry(const ID& cert_id,
                                                 CertRegistryCatalogInfo& info_out,
                                                 ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    auto predicate = [&cert_id](const CertRegistryRecord& rec) {
        return rec.cert_id == cert_id && rec.is_valid == 1;
    };
    auto result = findRecordInHeapPage<CertRegistryRecord>(cert_registry_table_page_, predicate, ctx);
    if (result.status != Status::OK)
    {
        return Status::NOT_FOUND;
    }
    if (!isValidCertKind(static_cast<CertKind>(result.record.cert_kind)) ||
        !isValidCertStatus(static_cast<CertStatus>(result.record.status)))
    {
        return Status::PAGE_CORRUPT;
    }

    info_out = CertRegistryCatalogInfo{};
    info_out.cert_id = result.record.cert_id;
    info_out.cert_kind = static_cast<CertKind>(result.record.cert_kind);
    info_out.not_before = result.record.not_before;
    info_out.not_after = result.record.not_after;
    info_out.public_key_id = result.record.public_key_id;
    info_out.cert_der_id = result.record.cert_der_id;
    info_out.cert_pem_id = result.record.cert_pem_id;
    info_out.signature_algorithm = fixedNameFromBuffer(
        result.record.signature_algorithm, sizeof(result.record.signature_algorithm));
    std::copy(std::begin(result.record.thumbprint_sha256), std::end(result.record.thumbprint_sha256),
              info_out.thumbprint_sha256.begin());
    info_out.status = static_cast<CertStatus>(result.record.status);
    info_out.created_time = result.record.created_time;
    info_out.has_revoked_time = result.record.has_revoked_time != 0;
    info_out.revoked_time = result.record.revoked_time;
    info_out.is_valid = result.record.is_valid == 1;

    uint64_t xmin = 0;
    if (!isZeroUuidLocal(result.record.subject_name_oid))
    {
        Status status = loadStringFromToast(result.record.subject_name_oid, xmin, info_out.subject_name, ctx);
        if (status != Status::OK) return status;
    }
    if (!isZeroUuidLocal(result.record.issuer_name_oid))
    {
        Status status = loadStringFromToast(result.record.issuer_name_oid, xmin, info_out.issuer_name, ctx);
        if (status != Status::OK) return status;
    }
    if (!isZeroUuidLocal(result.record.serial_number_oid))
    {
        Status status = loadStringFromToast(result.record.serial_number_oid, xmin, info_out.serial_number, ctx);
        if (status != Status::OK) return status;
    }
    return Status::OK;
}

auto CatalogManager::listCertRegistryCatalogEntries(std::vector<CertRegistryCatalogInfo>& rows_out,
                                                    ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    rows_out.clear();
    auto filter = [](const CertRegistryRecord& rec) { return rec.is_valid == 1; };
    auto converter = [this, ctx](const CertRegistryRecord& rec, CertRegistryCatalogInfo& info) {
        info = CertRegistryCatalogInfo{};
        info.cert_id = rec.cert_id;
        info.cert_kind = static_cast<CertKind>(rec.cert_kind);
        info.not_before = rec.not_before;
        info.not_after = rec.not_after;
        info.public_key_id = rec.public_key_id;
        info.cert_der_id = rec.cert_der_id;
        info.cert_pem_id = rec.cert_pem_id;
        info.signature_algorithm = fixedNameFromBuffer(rec.signature_algorithm, sizeof(rec.signature_algorithm));
        std::copy(std::begin(rec.thumbprint_sha256), std::end(rec.thumbprint_sha256),
                  info.thumbprint_sha256.begin());
        info.status = static_cast<CertStatus>(rec.status);
        info.created_time = rec.created_time;
        info.has_revoked_time = rec.has_revoked_time != 0;
        info.revoked_time = rec.revoked_time;
        info.is_valid = rec.is_valid == 1;
        uint64_t xmin = 0;
        if (!isZeroUuidLocal(rec.subject_name_oid))
        {
            std::string text;
            if (loadStringFromToast(rec.subject_name_oid, xmin, text, ctx) == Status::OK)
            {
                info.subject_name = std::move(text);
            }
        }
        if (!isZeroUuidLocal(rec.issuer_name_oid))
        {
            std::string text;
            if (loadStringFromToast(rec.issuer_name_oid, xmin, text, ctx) == Status::OK)
            {
                info.issuer_name = std::move(text);
            }
        }
        if (!isZeroUuidLocal(rec.serial_number_oid))
        {
            std::string text;
            if (loadStringFromToast(rec.serial_number_oid, xmin, text, ctx) == Status::OK)
            {
                info.serial_number = std::move(text);
            }
        }
    };
    return readRecordsToVector<CertRegistryRecord, CertRegistryCatalogInfo>(
        cert_registry_table_page_, rows_out, filter, converter, ctx);
}

