auto CatalogManager::upsertPrivateKeyStoreCatalogEntry(const PrivateKeyStoreCatalogInfo& info,
                                                       ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.key_id) || isZeroUuidLocal(info.cert_id) ||
        isZeroUuidLocal(info.key_material_encrypted_id) || isZeroUuidLocal(info.kek_profile_id))
    {
        return Status::INVALID_ARGUMENT;
    }
    if (!isValidKeyMaterialKind(info.key_kind))
    {
        return Status::INVALID_ARGUMENT;
    }
    if ((info.has_rotated_time && info.rotated_time == 0) ||
        (info.has_destroyed_time && info.destroyed_time == 0))
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.has_rotated_time && info.has_destroyed_time && info.destroyed_time < info.rotated_time)
    {
        return Status::INVALID_ARGUMENT;
    }

    auto duplicate_predicate = [&info](const PrivateKeyStoreRecord& row) {
        return row.is_valid == 1 && row.key_id != info.key_id && row.cert_id == info.cert_id;
    };
    auto duplicate = findRecordInHeapPage<PrivateKeyStoreRecord>(
        private_key_store_table_page_, duplicate_predicate, ctx);
    if (duplicate.status == Status::OK)
    {
        return Status::CONSTRAINT_VIOLATION;
    }
    if (duplicate.status != Status::NOT_FOUND)
    {
        return duplicate.status;
    }

    PrivateKeyStoreRecord rec{};
    rec.key_id = info.key_id;
    rec.cert_id = info.cert_id;
    rec.key_kind = static_cast<uint8_t>(info.key_kind);
    rec.key_material_encrypted_id = info.key_material_encrypted_id;
    rec.kek_profile_id = info.kek_profile_id;
    rec.created_time = (info.created_time == 0) ? catalogNowTicks() : info.created_time;
    rec.has_rotated_time = info.has_rotated_time ? 1 : 0;
    rec.rotated_time = info.has_rotated_time ? info.rotated_time : 0;
    rec.has_destroyed_time = info.has_destroyed_time ? 1 : 0;
    rec.destroyed_time = info.has_destroyed_time ? info.destroyed_time : 0;
    rec.is_valid = info.is_valid ? 1 : 0;

    auto existing_predicate = [&info](const PrivateKeyStoreRecord& row) {
        return row.key_id == info.key_id && row.is_valid == 1;
    };
    auto existing = findRecordInHeapPage<PrivateKeyStoreRecord>(
        private_key_store_table_page_, existing_predicate, ctx);
    if (existing.status == Status::OK)
    {
        rec.created_time = existing.record.created_time;
    }
    else if (existing.status != Status::NOT_FOUND)
    {
        return existing.status;
    }

    auto matcher = [&info](const PrivateKeyStoreRecord& row) {
        return row.key_id == info.key_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(private_key_store_table_page_, matcher, rec, ctx);
}

