auto CatalogManager::upsertCertRevocationCatalogEntry(const CertRevocationCatalogInfo& info,
                                                      ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.revocation_id) || isZeroUuidLocal(info.cert_id) || info.revoked_time == 0)
    {
        return Status::INVALID_ARGUMENT;
    }
    if (!isValidRevocationSource(info.source_kind) || !isValidRevocationReason(info.reason_code))
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.has_expiry_time && (info.expiry_time == 0 || info.expiry_time < info.revoked_time))
    {
        return Status::INVALID_ARGUMENT;
    }

    auto duplicate_predicate = [&info](const CertRevocationRecord& row) {
        return row.is_valid == 1 &&
               row.revocation_id != info.revocation_id &&
               row.cert_id == info.cert_id &&
               row.source_kind == static_cast<uint8_t>(info.source_kind) &&
               row.revoked_time == info.revoked_time;
    };
    auto duplicate = findRecordInHeapPage<CertRevocationRecord>(
        cert_revocation_table_page_, duplicate_predicate, ctx);
    if (duplicate.status == Status::OK)
    {
        return Status::CONSTRAINT_VIOLATION;
    }
    if (duplicate.status != Status::NOT_FOUND)
    {
        return duplicate.status;
    }

    CertRevocationRecord rec{};
    rec.revocation_id = info.revocation_id;
    rec.cert_id = info.cert_id;
    rec.source_kind = static_cast<uint8_t>(info.source_kind);
    rec.reason_code = static_cast<uint8_t>(info.reason_code);
    rec.has_expiry_time = info.has_expiry_time ? 1 : 0;
    rec.revoked_time = info.revoked_time;
    rec.expiry_time = info.has_expiry_time ? info.expiry_time : 0;
    rec.evidence_id = info.evidence_id;
    rec.created_time = (info.created_time == 0) ? catalogNowTicks() : info.created_time;
    rec.is_valid = info.is_valid ? 1 : 0;

    auto existing_predicate = [&info](const CertRevocationRecord& row) {
        return row.revocation_id == info.revocation_id && row.is_valid == 1;
    };
    auto existing = findRecordInHeapPage<CertRevocationRecord>(
        cert_revocation_table_page_, existing_predicate, ctx);
    if (existing.status == Status::OK)
    {
        rec.created_time = existing.record.created_time;
    }
    else if (existing.status != Status::NOT_FOUND)
    {
        return existing.status;
    }

    auto matcher = [&info](const CertRevocationRecord& row) {
        return row.revocation_id == info.revocation_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(cert_revocation_table_page_, matcher, rec, ctx);
}

