auto CatalogManager::upsertPkiDistributionStateCatalogEntry(const PkiDistributionStateCatalogInfo& info,
                                                            ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.distribution_id) || isZeroUuidLocal(info.member_id) ||
        isZeroUuidLocal(info.artifact_id))
    {
        return Status::INVALID_ARGUMENT;
    }
    if (!isValidPkiArtifactKind(info.artifact_kind) ||
        !isValidDistributionState(info.distribution_state))
    {
        return Status::INVALID_ARGUMENT;
    }
    if ((info.has_last_attempt_time && info.last_attempt_time == 0) ||
        (info.has_last_success_time && info.last_success_time == 0))
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.has_last_attempt_time && info.has_last_success_time &&
        info.last_success_time < info.last_attempt_time)
    {
        return Status::INVALID_ARGUMENT;
    }

    auto duplicate_predicate = [&info](const PkiDistributionStateRecord& row) {
        return row.is_valid == 1 &&
               row.distribution_id != info.distribution_id &&
               row.member_id == info.member_id &&
               row.artifact_kind == static_cast<uint8_t>(info.artifact_kind) &&
               row.artifact_id == info.artifact_id;
    };
    auto duplicate = findRecordInHeapPage<PkiDistributionStateRecord>(
        pki_distribution_state_table_page_, duplicate_predicate, ctx);
    if (duplicate.status == Status::OK)
    {
        return Status::CONSTRAINT_VIOLATION;
    }
    if (duplicate.status != Status::NOT_FOUND)
    {
        return duplicate.status;
    }

    PkiDistributionStateRecord rec{};
    rec.distribution_id = info.distribution_id;
    rec.member_id = info.member_id;
    rec.artifact_kind = static_cast<uint8_t>(info.artifact_kind);
    rec.distribution_state = static_cast<uint8_t>(info.distribution_state);
    rec.artifact_id = info.artifact_id;
    std::memcpy(rec.artifact_hash, info.artifact_hash.data(), 32);
    rec.retry_count = info.retry_count;
    rec.has_last_attempt_time = info.has_last_attempt_time ? 1 : 0;
    rec.last_attempt_time = info.has_last_attempt_time ? info.last_attempt_time : 0;
    rec.has_last_success_time = info.has_last_success_time ? 1 : 0;
    rec.last_success_time = info.has_last_success_time ? info.last_success_time : 0;
    rec.last_error_id = info.last_error_id;
    rec.is_valid = info.is_valid ? 1 : 0;

    auto matcher = [&info](const PkiDistributionStateRecord& row) {
        return row.distribution_id == info.distribution_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(pki_distribution_state_table_page_, matcher, rec, ctx);
}

auto CatalogManager::getPkiDistributionStateCatalogEntry(const ID& distribution_id,
                                                         PkiDistributionStateCatalogInfo& info_out,
                                                         ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    auto predicate = [&distribution_id](const PkiDistributionStateRecord& rec) {
        return rec.distribution_id == distribution_id && rec.is_valid == 1;
    };
    auto result = findRecordInHeapPage<PkiDistributionStateRecord>(
        pki_distribution_state_table_page_, predicate, ctx);
    if (result.status != Status::OK)
    {
        return Status::NOT_FOUND;
    }
    if (!isValidPkiArtifactKind(static_cast<PkiArtifactKind>(result.record.artifact_kind)) ||
        !isValidDistributionState(static_cast<DistributionState>(result.record.distribution_state)))
    {
        return Status::PAGE_CORRUPT;
    }

    info_out = PkiDistributionStateCatalogInfo{};
    info_out.distribution_id = result.record.distribution_id;
    info_out.member_id = result.record.member_id;
    info_out.artifact_kind = static_cast<PkiArtifactKind>(result.record.artifact_kind);
    info_out.artifact_id = result.record.artifact_id;
    std::copy(std::begin(result.record.artifact_hash), std::end(result.record.artifact_hash),
              info_out.artifact_hash.begin());
    info_out.distribution_state = static_cast<DistributionState>(result.record.distribution_state);
    info_out.retry_count = result.record.retry_count;
    info_out.has_last_attempt_time = result.record.has_last_attempt_time != 0;
    info_out.last_attempt_time = result.record.last_attempt_time;
    info_out.has_last_success_time = result.record.has_last_success_time != 0;
    info_out.last_success_time = result.record.last_success_time;
    info_out.last_error_id = result.record.last_error_id;
    info_out.is_valid = result.record.is_valid == 1;
    return Status::OK;
}

