auto CatalogManager::upsertTrustAnchorRolloverCatalogEntry(const TrustAnchorRolloverCatalogInfo& info,
                                                           ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.rollover_id) || isZeroUuidLocal(info.rollover_group_id) ||
        isZeroUuidLocal(info.old_anchor_id) || isZeroUuidLocal(info.new_anchor_id) ||
        info.old_anchor_id == info.new_anchor_id || info.started_time == 0)
    {
        return Status::INVALID_ARGUMENT;
    }
    if (!isValidRolloverPhase(info.phase))
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.quorum_required == 0 || info.quorum_acked > info.quorum_required)
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.has_completed_time && info.completed_time < info.started_time)
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.has_deadline_time && info.deadline_time < info.started_time)
    {
        return Status::INVALID_ARGUMENT;
    }

    auto duplicate_predicate = [&info](const TrustAnchorRolloverRecord& row) {
        return row.is_valid == 1 &&
               row.rollover_id != info.rollover_id &&
               row.rollover_group_id == info.rollover_group_id &&
               row.phase != static_cast<uint8_t>(RolloverPhase::COMPLETE) &&
               info.phase != RolloverPhase::COMPLETE;
    };
    auto duplicate = findRecordInHeapPage<TrustAnchorRolloverRecord>(
        trust_anchor_rollover_table_page_, duplicate_predicate, ctx);
    if (duplicate.status == Status::OK)
    {
        return Status::CONSTRAINT_VIOLATION;
    }
    if (duplicate.status != Status::NOT_FOUND)
    {
        return duplicate.status;
    }

    TrustAnchorRolloverRecord rec{};
    rec.rollover_id = info.rollover_id;
    rec.rollover_group_id = info.rollover_group_id;
    rec.old_anchor_id = info.old_anchor_id;
    rec.new_anchor_id = info.new_anchor_id;
    rec.phase = static_cast<uint8_t>(info.phase);
    rec.quorum_required = info.quorum_required;
    rec.quorum_acked = info.quorum_acked;
    rec.started_time = info.started_time;
    rec.has_completed_time = info.has_completed_time ? 1 : 0;
    rec.completed_time = info.has_completed_time ? info.completed_time : 0;
    rec.has_deadline_time = info.has_deadline_time ? 1 : 0;
    rec.deadline_time = info.has_deadline_time ? info.deadline_time : 0;
    rec.last_error_id = info.last_error_id;
    rec.is_valid = info.is_valid ? 1 : 0;

    auto matcher = [&info](const TrustAnchorRolloverRecord& row) {
        return row.rollover_id == info.rollover_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(trust_anchor_rollover_table_page_, matcher, rec, ctx);
}

