auto CatalogManager::upsertNodeCatalogEntry(const NodeCatalogInfo& info,
                                            ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.node_id) || isZeroUuidLocal(info.cluster_id) ||
        info.node_name.empty() || info.host.empty() || info.port == 0)
    {
        return Status::INVALID_ARGUMENT;
    }
    if (!isValidClusterNodeRole(info.node_role) ||
        !isValidClusterNodeState(info.state) ||
        !isValidConnectionTransport(info.transport))
    {
        return Status::INVALID_ARGUMENT;
    }

    ErrorContext local_ctx;
    Status status = UTF8Utils::validateStorageCapacity(
        info.node_name, sizeof(NodeRecord{}.node_name), sizeof(NodeRecord{}.node_name), &local_ctx);
    if (status != Status::OK)
    {
        return status;
    }
    status = UTF8Utils::validateStorageCapacity(
        info.host, sizeof(NodeRecord{}.host), sizeof(NodeRecord{}.host), &local_ctx);
    if (status != Status::OK)
    {
        return status;
    }
    if (!info.region.empty())
    {
        status = UTF8Utils::validateStorageCapacity(
            info.region, sizeof(NodeRecord{}.region), sizeof(NodeRecord{}.region), &local_ctx);
        if (status != Status::OK) return status;
    }
    if (!info.zone.empty())
    {
        status = UTF8Utils::validateStorageCapacity(
            info.zone, sizeof(NodeRecord{}.zone), sizeof(NodeRecord{}.zone), &local_ctx);
        if (status != Status::OK) return status;
    }
    if (!info.rack.empty())
    {
        status = UTF8Utils::validateStorageCapacity(
            info.rack, sizeof(NodeRecord{}.rack), sizeof(NodeRecord{}.rack), &local_ctx);
        if (status != Status::OK) return status;
    }
    if (info.has_last_heartbeat_time && info.last_heartbeat_time == 0)
    {
        return Status::INVALID_ARGUMENT;
    }

    auto duplicate_predicate = [&info](const NodeRecord& row) {
        return row.is_valid == 1 &&
               row.node_id != info.node_id &&
               row.cluster_id == info.cluster_id &&
               fixedNameFromBuffer(row.node_name, sizeof(row.node_name)) == info.node_name;
    };
    auto duplicate = findRecordInHeapPage<NodeRecord>(node_table_page_, duplicate_predicate, ctx);
    if (duplicate.status == Status::OK)
    {
        return Status::CONSTRAINT_VIOLATION;
    }
    if (duplicate.status != Status::NOT_FOUND)
    {
        return duplicate.status;
    }

    const uint64_t now = catalogNowTicks();
    NodeRecord rec{};
    rec.node_id = info.node_id;
    rec.cluster_id = info.cluster_id;
    std::strncpy(rec.node_name,
                 UTF8Utils::truncateToBytes(info.node_name, sizeof(rec.node_name)).c_str(),
                 sizeof(rec.node_name) - 1);
    rec.node_role = static_cast<uint8_t>(info.node_role);
    rec.node_state = static_cast<uint8_t>(info.state);
    rec.transport = static_cast<uint8_t>(info.transport);
    std::strncpy(rec.host,
                 UTF8Utils::truncateToBytes(info.host, sizeof(rec.host)).c_str(),
                 sizeof(rec.host) - 1);
    if (!info.region.empty())
    {
        std::strncpy(rec.region,
                     UTF8Utils::truncateToBytes(info.region, sizeof(rec.region)).c_str(),
                     sizeof(rec.region) - 1);
    }
    if (!info.zone.empty())
    {
        std::strncpy(rec.zone,
                     UTF8Utils::truncateToBytes(info.zone, sizeof(rec.zone)).c_str(),
                     sizeof(rec.zone) - 1);
    }
    if (!info.rack.empty())
    {
        std::strncpy(rec.rack,
                     UTF8Utils::truncateToBytes(info.rack, sizeof(rec.rack)).c_str(),
                     sizeof(rec.rack) - 1);
    }
    rec.port = info.port;
    rec.has_last_heartbeat_time = info.has_last_heartbeat_time ? 1 : 0;
    rec.last_heartbeat_time = info.has_last_heartbeat_time ? info.last_heartbeat_time : 0;
    rec.created_txid = info.created_txid;
    rec.last_modified_txid = info.last_modified_txid;
    rec.created_time = (info.created_time == 0) ? now : info.created_time;
    rec.last_modified_time = (info.last_modified_time == 0) ? now : info.last_modified_time;
    rec.is_valid = info.is_valid ? 1 : 0;

    auto existing_predicate = [&info](const NodeRecord& row) {
        return row.node_id == info.node_id && row.is_valid == 1;
    };
    auto existing = findRecordInHeapPage<NodeRecord>(node_table_page_, existing_predicate, ctx);
    ID previous_cluster_id{};
    std::string previous_node_name;
    if (existing.status == Status::OK)
    {
        rec.created_time = existing.record.created_time;
        rec.created_txid = existing.record.created_txid;
        previous_cluster_id = existing.record.cluster_id;
        previous_node_name = fixedNameFromBuffer(existing.record.node_name, sizeof(existing.record.node_name));
    }
    else if (existing.status != Status::NOT_FOUND)
    {
        return existing.status;
    }

    auto matcher = [&info](const NodeRecord& row) {
        return row.node_id == info.node_id && row.is_valid == 1;
    };
    status = updateRecordInHeapPage(node_table_page_, matcher, rec, ctx);
    if (status != Status::OK)
    {
        return status;
    }

    if (rec.is_valid == 1)
    {
        ClusterCatalogInfo cluster_info{};
        status = getClusterCatalogEntry(rec.cluster_id, cluster_info, nullptr);
        if (status == Status::OK)
        {
            status = ensureOverlaySchemaChildUnlocked("cluster", cluster_info.cluster_name, nullptr, ctx);
            if (status != Status::OK)
            {
                SET_ERROR_CONTEXT(ctx, status, "Failed to materialize cluster overlay schema for node");
                return status;
            }

            status = ensureOverlaySchemaChildUnlocked("cluster." + cluster_info.cluster_name,
                                                      info.node_name,
                                                      nullptr,
                                                      ctx);
            if (status != Status::OK)
            {
                SET_ERROR_CONTEXT(ctx, status, "Failed to materialize cluster node overlay schema");
                return status;
            }
        }
        else if (status != Status::NOT_FOUND)
        {
            SET_ERROR_CONTEXT(ctx, status, "Failed to resolve cluster for node overlay path");
            return status;
        }

        if (!previous_node_name.empty())
        {
            ClusterCatalogInfo previous_cluster_info{};
            if (getClusterCatalogEntry(previous_cluster_id, previous_cluster_info, nullptr) == Status::OK)
            {
                bool drop_previous_overlay = false;
                if (status == Status::OK)
                {
                    const bool cluster_changed =
                        !IdentifierUtils::namesConflict(cluster_info.cluster_name,
                                                        false /*new_is_delimited*/,
                                                        previous_cluster_info.cluster_name,
                                                        false /*stored_delimited*/);
                    const bool node_renamed =
                        !IdentifierUtils::namesConflict(info.node_name,
                                                        false /*new_is_delimited*/,
                                                        previous_node_name,
                                                        false /*stored_delimited*/);
                    drop_previous_overlay = cluster_changed || node_renamed;
                }
                else if (status == Status::NOT_FOUND)
                {
                    // Cluster row is absent for the updated node binding; remove stale mount if one existed.
                    drop_previous_overlay = true;
                }

                if (drop_previous_overlay)
                {
                    status = dropOverlaySchemaChildUnlocked("cluster." + previous_cluster_info.cluster_name,
                                                            previous_node_name,
                                                            ctx);
                    if (status != Status::OK)
                    {
                        SET_ERROR_CONTEXT(ctx, status, "Failed to drop previous cluster node overlay schema");
                        return status;
                    }
                }
            }
        }
    }

    return Status::OK;
}

auto CatalogManager::getNodeCatalogEntry(const ID& node_id,
                                         NodeCatalogInfo& info_out,
                                         ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    auto predicate = [&node_id](const NodeRecord& rec) {
        return rec.node_id == node_id && rec.is_valid == 1;
    };
    auto result = findRecordInHeapPage<NodeRecord>(node_table_page_, predicate, ctx);
    if (result.status != Status::OK)
    {
        return Status::NOT_FOUND;
    }
    if (!isValidClusterNodeRole(static_cast<ClusterNodeRole>(result.record.node_role)) ||
        !isValidClusterNodeState(static_cast<ClusterNodeState>(result.record.node_state)) ||
        !isValidConnectionTransport(static_cast<ConnectionTransport>(result.record.transport)))
    {
        return Status::PAGE_CORRUPT;
    }

    info_out = NodeCatalogInfo{};
    info_out.node_id = result.record.node_id;
    info_out.cluster_id = result.record.cluster_id;
    info_out.node_name = fixedNameFromBuffer(result.record.node_name, sizeof(result.record.node_name));
    info_out.node_role = static_cast<ClusterNodeRole>(result.record.node_role);
    info_out.host = fixedNameFromBuffer(result.record.host, sizeof(result.record.host));
    info_out.port = result.record.port;
    info_out.transport = static_cast<ConnectionTransport>(result.record.transport);
    info_out.region = fixedNameFromBuffer(result.record.region, sizeof(result.record.region));
    info_out.zone = fixedNameFromBuffer(result.record.zone, sizeof(result.record.zone));
    info_out.rack = fixedNameFromBuffer(result.record.rack, sizeof(result.record.rack));
    info_out.state = static_cast<ClusterNodeState>(result.record.node_state);
    info_out.has_last_heartbeat_time = result.record.has_last_heartbeat_time != 0;
    info_out.last_heartbeat_time = result.record.last_heartbeat_time;
    info_out.created_txid = result.record.created_txid;
    info_out.last_modified_txid = result.record.last_modified_txid;
    info_out.created_time = result.record.created_time;
    info_out.last_modified_time = result.record.last_modified_time;
    info_out.is_valid = result.record.is_valid == 1;
    return Status::OK;
}

auto CatalogManager::listNodeCatalogEntries(const ID& cluster_id,
                                            std::vector<NodeCatalogInfo>& rows_out,
                                            ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    rows_out.clear();
    auto filter = [&cluster_id](const NodeRecord& rec) {
        if (rec.is_valid != 1)
        {
            return false;
        }
        return isZeroUuidLocal(cluster_id) || rec.cluster_id == cluster_id;
    };
    auto converter = [](const NodeRecord& rec, NodeCatalogInfo& info) {
        info = NodeCatalogInfo{};
        info.node_id = rec.node_id;
        info.cluster_id = rec.cluster_id;
        info.node_name = fixedNameFromBuffer(rec.node_name, sizeof(rec.node_name));
        info.node_role = static_cast<ClusterNodeRole>(rec.node_role);
        info.host = fixedNameFromBuffer(rec.host, sizeof(rec.host));
        info.port = rec.port;
        info.transport = static_cast<ConnectionTransport>(rec.transport);
        info.region = fixedNameFromBuffer(rec.region, sizeof(rec.region));
        info.zone = fixedNameFromBuffer(rec.zone, sizeof(rec.zone));
        info.rack = fixedNameFromBuffer(rec.rack, sizeof(rec.rack));
        info.state = static_cast<ClusterNodeState>(rec.node_state);
        info.has_last_heartbeat_time = rec.has_last_heartbeat_time != 0;
        info.last_heartbeat_time = rec.last_heartbeat_time;
        info.created_txid = rec.created_txid;
        info.last_modified_txid = rec.last_modified_txid;
        info.created_time = rec.created_time;
        info.last_modified_time = rec.last_modified_time;
        info.is_valid = rec.is_valid == 1;
    };
    return readRecordsToVector<NodeRecord, NodeCatalogInfo>(node_table_page_, rows_out, filter, converter, ctx);
}

auto CatalogManager::deleteNodeCatalogEntry(const ID& node_id,
                                            ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    auto predicate = [&node_id](const NodeRecord& rec) {
        return rec.node_id == node_id && rec.is_valid == 1;
    };
    auto result = findRecordInHeapPage<NodeRecord>(node_table_page_, predicate, ctx);
    if (result.status != Status::OK)
    {
        return Status::NOT_FOUND;
    }

    ClusterCatalogInfo cluster_info{};
    if (getClusterCatalogEntry(result.record.cluster_id, cluster_info, nullptr) == Status::OK)
    {
        const std::string node_name =
            fixedNameFromBuffer(result.record.node_name, sizeof(result.record.node_name));
        Status status = dropOverlaySchemaChildUnlocked("cluster." + cluster_info.cluster_name,
                                                       node_name,
                                                       ctx);
        if (status != Status::OK)
        {
            SET_ERROR_CONTEXT(ctx, status, "Failed to drop cluster node overlay schema");
            return status;
        }
    }

    NodeRecord updated = result.record;
    updated.is_valid = 0;
    updated.last_modified_time = catalogNowTicks();
    return updateRecordInHeapPage(node_table_page_, result.slot_index, updated, ctx);
}

