auto CatalogManager::upsertNodeServiceCatalogEntry(const NodeServiceCatalogInfo& info,
                                                   ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.service_id) || isZeroUuidLocal(info.node_id) ||
        info.host.empty() || info.port == 0 ||
        !isValidClusterNodeRole(info.role) ||
        !isValidClusterServiceType(info.service_type) ||
        !isValidClusterServiceState(info.state) ||
        !isValidConnectionTransport(info.transport))
    {
        return Status::INVALID_ARGUMENT;
    }
    auto node_predicate = [&info](const NodeRecord& rec) {
        return rec.node_id == info.node_id && rec.is_valid == 1;
    };
    auto node = findRecordInHeapPage<NodeRecord>(node_table_page_, node_predicate, ctx);
    if (node.status != Status::OK)
    {
        return Status::NOT_FOUND;
    }

    ErrorContext local_ctx;
    Status status = UTF8Utils::validateStorageCapacity(
        info.host, sizeof(NodeServiceRecord{}.host), sizeof(NodeServiceRecord{}.host), &local_ctx);
    if (status != Status::OK)
    {
        return status;
    }

    auto duplicate_predicate = [&info](const NodeServiceRecord& row) {
        return row.is_valid == 1 &&
               row.service_id != info.service_id &&
               row.node_id == info.node_id &&
               row.service_type == static_cast<uint8_t>(info.service_type) &&
               row.port == info.port;
    };
    auto duplicate = findRecordInHeapPage<NodeServiceRecord>(node_service_table_page_, duplicate_predicate, ctx);
    if (duplicate.status == Status::OK)
    {
        return Status::CONSTRAINT_VIOLATION;
    }
    if (duplicate.status != Status::NOT_FOUND)
    {
        return duplicate.status;
    }

    const uint64_t now = catalogNowTicks();
    NodeServiceRecord rec{};
    rec.service_id = info.service_id;
    rec.node_id = info.node_id;
    rec.role = static_cast<uint8_t>(info.role);
    rec.service_type = static_cast<uint8_t>(info.service_type);
    rec.transport = static_cast<uint8_t>(info.transport);
    rec.state = static_cast<uint8_t>(info.state);
    rec.port = info.port;
    std::strncpy(rec.host,
                 UTF8Utils::truncateToBytes(info.host, sizeof(rec.host)).c_str(),
                 sizeof(rec.host) - 1);
    rec.tls_profile_id = info.tls_profile_id;
    rec.auth_profile_id = info.auth_profile_id;
    rec.created_txid = info.created_txid;
    rec.last_modified_txid = info.last_modified_txid;
    rec.created_time = (info.created_time == 0) ? now : info.created_time;
    rec.last_modified_time = (info.last_modified_time == 0) ? now : info.last_modified_time;
    rec.is_valid = info.is_valid ? 1 : 0;

    auto existing_predicate = [&info](const NodeServiceRecord& row) {
        return row.service_id == info.service_id && row.is_valid == 1;
    };
    auto existing = findRecordInHeapPage<NodeServiceRecord>(node_service_table_page_, existing_predicate, ctx);
    if (existing.status == Status::OK)
    {
        rec.created_time = existing.record.created_time;
        rec.created_txid = existing.record.created_txid;
    }
    else if (existing.status != Status::NOT_FOUND)
    {
        return existing.status;
    }

    auto matcher = [&info](const NodeServiceRecord& row) {
        return row.service_id == info.service_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(node_service_table_page_, matcher, rec, ctx);
}

