auto CatalogManager::upsertNodeCapabilityCatalogEntry(const NodeCapabilityCatalogInfo& info,
                                                      ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.capability_id) || isZeroUuidLocal(info.node_id) || info.capability_key.empty())
    {
        return Status::INVALID_ARGUMENT;
    }
    auto node_predicate = [&info](const NodeRecord& rec) {
        return rec.node_id == info.node_id && rec.is_valid == 1;
    };
    auto node = findRecordInHeapPage<NodeRecord>(node_table_page_, node_predicate, ctx);
    if (node.status != Status::OK)
    {
        return Status::NOT_FOUND;
    }

    ErrorContext local_ctx;
    Status status = UTF8Utils::validateStorageCapacity(
        info.capability_key, sizeof(NodeCapabilityRecord{}.capability_key),
        sizeof(NodeCapabilityRecord{}.capability_key), &local_ctx);
    if (status != Status::OK)
    {
        return status;
    }

    auto duplicate_predicate = [&info](const NodeCapabilityRecord& row) {
        return row.is_valid == 1 &&
               row.capability_id != info.capability_id &&
               row.node_id == info.node_id &&
               fixedNameFromBuffer(row.capability_key, sizeof(row.capability_key)) == info.capability_key;
    };
    auto duplicate = findRecordInHeapPage<NodeCapabilityRecord>(
        node_capability_table_page_, duplicate_predicate, ctx);
    if (duplicate.status == Status::OK)
    {
        return Status::CONSTRAINT_VIOLATION;
    }
    if (duplicate.status != Status::NOT_FOUND)
    {
        return duplicate.status;
    }

    NodeCapabilityRecord rec{};
    rec.capability_id = info.capability_id;
    rec.node_id = info.node_id;
    std::strncpy(rec.capability_key,
                 UTF8Utils::truncateToBytes(info.capability_key, sizeof(rec.capability_key)).c_str(),
                 sizeof(rec.capability_key) - 1);
    rec.created_time = (info.created_time == 0) ? catalogNowTicks() : info.created_time;
    rec.last_modified_time = (info.last_modified_time == 0) ? catalogNowTicks() : info.last_modified_time;
    rec.is_valid = info.is_valid ? 1 : 0;
    uint64_t xmin = 0;
    if (!info.capability_value.empty())
    {
        status = storeStringInToast(info.capability_value, xmin, rec.capability_value_oid, ctx);
        if (status != Status::OK)
        {
            return status;
        }
    }

    auto existing_predicate = [&info](const NodeCapabilityRecord& row) {
        return row.capability_id == info.capability_id && row.is_valid == 1;
    };
    auto existing = findRecordInHeapPage<NodeCapabilityRecord>(
        node_capability_table_page_, existing_predicate, ctx);
    if (existing.status == Status::OK)
    {
        rec.created_time = existing.record.created_time;
    }
    else if (existing.status != Status::NOT_FOUND)
    {
        return existing.status;
    }

    auto matcher = [&info](const NodeCapabilityRecord& row) {
        return row.capability_id == info.capability_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(node_capability_table_page_, matcher, rec, ctx);
}

auto CatalogManager::getNodeCapabilityCatalogEntry(const ID& capability_id,
                                                   NodeCapabilityCatalogInfo& info_out,
                                                   ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    auto predicate = [&capability_id](const NodeCapabilityRecord& rec) {
        return rec.capability_id == capability_id && rec.is_valid == 1;
    };
    auto result = findRecordInHeapPage<NodeCapabilityRecord>(node_capability_table_page_, predicate, ctx);
    if (result.status != Status::OK)
    {
        return Status::NOT_FOUND;
    }

    info_out = NodeCapabilityCatalogInfo{};
    info_out.capability_id = result.record.capability_id;
    info_out.node_id = result.record.node_id;
    info_out.capability_key =
        fixedNameFromBuffer(result.record.capability_key, sizeof(result.record.capability_key));
    info_out.created_time = result.record.created_time;
    info_out.last_modified_time = result.record.last_modified_time;
    info_out.is_valid = result.record.is_valid == 1;
    if (!isZeroUuidLocal(result.record.capability_value_oid))
    {
        uint64_t xmin = 0;
        Status status = loadStringFromToast(result.record.capability_value_oid, xmin, info_out.capability_value, ctx);
        if (status != Status::OK)
        {
            return status;
        }
    }
    return Status::OK;
}

auto CatalogManager::listNodeCapabilityCatalogEntries(const ID& node_id,
                                                      std::vector<NodeCapabilityCatalogInfo>& rows_out,
                                                      ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    rows_out.clear();
    auto filter = [&node_id](const NodeCapabilityRecord& rec) {
        if (rec.is_valid != 1)
        {
            return false;
        }
        return isZeroUuidLocal(node_id) || rec.node_id == node_id;
    };
    auto converter = [this, ctx](const NodeCapabilityRecord& rec, NodeCapabilityCatalogInfo& info) {
        info = NodeCapabilityCatalogInfo{};
        info.capability_id = rec.capability_id;
        info.node_id = rec.node_id;
        info.capability_key = fixedNameFromBuffer(rec.capability_key, sizeof(rec.capability_key));
        info.created_time = rec.created_time;
        info.last_modified_time = rec.last_modified_time;
        info.is_valid = rec.is_valid == 1;
        if (!isZeroUuidLocal(rec.capability_value_oid))
        {
            uint64_t xmin = 0;
            std::string text;
            if (loadStringFromToast(rec.capability_value_oid, xmin, text, ctx) == Status::OK)
            {
                info.capability_value = std::move(text);
            }
        }
    };
    return readRecordsToVector<NodeCapabilityRecord, NodeCapabilityCatalogInfo>(
        node_capability_table_page_, rows_out, filter, converter, ctx);
}

