auto CatalogManager::upsertClockSourceCatalogEntry(const ClockSourceCatalogInfo& info,
                                                   ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.clock_source_id) || isZeroUuidLocal(info.clock_policy_id) ||
        info.endpoint.empty())
    {
        return Status::INVALID_ARGUMENT;
    }
    if (!isValidClockSourceKind(info.source_kind))
    {
        return Status::INVALID_ARGUMENT;
    }
    if ((info.has_last_probe_time && info.last_probe_time == 0) ||
        (info.has_last_probe_jitter_ms && !info.has_last_probe_time))
    {
        return Status::INVALID_ARGUMENT;
    }
    ErrorContext local_ctx;
    Status status = UTF8Utils::validateStorageCapacity(
        info.endpoint, sizeof(ClockSourceRecord{}.endpoint),
        sizeof(ClockSourceRecord{}.endpoint), &local_ctx);
    if (status != Status::OK)
    {
        return status;
    }
    auto policy_predicate = [&info](const ClockPolicyRecord& rec) {
        return rec.clock_policy_id == info.clock_policy_id && rec.is_valid == 1;
    };
    auto policy = findRecordInHeapPage<ClockPolicyRecord>(clock_policy_table_page_, policy_predicate, ctx);
    if (policy.status != Status::OK)
    {
        return Status::NOT_FOUND;
    }

    auto duplicate_predicate = [&info](const ClockSourceRecord& row) {
        return row.is_valid == 1 &&
               row.clock_source_id != info.clock_source_id &&
               row.clock_policy_id == info.clock_policy_id &&
               row.priority_rank == info.priority_rank;
    };
    auto duplicate = findRecordInHeapPage<ClockSourceRecord>(clock_source_table_page_, duplicate_predicate, ctx);
    if (duplicate.status == Status::OK)
    {
        return Status::CONSTRAINT_VIOLATION;
    }
    if (duplicate.status != Status::NOT_FOUND)
    {
        return duplicate.status;
    }

    ClockSourceRecord rec{};
    rec.clock_source_id = info.clock_source_id;
    rec.clock_policy_id = info.clock_policy_id;
    rec.source_kind = static_cast<uint8_t>(info.source_kind);
    std::strncpy(rec.endpoint,
                 UTF8Utils::truncateToBytes(info.endpoint, sizeof(rec.endpoint)).c_str(),
                 sizeof(rec.endpoint) - 1);
    rec.priority_rank = info.priority_rank;
    rec.is_enabled = info.is_enabled ? 1 : 0;
    rec.has_last_probe_time = info.has_last_probe_time ? 1 : 0;
    rec.last_probe_time = info.has_last_probe_time ? info.last_probe_time : 0;
    rec.has_last_probe_offset_ms = info.has_last_probe_offset_ms ? 1 : 0;
    rec.last_probe_offset_ms = info.has_last_probe_offset_ms ? info.last_probe_offset_ms : 0;
    rec.has_last_probe_jitter_ms = info.has_last_probe_jitter_ms ? 1 : 0;
    rec.last_probe_jitter_ms = info.has_last_probe_jitter_ms ? info.last_probe_jitter_ms : 0;
    rec.version_u64 = (info.version_u64 == 0) ? 1 : info.version_u64;
    rec.is_valid = info.is_valid ? 1 : 0;

    auto matcher = [&info](const ClockSourceRecord& row) {
        return row.clock_source_id == info.clock_source_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(clock_source_table_page_, matcher, rec, ctx);
}

auto CatalogManager::getClockSourceCatalogEntry(const ID& clock_source_id,
                                                ClockSourceCatalogInfo& info_out,
                                                ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    auto predicate = [&clock_source_id](const ClockSourceRecord& rec) {
        return rec.clock_source_id == clock_source_id && rec.is_valid == 1;
    };
    auto result = findRecordInHeapPage<ClockSourceRecord>(clock_source_table_page_, predicate, ctx);
    if (result.status != Status::OK)
    {
        return Status::NOT_FOUND;
    }
    if (!isValidClockSourceKind(static_cast<ClockSourceKind>(result.record.source_kind)))
    {
        return Status::PAGE_CORRUPT;
    }

    info_out = ClockSourceCatalogInfo{};
    info_out.clock_source_id = result.record.clock_source_id;
    info_out.clock_policy_id = result.record.clock_policy_id;
    info_out.source_kind = static_cast<ClockSourceKind>(result.record.source_kind);
    info_out.endpoint = fixedNameFromBuffer(result.record.endpoint, sizeof(result.record.endpoint));
    info_out.priority_rank = result.record.priority_rank;
    info_out.is_enabled = result.record.is_enabled != 0;
    info_out.has_last_probe_time = result.record.has_last_probe_time != 0;
    info_out.last_probe_time = result.record.last_probe_time;
    info_out.has_last_probe_offset_ms = result.record.has_last_probe_offset_ms != 0;
    info_out.last_probe_offset_ms = result.record.last_probe_offset_ms;
    info_out.has_last_probe_jitter_ms = result.record.has_last_probe_jitter_ms != 0;
    info_out.last_probe_jitter_ms = result.record.last_probe_jitter_ms;
    info_out.version_u64 = result.record.version_u64;
    info_out.is_valid = result.record.is_valid == 1;
    return Status::OK;
}

