auto CatalogManager::upsertClockViolationEventCatalogEntry(const ClockViolationEventCatalogInfo& info,
                                                           ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.clock_violation_event_id) || isZeroUuidLocal(info.node_id) ||
        isZeroUuidLocal(info.clock_policy_id) || info.event_time == 0)
    {
        return Status::INVALID_ARGUMENT;
    }
    if (!isValidClockStateLabel(info.clock_state) ||
        info.clock_state == ClockStateLabel::HEALTHY ||
        !isValidClockActionTaken(info.action_taken))
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.has_resolved_time && info.resolved_time < info.event_time)
    {
        return Status::INVALID_ARGUMENT;
    }
    auto node_predicate = [&info](const NodeRecord& rec) {
        return rec.node_id == info.node_id && rec.is_valid == 1;
    };
    auto node = findRecordInHeapPage<NodeRecord>(node_table_page_, node_predicate, ctx);
    if (node.status != Status::OK)
    {
        return Status::NOT_FOUND;
    }
    auto policy_predicate = [&info](const ClockPolicyRecord& rec) {
        return rec.clock_policy_id == info.clock_policy_id && rec.is_valid == 1;
    };
    auto policy = findRecordInHeapPage<ClockPolicyRecord>(clock_policy_table_page_, policy_predicate, ctx);
    if (policy.status != Status::OK)
    {
        return Status::NOT_FOUND;
    }

    ClockViolationEventRecord rec{};
    rec.clock_violation_event_id = info.clock_violation_event_id;
    rec.node_id = info.node_id;
    rec.clock_policy_id = info.clock_policy_id;
    rec.clock_state = static_cast<uint8_t>(info.clock_state);
    rec.offset_ms = info.offset_ms;
    rec.jitter_ms = info.jitter_ms;
    rec.action_taken = static_cast<uint8_t>(info.action_taken);
    rec.event_time = info.event_time;
    rec.has_resolved_time = info.has_resolved_time ? 1 : 0;
    rec.resolved_time = info.has_resolved_time ? info.resolved_time : 0;
    rec.version_u64 = (info.version_u64 == 0) ? 1 : info.version_u64;
    rec.is_valid = info.is_valid ? 1 : 0;

    auto matcher = [&info](const ClockViolationEventRecord& row) {
        return row.clock_violation_event_id == info.clock_violation_event_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(clock_violation_event_table_page_, matcher, rec, ctx);
}

