auto CatalogManager::upsertClusterCatalogEntry(const ClusterCatalogInfo& info,
                                               ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.cluster_id) || info.cluster_name.empty() ||
        !isValidClusterMode(info.cluster_mode) ||
        !isValidClusterState(info.cluster_state) ||
        !isValidConsensusMode(info.consensus_mode))
    {
        return Status::INVALID_ARGUMENT;
    }

    ErrorContext local_ctx;
    Status status = UTF8Utils::validateStorageCapacity(
        info.cluster_name, sizeof(ClusterRecord{}.cluster_name), sizeof(ClusterRecord{}.cluster_name), &local_ctx);
    if (status != Status::OK)
    {
        return status;
    }

    auto duplicate_predicate = [&info](const ClusterRecord& row) {
        return row.is_valid == 1 &&
               row.cluster_id != info.cluster_id &&
               fixedNameFromBuffer(row.cluster_name, sizeof(row.cluster_name)) == info.cluster_name;
    };
    auto duplicate = findRecordInHeapPage<ClusterRecord>(cluster_table_page_, duplicate_predicate, ctx);
    if (duplicate.status == Status::OK)
    {
        return Status::CONSTRAINT_VIOLATION;
    }
    if (duplicate.status != Status::NOT_FOUND)
    {
        return duplicate.status;
    }

    const uint64_t now = catalogNowTicks();
    ClusterRecord rec{};
    rec.cluster_id = info.cluster_id;
    std::strncpy(rec.cluster_name,
                 UTF8Utils::truncateToBytes(info.cluster_name, sizeof(rec.cluster_name)).c_str(),
                 sizeof(rec.cluster_name) - 1);
    rec.cluster_mode = static_cast<uint8_t>(info.cluster_mode);
    rec.cluster_state = static_cast<uint8_t>(info.cluster_state);
    rec.consensus_mode = static_cast<uint8_t>(info.consensus_mode);
    rec.cluster_state_version = info.cluster_state_version;
    rec.policy_id = info.policy_id;
    rec.config_version = info.config_version;
    rec.created_txid = info.created_txid;
    rec.last_modified_txid = info.last_modified_txid;
    rec.created_time = (info.created_time == 0) ? now : info.created_time;
    rec.last_state_change_time = (info.last_state_change_time == 0) ? now : info.last_state_change_time;
    rec.is_valid = info.is_valid ? 1 : 0;
    if (!info.description.empty())
    {
        uint64_t xmin = 0;
        status = storeStringInToast(info.description, xmin, rec.description_oid, ctx);
        if (status != Status::OK)
        {
            return status;
        }
    }

    auto existing_predicate = [&info](const ClusterRecord& row) {
        return row.cluster_id == info.cluster_id && row.is_valid == 1;
    };
    auto existing = findRecordInHeapPage<ClusterRecord>(cluster_table_page_, existing_predicate, ctx);
    std::string previous_cluster_name;
    if (existing.status == Status::OK)
    {
        rec.created_time = existing.record.created_time;
        rec.created_txid = existing.record.created_txid;
        previous_cluster_name = fixedNameFromBuffer(existing.record.cluster_name,
                                                    sizeof(existing.record.cluster_name));
    }
    else if (existing.status != Status::NOT_FOUND)
    {
        return existing.status;
    }

    auto matcher = [&info](const ClusterRecord& row) {
        return row.cluster_id == info.cluster_id && row.is_valid == 1;
    };
    status = updateRecordInHeapPage(cluster_table_page_, matcher, rec, ctx);
    if (status != Status::OK)
    {
        return status;
    }

    if (rec.is_valid == 1)
    {
        status = ensureOverlaySchemaChildUnlocked("cluster", info.cluster_name, nullptr, ctx);
        if (status != Status::OK)
        {
            SET_ERROR_CONTEXT(ctx, status, "Failed to create cluster overlay schema");
            return status;
        }

        if (!previous_cluster_name.empty() &&
            !IdentifierUtils::namesConflict(info.cluster_name, false /*new_is_delimited*/,
                                            previous_cluster_name, false /*stored_delimited*/))
        {
            status = dropOverlaySchemaChildUnlocked("cluster", previous_cluster_name, ctx);
            if (status != Status::OK)
            {
                SET_ERROR_CONTEXT(ctx, status, "Failed to drop previous cluster overlay schema");
                return status;
            }
        }
    }

    return Status::OK;
}

auto CatalogManager::getClusterCatalogEntry(const ID& cluster_id,
                                            ClusterCatalogInfo& info_out,
                                            ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    auto predicate = [&cluster_id](const ClusterRecord& rec) {
        return rec.cluster_id == cluster_id && rec.is_valid == 1;
    };
    auto result = findRecordInHeapPage<ClusterRecord>(cluster_table_page_, predicate, ctx);
    if (result.status != Status::OK)
    {
        return Status::NOT_FOUND;
    }
    if (!isValidClusterMode(static_cast<ClusterMode>(result.record.cluster_mode)) ||
        !isValidClusterState(static_cast<ClusterState>(result.record.cluster_state)) ||
        !isValidConsensusMode(static_cast<ConsensusMode>(result.record.consensus_mode)))
    {
        return Status::PAGE_CORRUPT;
    }

    info_out = ClusterCatalogInfo{};
    info_out.cluster_id = result.record.cluster_id;
    info_out.cluster_name = fixedNameFromBuffer(result.record.cluster_name, sizeof(result.record.cluster_name));
    info_out.cluster_mode = static_cast<ClusterMode>(result.record.cluster_mode);
    info_out.cluster_state = static_cast<ClusterState>(result.record.cluster_state);
    info_out.cluster_state_version = result.record.cluster_state_version;
    info_out.consensus_mode = static_cast<ConsensusMode>(result.record.consensus_mode);
    info_out.policy_id = result.record.policy_id;
    info_out.config_version = result.record.config_version;
    info_out.created_txid = result.record.created_txid;
    info_out.last_modified_txid = result.record.last_modified_txid;
    info_out.created_time = result.record.created_time;
    info_out.last_state_change_time = result.record.last_state_change_time;
    info_out.is_valid = result.record.is_valid == 1;
    if (!isZeroUuidLocal(result.record.description_oid))
    {
        uint64_t xmin = 0;
        Status status = loadStringFromToast(result.record.description_oid, xmin, info_out.description, ctx);
        if (status != Status::OK)
        {
            return status;
        }
    }
    return Status::OK;
}

auto CatalogManager::listClusterCatalogEntries(std::vector<ClusterCatalogInfo>& rows_out,
                                               ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    rows_out.clear();
    auto filter = [](const ClusterRecord& rec) { return rec.is_valid == 1; };
    auto converter = [this, ctx](const ClusterRecord& rec, ClusterCatalogInfo& info) {
        info = ClusterCatalogInfo{};
        info.cluster_id = rec.cluster_id;
        info.cluster_name = fixedNameFromBuffer(rec.cluster_name, sizeof(rec.cluster_name));
        info.cluster_mode = static_cast<ClusterMode>(rec.cluster_mode);
        info.cluster_state = static_cast<ClusterState>(rec.cluster_state);
        info.cluster_state_version = rec.cluster_state_version;
        info.consensus_mode = static_cast<ConsensusMode>(rec.consensus_mode);
        info.policy_id = rec.policy_id;
        info.config_version = rec.config_version;
        info.created_txid = rec.created_txid;
        info.last_modified_txid = rec.last_modified_txid;
        info.created_time = rec.created_time;
        info.last_state_change_time = rec.last_state_change_time;
        info.is_valid = rec.is_valid == 1;
        if (!isZeroUuidLocal(rec.description_oid))
        {
            uint64_t xmin = 0;
            std::string text;
            if (loadStringFromToast(rec.description_oid, xmin, text, ctx) == Status::OK)
            {
                info.description = std::move(text);
            }
        }
    };
    return readRecordsToVector<ClusterRecord, ClusterCatalogInfo>(
        cluster_table_page_, rows_out, filter, converter, ctx);
}

auto CatalogManager::deleteClusterCatalogEntry(const ID& cluster_id,
                                               ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    auto predicate = [&cluster_id](const ClusterRecord& rec) {
        return rec.cluster_id == cluster_id && rec.is_valid == 1;
    };
    auto result = findRecordInHeapPage<ClusterRecord>(cluster_table_page_, predicate, ctx);
    if (result.status != Status::OK)
    {
        return Status::NOT_FOUND;
    }
    const std::string cluster_name =
        fixedNameFromBuffer(result.record.cluster_name, sizeof(result.record.cluster_name));
    ClusterRecord updated = result.record;
    updated.is_valid = 0;
    updated.last_state_change_time = catalogNowTicks();
    Status status = updateRecordInHeapPage(cluster_table_page_, result.slot_index, updated, ctx);
    if (status != Status::OK)
    {
        return status;
    }

    status = dropOverlaySchemaChildUnlocked("cluster", cluster_name, ctx);
    if (status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, status, "Failed to drop cluster overlay schema");
        return status;
    }

    return Status::OK;
}

auto CatalogManager::upsertShardPolicyCatalogEntry(const ShardPolicyCatalogInfo& info,
                                                   ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.policy_id) || info.policy_name.empty() || info.replication_factor == 0 ||
        !isValidConsistencyLevel(info.consistency_read) ||
        !isValidConsistencyLevel(info.consistency_write) ||
        !isValidFailoverMode(info.failover_mode) ||
        !isValidRebalanceMode(info.rebalance_mode))
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.shard_growth_trigger_pct > 100)
    {
        return Status::INVALID_ARGUMENT;
    }

    ErrorContext local_ctx;
    Status status = UTF8Utils::validateStorageCapacity(
        info.policy_name, sizeof(ShardPolicyRecord{}.policy_name), sizeof(ShardPolicyRecord{}.policy_name), &local_ctx);
    if (status != Status::OK)
    {
        return status;
    }

    auto duplicate_predicate = [&info](const ShardPolicyRecord& row) {
        return row.is_valid == 1 &&
               row.policy_id != info.policy_id &&
               fixedNameFromBuffer(row.policy_name, sizeof(row.policy_name)) == info.policy_name;
    };
    auto duplicate = findRecordInHeapPage<ShardPolicyRecord>(shard_policy_table_page_, duplicate_predicate, ctx);
    if (duplicate.status == Status::OK)
    {
        return Status::CONSTRAINT_VIOLATION;
    }
    if (duplicate.status != Status::NOT_FOUND)
    {
        return duplicate.status;
    }

    const uint64_t now = catalogNowTicks();
    ShardPolicyRecord rec{};
    rec.policy_id = info.policy_id;
    std::strncpy(rec.policy_name,
                 UTF8Utils::truncateToBytes(info.policy_name, sizeof(rec.policy_name)).c_str(),
                 sizeof(rec.policy_name) - 1);
    rec.replication_factor = info.replication_factor;
    rec.consistency_read = static_cast<uint8_t>(info.consistency_read);
    rec.consistency_write = static_cast<uint8_t>(info.consistency_write);
    rec.failover_mode = static_cast<uint8_t>(info.failover_mode);
    rec.rebalance_mode = static_cast<uint8_t>(info.rebalance_mode);
    rec.shard_key_required = info.shard_key_required ? 1 : 0;
    rec.allow_cross_shard_txn = info.allow_cross_shard_txn ? 1 : 0;
    rec.default_shard_count = info.default_shard_count;
    rec.shard_size_target_mb = info.shard_size_target_mb;
    rec.shard_growth_trigger_pct = info.shard_growth_trigger_pct;
    rec.rebalance_interval_ms = info.rebalance_interval_ms;
    rec.created_txid = info.created_txid;
    rec.last_modified_txid = info.last_modified_txid;
    rec.created_time = (info.created_time == 0) ? now : info.created_time;
    rec.last_modified_time = (info.last_modified_time == 0) ? now : info.last_modified_time;
    rec.is_valid = info.is_valid ? 1 : 0;

    auto existing_predicate = [&info](const ShardPolicyRecord& row) {
        return row.policy_id == info.policy_id && row.is_valid == 1;
    };
    auto existing = findRecordInHeapPage<ShardPolicyRecord>(shard_policy_table_page_, existing_predicate, ctx);
    if (existing.status == Status::OK)
    {
        rec.created_time = existing.record.created_time;
        rec.created_txid = existing.record.created_txid;
    }
    else if (existing.status != Status::NOT_FOUND)
    {
        return existing.status;
    }

    auto matcher = [&info](const ShardPolicyRecord& row) {
        return row.policy_id == info.policy_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(shard_policy_table_page_, matcher, rec, ctx);
}

