auto CatalogManager::upsertShardKeyCatalogEntry(const ShardKeyCatalogInfo& info,
                                                ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.shard_key_id) || isZeroUuidLocal(info.table_id) ||
        !isValidShardKeyKind(info.shard_key_kind) ||
        !isValidHashFunctionKind(info.hash_function))
    {
        return Status::INVALID_ARGUMENT;
    }
    const bool has_key_columns = !isZeroUuidLocal(info.key_columns_id);
    const bool has_key_expression = !isZeroUuidLocal(info.key_expression_sblr_id);
    if (has_key_columns == has_key_expression)
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.has_partition_count && info.partition_count == 0)
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.has_range_order &&
        (!isValidRangeOrderKind(info.range_order) || info.shard_key_kind != ShardKeyKind::RANGE))
    {
        return Status::INVALID_ARGUMENT;
    }

    auto table_predicate = [&info](const TableRecord& row) {
        return row.table_id == info.table_id && row.is_valid == 1;
    };
    auto table = findRecordInHeapPage<TableRecord>(tables_table_page_, table_predicate, ctx);
    if (table.status != Status::OK)
    {
        return Status::NOT_FOUND;
    }

    if (info.is_active)
    {
        auto duplicate_active = [&info](const ShardKeyRecord& row) {
            return row.is_valid == 1 &&
                   row.shard_key_id != info.shard_key_id &&
                   row.table_id == info.table_id &&
                   row.is_active == 1;
        };
        auto existing_active = findRecordInHeapPage<ShardKeyRecord>(shard_key_table_page_, duplicate_active, ctx);
        if (existing_active.status == Status::OK)
        {
            return Status::CONSTRAINT_VIOLATION;
        }
        if (existing_active.status != Status::NOT_FOUND)
        {
            return existing_active.status;
        }
    }

    const uint64_t now = catalogNowTicks();
    ShardKeyRecord rec{};
    rec.shard_key_id = info.shard_key_id;
    rec.table_id = info.table_id;
    rec.shard_key_kind = static_cast<uint8_t>(info.shard_key_kind);
    rec.hash_function = static_cast<uint8_t>(info.hash_function);
    rec.has_partition_count = info.has_partition_count ? 1 : 0;
    rec.has_range_order = info.has_range_order ? 1 : 0;
    rec.range_order = static_cast<uint8_t>(info.range_order);
    rec.is_active = info.is_active ? 1 : 0;
    rec.is_valid = info.is_valid ? 1 : 0;
    rec.key_columns_id = info.key_columns_id;
    rec.key_expression_sblr_id = info.key_expression_sblr_id;
    rec.partition_count = info.partition_count;
    rec.key_version = info.key_version;
    rec.created_txid = info.created_txid;
    rec.last_modified_txid = info.last_modified_txid;
    rec.created_time = (info.created_time == 0) ? now : info.created_time;
    rec.last_modified_time = (info.last_modified_time == 0) ? now : info.last_modified_time;

    auto existing_predicate = [&info](const ShardKeyRecord& row) {
        return row.shard_key_id == info.shard_key_id && row.is_valid == 1;
    };
    auto existing = findRecordInHeapPage<ShardKeyRecord>(shard_key_table_page_, existing_predicate, ctx);
    if (existing.status == Status::OK)
    {
        rec.created_time = existing.record.created_time;
        rec.created_txid = existing.record.created_txid;
    }
    else if (existing.status != Status::NOT_FOUND)
    {
        return existing.status;
    }

    auto matcher = [&info](const ShardKeyRecord& row) {
        return row.shard_key_id == info.shard_key_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(shard_key_table_page_, matcher, rec, ctx);
}

auto CatalogManager::getShardKeyCatalogEntry(const ID& shard_key_id,
                                             ShardKeyCatalogInfo& info_out,
                                             ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    auto predicate = [&shard_key_id](const ShardKeyRecord& rec) {
        return rec.shard_key_id == shard_key_id && rec.is_valid == 1;
    };
    auto result = findRecordInHeapPage<ShardKeyRecord>(shard_key_table_page_, predicate, ctx);
    if (result.status != Status::OK)
    {
        return Status::NOT_FOUND;
    }
    if (!isValidShardKeyKind(static_cast<ShardKeyKind>(result.record.shard_key_kind)) ||
        !isValidHashFunctionKind(static_cast<HashFunctionKind>(result.record.hash_function)) ||
        (result.record.has_range_order != 0 &&
         !isValidRangeOrderKind(static_cast<RangeOrderKind>(result.record.range_order))))
    {
        return Status::PAGE_CORRUPT;
    }

    info_out = ShardKeyCatalogInfo{};
    info_out.shard_key_id = result.record.shard_key_id;
    info_out.table_id = result.record.table_id;
    info_out.shard_key_kind = static_cast<ShardKeyKind>(result.record.shard_key_kind);
    info_out.key_columns_id = result.record.key_columns_id;
    info_out.key_expression_sblr_id = result.record.key_expression_sblr_id;
    info_out.hash_function = static_cast<HashFunctionKind>(result.record.hash_function);
    info_out.has_partition_count = result.record.has_partition_count != 0;
    info_out.partition_count = result.record.partition_count;
    info_out.has_range_order = result.record.has_range_order != 0;
    info_out.range_order = static_cast<RangeOrderKind>(result.record.range_order);
    info_out.key_version = result.record.key_version;
    info_out.is_active = result.record.is_active != 0;
    info_out.created_txid = result.record.created_txid;
    info_out.last_modified_txid = result.record.last_modified_txid;
    info_out.created_time = result.record.created_time;
    info_out.last_modified_time = result.record.last_modified_time;
    info_out.is_valid = result.record.is_valid == 1;
    return Status::OK;
}

