auto CatalogManager::upsertShardMigrationCatalogEntry(const ShardMigrationCatalogInfo& info,
                                                      ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.migration_id) || isZeroUuidLocal(info.shard_id) ||
        isZeroUuidLocal(info.source_node_id) || isZeroUuidLocal(info.target_node_id) ||
        info.source_node_id == info.target_node_id ||
        !isValidShardMigrationState(info.state) || !isValidThrottleState(info.throttle_state))
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.bytes_copied > info.bytes_total || info.rows_copied > info.rows_total)
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.has_completed_time && info.completed_time < info.started_time)
    {
        return Status::INVALID_ARGUMENT;
    }

    auto shard_predicate = [&info](const ShardRecord& rec) {
        return rec.shard_id == info.shard_id && rec.is_valid == 1;
    };
    auto shard = findRecordInHeapPage<ShardRecord>(shard_table_page_, shard_predicate, ctx);
    if (shard.status != Status::OK)
    {
        return Status::NOT_FOUND;
    }
    auto source_node_predicate = [&info](const NodeRecord& rec) {
        return rec.node_id == info.source_node_id && rec.is_valid == 1;
    };
    auto source_node = findRecordInHeapPage<NodeRecord>(node_table_page_, source_node_predicate, ctx);
    if (source_node.status != Status::OK)
    {
        return Status::NOT_FOUND;
    }
    auto target_node_predicate = [&info](const NodeRecord& rec) {
        return rec.node_id == info.target_node_id && rec.is_valid == 1;
    };
    auto target_node = findRecordInHeapPage<NodeRecord>(node_table_page_, target_node_predicate, ctx);
    if (target_node.status != Status::OK)
    {
        return Status::NOT_FOUND;
    }
    if (!info.error_code.empty())
    {
        ErrorContext local_ctx;
        Status status = UTF8Utils::validateStorageCapacity(
            info.error_code, sizeof(ShardMigrationRecord{}.error_code),
            sizeof(ShardMigrationRecord{}.error_code), &local_ctx);
        if (status != Status::OK)
        {
            return status;
        }
    }

    ShardMigrationRecord rec{};
    rec.migration_id = info.migration_id;
    rec.shard_id = info.shard_id;
    rec.source_node_id = info.source_node_id;
    rec.target_node_id = info.target_node_id;
    rec.state = static_cast<uint8_t>(info.state);
    rec.throttle_state = static_cast<uint8_t>(info.throttle_state);
    rec.bytes_total = info.bytes_total;
    rec.bytes_copied = info.bytes_copied;
    rec.rows_total = info.rows_total;
    rec.rows_copied = info.rows_copied;
    rec.started_time = info.started_time;
    rec.updated_time = info.updated_time;
    rec.has_completed_time = info.has_completed_time ? 1 : 0;
    rec.completed_time = info.has_completed_time ? info.completed_time : 0;
    rec.is_valid = info.is_valid ? 1 : 0;
    if (!info.error_code.empty())
    {
        std::strncpy(rec.error_code,
                     UTF8Utils::truncateToBytes(info.error_code, sizeof(rec.error_code)).c_str(),
                     sizeof(rec.error_code) - 1);
    }
    if (!info.error_message.empty())
    {
        uint64_t xmin = 0;
        Status status = storeStringInToast(info.error_message, xmin, rec.error_message_oid, ctx);
        if (status != Status::OK)
        {
            return status;
        }
    }

    auto existing_predicate = [&info](const ShardMigrationRecord& row) {
        return row.migration_id == info.migration_id && row.is_valid == 1;
    };
    auto existing = findRecordInHeapPage<ShardMigrationRecord>(shard_migration_table_page_, existing_predicate, ctx);
    if (existing.status != Status::NOT_FOUND && existing.status != Status::OK)
    {
        return existing.status;
    }

    auto matcher = [&info](const ShardMigrationRecord& row) {
        return row.migration_id == info.migration_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(shard_migration_table_page_, matcher, rec, ctx);
}

