auto CatalogManager::upsertShardZoneCatalogEntry(const ShardZoneCatalogInfo& info,
                                                 ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.zone_id) || info.zone_name.empty())
    {
        return Status::INVALID_ARGUMENT;
    }

    ErrorContext local_ctx;
    Status status = UTF8Utils::validateStorageCapacity(
        info.zone_name, sizeof(ShardZoneRecord{}.zone_name), sizeof(ShardZoneRecord{}.zone_name), &local_ctx);
    if (status != Status::OK)
    {
        return status;
    }

    auto duplicate_predicate = [&info](const ShardZoneRecord& row) {
        return row.is_valid == 1 &&
               row.zone_id != info.zone_id &&
               fixedNameFromBuffer(row.zone_name, sizeof(row.zone_name)) == info.zone_name;
    };
    auto duplicate = findRecordInHeapPage<ShardZoneRecord>(shard_zone_table_page_, duplicate_predicate, ctx);
    if (duplicate.status == Status::OK)
    {
        return Status::CONSTRAINT_VIOLATION;
    }
    if (duplicate.status != Status::NOT_FOUND)
    {
        return duplicate.status;
    }

    ShardZoneRecord rec{};
    rec.zone_id = info.zone_id;
    std::strncpy(rec.zone_name,
                 UTF8Utils::truncateToBytes(info.zone_name, sizeof(rec.zone_name)).c_str(),
                 sizeof(rec.zone_name) - 1);
    rec.created_time = (info.created_time == 0) ? catalogNowTicks() : info.created_time;
    rec.last_modified_time = (info.last_modified_time == 0) ? catalogNowTicks() : info.last_modified_time;
    rec.is_valid = info.is_valid ? 1 : 0;
    if (!info.description.empty())
    {
        uint64_t xmin = 0;
        status = storeStringInToast(info.description, xmin, rec.description_oid, ctx);
        if (status != Status::OK)
        {
            return status;
        }
    }

    auto existing_predicate = [&info](const ShardZoneRecord& row) {
        return row.zone_id == info.zone_id && row.is_valid == 1;
    };
    auto existing = findRecordInHeapPage<ShardZoneRecord>(shard_zone_table_page_, existing_predicate, ctx);
    if (existing.status == Status::OK)
    {
        rec.created_time = existing.record.created_time;
    }
    else if (existing.status != Status::NOT_FOUND)
    {
        return existing.status;
    }

    auto matcher = [&info](const ShardZoneRecord& row) {
        return row.zone_id == info.zone_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(shard_zone_table_page_, matcher, rec, ctx);
}

