auto CatalogManager::upsertShardZoneRangeCatalogEntry(const ShardZoneRangeCatalogInfo& info,
                                                      ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.zone_range_id) || isZeroUuidLocal(info.zone_id) || isZeroUuidLocal(info.range_id))
    {
        return Status::INVALID_ARGUMENT;
    }

    auto zone_predicate = [&info](const ShardZoneRecord& rec) {
        return rec.zone_id == info.zone_id && rec.is_valid == 1;
    };
    auto zone = findRecordInHeapPage<ShardZoneRecord>(shard_zone_table_page_, zone_predicate, ctx);
    if (zone.status != Status::OK)
    {
        return Status::NOT_FOUND;
    }
    auto range_predicate = [&info](const ShardRangeRecord& rec) {
        return rec.range_id == info.range_id && rec.is_valid == 1;
    };
    auto range = findRecordInHeapPage<ShardRangeRecord>(shard_range_table_page_, range_predicate, ctx);
    if (range.status != Status::OK)
    {
        return Status::NOT_FOUND;
    }

    auto duplicate_predicate = [&info](const ShardZoneRangeRecord& row) {
        return row.is_valid == 1 &&
               row.zone_range_id != info.zone_range_id &&
               row.zone_id == info.zone_id &&
               row.range_id == info.range_id;
    };
    auto duplicate = findRecordInHeapPage<ShardZoneRangeRecord>(shard_zone_range_table_page_, duplicate_predicate, ctx);
    if (duplicate.status == Status::OK)
    {
        return Status::CONSTRAINT_VIOLATION;
    }
    if (duplicate.status != Status::NOT_FOUND)
    {
        return duplicate.status;
    }

    ShardZoneRangeRecord rec{};
    rec.zone_range_id = info.zone_range_id;
    rec.zone_id = info.zone_id;
    rec.range_id = info.range_id;
    rec.created_time = (info.created_time == 0) ? catalogNowTicks() : info.created_time;
    rec.last_modified_time = (info.last_modified_time == 0) ? catalogNowTicks() : info.last_modified_time;
    rec.is_valid = info.is_valid ? 1 : 0;

    auto existing_predicate = [&info](const ShardZoneRangeRecord& row) {
        return row.zone_range_id == info.zone_range_id && row.is_valid == 1;
    };
    auto existing = findRecordInHeapPage<ShardZoneRangeRecord>(shard_zone_range_table_page_, existing_predicate, ctx);
    if (existing.status == Status::OK)
    {
        rec.created_time = existing.record.created_time;
    }
    else if (existing.status != Status::NOT_FOUND)
    {
        return existing.status;
    }

    auto matcher = [&info](const ShardZoneRangeRecord& row) {
        return row.zone_range_id == info.zone_range_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(shard_zone_range_table_page_, matcher, rec, ctx);
}

