auto CatalogManager::upsertWorkloadClassCatalogEntry(const WorkloadClassCatalogInfo& info,
                                                     ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.class_id) || info.class_name.empty() ||
        !isValidWorkloadMatchKind(info.match_kind))
    {
        return Status::INVALID_ARGUMENT;
    }
    const bool has_expr = !isZeroUuidLocal(info.match_expr_sblr_id);
    const bool has_text = !info.match_text.empty();
    if (has_expr == has_text)
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.has_default_role && !isValidClusterNodeRole(info.default_role))
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.has_max_latency_ms && info.max_latency_ms == 0)
    {
        return Status::INVALID_ARGUMENT;
    }

    ErrorContext local_ctx;
    Status status = UTF8Utils::validateStorageCapacity(
        info.class_name, sizeof(WorkloadClassRecord{}.class_name),
        sizeof(WorkloadClassRecord{}.class_name), &local_ctx);
    if (status != Status::OK)
    {
        return status;
    }

    auto duplicate_predicate = [&info](const WorkloadClassRecord& row) {
        return row.is_valid == 1 &&
               row.class_id != info.class_id &&
               fixedNameFromBuffer(row.class_name, sizeof(row.class_name)) == info.class_name;
    };
    auto duplicate = findRecordInHeapPage<WorkloadClassRecord>(
        workload_class_table_page_, duplicate_predicate, ctx);
    if (duplicate.status == Status::OK)
    {
        return Status::CONSTRAINT_VIOLATION;
    }
    if (duplicate.status != Status::NOT_FOUND)
    {
        return duplicate.status;
    }

    const uint64_t now = catalogNowTicks();
    WorkloadClassRecord rec{};
    rec.class_id = info.class_id;
    std::strncpy(rec.class_name,
                 UTF8Utils::truncateToBytes(info.class_name, sizeof(rec.class_name)).c_str(),
                 sizeof(rec.class_name) - 1);
    rec.match_kind = static_cast<uint8_t>(info.match_kind);
    rec.has_default_role = info.has_default_role ? 1 : 0;
    rec.default_role = static_cast<uint8_t>(info.default_role);
    rec.priority = info.priority;
    rec.has_max_latency_ms = info.has_max_latency_ms ? 1 : 0;
    rec.max_latency_ms = info.has_max_latency_ms ? info.max_latency_ms : 0;
    rec.allow_cross_shard = info.allow_cross_shard ? 1 : 0;
    rec.is_enabled = info.is_enabled ? 1 : 0;
    rec.is_valid = info.is_valid ? 1 : 0;
    rec.match_expr_sblr_id = has_expr ? info.match_expr_sblr_id : ID{};
    rec.created_time = (info.created_time == 0) ? now : info.created_time;
    rec.last_modified_time = (info.last_modified_time == 0) ? now : info.last_modified_time;

    if (!info.description.empty())
    {
        uint64_t xmin = 0;
        status = storeStringInToast(info.description, xmin, rec.description_oid, ctx);
        if (status != Status::OK)
        {
            return status;
        }
    }
    if (has_text)
    {
        uint64_t xmin = 0;
        status = storeStringInToast(info.match_text, xmin, rec.match_text_oid, ctx);
        if (status != Status::OK)
        {
            return status;
        }
    }

    auto existing_predicate = [&info](const WorkloadClassRecord& row) {
        return row.class_id == info.class_id && row.is_valid == 1;
    };
    auto existing = findRecordInHeapPage<WorkloadClassRecord>(
        workload_class_table_page_, existing_predicate, ctx);
    if (existing.status == Status::OK)
    {
        rec.created_time = existing.record.created_time;
    }
    else if (existing.status != Status::NOT_FOUND)
    {
        return existing.status;
    }

    auto matcher = [&info](const WorkloadClassRecord& row) {
        return row.class_id == info.class_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(workload_class_table_page_, matcher, rec, ctx);
}

auto CatalogManager::getWorkloadClassCatalogEntry(const ID& class_id,
                                                  WorkloadClassCatalogInfo& info_out,
                                                  ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    auto predicate = [&class_id](const WorkloadClassRecord& rec) {
        return rec.class_id == class_id && rec.is_valid == 1;
    };
    auto result = findRecordInHeapPage<WorkloadClassRecord>(workload_class_table_page_, predicate, ctx);
    if (result.status != Status::OK)
    {
        return Status::NOT_FOUND;
    }
    if (!isValidWorkloadMatchKind(static_cast<WorkloadMatchKind>(result.record.match_kind)))
    {
        return Status::PAGE_CORRUPT;
    }
    if (result.record.has_default_role != 0 &&
        !isValidClusterNodeRole(static_cast<ClusterNodeRole>(result.record.default_role)))
    {
        return Status::PAGE_CORRUPT;
    }

    info_out = WorkloadClassCatalogInfo{};
    info_out.class_id = result.record.class_id;
    info_out.class_name = fixedNameFromBuffer(result.record.class_name, sizeof(result.record.class_name));
    info_out.match_kind = static_cast<WorkloadMatchKind>(result.record.match_kind);
    info_out.has_default_role = result.record.has_default_role != 0;
    info_out.default_role = static_cast<ClusterNodeRole>(result.record.default_role);
    info_out.priority = result.record.priority;
    info_out.has_max_latency_ms = result.record.has_max_latency_ms != 0;
    info_out.max_latency_ms = result.record.max_latency_ms;
    info_out.allow_cross_shard = result.record.allow_cross_shard != 0;
    info_out.is_enabled = result.record.is_enabled != 0;
    info_out.created_time = result.record.created_time;
    info_out.last_modified_time = result.record.last_modified_time;
    info_out.match_expr_sblr_id = result.record.match_expr_sblr_id;
    info_out.is_valid = result.record.is_valid == 1;

    uint64_t xmin = 0;
    if (!isZeroUuidLocal(result.record.description_oid))
    {
        Status status = loadStringFromToast(result.record.description_oid, xmin, info_out.description, ctx);
        if (status != Status::OK)
        {
            return status;
        }
    }
    if (!isZeroUuidLocal(result.record.match_text_oid))
    {
        Status status = loadStringFromToast(result.record.match_text_oid, xmin, info_out.match_text, ctx);
        if (status != Status::OK)
        {
            return status;
        }
    }
    return Status::OK;
}

auto CatalogManager::listWorkloadClassCatalogEntries(std::vector<WorkloadClassCatalogInfo>& rows_out,
                                                     ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    rows_out.clear();
    auto filter = [](const WorkloadClassRecord& rec) { return rec.is_valid == 1; };
    auto converter = [this, ctx](const WorkloadClassRecord& rec, WorkloadClassCatalogInfo& info) {
        info = WorkloadClassCatalogInfo{};
        info.class_id = rec.class_id;
        info.class_name = fixedNameFromBuffer(rec.class_name, sizeof(rec.class_name));
        info.match_kind = static_cast<WorkloadMatchKind>(rec.match_kind);
        info.has_default_role = rec.has_default_role != 0;
        info.default_role = static_cast<ClusterNodeRole>(rec.default_role);
        info.priority = rec.priority;
        info.has_max_latency_ms = rec.has_max_latency_ms != 0;
        info.max_latency_ms = rec.max_latency_ms;
        info.allow_cross_shard = rec.allow_cross_shard != 0;
        info.is_enabled = rec.is_enabled != 0;
        info.match_expr_sblr_id = rec.match_expr_sblr_id;
        info.created_time = rec.created_time;
        info.last_modified_time = rec.last_modified_time;
        info.is_valid = rec.is_valid == 1;
        uint64_t xmin = 0;
        if (!isZeroUuidLocal(rec.description_oid))
        {
            std::string text;
            if (loadStringFromToast(rec.description_oid, xmin, text, ctx) == Status::OK)
            {
                info.description = std::move(text);
            }
        }
        if (!isZeroUuidLocal(rec.match_text_oid))
        {
            std::string text;
            if (loadStringFromToast(rec.match_text_oid, xmin, text, ctx) == Status::OK)
            {
                info.match_text = std::move(text);
            }
        }
    };
    return readRecordsToVector<WorkloadClassRecord, WorkloadClassCatalogInfo>(
        workload_class_table_page_, rows_out, filter, converter, ctx);
}

