auto CatalogManager::upsertWorkloadRouteCatalogEntry(const WorkloadRouteCatalogInfo& info,
                                                     ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.route_id) || isZeroUuidLocal(info.class_id) || info.route_name.empty() ||
        !isValidRouteTargetKind(info.target_kind) || !isValidConnectionTransport(info.transport))
    {
        return Status::INVALID_ARGUMENT;
    }
    const bool has_target_uuid = !isZeroUuidLocal(info.target_uuid);
    const bool has_target_label = !info.target_label.empty();
    if (!has_target_uuid && !has_target_label)
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.has_role && !isValidClusterNodeRole(info.role))
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.has_service_type && !isValidClusterServiceType(info.service_type))
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.route_weight == 0)
    {
        return Status::INVALID_ARGUMENT;
    }

    auto class_predicate = [&info](const WorkloadClassRecord& rec) {
        return rec.class_id == info.class_id && rec.is_valid == 1;
    };
    if (findRecordInHeapPage<WorkloadClassRecord>(workload_class_table_page_, class_predicate, ctx).status != Status::OK)
    {
        return Status::NOT_FOUND;
    }
    if (!isZeroUuidLocal(info.fallback_route_id) && info.fallback_route_id != info.route_id)
    {
        auto fallback_predicate = [&info](const WorkloadRouteRecord& rec) {
            return rec.route_id == info.fallback_route_id && rec.is_valid == 1;
        };
        if (findRecordInHeapPage<WorkloadRouteRecord>(workload_route_table_page_, fallback_predicate, ctx).status != Status::OK)
        {
            return Status::NOT_FOUND;
        }
    }

    ErrorContext local_ctx;
    Status status = UTF8Utils::validateStorageCapacity(
        info.route_name, sizeof(WorkloadRouteRecord{}.route_name),
        sizeof(WorkloadRouteRecord{}.route_name), &local_ctx);
    if (status != Status::OK)
    {
        return status;
    }
    if (has_target_label)
    {
        status = UTF8Utils::validateStorageCapacity(
            info.target_label, sizeof(WorkloadRouteRecord{}.target_label),
            sizeof(WorkloadRouteRecord{}.target_label), &local_ctx);
        if (status != Status::OK)
        {
            return status;
        }
    }

    auto duplicate_predicate = [&info](const WorkloadRouteRecord& row) {
        return row.is_valid == 1 &&
               row.route_id != info.route_id &&
               row.class_id == info.class_id &&
               fixedNameFromBuffer(row.route_name, sizeof(row.route_name)) == info.route_name;
    };
    auto duplicate = findRecordInHeapPage<WorkloadRouteRecord>(workload_route_table_page_, duplicate_predicate, ctx);
    if (duplicate.status == Status::OK)
    {
        return Status::CONSTRAINT_VIOLATION;
    }
    if (duplicate.status != Status::NOT_FOUND)
    {
        return duplicate.status;
    }

    const uint64_t now = catalogNowTicks();
    WorkloadRouteRecord rec{};
    rec.route_id = info.route_id;
    rec.class_id = info.class_id;
    std::strncpy(rec.route_name,
                 UTF8Utils::truncateToBytes(info.route_name, sizeof(rec.route_name)).c_str(),
                 sizeof(rec.route_name) - 1);
    rec.target_kind = static_cast<uint8_t>(info.target_kind);
    rec.has_target_uuid = has_target_uuid ? 1 : 0;
    rec.has_target_label = has_target_label ? 1 : 0;
    rec.has_role = info.has_role ? 1 : 0;
    rec.has_service_type = info.has_service_type ? 1 : 0;
    rec.role = static_cast<uint8_t>(info.role);
    rec.service_type = static_cast<uint8_t>(info.service_type);
    rec.transport = static_cast<uint8_t>(info.transport);
    rec.route_weight = info.route_weight;
    rec.target_uuid = has_target_uuid ? info.target_uuid : ID{};
    if (has_target_label)
    {
        std::strncpy(rec.target_label,
                     UTF8Utils::truncateToBytes(info.target_label, sizeof(rec.target_label)).c_str(),
                     sizeof(rec.target_label) - 1);
    }
    rec.selector_expr_sblr_id = info.selector_expr_sblr_id;
    rec.fallback_route_id = info.fallback_route_id;
    rec.is_enabled = info.is_enabled ? 1 : 0;
    rec.is_valid = info.is_valid ? 1 : 0;
    rec.created_time = (info.created_time == 0) ? now : info.created_time;
    rec.last_modified_time = (info.last_modified_time == 0) ? now : info.last_modified_time;

    auto existing_predicate = [&info](const WorkloadRouteRecord& row) {
        return row.route_id == info.route_id && row.is_valid == 1;
    };
    auto existing = findRecordInHeapPage<WorkloadRouteRecord>(workload_route_table_page_, existing_predicate, ctx);
    if (existing.status == Status::OK)
    {
        rec.created_time = existing.record.created_time;
    }
    else if (existing.status != Status::NOT_FOUND)
    {
        return existing.status;
    }

    auto matcher = [&info](const WorkloadRouteRecord& row) {
        return row.route_id == info.route_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(workload_route_table_page_, matcher, rec, ctx);
}

