auto CatalogManager::upsertSloProfileCatalogEntry(const SloProfileCatalogInfo& info,
                                                  ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.slo_profile_id) || info.profile_name.empty() ||
        !isValidClusterNodeRole(info.role))
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.latency_p95_target_ms == 0 ||
        info.latency_p99_target_ms == 0 ||
        info.latency_p95_target_ms > info.latency_p99_target_ms ||
        info.window_minutes == 0 ||
        info.short_burn_window_minutes == 0 ||
        info.long_burn_window_minutes == 0 ||
        info.short_burn_window_minutes > info.long_burn_window_minutes)
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.moderate_burn_threshold > info.high_burn_threshold ||
        info.high_burn_threshold > info.critical_burn_threshold)
    {
        return Status::INVALID_ARGUMENT;
    }

    ErrorContext local_ctx;
    Status status = UTF8Utils::validateStorageCapacity(
        info.profile_name, sizeof(SloProfileRecord{}.profile_name),
        sizeof(SloProfileRecord{}.profile_name), &local_ctx);
    if (status != Status::OK)
    {
        return status;
    }

    auto duplicate_predicate = [&info](const SloProfileRecord& row) {
        return row.is_valid == 1 &&
               row.slo_profile_id != info.slo_profile_id &&
               fixedNameFromBuffer(row.profile_name, sizeof(row.profile_name)) == info.profile_name;
    };
    auto duplicate = findRecordInHeapPage<SloProfileRecord>(slo_profile_table_page_, duplicate_predicate, ctx);
    if (duplicate.status == Status::OK)
    {
        return Status::CONSTRAINT_VIOLATION;
    }
    if (duplicate.status != Status::NOT_FOUND)
    {
        return duplicate.status;
    }

    SloProfileRecord rec{};
    rec.slo_profile_id = info.slo_profile_id;
    std::strncpy(rec.profile_name,
                 UTF8Utils::truncateToBytes(info.profile_name, sizeof(rec.profile_name)).c_str(),
                 sizeof(rec.profile_name) - 1);
    rec.role = static_cast<uint8_t>(info.role);
    rec.availability_target_pct = info.availability_target_pct;
    rec.latency_p95_target_ms = info.latency_p95_target_ms;
    rec.latency_p99_target_ms = info.latency_p99_target_ms;
    rec.error_rate_target_pct = info.error_rate_target_pct;
    rec.window_minutes = info.window_minutes;
    rec.short_burn_window_minutes = info.short_burn_window_minutes;
    rec.long_burn_window_minutes = info.long_burn_window_minutes;
    rec.critical_burn_threshold = info.critical_burn_threshold;
    rec.high_burn_threshold = info.high_burn_threshold;
    rec.moderate_burn_threshold = info.moderate_burn_threshold;
    rec.version_u64 = info.version_u64;
    rec.is_active = info.is_active ? 1 : 0;
    rec.is_valid = info.is_valid ? 1 : 0;

    auto matcher = [&info](const SloProfileRecord& row) {
        return row.slo_profile_id == info.slo_profile_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(slo_profile_table_page_, matcher, rec, ctx);
}

