auto CatalogManager::upsertSloBurnEventCatalogEntry(const SloBurnEventCatalogInfo& info,
                                                    ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.slo_burn_event_id) ||
        isZeroUuidLocal(info.node_id) ||
        isZeroUuidLocal(info.slo_profile_id) ||
        !isValidClusterNodeRole(info.role) ||
        !isValidSloBurnSeverity(info.burn_severity) ||
        !isValidSloActionPlan(info.action_plan) ||
        info.event_time == 0)
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.has_resolved_time && info.resolved_time < info.event_time)
    {
        return Status::INVALID_ARGUMENT;
    }

    auto node_predicate = [&info](const NodeRecord& rec) {
        return rec.node_id == info.node_id && rec.is_valid == 1;
    };
    if (findRecordInHeapPage<NodeRecord>(node_table_page_, node_predicate, ctx).status != Status::OK)
    {
        return Status::NOT_FOUND;
    }
    auto profile_predicate = [&info](const SloProfileRecord& rec) {
        return rec.slo_profile_id == info.slo_profile_id && rec.is_valid == 1;
    };
    if (findRecordInHeapPage<SloProfileRecord>(slo_profile_table_page_, profile_predicate, ctx).status != Status::OK)
    {
        return Status::NOT_FOUND;
    }

    SloBurnEventRecord rec{};
    rec.slo_burn_event_id = info.slo_burn_event_id;
    rec.node_id = info.node_id;
    rec.slo_profile_id = info.slo_profile_id;
    rec.role = static_cast<uint8_t>(info.role);
    rec.short_burn_rate = info.short_burn_rate;
    rec.long_burn_rate = info.long_burn_rate;
    rec.burn_severity = static_cast<uint8_t>(info.burn_severity);
    rec.action_plan = static_cast<uint8_t>(info.action_plan);
    rec.event_time = info.event_time;
    rec.has_resolved_time = info.has_resolved_time ? 1 : 0;
    rec.resolved_time = info.has_resolved_time ? info.resolved_time : 0;
    rec.is_valid = info.is_valid ? 1 : 0;

    auto matcher = [&info](const SloBurnEventRecord& row) {
        return row.slo_burn_event_id == info.slo_burn_event_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(slo_burn_event_table_page_, matcher, rec, ctx);
}

