auto CatalogManager::upsertAutoscalePolicyCatalogEntry(const AutoscalePolicyCatalogInfo& info,
                                                       ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.autoscale_policy_id) || !isValidClusterNodeRole(info.role))
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.min_nodes == 0 || info.max_nodes == 0 || info.min_nodes > info.max_nodes ||
        info.scale_out_step == 0 || info.scale_in_step == 0)
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.cpu_scale_out_pct > 100 || info.queue_scale_out_pct > 100)
    {
        return Status::INVALID_ARGUMENT;
    }

    auto duplicate_predicate = [&info](const AutoscalePolicyRecord& row) {
        return row.is_valid == 1 &&
               row.autoscale_policy_id != info.autoscale_policy_id &&
               row.role == static_cast<uint8_t>(info.role);
    };
    auto duplicate = findRecordInHeapPage<AutoscalePolicyRecord>(
        autoscale_policy_table_page_, duplicate_predicate, ctx);
    if (duplicate.status == Status::OK)
    {
        return Status::CONSTRAINT_VIOLATION;
    }
    if (duplicate.status != Status::NOT_FOUND)
    {
        return duplicate.status;
    }

    AutoscalePolicyRecord rec{};
    rec.autoscale_policy_id = info.autoscale_policy_id;
    rec.role = static_cast<uint8_t>(info.role);
    rec.min_nodes = info.min_nodes;
    rec.max_nodes = info.max_nodes;
    rec.scale_out_step = info.scale_out_step;
    rec.scale_in_step = info.scale_in_step;
    rec.scale_out_cooldown_ms = info.scale_out_cooldown_ms;
    rec.scale_in_cooldown_ms = info.scale_in_cooldown_ms;
    rec.cpu_scale_out_pct = info.cpu_scale_out_pct;
    rec.queue_scale_out_pct = info.queue_scale_out_pct;
    rec.slo_burn_scale_out_threshold = info.slo_burn_scale_out_threshold;
    rec.slo_recovery_scale_in_threshold = info.slo_recovery_scale_in_threshold;
    rec.version_u64 = info.version_u64;
    rec.is_valid = info.is_valid ? 1 : 0;

    auto matcher = [&info](const AutoscalePolicyRecord& row) {
        return row.autoscale_policy_id == info.autoscale_policy_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(autoscale_policy_table_page_, matcher, rec, ctx);
}

