auto CatalogManager::upsertAutoscaleActionCatalogEntry(const AutoscaleActionCatalogInfo& info,
                                                       ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.autoscale_action_id) || !isValidClusterNodeRole(info.role) ||
        !isValidAutoscaleActionKind(info.action_kind) || !isValidAutoscaleActionState(info.action_state) ||
        info.action_time == 0)
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.has_completed_time && info.completed_time < info.action_time)
    {
        return Status::INVALID_ARGUMENT;
    }
    if (!info.failure_code.empty())
    {
        ErrorContext local_ctx;
        Status status = UTF8Utils::validateStorageCapacity(
            info.failure_code, sizeof(AutoscaleActionRecord{}.failure_code),
            sizeof(AutoscaleActionRecord{}.failure_code), &local_ctx);
        if (status != Status::OK)
        {
            return status;
        }
    }

    AutoscaleActionRecord rec{};
    rec.autoscale_action_id = info.autoscale_action_id;
    rec.role = static_cast<uint8_t>(info.role);
    rec.action_kind = static_cast<uint8_t>(info.action_kind);
    rec.requested_count_delta = info.requested_count_delta;
    rec.applied_count_delta = info.applied_count_delta;
    rec.trigger_burn_rate = info.trigger_burn_rate;
    rec.policy_version_u64 = info.policy_version_u64;
    rec.action_time = info.action_time;
    rec.has_completed_time = info.has_completed_time ? 1 : 0;
    rec.completed_time = info.has_completed_time ? info.completed_time : 0;
    rec.action_state = static_cast<uint8_t>(info.action_state);
    rec.is_valid = info.is_valid ? 1 : 0;
    if (!info.failure_code.empty())
    {
        std::strncpy(rec.failure_code,
                     UTF8Utils::truncateToBytes(info.failure_code, sizeof(rec.failure_code)).c_str(),
                     sizeof(rec.failure_code) - 1);
    }
    if (!info.trigger_reason.empty())
    {
        uint64_t xmin = 0;
        Status status = storeStringInToast(info.trigger_reason, xmin, rec.trigger_reason_oid, ctx);
        if (status != Status::OK)
        {
            return status;
        }
    }

    auto matcher = [&info](const AutoscaleActionRecord& row) {
        return row.autoscale_action_id == info.autoscale_action_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(autoscale_action_table_page_, matcher, rec, ctx);
}

