auto CatalogManager::upsertClusterPolicyCatalogEntry(const ClusterPolicyCatalogInfo& info,
                                                     ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.policy_id) || isZeroUuidLocal(info.cluster_id) ||
        info.policy_name.empty() || !isValidClusterPolicyKind(info.policy_kind))
    {
        return Status::INVALID_ARGUMENT;
    }

    auto cluster_predicate = [&info](const ClusterRecord& rec) {
        return rec.cluster_id == info.cluster_id && rec.is_valid == 1;
    };
    if (findRecordInHeapPage<ClusterRecord>(cluster_table_page_, cluster_predicate, ctx).status != Status::OK)
    {
        return Status::NOT_FOUND;
    }

    auto duplicate_predicate = [&info](const ClusterPolicyRecord& row) {
        return row.is_valid == 1 &&
               row.policy_id != info.policy_id &&
               row.cluster_id == info.cluster_id &&
               fixedNameFromBuffer(row.policy_name, sizeof(row.policy_name)) == info.policy_name;
    };
    auto duplicate = findRecordInHeapPage<ClusterPolicyRecord>(cluster_policy_table_page_, duplicate_predicate, ctx);
    if (duplicate.status == Status::OK)
    {
        return Status::CONSTRAINT_VIOLATION;
    }
    if (duplicate.status != Status::NOT_FOUND)
    {
        return duplicate.status;
    }

    ClusterPolicyRecord rec{};
    rec.policy_id = info.policy_id;
    rec.cluster_id = info.cluster_id;
    std::strncpy(rec.policy_name,
                 UTF8Utils::truncateToBytes(info.policy_name, sizeof(rec.policy_name)).c_str(),
                 sizeof(rec.policy_name) - 1);
    rec.policy_kind = static_cast<uint8_t>(info.policy_kind);
    rec.has_policy_json_oid = (info.has_policy_json_uuid && !isZeroUuidLocal(info.policy_json_uuid)) ? 1 : 0;
    rec.policy_json_oid = rec.has_policy_json_oid ? info.policy_json_uuid : ID{};
    rec.is_active = info.is_active ? 1 : 0;
    rec.is_valid = info.is_valid ? 1 : 0;
    rec.created_time = info.created_time;
    rec.last_modified_time = info.last_modified_time;
    const uint64_t now = catalogNowTicks();
    if (rec.created_time == 0)
    {
        rec.created_time = now;
    }
    rec.last_modified_time = now;

    auto existing_predicate = [&info](const ClusterPolicyRecord& row) {
        return row.policy_id == info.policy_id && row.is_valid == 1;
    };
    auto existing = findRecordInHeapPage<ClusterPolicyRecord>(cluster_policy_table_page_, existing_predicate, ctx);
    if (existing.status == Status::OK)
    {
        rec.created_time = existing.record.created_time;
    }
    else if (existing.status != Status::NOT_FOUND)
    {
        return existing.status;
    }

    auto matcher = [&info](const ClusterPolicyRecord& row) {
        return row.policy_id == info.policy_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(cluster_policy_table_page_, matcher, rec, ctx);
}

