auto CatalogManager::upsertAlertRuleCatalogEntry(const AlertRuleCatalogInfo& info,
                                                 ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.rule_id) || info.rule_name.empty() ||
        !isValidAlertRuleKind(info.rule_kind) ||
        !isValidAlertSeverity(info.severity) ||
        info.throttle_interval_ms == 0)
    {
        return Status::INVALID_ARGUMENT;
    }

    const bool has_sblr = info.has_condition_sblr_uuid && !isZeroUuidLocal(info.condition_sblr_uuid);
    const bool has_text = info.has_condition_text && !info.condition_text.empty();
    if (has_sblr == has_text)
    {
        return Status::INVALID_ARGUMENT;
    }

    auto duplicate_predicate = [&info](const AlertRuleRecord& row) {
        return row.is_valid == 1 &&
               row.rule_id != info.rule_id &&
               fixedNameFromBuffer(row.rule_name, sizeof(row.rule_name)) == info.rule_name;
    };
    auto duplicate = findRecordInHeapPage<AlertRuleRecord>(alert_rule_table_page_, duplicate_predicate, ctx);
    if (duplicate.status == Status::OK)
    {
        return Status::CONSTRAINT_VIOLATION;
    }
    if (duplicate.status != Status::NOT_FOUND)
    {
        return duplicate.status;
    }

    AlertRuleRecord rec{};
    rec.rule_id = info.rule_id;
    std::strncpy(rec.rule_name,
                 UTF8Utils::truncateToBytes(info.rule_name, sizeof(rec.rule_name)).c_str(),
                 sizeof(rec.rule_name) - 1);
    rec.rule_kind = static_cast<uint8_t>(info.rule_kind);
    rec.severity = static_cast<uint8_t>(info.severity);
    rec.has_condition_sblr = has_sblr ? 1 : 0;
    rec.condition_sblr_uuid = has_sblr ? info.condition_sblr_uuid : ID{};
    rec.has_condition_text = has_text ? 1 : 0;
    if (has_text)
    {
        uint64_t xmin = 0;
        Status status = storeStringInToast(info.condition_text, xmin, rec.condition_text_oid, ctx);
        if (status != Status::OK)
        {
            return status;
        }
    }
    rec.throttle_interval_ms = info.throttle_interval_ms;
    rec.is_enabled = info.is_enabled ? 1 : 0;
    rec.is_valid = info.is_valid ? 1 : 0;
    rec.created_time = info.created_time;
    rec.last_modified_time = info.last_modified_time;
    const uint64_t now = catalogNowTicks();
    if (rec.created_time == 0)
    {
        rec.created_time = now;
    }
    rec.last_modified_time = now;

    auto existing_predicate = [&info](const AlertRuleRecord& row) {
        return row.rule_id == info.rule_id && row.is_valid == 1;
    };
    auto existing = findRecordInHeapPage<AlertRuleRecord>(alert_rule_table_page_, existing_predicate, ctx);
    if (existing.status == Status::OK)
    {
        rec.created_time = existing.record.created_time;
    }
    else if (existing.status != Status::NOT_FOUND)
    {
        return existing.status;
    }

    auto matcher = [&info](const AlertRuleRecord& row) {
        return row.rule_id == info.rule_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(alert_rule_table_page_, matcher, rec, ctx);
}

