auto CatalogManager::upsertAlertRouteCatalogEntry(const AlertRouteCatalogInfo& info,
                                                  ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.route_id) || isZeroUuidLocal(info.rule_id) || isZeroUuidLocal(info.target_id) ||
        !isValidAlertRouteKind(info.route_kind) ||
        !isValidAlertSeverity(info.severity_min) ||
        !isValidAlertSeverity(info.severity_max) ||
        static_cast<uint8_t>(info.severity_min) > static_cast<uint8_t>(info.severity_max))
    {
        return Status::INVALID_ARGUMENT;
    }

    auto rule_predicate = [&info](const AlertRuleRecord& rec) {
        return rec.rule_id == info.rule_id && rec.is_valid == 1;
    };
    if (findRecordInHeapPage<AlertRuleRecord>(alert_rule_table_page_, rule_predicate, ctx).status != Status::OK)
    {
        return Status::NOT_FOUND;
    }
    auto target_predicate = [&info](const AlertTargetRecord& rec) {
        return rec.target_id == info.target_id && rec.is_valid == 1;
    };
    if (findRecordInHeapPage<AlertTargetRecord>(alert_target_table_page_, target_predicate, ctx).status != Status::OK)
    {
        return Status::NOT_FOUND;
    }

    auto duplicate_predicate = [&info](const AlertRouteRecord& row) {
        return row.is_valid == 1 &&
               row.route_id != info.route_id &&
               row.rule_id == info.rule_id &&
               row.target_id == info.target_id;
    };
    auto duplicate = findRecordInHeapPage<AlertRouteRecord>(alert_route_table_page_, duplicate_predicate, ctx);
    if (duplicate.status == Status::OK)
    {
        return Status::CONSTRAINT_VIOLATION;
    }
    if (duplicate.status != Status::NOT_FOUND)
    {
        return duplicate.status;
    }

    AlertRouteRecord rec{};
    rec.route_id = info.route_id;
    rec.rule_id = info.rule_id;
    rec.target_id = info.target_id;
    rec.route_kind = static_cast<uint8_t>(info.route_kind);
    rec.severity_min = static_cast<uint8_t>(info.severity_min);
    rec.severity_max = static_cast<uint8_t>(info.severity_max);
    rec.is_enabled = info.is_enabled ? 1 : 0;
    rec.is_valid = info.is_valid ? 1 : 0;
    rec.created_time = info.created_time;
    rec.last_modified_time = info.last_modified_time;
    const uint64_t now = catalogNowTicks();
    if (rec.created_time == 0)
    {
        rec.created_time = now;
    }
    rec.last_modified_time = now;

    auto existing_predicate = [&info](const AlertRouteRecord& row) {
        return row.route_id == info.route_id && row.is_valid == 1;
    };
    auto existing = findRecordInHeapPage<AlertRouteRecord>(alert_route_table_page_, existing_predicate, ctx);
    if (existing.status == Status::OK)
    {
        rec.created_time = existing.record.created_time;
    }
    else if (existing.status != Status::NOT_FOUND)
    {
        return existing.status;
    }

    auto matcher = [&info](const AlertRouteRecord& row) {
        return row.route_id == info.route_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(alert_route_table_page_, matcher, rec, ctx);
}

