auto CatalogManager::upsertAlertEventCatalogEntry(const AlertEventCatalogInfo& info,
                                                  ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.event_id) || isZeroUuidLocal(info.rule_id) ||
        !isValidAlertSeverity(info.severity) ||
        !isValidAlertEventState(info.event_state) ||
        info.event_time == 0)
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.has_resolved_time && info.resolved_time < info.event_time)
    {
        return Status::INVALID_ARGUMENT;
    }

    auto rule_predicate = [&info](const AlertRuleRecord& rec) {
        return rec.rule_id == info.rule_id && rec.is_valid == 1;
    };
    if (findRecordInHeapPage<AlertRuleRecord>(alert_rule_table_page_, rule_predicate, ctx).status != Status::OK)
    {
        return Status::NOT_FOUND;
    }

    AlertEventRecord rec{};
    rec.event_id = info.event_id;
    rec.rule_id = info.rule_id;
    rec.severity = static_cast<uint8_t>(info.severity);
    rec.event_state = static_cast<uint8_t>(info.event_state);
    rec.event_time = info.event_time;
    rec.has_resolved_time = info.has_resolved_time ? 1 : 0;
    rec.resolved_time = info.has_resolved_time ? info.resolved_time : 0;
    rec.has_event_payload_oid = (info.has_event_payload_uuid && !isZeroUuidLocal(info.event_payload_uuid)) ? 1 : 0;
    rec.event_payload_oid = rec.has_event_payload_oid ? info.event_payload_uuid : ID{};
    rec.is_valid = info.is_valid ? 1 : 0;

    auto matcher = [&info](const AlertEventRecord& row) {
        return row.event_id == info.event_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(alert_event_table_page_, matcher, rec, ctx);
}

