auto CatalogManager::upsertAlertAckCatalogEntry(const AlertAckCatalogInfo& info,
                                                ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.ack_id) || isZeroUuidLocal(info.event_id) || isZeroUuidLocal(info.user_id) ||
        info.ack_time == 0)
    {
        return Status::INVALID_ARGUMENT;
    }

    auto event_predicate = [&info](const AlertEventRecord& rec) {
        return rec.event_id == info.event_id && rec.is_valid == 1;
    };
    if (findRecordInHeapPage<AlertEventRecord>(alert_event_table_page_, event_predicate, ctx).status != Status::OK)
    {
        return Status::NOT_FOUND;
    }
    auto user_predicate = [&info](const UserRecord& rec) {
        return rec.user_id == info.user_id && rec.is_valid == 1;
    };
    if (findRecordInHeapPage<UserRecord>(users_table_page_, user_predicate, ctx).status != Status::OK)
    {
        return Status::NOT_FOUND;
    }

    AlertAckRecord rec{};
    rec.ack_id = info.ack_id;
    rec.event_id = info.event_id;
    rec.user_id = info.user_id;
    rec.ack_time = info.ack_time;
    rec.has_comment = (info.has_comment && !info.comment.empty()) ? 1 : 0;
    rec.is_valid = info.is_valid ? 1 : 0;
    if (rec.has_comment)
    {
        uint64_t xmin = 0;
        Status status = storeStringInToast(info.comment, xmin, rec.comment_oid, ctx);
        if (status != Status::OK)
        {
            return status;
        }
    }

    auto matcher = [&info](const AlertAckRecord& row) {
        return row.ack_id == info.ack_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(alert_ack_table_page_, matcher, rec, ctx);
}

