auto CatalogManager::upsertNetworkPartitionMemberCatalogEntry(const NetworkPartitionMemberCatalogInfo& info,
                                                              ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.member_id) || isZeroUuidLocal(info.partition_id) || isZeroUuidLocal(info.node_id))
    {
        return Status::INVALID_ARGUMENT;
    }

    auto event_predicate = [&info](const NetworkPartitionEventRecord& rec) {
        return rec.partition_id == info.partition_id && rec.is_valid == 1;
    };
    if (findRecordInHeapPage<NetworkPartitionEventRecord>(network_partition_event_table_page_, event_predicate, ctx).status != Status::OK)
    {
        return Status::NOT_FOUND;
    }
    auto node_predicate = [&info](const NodeRecord& rec) {
        return rec.node_id == info.node_id && rec.is_valid == 1;
    };
    if (findRecordInHeapPage<NodeRecord>(node_table_page_, node_predicate, ctx).status != Status::OK)
    {
        return Status::NOT_FOUND;
    }

    auto duplicate_predicate = [&info](const NetworkPartitionMemberRecord& row) {
        return row.is_valid == 1 &&
               row.member_id != info.member_id &&
               row.partition_id == info.partition_id &&
               row.node_id == info.node_id;
    };
    auto duplicate = findRecordInHeapPage<NetworkPartitionMemberRecord>(
        network_partition_member_table_page_, duplicate_predicate, ctx);
    if (duplicate.status == Status::OK)
    {
        return Status::CONSTRAINT_VIOLATION;
    }
    if (duplicate.status != Status::NOT_FOUND)
    {
        return duplicate.status;
    }

    NetworkPartitionMemberRecord rec{};
    rec.member_id = info.member_id;
    rec.partition_id = info.partition_id;
    rec.node_id = info.node_id;
    rec.side_id = info.side_id;
    rec.reachable = info.reachable ? 1 : 0;
    rec.is_valid = info.is_valid ? 1 : 0;

    auto matcher = [&info](const NetworkPartitionMemberRecord& row) {
        return row.member_id == info.member_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(network_partition_member_table_page_, matcher, rec, ctx);
}

