    auto predicate = [&member_id](const NetworkPartitionMemberRecord& rec) {
        return rec.member_id == member_id && rec.is_valid == 1;
    };
    auto result = findRecordInHeapPage<NetworkPartitionMemberRecord>(network_partition_member_table_page_, predicate, ctx);
    if (result.status != Status::OK)
    {
        return Status::NOT_FOUND;
    }
    NetworkPartitionMemberRecord updated = result.record;
