auto CatalogManager::upsertHealingActionParamCatalogEntry(const HealingActionParamCatalogInfo& info,
                                                          ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.param_id) || isZeroUuidLocal(info.action_id) || info.param_key.empty() ||
        !isValidHealingParamType(info.param_type))
    {
        return Status::INVALID_ARGUMENT;
    }

    auto action_predicate = [&info](const HealingActionRecord& rec) {
        return rec.action_id == info.action_id && rec.is_valid == 1;
    };
    if (findRecordInHeapPage<HealingActionRecord>(healing_action_table_page_, action_predicate, ctx).status != Status::OK)
    {
        return Status::NOT_FOUND;
    }

    const uint8_t value_count = static_cast<uint8_t>(info.has_val_u64) +
                                static_cast<uint8_t>(info.has_val_i64) +
                                static_cast<uint8_t>(info.has_val_f64) +
                                static_cast<uint8_t>(info.has_val_bool) +
                                static_cast<uint8_t>(info.has_val_text && !info.val_text.empty()) +
                                static_cast<uint8_t>(info.has_val_uuid && !isZeroUuidLocal(info.val_uuid)) +
                                static_cast<uint8_t>(info.has_val_json && !info.val_json.empty());
    if (value_count != 1)
    {
        return Status::INVALID_ARGUMENT;
    }
    bool type_match = false;
    switch (info.param_type)
    {
        case HealingParamType::BOOL: type_match = info.has_val_bool; break;
        case HealingParamType::INT: type_match = info.has_val_i64; break;
        case HealingParamType::FLOAT: type_match = info.has_val_f64; break;
        case HealingParamType::STRING: type_match = info.has_val_text && !info.val_text.empty(); break;
        case HealingParamType::UUID: type_match = info.has_val_uuid && !isZeroUuidLocal(info.val_uuid); break;
        case HealingParamType::JSON: type_match = info.has_val_json && !info.val_json.empty(); break;
    }
    if (!type_match)
    {
        return Status::INVALID_ARGUMENT;
    }

    auto duplicate_predicate = [&info](const HealingActionParamRecord& row) {
        return row.is_valid == 1 &&
               row.param_id != info.param_id &&
               row.action_id == info.action_id &&
               fixedNameFromBuffer(row.param_key, sizeof(row.param_key)) == info.param_key;
    };
    auto duplicate = findRecordInHeapPage<HealingActionParamRecord>(healing_action_param_table_page_, duplicate_predicate, ctx);
    if (duplicate.status == Status::OK)
    {
        return Status::CONSTRAINT_VIOLATION;
    }
    if (duplicate.status != Status::NOT_FOUND)
    {
        return duplicate.status;
    }

    HealingActionParamRecord rec{};
    rec.param_id = info.param_id;
    rec.action_id = info.action_id;
    std::strncpy(rec.param_key,
                 UTF8Utils::truncateToBytes(info.param_key, sizeof(rec.param_key)).c_str(),
                 sizeof(rec.param_key) - 1);
    rec.param_type = static_cast<uint8_t>(info.param_type);
    rec.has_val_u64 = info.has_val_u64 ? 1 : 0;
    rec.has_val_i64 = info.has_val_i64 ? 1 : 0;
    rec.has_val_f64 = info.has_val_f64 ? 1 : 0;
    rec.has_val_bool = info.has_val_bool ? 1 : 0;
    rec.has_val_text = (info.has_val_text && !info.val_text.empty()) ? 1 : 0;
    rec.has_val_uuid = (info.has_val_uuid && !isZeroUuidLocal(info.val_uuid)) ? 1 : 0;
    rec.has_val_json = (info.has_val_json && !info.val_json.empty()) ? 1 : 0;
    rec.is_valid = info.is_valid ? 1 : 0;
    rec.val_u64 = info.val_u64;
    rec.val_i64 = info.val_i64;
    rec.val_f64 = info.val_f64;
    rec.val_bool = info.val_bool ? 1 : 0;
    rec.val_uuid = rec.has_val_uuid ? info.val_uuid : ID{};
    if (rec.has_val_text)
    {
        uint64_t xmin = 0;
        Status status = storeStringInToast(info.val_text, xmin, rec.val_text_oid, ctx);
        if (status != Status::OK)
        {
            return status;
        }
    }
    if (rec.has_val_json)
    {
        uint64_t xmin = 0;
        Status status = storeStringInToast(info.val_json, xmin, rec.val_json_oid, ctx);
        if (status != Status::OK)
        {
            return status;
        }
    }

    auto matcher = [&info](const HealingActionParamRecord& row) {
        return row.param_id == info.param_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(healing_action_param_table_page_, matcher, rec, ctx);
}

auto CatalogManager::getHealingActionParamCatalogEntry(const ID& param_id,
                                                       HealingActionParamCatalogInfo& info_out,
                                                       ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    auto predicate = [&param_id](const HealingActionParamRecord& rec) {
        return rec.param_id == param_id && rec.is_valid == 1;
    };
    auto result = findRecordInHeapPage<HealingActionParamRecord>(healing_action_param_table_page_, predicate, ctx);
    if (result.status != Status::OK)
    {
        return Status::NOT_FOUND;
    }
    if (!isValidHealingParamType(static_cast<HealingParamType>(result.record.param_type)))
    {
        return Status::PAGE_CORRUPT;
    }
    info_out = HealingActionParamCatalogInfo{};
    info_out.param_id = result.record.param_id;
    info_out.action_id = result.record.action_id;
    info_out.param_key = fixedNameFromBuffer(result.record.param_key, sizeof(result.record.param_key));
    info_out.param_type = static_cast<HealingParamType>(result.record.param_type);
    info_out.has_val_u64 = result.record.has_val_u64 != 0;
    info_out.val_u64 = result.record.val_u64;
    info_out.has_val_i64 = result.record.has_val_i64 != 0;
    info_out.val_i64 = result.record.val_i64;
    info_out.has_val_f64 = result.record.has_val_f64 != 0;
    info_out.val_f64 = result.record.val_f64;
    info_out.has_val_bool = result.record.has_val_bool != 0;
    info_out.val_bool = result.record.val_bool != 0;
    info_out.has_val_text = result.record.has_val_text != 0;
    if (info_out.has_val_text)
    {
        uint64_t xmin = 0;
        Status status = loadStringFromToast(result.record.val_text_oid, xmin, info_out.val_text, ctx);
        if (status != Status::OK)
        {
            return status;
        }
    }
    info_out.has_val_uuid = result.record.has_val_uuid != 0;
    info_out.val_uuid = info_out.has_val_uuid ? result.record.val_uuid : ID{};
    info_out.has_val_json = result.record.has_val_json != 0;
    if (info_out.has_val_json)
    {
        uint64_t xmin = 0;
        Status status = loadStringFromToast(result.record.val_json_oid, xmin, info_out.val_json, ctx);
        if (status != Status::OK)
        {
            return status;
        }
    }
    info_out.is_valid = result.record.is_valid == 1;
    return Status::OK;
}

auto CatalogManager::listHealingActionParamCatalogEntries(
    const ID& action_id,
    std::vector<HealingActionParamCatalogInfo>& rows_out,
    ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    rows_out.clear();
    auto filter = [&action_id](const HealingActionParamRecord& rec) {
        return rec.is_valid == 1 &&
               (isZeroUuidLocal(action_id) || rec.action_id == action_id);
    };
    auto converter = [this, ctx](const HealingActionParamRecord& rec, HealingActionParamCatalogInfo& info) {
        info = HealingActionParamCatalogInfo{};
        info.param_id = rec.param_id;
        info.action_id = rec.action_id;
        info.param_key = fixedNameFromBuffer(rec.param_key, sizeof(rec.param_key));
        info.param_type = static_cast<HealingParamType>(rec.param_type);
        info.has_val_u64 = rec.has_val_u64 != 0;
        info.val_u64 = rec.val_u64;
        info.has_val_i64 = rec.has_val_i64 != 0;
        info.val_i64 = rec.val_i64;
        info.has_val_f64 = rec.has_val_f64 != 0;
        info.val_f64 = rec.val_f64;
        info.has_val_bool = rec.has_val_bool != 0;
        info.val_bool = rec.val_bool != 0;
        info.has_val_text = rec.has_val_text != 0;
        if (info.has_val_text)
        {
            uint64_t xmin = 0;
            std::string text;
            if (loadStringFromToast(rec.val_text_oid, xmin, text, ctx) == Status::OK)
            {
                info.val_text = std::move(text);
            }
        }
        info.has_val_uuid = rec.has_val_uuid != 0;
        info.val_uuid = info.has_val_uuid ? rec.val_uuid : ID{};
        info.has_val_json = rec.has_val_json != 0;
        if (info.has_val_json)
        {
            uint64_t xmin = 0;
            std::string text;
            if (loadStringFromToast(rec.val_json_oid, xmin, text, ctx) == Status::OK)
            {
                info.val_json = std::move(text);
            }
        }
        info.is_valid = rec.is_valid == 1;
    };
    return readRecordsToVector<HealingActionParamRecord, HealingActionParamCatalogInfo>(
        healing_action_param_table_page_, rows_out, filter, converter, ctx);
}

