auto CatalogManager::upsertHealingRunCatalogEntry(const HealingRunCatalogInfo& info,
                                                  ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.run_id) || isZeroUuidLocal(info.policy_id) ||
        !isValidHealingRunState(info.state) || info.started_time == 0)
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.has_completed_time && info.completed_time < info.started_time)
    {
        return Status::INVALID_ARGUMENT;
    }

    auto policy_predicate = [&info](const HealingPolicyRecord& rec) {
        return rec.policy_id == info.policy_id && rec.is_valid == 1;
    };
    if (findRecordInHeapPage<HealingPolicyRecord>(healing_policy_table_page_, policy_predicate, ctx).status != Status::OK)
    {
        return Status::NOT_FOUND;
    }
    if (info.has_trigger_event_id)
    {
        auto trigger_predicate = [&info](const AlertEventRecord& rec) {
            return rec.event_id == info.trigger_event_id && rec.is_valid == 1;
        };
        if (findRecordInHeapPage<AlertEventRecord>(alert_event_table_page_, trigger_predicate, ctx).status != Status::OK)
        {
            return Status::NOT_FOUND;
        }
    }

    HealingRunRecord rec{};
    rec.run_id = info.run_id;
    rec.policy_id = info.policy_id;
    rec.has_trigger_event_id = info.has_trigger_event_id ? 1 : 0;
    rec.trigger_event_id = info.has_trigger_event_id ? info.trigger_event_id : ID{};
    rec.state = static_cast<uint8_t>(info.state);
    rec.started_time = info.started_time;
    rec.has_completed_time = info.has_completed_time ? 1 : 0;
    rec.completed_time = info.has_completed_time ? info.completed_time : 0;
    rec.has_error_message = (info.has_error_message && !info.error_message.empty()) ? 1 : 0;
    if (rec.has_error_message)
    {
        uint64_t xmin = 0;
        Status status = storeStringInToast(info.error_message, xmin, rec.error_message_oid, ctx);
        if (status != Status::OK)
        {
            return status;
        }
    }
    rec.is_valid = info.is_valid ? 1 : 0;

    auto matcher = [&info](const HealingRunRecord& row) {
        return row.run_id == info.run_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(healing_run_table_page_, matcher, rec, ctx);
}

auto CatalogManager::getHealingRunCatalogEntry(const ID& run_id,
                                               HealingRunCatalogInfo& info_out,
                                               ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    auto predicate = [&run_id](const HealingRunRecord& rec) {
        return rec.run_id == run_id && rec.is_valid == 1;
    };
    auto result = findRecordInHeapPage<HealingRunRecord>(healing_run_table_page_, predicate, ctx);
    if (result.status != Status::OK)
    {
        return Status::NOT_FOUND;
    }
    if (!isValidHealingRunState(static_cast<HealingRunState>(result.record.state)))
    {
        return Status::PAGE_CORRUPT;
    }
    info_out = HealingRunCatalogInfo{};
    info_out.run_id = result.record.run_id;
    info_out.policy_id = result.record.policy_id;
    info_out.has_trigger_event_id = result.record.has_trigger_event_id != 0;
    info_out.trigger_event_id = info_out.has_trigger_event_id ? result.record.trigger_event_id : ID{};
    info_out.state = static_cast<HealingRunState>(result.record.state);
    info_out.started_time = result.record.started_time;
    info_out.has_completed_time = result.record.has_completed_time != 0;
    info_out.completed_time = result.record.completed_time;
    info_out.has_error_message = result.record.has_error_message != 0;
    if (info_out.has_error_message)
    {
        uint64_t xmin = 0;
        Status status = loadStringFromToast(result.record.error_message_oid, xmin, info_out.error_message, ctx);
        if (status != Status::OK)
        {
            return status;
        }
    }
    info_out.is_valid = result.record.is_valid == 1;
    return Status::OK;
}

