auto CatalogManager::upsertHealingStepCatalogEntry(const HealingStepCatalogInfo& info,
                                                   ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.step_id) || isZeroUuidLocal(info.run_id) || isZeroUuidLocal(info.action_id) ||
        !isValidHealingStepState(info.state))
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.has_completed_time && info.has_started_time && info.completed_time < info.started_time)
    {
        return Status::INVALID_ARGUMENT;
    }

    auto run_predicate = [&info](const HealingRunRecord& rec) {
        return rec.run_id == info.run_id && rec.is_valid == 1;
    };
    if (findRecordInHeapPage<HealingRunRecord>(healing_run_table_page_, run_predicate, ctx).status != Status::OK)
    {
        return Status::NOT_FOUND;
    }
    auto action_predicate = [&info](const HealingActionRecord& rec) {
        return rec.action_id == info.action_id && rec.is_valid == 1;
    };
    if (findRecordInHeapPage<HealingActionRecord>(healing_action_table_page_, action_predicate, ctx).status != Status::OK)
    {
        return Status::NOT_FOUND;
    }

    auto duplicate_predicate = [&info](const HealingStepRecord& row) {
        return row.is_valid == 1 &&
               row.step_id != info.step_id &&
               row.run_id == info.run_id &&
               row.step_index == info.step_index;
    };
    auto duplicate = findRecordInHeapPage<HealingStepRecord>(healing_step_table_page_, duplicate_predicate, ctx);
    if (duplicate.status == Status::OK)
    {
        return Status::CONSTRAINT_VIOLATION;
    }
    if (duplicate.status != Status::NOT_FOUND)
    {
        return duplicate.status;
    }

    HealingStepRecord rec{};
    rec.step_id = info.step_id;
    rec.run_id = info.run_id;
    rec.action_id = info.action_id;
    rec.step_index = info.step_index;
    rec.state = static_cast<uint8_t>(info.state);
    rec.has_started_time = info.has_started_time ? 1 : 0;
    rec.started_time = info.has_started_time ? info.started_time : 0;
    rec.has_completed_time = info.has_completed_time ? 1 : 0;
    rec.completed_time = info.has_completed_time ? info.completed_time : 0;
    rec.has_error_message = (info.has_error_message && !info.error_message.empty()) ? 1 : 0;
    if (rec.has_error_message)
    {
        uint64_t xmin = 0;
        Status status = storeStringInToast(info.error_message, xmin, rec.error_message_oid, ctx);
        if (status != Status::OK)
        {
            return status;
        }
    }
    rec.is_valid = info.is_valid ? 1 : 0;

    auto matcher = [&info](const HealingStepRecord& row) {
        return row.step_id == info.step_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(healing_step_table_page_, matcher, rec, ctx);
}

