auto CatalogManager::upsertJobTypeParamCatalogEntry(const JobTypeParamCatalogInfo& info,
                                                    ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.param_id) || isZeroUuidLocal(info.job_type_id) ||
        info.param_key.empty() || !isValidJobParamType(info.param_type))
    {
        return Status::INVALID_ARGUMENT;
    }

    auto job_type_predicate = [&info](const JobTypeCatalogRecord& rec) {
        return rec.job_type_id == info.job_type_id && rec.is_valid == 1;
    };
    if (findRecordInHeapPage<JobTypeCatalogRecord>(job_type_table_page_, job_type_predicate, ctx).status != Status::OK)
    {
        return Status::NOT_FOUND;
    }

    auto duplicate_predicate = [&info](const JobTypeParamCatalogRecord& row) {
        return row.is_valid == 1 &&
               row.param_id != info.param_id &&
               row.job_type_id == info.job_type_id &&
               fixedNameFromBuffer(row.param_key, sizeof(row.param_key)) == info.param_key;
    };
    auto duplicate = findRecordInHeapPage<JobTypeParamCatalogRecord>(
        job_type_param_table_page_, duplicate_predicate, ctx);
    if (duplicate.status == Status::OK)
    {
        return Status::CONSTRAINT_VIOLATION;
    }
    if (duplicate.status != Status::NOT_FOUND)
    {
        return duplicate.status;
    }

    JobTypeParamCatalogRecord rec{};
    rec.param_id = info.param_id;
    rec.job_type_id = info.job_type_id;
    std::strncpy(rec.param_key,
                 UTF8Utils::truncateToBytes(info.param_key, sizeof(rec.param_key)).c_str(),
                 sizeof(rec.param_key) - 1);
    rec.param_type = static_cast<uint8_t>(info.param_type);
    rec.is_required = info.is_required ? 1 : 0;
    rec.has_default_value = (info.has_default_value && !info.default_value.empty()) ? 1 : 0;
    rec.has_description = (info.has_description && !info.description.empty()) ? 1 : 0;
    rec.is_valid = info.is_valid ? 1 : 0;

    if (rec.has_default_value != 0)
    {
        uint64_t xmin = 0;
        Status status = storeStringInToast(info.default_value, xmin, rec.default_value_oid, ctx);
        if (status != Status::OK)
        {
            return status;
        }
    }
    if (rec.has_description != 0)
    {
        uint64_t xmin = 0;
        Status status = storeStringInToast(info.description, xmin, rec.description_oid, ctx);
        if (status != Status::OK)
        {
            return status;
        }
    }

    auto matcher = [&info](const JobTypeParamCatalogRecord& row) {
        return row.param_id == info.param_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(job_type_param_table_page_, matcher, rec, ctx);
}

