auto CatalogManager::upsertJobScheduleCatalogEntry(const JobScheduleCatalogInfo& info,
                                                   ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.schedule_id) || !isValidScheduleKind(info.schedule_kind))
    {
        return Status::INVALID_ARGUMENT;
    }

    const bool has_interval = info.has_interval_ms && info.interval_ms > 0;
    const bool has_cron = info.has_cron_expr && !info.cron_expr.empty();
    if (info.schedule_kind == ScheduleKind::EVERY && (!has_interval || has_cron))
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.schedule_kind == ScheduleKind::CRON && (!has_cron || has_interval))
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.schedule_kind == ScheduleKind::AT && (has_interval || has_cron))
    {
        return Status::INVALID_ARGUMENT;
    }

    JobScheduleCatalogRecord rec{};
    rec.schedule_id = info.schedule_id;
    rec.schedule_kind = static_cast<uint8_t>(info.schedule_kind);
    rec.has_interval_ms = has_interval ? 1 : 0;
    rec.has_cron_expr = has_cron ? 1 : 0;
    rec.is_enabled = info.is_enabled ? 1 : 0;
    rec.is_valid = info.is_valid ? 1 : 0;
    rec.interval_ms = has_interval ? info.interval_ms : 0;
    if (has_cron)
    {
        uint64_t xmin = 0;
        Status status = storeStringInToast(info.cron_expr, xmin, rec.cron_expr_oid, ctx);
        if (status != Status::OK)
        {
            return status;
        }
    }

    auto matcher = [&info](const JobScheduleCatalogRecord& row) {
        return row.schedule_id == info.schedule_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(job_schedule_table_page_, matcher, rec, ctx);
}

auto CatalogManager::getJobScheduleCatalogEntry(const ID& schedule_id,
                                                JobScheduleCatalogInfo& info_out,
                                                ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    auto predicate = [&schedule_id](const JobScheduleCatalogRecord& rec) {
        return rec.schedule_id == schedule_id && rec.is_valid == 1;
    };
    auto result = findRecordInHeapPage<JobScheduleCatalogRecord>(job_schedule_table_page_, predicate, ctx);
    if (result.status != Status::OK)
    {
        return Status::NOT_FOUND;
    }
    if (!isValidScheduleKind(static_cast<ScheduleKind>(result.record.schedule_kind)))
    {
        return Status::PAGE_CORRUPT;
    }
    info_out = JobScheduleCatalogInfo{};
    info_out.schedule_id = result.record.schedule_id;
    info_out.schedule_kind = static_cast<ScheduleKind>(result.record.schedule_kind);
    info_out.has_interval_ms = result.record.has_interval_ms != 0;
    info_out.interval_ms = info_out.has_interval_ms ? result.record.interval_ms : 0;
    info_out.has_cron_expr = result.record.has_cron_expr != 0;
    if (info_out.has_cron_expr)
    {
        uint64_t xmin = 0;
        Status status = loadStringFromToast(result.record.cron_expr_oid, xmin, info_out.cron_expr, ctx);
        if (status != Status::OK)
        {
            return status;
        }
    }
    info_out.is_enabled = result.record.is_enabled != 0;
    info_out.is_valid = result.record.is_valid == 1;

    if (info_out.schedule_kind == ScheduleKind::EVERY && !info_out.has_interval_ms)
    {
        return Status::PAGE_CORRUPT;
    }
    if (info_out.schedule_kind == ScheduleKind::CRON && !info_out.has_cron_expr)
    {
        return Status::PAGE_CORRUPT;
    }
    if (info_out.schedule_kind == ScheduleKind::AT &&
        (info_out.has_interval_ms || info_out.has_cron_expr))
    {
        return Status::PAGE_CORRUPT;
    }
    return Status::OK;
}

