auto CatalogManager::upsertRemoteConnectorCatalogEntry(const RemoteConnectorCatalogInfo& info,
                                                       ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.remote_connector_id) || isZeroUuidLocal(info.fdw_server_id) ||
        isZeroUuidLocal(info.fdw_id) || info.connector_name.empty() ||
        info.engine_name.empty() || info.endpoint_uri.empty() ||
        !isValidRemoteConnectorState(info.state))
    {
        return Status::INVALID_ARGUMENT;
    }

    auto server_predicate = [&info](const ForeignServerRecord& rec) {
        return rec.server_id == info.fdw_server_id && rec.is_valid == 1;
    };
    if (findRecordInHeapPage<ForeignServerRecord>(foreign_servers_table_page_, server_predicate, ctx).status != Status::OK)
    {
        return Status::NOT_FOUND;
    }
    if (info.has_default_mapping_id)
    {
        auto mapping_predicate = [&info](const UserMappingRecord& rec) {
            return rec.mapping_id == info.default_mapping_id && rec.is_valid == 1;
        };
        if (findRecordInHeapPage<UserMappingRecord>(user_mappings_table_page_, mapping_predicate, ctx).status != Status::OK)
        {
            return Status::NOT_FOUND;
        }
    }
    if (info.has_last_ready_time && info.has_last_probe_time &&
        info.last_ready_time < info.last_probe_time)
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.state == RemoteConnectorState::READY ||
        info.state == RemoteConnectorState::DEGRADED)
    {
        if (info.module_checksum == 0)
        {
            SET_ERROR_CONTEXT(ctx,
                              Status::CONSTRAINT_VIOLATION,
                              "remote connector attestation requires module checksum");
            return Status::CONSTRAINT_VIOLATION;
        }
        if (!info.has_engine_version_text || info.engine_version_text.empty())
        {
            SET_ERROR_CONTEXT(ctx,
                              Status::CONSTRAINT_VIOLATION,
                              "remote connector attestation requires engine version text");
            return Status::CONSTRAINT_VIOLATION;
        }
    }

    auto duplicate_server_predicate = [&info](const RemoteConnectorRecord& row) {
        return row.is_valid == 1 &&
               row.remote_connector_id != info.remote_connector_id &&
               row.fdw_server_id == info.fdw_server_id;
    };
    auto duplicate_server = findRecordInHeapPage<RemoteConnectorRecord>(
        remote_connector_table_page_, duplicate_server_predicate, ctx);
    if (duplicate_server.status == Status::OK)
    {
        return Status::CONSTRAINT_VIOLATION;
    }
    if (duplicate_server.status != Status::NOT_FOUND)
    {
        return duplicate_server.status;
    }

    auto duplicate_name_predicate = [&info](const RemoteConnectorRecord& row) {
        return row.is_valid == 1 &&
               row.remote_connector_id != info.remote_connector_id &&
               fixedNameFromBuffer(row.connector_name, sizeof(row.connector_name)) == info.connector_name;
    };
    auto duplicate_name = findRecordInHeapPage<RemoteConnectorRecord>(
        remote_connector_table_page_, duplicate_name_predicate, ctx);
    if (duplicate_name.status == Status::OK)
    {
        return Status::CONSTRAINT_VIOLATION;
    }
    if (duplicate_name.status != Status::NOT_FOUND)
    {
        return duplicate_name.status;
    }

    const uint64_t now = catalogNowTicks();
    RemoteConnectorRecord rec{};
    rec.remote_connector_id = info.remote_connector_id;
    rec.fdw_server_id = info.fdw_server_id;
    rec.fdw_id = info.fdw_id;
    std::strncpy(rec.connector_name,
                 UTF8Utils::truncateToBytes(info.connector_name, sizeof(rec.connector_name)).c_str(),
                 sizeof(rec.connector_name) - 1);
    std::strncpy(rec.engine_name,
                 UTF8Utils::truncateToBytes(info.engine_name, sizeof(rec.engine_name)).c_str(),
                 sizeof(rec.engine_name) - 1);
    std::strncpy(rec.endpoint_uri,
                 UTF8Utils::truncateToBytes(info.endpoint_uri, sizeof(rec.endpoint_uri)).c_str(),
                 sizeof(rec.endpoint_uri) - 1);
    rec.has_engine_version_text = (info.has_engine_version_text && !info.engine_version_text.empty()) ? 1 : 0;
    rec.has_default_mapping_id = info.has_default_mapping_id ? 1 : 0;
    rec.has_policy_id = info.has_policy_id ? 1 : 0;
    rec.state = static_cast<uint8_t>(info.state);
    rec.has_last_probe_time = info.has_last_probe_time ? 1 : 0;
    rec.has_last_ready_time = info.has_last_ready_time ? 1 : 0;
    rec.is_valid = info.is_valid ? 1 : 0;
    rec.failure_count = info.failure_count;
    rec.module_checksum = info.module_checksum;
    rec.default_mapping_id = info.has_default_mapping_id ? info.default_mapping_id : ID{};
    rec.policy_id = info.has_policy_id ? info.policy_id : ID{};
    rec.last_probe_time = info.has_last_probe_time ? info.last_probe_time : 0;
    rec.last_ready_time = info.has_last_ready_time ? info.last_ready_time : 0;
    rec.created_time = (info.created_time == 0) ? now : info.created_time;
    rec.last_modified_time = now;

    if (rec.has_engine_version_text != 0)
    {
        uint64_t xmin = 0;
        Status status = storeStringInToast(info.engine_version_text, xmin, rec.engine_version_text_oid, ctx);
        if (status != Status::OK)
        {
            return status;
        }
    }

    auto existing_predicate = [&info](const RemoteConnectorRecord& row) {
        return row.remote_connector_id == info.remote_connector_id && row.is_valid == 1;
    };
    auto existing = findRecordInHeapPage<RemoteConnectorRecord>(
        remote_connector_table_page_, existing_predicate, ctx);
    std::string previous_connector_name;
    if (existing.status == Status::OK)
    {
        const auto previous_state = static_cast<RemoteConnectorState>(existing.record.state);
        if (!isValidRemoteConnectorState(previous_state))
        {
            SET_ERROR_CONTEXT(ctx, Status::PAGE_CORRUPT, "remote connector state is invalid");
            return Status::PAGE_CORRUPT;
        }
        if (!isAllowedRemoteConnectorTransition(previous_state, info.state))
        {
            SET_ERROR_CONTEXT(ctx, Status::CONSTRAINT_VIOLATION, "invalid remote connector state transition");
            return Status::CONSTRAINT_VIOLATION;
        }
        rec.created_time = existing.record.created_time;
        previous_connector_name = fixedNameFromBuffer(existing.record.connector_name,
                                                      sizeof(existing.record.connector_name));
    }
    else if (existing.status != Status::NOT_FOUND)
    {
        return existing.status;
    }

    auto matcher = [&info](const RemoteConnectorRecord& row) {
        return row.remote_connector_id == info.remote_connector_id && row.is_valid == 1;
    };
    Status status = updateRecordInHeapPage(remote_connector_table_page_, matcher, rec, ctx);
    if (status != Status::OK)
    {
        return status;
    }

    if (rec.is_valid == 1)
    {
        status = ensureOverlaySchemaChildUnlocked("connections", info.connector_name, nullptr, ctx);
        if (status != Status::OK)
        {
            SET_ERROR_CONTEXT(ctx, status, "Failed to create connection mount schema");
            return status;
        }

        if (!previous_connector_name.empty() &&
            !IdentifierUtils::namesConflict(info.connector_name, false /*new_is_delimited*/,
                                            previous_connector_name, false /*stored_delimited*/))
        {
            status = dropOverlaySchemaChildUnlocked("connections", previous_connector_name, ctx);
            if (status != Status::OK)
            {
                SET_ERROR_CONTEXT(ctx, status, "Failed to drop previous connection mount schema");
                return status;
            }
        }
    }
    else if (!previous_connector_name.empty())
    {
        status = dropOverlaySchemaChildUnlocked("connections", previous_connector_name, ctx);
        if (status != Status::OK)
        {
            SET_ERROR_CONTEXT(ctx, status, "Failed to drop connection mount schema");
            return status;
        }
    }

    return Status::OK;
}

auto CatalogManager::getRemoteConnectorCatalogEntry(const ID& remote_connector_id,
                                                    RemoteConnectorCatalogInfo& info_out,
                                                    ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    auto predicate = [&remote_connector_id](const RemoteConnectorRecord& rec) {
        return rec.remote_connector_id == remote_connector_id && rec.is_valid == 1;
    };
    auto result = findRecordInHeapPage<RemoteConnectorRecord>(remote_connector_table_page_, predicate, ctx);
    if (result.status != Status::OK)
    {
        return Status::NOT_FOUND;
    }
    if (!isValidRemoteConnectorState(static_cast<RemoteConnectorState>(result.record.state)))
    {
        return Status::PAGE_CORRUPT;
    }

    info_out = RemoteConnectorCatalogInfo{};
    info_out.remote_connector_id = result.record.remote_connector_id;
    info_out.fdw_server_id = result.record.fdw_server_id;
    info_out.fdw_id = result.record.fdw_id;
    info_out.connector_name = fixedNameFromBuffer(result.record.connector_name, sizeof(result.record.connector_name));
    info_out.engine_name = fixedNameFromBuffer(result.record.engine_name, sizeof(result.record.engine_name));
    info_out.endpoint_uri = fixedNameFromBuffer(result.record.endpoint_uri, sizeof(result.record.endpoint_uri));
    info_out.has_engine_version_text = result.record.has_engine_version_text != 0;
    info_out.has_default_mapping_id = result.record.has_default_mapping_id != 0;
    info_out.default_mapping_id = result.record.default_mapping_id;
    info_out.has_policy_id = result.record.has_policy_id != 0;
    info_out.policy_id = result.record.policy_id;
    info_out.state = static_cast<RemoteConnectorState>(result.record.state);
    info_out.failure_count = result.record.failure_count;
    info_out.has_last_probe_time = result.record.has_last_probe_time != 0;
    info_out.last_probe_time = result.record.last_probe_time;
    info_out.has_last_ready_time = result.record.has_last_ready_time != 0;
    info_out.last_ready_time = result.record.last_ready_time;
    info_out.module_checksum = result.record.module_checksum;
    info_out.created_time = result.record.created_time;
    info_out.last_modified_time = result.record.last_modified_time;
    info_out.is_valid = result.record.is_valid == 1;
    if (info_out.has_engine_version_text)
    {
        uint64_t xmin = 0;
        Status status = loadStringFromToast(result.record.engine_version_text_oid, xmin, info_out.engine_version_text, ctx);
        if (status != Status::OK)
        {
            return status;
        }
    }
    return Status::OK;
}

auto CatalogManager::listRemoteConnectorCatalogEntries(
    std::vector<RemoteConnectorCatalogInfo>& rows_out,
    ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    rows_out.clear();
    auto filter = [](const RemoteConnectorRecord& rec) { return rec.is_valid == 1; };
    auto converter = [this, ctx](const RemoteConnectorRecord& rec, RemoteConnectorCatalogInfo& info) {
        info = RemoteConnectorCatalogInfo{};
        info.remote_connector_id = rec.remote_connector_id;
        info.fdw_server_id = rec.fdw_server_id;
        info.fdw_id = rec.fdw_id;
        info.connector_name = fixedNameFromBuffer(rec.connector_name, sizeof(rec.connector_name));
        info.engine_name = fixedNameFromBuffer(rec.engine_name, sizeof(rec.engine_name));
        info.endpoint_uri = fixedNameFromBuffer(rec.endpoint_uri, sizeof(rec.endpoint_uri));
        info.has_engine_version_text = rec.has_engine_version_text != 0;
        info.has_default_mapping_id = rec.has_default_mapping_id != 0;
        info.default_mapping_id = rec.default_mapping_id;
        info.has_policy_id = rec.has_policy_id != 0;
        info.policy_id = rec.policy_id;
        info.state = static_cast<RemoteConnectorState>(rec.state);
        info.failure_count = rec.failure_count;
        info.has_last_probe_time = rec.has_last_probe_time != 0;
        info.last_probe_time = rec.last_probe_time;
        info.has_last_ready_time = rec.has_last_ready_time != 0;
        info.last_ready_time = rec.last_ready_time;
        info.module_checksum = rec.module_checksum;
        info.created_time = rec.created_time;
        info.last_modified_time = rec.last_modified_time;
        info.is_valid = rec.is_valid == 1;
        if (info.has_engine_version_text)
        {
            uint64_t xmin = 0;
            std::string text;
            if (loadStringFromToast(rec.engine_version_text_oid, xmin, text, ctx) == Status::OK)
            {
                info.engine_version_text = std::move(text);
            }
        }
    };
    return readRecordsToVector<RemoteConnectorRecord, RemoteConnectorCatalogInfo>(
        remote_connector_table_page_, rows_out, filter, converter, ctx);
}

auto CatalogManager::deleteRemoteConnectorCatalogEntry(const ID& remote_connector_id,
                                                       ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    auto predicate = [&remote_connector_id](const RemoteConnectorRecord& rec) {
        return rec.remote_connector_id == remote_connector_id && rec.is_valid == 1;
    };
    auto result = findRecordInHeapPage<RemoteConnectorRecord>(remote_connector_table_page_, predicate, ctx);
    if (result.status != Status::OK)
    {
        return Status::NOT_FOUND;
    }

    const std::string connector_name =
        fixedNameFromBuffer(result.record.connector_name, sizeof(result.record.connector_name));
    Status status = dropOverlaySchemaChildUnlocked("connections", connector_name, ctx);
    if (status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, status, "Failed to drop connection mount schema");
        return status;
    }

    RemoteConnectorRecord updated = result.record;
    updated.is_valid = 0;
    updated.last_modified_time = catalogNowTicks();
    return updateRecordInHeapPage(remote_connector_table_page_, result.slot_index, updated, ctx);
}

auto CatalogManager::upsertRemoteConnectorCapabilityCatalogEntry(
    const RemoteConnectorCapabilityCatalogInfo& info,
    ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.capability_id) || isZeroUuidLocal(info.remote_connector_id) ||
        info.capability_key.empty() || info.capability_group.empty() ||
        info.capability_value_json.empty())
    {
        return Status::INVALID_ARGUMENT;
    }
    auto connector_predicate = [&info](const RemoteConnectorRecord& rec) {
        return rec.remote_connector_id == info.remote_connector_id && rec.is_valid == 1;
    };
    auto connector_result = findRecordInHeapPage<RemoteConnectorRecord>(
        remote_connector_table_page_, connector_predicate, ctx);
    if (connector_result.status != Status::OK)
    {
        return Status::NOT_FOUND;
    }
    const auto connector_state = static_cast<RemoteConnectorState>(connector_result.record.state);
    if (!isValidRemoteConnectorState(connector_state))
    {
        return Status::PAGE_CORRUPT;
    }
    std::string connector_engine_version;
    if (connector_result.record.has_engine_version_text != 0)
    {
        uint64_t xmin = 0;
        Status load_status = loadStringFromToast(connector_result.record.engine_version_text_oid,
                                                 xmin,
                                                 connector_engine_version,
                                                 ctx);
        if (load_status != Status::OK)
        {
            return load_status;
        }
    }

    if (info.is_enabled && (!info.has_source_version_text || info.source_version_text.empty()))
    {
        SET_ERROR_CONTEXT(ctx,
                          Status::CONSTRAINT_VIOLATION,
                          "enabled remote capability requires source version lineage");
        return Status::CONSTRAINT_VIOLATION;
    }
    if (info.is_enabled &&
        !connector_engine_version.empty() &&
        info.source_version_text != connector_engine_version)
    {
        SET_ERROR_CONTEXT(ctx,
                          Status::CONSTRAINT_VIOLATION,
                          "remote capability source version must match connector engine version");
        return Status::CONSTRAINT_VIOLATION;
    }
    if ((connector_state == RemoteConnectorState::READY ||
         connector_state == RemoteConnectorState::DEGRADED) &&
        !info.is_enabled)
    {
        SET_ERROR_CONTEXT(ctx,
                          Status::CONSTRAINT_VIOLATION,
                          "ready/degraded connectors require enabled capability lineage rows");
        return Status::CONSTRAINT_VIOLATION;
    }

    auto duplicate_predicate = [&info](const RemoteConnectorCapabilityRecord& row) {
        return row.is_valid == 1 &&
               row.capability_id != info.capability_id &&
               row.remote_connector_id == info.remote_connector_id &&
               fixedNameFromBuffer(row.capability_key, sizeof(row.capability_key)) == info.capability_key;
    };
    auto duplicate = findRecordInHeapPage<RemoteConnectorCapabilityRecord>(
        remote_connector_capability_table_page_, duplicate_predicate, ctx);
    if (duplicate.status == Status::OK)
    {
        return Status::CONSTRAINT_VIOLATION;
    }
    if (duplicate.status != Status::NOT_FOUND)
    {
        return duplicate.status;
    }

    const uint64_t discovered_time = (info.discovered_time == 0) ? catalogNowTicks() : info.discovered_time;
    auto existing_predicate = [&info](const RemoteConnectorCapabilityRecord& row) {
        return row.capability_id == info.capability_id && row.is_valid == 1;
    };
    auto existing = findRecordInHeapPage<RemoteConnectorCapabilityRecord>(
        remote_connector_capability_table_page_, existing_predicate, ctx);
    if (existing.status == Status::OK)
    {
        if (discovered_time < existing.record.discovered_time)
        {
            SET_ERROR_CONTEXT(ctx,
                              Status::CONSTRAINT_VIOLATION,
                              "remote capability lineage discovered_time cannot move backwards");
            return Status::CONSTRAINT_VIOLATION;
        }

        uint64_t xmin = 0;
        std::string existing_value_json;
        Status load_status = loadStringFromToast(existing.record.capability_value_oid,
                                                 xmin,
                                                 existing_value_json,
                                                 ctx);
        if (load_status != Status::OK)
        {
            return load_status;
        }
        std::string existing_source_version;
        if (existing.record.has_source_version_text != 0)
        {
            load_status = loadStringFromToast(existing.record.source_version_text_oid,
                                              xmin,
                                              existing_source_version,
                                              ctx);
            if (load_status != Status::OK)
            {
                return load_status;
            }
        }
        const bool source_changed = existing.record.has_source_version_text !=
                                        (info.has_source_version_text && !info.source_version_text.empty()) ||
                                    existing_source_version != info.source_version_text;
        const bool value_changed = existing_value_json != info.capability_value_json;
        if ((source_changed || value_changed) &&
            discovered_time == existing.record.discovered_time)
        {
            SET_ERROR_CONTEXT(ctx,
                              Status::CONSTRAINT_VIOLATION,
                              "remote capability lineage changes require newer discovered_time");
            return Status::CONSTRAINT_VIOLATION;
        }
    }
    else if (existing.status != Status::NOT_FOUND)
    {
        return existing.status;
    }

    RemoteConnectorCapabilityRecord rec{};
    rec.capability_id = info.capability_id;
    rec.remote_connector_id = info.remote_connector_id;
    std::strncpy(rec.capability_key,
                 UTF8Utils::truncateToBytes(info.capability_key, sizeof(rec.capability_key)).c_str(),
                 sizeof(rec.capability_key) - 1);
    std::strncpy(rec.capability_group,
                 UTF8Utils::truncateToBytes(info.capability_group, sizeof(rec.capability_group)).c_str(),
                 sizeof(rec.capability_group) - 1);
    rec.has_source_version_text = (info.has_source_version_text && !info.source_version_text.empty()) ? 1 : 0;
    rec.is_enabled = info.is_enabled ? 1 : 0;
    rec.is_valid = info.is_valid ? 1 : 0;
    rec.discovered_time = discovered_time;
    uint64_t xmin = 0;
    Status status = storeStringInToast(info.capability_value_json, xmin, rec.capability_value_oid, ctx);
    if (status != Status::OK)
    {
        return status;
    }
    if (rec.has_source_version_text != 0)
    {
        status = storeStringInToast(info.source_version_text, xmin, rec.source_version_text_oid, ctx);
        if (status != Status::OK)
        {
            return status;
        }
    }

    auto matcher = [&info](const RemoteConnectorCapabilityRecord& row) {
        return row.capability_id == info.capability_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(remote_connector_capability_table_page_, matcher, rec, ctx);
}

