auto CatalogManager::listRemoteConnectorCapabilityCatalogEntries(
    const ID& remote_connector_id,
    std::vector<RemoteConnectorCapabilityCatalogInfo>& rows_out,
    ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    rows_out.clear();
    auto filter = [&remote_connector_id](const RemoteConnectorCapabilityRecord& rec) {
        return rec.is_valid == 1 &&
               (isZeroUuidLocal(remote_connector_id) || rec.remote_connector_id == remote_connector_id);
    };
    auto converter = [this, ctx](const RemoteConnectorCapabilityRecord& rec, RemoteConnectorCapabilityCatalogInfo& info) {
        info = RemoteConnectorCapabilityCatalogInfo{};
        info.capability_id = rec.capability_id;
        info.remote_connector_id = rec.remote_connector_id;
        info.capability_key = fixedNameFromBuffer(rec.capability_key, sizeof(rec.capability_key));
        info.capability_group = fixedNameFromBuffer(rec.capability_group, sizeof(rec.capability_group));
        info.has_source_version_text = rec.has_source_version_text != 0;
        info.is_enabled = rec.is_enabled != 0;
        info.discovered_time = rec.discovered_time;
        info.is_valid = rec.is_valid == 1;
        uint64_t xmin = 0;
        std::string text;
        if (loadStringFromToast(rec.capability_value_oid, xmin, text, ctx) == Status::OK)
        {
            info.capability_value_json = std::move(text);
        }
        if (info.has_source_version_text)
        {
            if (loadStringFromToast(rec.source_version_text_oid, xmin, text, ctx) == Status::OK)
            {
                info.source_version_text = std::move(text);
            }
        }
    };
    return readRecordsToVector<RemoteConnectorCapabilityRecord, RemoteConnectorCapabilityCatalogInfo>(
        remote_connector_capability_table_page_, rows_out, filter, converter, ctx);
}

