auto CatalogManager::upsertRemotePreparedStatementCatalogEntry(
    const RemotePreparedStatementCatalogInfo& info,
    ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.remote_prepared_id) || isZeroUuidLocal(info.remote_connector_id) ||
        isZeroUuidLocal(info.session_id) || info.statement_name.empty() ||
        info.command_text.empty() || info.remote_handle.empty())
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.has_expires_time && info.expires_time == 0)
    {
        return Status::INVALID_ARGUMENT;
    }
    auto connector_predicate = [&info](const RemoteConnectorRecord& rec) {
        return rec.remote_connector_id == info.remote_connector_id && rec.is_valid == 1;
    };
    if (findRecordInHeapPage<RemoteConnectorRecord>(remote_connector_table_page_, connector_predicate, ctx).status != Status::OK)
    {
        return Status::NOT_FOUND;
    }
    auto session_predicate = [&info](const SessionRecord& rec) {
        return rec.session_id == info.session_id && rec.is_valid == 1;
    };
    if (findRecordInHeapPage<SessionRecord>(sessions_table_page_, session_predicate, ctx).status != Status::OK)
    {
        return Status::NOT_FOUND;
    }
    auto duplicate_predicate = [&info](const RemotePreparedStatementRecord& row) {
        return row.is_valid == 1 &&
               row.remote_prepared_id != info.remote_prepared_id &&
               row.remote_connector_id == info.remote_connector_id &&
               row.session_id == info.session_id &&
               fixedNameFromBuffer(row.statement_name, sizeof(row.statement_name)) == info.statement_name;
    };
    auto duplicate = findRecordInHeapPage<RemotePreparedStatementRecord>(
        remote_prepared_statement_table_page_, duplicate_predicate, ctx);
    if (duplicate.status == Status::OK)
    {
        return Status::CONSTRAINT_VIOLATION;
    }
    if (duplicate.status != Status::NOT_FOUND)
    {
        return duplicate.status;
    }

    const uint64_t now = catalogNowTicks();
    RemotePreparedStatementRecord rec{};
    rec.remote_prepared_id = info.remote_prepared_id;
    rec.remote_connector_id = info.remote_connector_id;
    rec.session_id = info.session_id;
    std::strncpy(rec.statement_name,
                 UTF8Utils::truncateToBytes(info.statement_name, sizeof(rec.statement_name)).c_str(),
                 sizeof(rec.statement_name) - 1);
    rec.statement_fingerprint = info.statement_fingerprint;
    rec.has_parameter_signature = info.has_parameter_signature ? 1 : 0;
    rec.parameter_signature = info.has_parameter_signature ? info.parameter_signature : 0;
    rec.has_expires_time = info.has_expires_time ? 1 : 0;
    rec.expires_time = info.has_expires_time ? info.expires_time : 0;
    rec.is_valid = info.is_valid ? 1 : 0;
    rec.created_time = (info.created_time == 0) ? now : info.created_time;
    rec.last_used_time = (info.last_used_time == 0) ? rec.created_time : info.last_used_time;
    if (rec.has_expires_time != 0 && rec.expires_time < rec.created_time)
    {
        return Status::INVALID_ARGUMENT;
    }
    uint64_t xmin = 0;
    Status status = storeStringInToast(info.command_text, xmin, rec.command_text_oid, ctx);
    if (status != Status::OK)
    {
        return status;
    }
    status = storeStringInToast(info.remote_handle, xmin, rec.remote_handle_oid, ctx);
    if (status != Status::OK)
    {
        return status;
    }
    auto existing_predicate = [&info](const RemotePreparedStatementRecord& row) {
        return row.remote_prepared_id == info.remote_prepared_id && row.is_valid == 1;
    };
    auto existing = findRecordInHeapPage<RemotePreparedStatementRecord>(
        remote_prepared_statement_table_page_, existing_predicate, ctx);
    if (existing.status == Status::OK)
    {
        rec.created_time = existing.record.created_time;
    }
    else if (existing.status != Status::NOT_FOUND)
    {
        return existing.status;
    }
    auto matcher = [&info](const RemotePreparedStatementRecord& row) {
        return row.remote_prepared_id == info.remote_prepared_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(remote_prepared_statement_table_page_, matcher, rec, ctx);
}

