auto CatalogManager::upsertRemoteErrorCatalogEntry(const RemoteErrorCatalogInfo& info,
                                                   ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.remote_error_id) || isZeroUuidLocal(info.remote_connector_id) ||
        !isValidRemoteErrorClass(info.error_class) || info.message_text.empty())
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.has_remote_code && info.remote_code.empty())
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.occurrence_count == 0)
    {
        return Status::INVALID_ARGUMENT;
    }
    const uint64_t now = catalogNowTicks();
    const uint64_t first_seen = (info.first_seen_time == 0) ? now : info.first_seen_time;
    const uint64_t last_seen = (info.last_seen_time == 0) ? first_seen : info.last_seen_time;
    if (last_seen < first_seen)
    {
        return Status::INVALID_ARGUMENT;
    }
    auto connector_predicate = [&info](const RemoteConnectorRecord& rec) {
        return rec.remote_connector_id == info.remote_connector_id && rec.is_valid == 1;
    };
    if (findRecordInHeapPage<RemoteConnectorRecord>(remote_connector_table_page_, connector_predicate, ctx).status != Status::OK)
    {
        return Status::NOT_FOUND;
    }

    std::string sanitized_message_text = redactSensitiveDiagnosticText(info.message_text);
    if (sanitized_message_text.empty())
    {
        sanitized_message_text = "<redacted>";
    }

    RemoteErrorRecord rec{};
    rec.remote_error_id = info.remote_error_id;
    rec.remote_connector_id = info.remote_connector_id;
    rec.error_class = static_cast<uint8_t>(info.error_class);
    rec.has_remote_code = info.has_remote_code ? 1 : 0;
    rec.is_open = info.is_open ? 1 : 0;
    rec.is_valid = info.is_valid ? 1 : 0;
    rec.first_seen_time = first_seen;
    rec.last_seen_time = last_seen;
    rec.occurrence_count = info.occurrence_count;

    uint64_t xmin = 0;
    Status status = storeStringInToast(sanitized_message_text, xmin, rec.message_text_oid, ctx);
    if (status != Status::OK)
    {
        return status;
    }
    status = storeStringInToast(info.mapped_code, xmin, rec.mapped_code_oid, ctx);
    if (status != Status::OK)
    {
        return status;
    }
    if (rec.has_remote_code != 0)
    {
        status = storeStringInToast(info.remote_code, xmin, rec.remote_code_oid, ctx);
        if (status != Status::OK)
        {
            return status;
        }
    }

    auto existing_predicate = [&info](const RemoteErrorRecord& row) {
        return row.remote_error_id == info.remote_error_id && row.is_valid == 1;
    };
    auto existing = findRecordInHeapPage<RemoteErrorRecord>(
        remote_error_table_page_, existing_predicate, ctx);
    if (existing.status == Status::OK)
    {
        rec.first_seen_time = existing.record.first_seen_time;
    }
    else if (existing.status != Status::NOT_FOUND)
    {
        return existing.status;
    }

    auto matcher = [&info](const RemoteErrorRecord& row) {
        return row.remote_error_id == info.remote_error_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(remote_error_table_page_, matcher, rec, ctx);
}

auto CatalogManager::getRemoteErrorCatalogEntry(const ID& remote_error_id,
                                                RemoteErrorCatalogInfo& info_out,
                                                ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    auto predicate = [&remote_error_id](const RemoteErrorRecord& rec) {
        return rec.remote_error_id == remote_error_id && rec.is_valid == 1;
    };
    auto result = findRecordInHeapPage<RemoteErrorRecord>(remote_error_table_page_, predicate, ctx);
    if (result.status != Status::OK)
    {
        return Status::NOT_FOUND;
    }
    if (!isValidRemoteErrorClass(static_cast<RemoteErrorClass>(result.record.error_class)))
    {
        return Status::PAGE_CORRUPT;
    }
    if (result.record.occurrence_count == 0 || result.record.last_seen_time < result.record.first_seen_time)
    {
        return Status::PAGE_CORRUPT;
    }
    info_out = RemoteErrorCatalogInfo{};
    info_out.remote_error_id = result.record.remote_error_id;
    info_out.remote_connector_id = result.record.remote_connector_id;
    info_out.error_class = static_cast<RemoteErrorClass>(result.record.error_class);
    info_out.has_remote_code = result.record.has_remote_code != 0;
    info_out.is_open = result.record.is_open != 0;
    info_out.is_valid = result.record.is_valid == 1;
    info_out.first_seen_time = result.record.first_seen_time;
    info_out.last_seen_time = result.record.last_seen_time;
    info_out.occurrence_count = result.record.occurrence_count;
    uint64_t xmin = 0;
    Status status = loadStringFromToast(result.record.mapped_code_oid, xmin, info_out.mapped_code, ctx);
    if (status != Status::OK)
    {
        return status;
    }
    status = loadStringFromToast(result.record.message_text_oid, xmin, info_out.message_text, ctx);
    if (status != Status::OK)
    {
        return status;
    }
    if (info_out.has_remote_code)
    {
        status = loadStringFromToast(result.record.remote_code_oid, xmin, info_out.remote_code, ctx);
        if (status != Status::OK)
        {
            return status;
        }
    }
    return Status::OK;
}

auto CatalogManager::listRemoteErrorCatalogEntries(const ID& remote_connector_id,
                                                   std::vector<RemoteErrorCatalogInfo>& rows_out,
                                                   ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    rows_out.clear();
    auto filter = [&remote_connector_id](const RemoteErrorRecord& rec) {
        return rec.is_valid == 1 &&
               (isZeroUuidLocal(remote_connector_id) || rec.remote_connector_id == remote_connector_id);
    };
    auto converter = [this, ctx](const RemoteErrorRecord& rec, RemoteErrorCatalogInfo& info) {
        info = RemoteErrorCatalogInfo{};
        info.remote_error_id = rec.remote_error_id;
        info.remote_connector_id = rec.remote_connector_id;
        info.error_class = static_cast<RemoteErrorClass>(rec.error_class);
        info.has_remote_code = rec.has_remote_code != 0;
        info.is_open = rec.is_open != 0;
        info.is_valid = rec.is_valid == 1;
        info.first_seen_time = rec.first_seen_time;
        info.last_seen_time = rec.last_seen_time;
        info.occurrence_count = rec.occurrence_count;
        uint64_t xmin = 0;
        std::string text;
        if (loadStringFromToast(rec.mapped_code_oid, xmin, text, ctx) == Status::OK)
        {
            info.mapped_code = std::move(text);
        }
        if (loadStringFromToast(rec.message_text_oid, xmin, text, ctx) == Status::OK)
        {
            info.message_text = std::move(text);
        }
        if (info.has_remote_code)
        {
            if (loadStringFromToast(rec.remote_code_oid, xmin, text, ctx) == Status::OK)
            {
                info.remote_code = std::move(text);
            }
        }
    };
    Status status = readRecordsToVector<RemoteErrorRecord, RemoteErrorCatalogInfo>(
        remote_error_table_page_, rows_out, filter, converter, ctx);
    if (status != Status::OK)
    {
        return status;
    }
    for (const auto& row : rows_out)
    {
        if (!isValidRemoteErrorClass(row.error_class) ||
            row.occurrence_count == 0 ||
            row.last_seen_time < row.first_seen_time)
        {
            return Status::PAGE_CORRUPT;
        }
    }
    return Status::OK;
}

