auto CatalogManager::upsertPublicationCatalogEntry(const PublicationCatalogInfo& info,
                                                   ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.publication_id) || info.publication_name.empty() || isZeroUuidLocal(info.owner_id))
    {
        return Status::INVALID_ARGUMENT;
    }

    auto owner_predicate = [&info](const UserRecord& rec) {
        return rec.user_id == info.owner_id && rec.is_valid == 1;
    };
    if (findRecordInHeapPage<UserRecord>(users_table_page_, owner_predicate, ctx).status != Status::OK)
    {
        return Status::NOT_FOUND;
    }

    const std::string folded_name = canonicalIdentifierForLookup(info.publication_name);
    auto duplicate_predicate = [&info, &folded_name](const PublicationRecord& rec) {
        return rec.is_valid == 1 &&
               rec.publication_id != info.publication_id &&
               canonicalIdentifierForLookup(
                   fixedNameFromBuffer(rec.publication_name, sizeof(rec.publication_name))) == folded_name;
    };
    auto duplicate = findRecordInHeapPage<PublicationRecord>(
        publication_table_page_, duplicate_predicate, ctx);
    if (duplicate.status == Status::OK)
    {
        return Status::CONSTRAINT_VIOLATION;
    }
    if (duplicate.status != Status::NOT_FOUND)
    {
        return duplicate.status;
    }

    const uint64_t now = catalogNowTicks();
    PublicationRecord rec{};
    rec.publication_id = info.publication_id;
    std::strncpy(rec.publication_name,
                 UTF8Utils::truncateToBytes(info.publication_name, sizeof(rec.publication_name)).c_str(),
                 sizeof(rec.publication_name) - 1);
    rec.owner_id = info.owner_id;
    rec.publish_insert = info.publish_insert ? 1 : 0;
    rec.publish_update = info.publish_update ? 1 : 0;
    rec.publish_delete = info.publish_delete ? 1 : 0;
    rec.publish_truncate = info.publish_truncate ? 1 : 0;
    rec.publish_via_partition_root = info.publish_via_partition_root ? 1 : 0;
    rec.created_time = (info.created_time == 0) ? now : info.created_time;
    rec.last_modified_time = now;
    rec.is_valid = info.is_valid ? 1 : 0;

    auto existing_predicate = [&info](const PublicationRecord& row) {
        return row.publication_id == info.publication_id && row.is_valid == 1;
    };
    auto existing = findRecordInHeapPage<PublicationRecord>(
        publication_table_page_, existing_predicate, ctx);
    if (existing.status == Status::OK)
    {
        rec.created_time = existing.record.created_time;
    }
    else if (existing.status != Status::NOT_FOUND)
    {
        return existing.status;
    }

    auto matcher = [&info](const PublicationRecord& row) {
        return row.publication_id == info.publication_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(publication_table_page_, matcher, rec, ctx);
}

