auto CatalogManager::upsertReplicationCursorCatalogEntry(const ReplicationCursorCatalogInfo& info,
                                                         ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.replication_cursor_id) || isZeroUuidLocal(info.replication_channel_id) ||
        isZeroUuidLocal(info.channel_member_id) || info.cursor_name.empty() ||
        !isValidReplicationCursorState(info.cursor_state) ||
        info.applied_commit_seq > info.source_commit_seq ||
        info.cursor_payload.empty())
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.has_last_error_id && isZeroUuidLocal(info.last_error_id))
    {
        return Status::INVALID_ARGUMENT;
    }

    auto channel_predicate = [&info](const ReplicationChannelRecord& rec) {
        return rec.replication_channel_id == info.replication_channel_id && rec.is_valid == 1;
    };
    if (findRecordInHeapPage<ReplicationChannelRecord>(replication_channel_table_page_, channel_predicate, ctx).status != Status::OK)
    {
        return Status::NOT_FOUND;
    }

    auto member_predicate = [&info](const ReplicationChannelMemberRecord& rec) {
        return rec.channel_member_id == info.channel_member_id &&
               rec.replication_channel_id == info.replication_channel_id &&
               rec.is_valid == 1;
    };
    if (findRecordInHeapPage<ReplicationChannelMemberRecord>(replication_channel_member_table_page_, member_predicate, ctx).status != Status::OK)
    {
        return Status::NOT_FOUND;
    }

    if (info.has_last_error_id)
    {
        auto error_predicate = [&info](const ReplicationErrorRecord& rec) {
            return rec.replication_error_id == info.last_error_id && rec.is_valid == 1;
        };
        if (findRecordInHeapPage<ReplicationErrorRecord>(replication_error_table_page_, error_predicate, ctx).status != Status::OK)
        {
            return Status::NOT_FOUND;
        }
    }

    auto duplicate_predicate = [&info](const ReplicationCursorRecord& row) {
        return row.is_valid == 1 &&
               row.replication_cursor_id != info.replication_cursor_id &&
               row.replication_channel_id == info.replication_channel_id &&
               row.channel_member_id == info.channel_member_id &&
               fixedNameFromBuffer(row.cursor_name, sizeof(row.cursor_name)) == info.cursor_name;
    };
    auto duplicate = findRecordInHeapPage<ReplicationCursorRecord>(
        replication_cursor_table_page_, duplicate_predicate, ctx);
    if (duplicate.status == Status::OK)
    {
        return Status::CONSTRAINT_VIOLATION;
    }
    if (duplicate.status != Status::NOT_FOUND)
    {
        return duplicate.status;
    }

    ReplicationCursorRecord rec{};
    rec.replication_cursor_id = info.replication_cursor_id;
    rec.replication_channel_id = info.replication_channel_id;
    rec.channel_member_id = info.channel_member_id;
    std::strncpy(rec.cursor_name,
                 UTF8Utils::truncateToBytes(info.cursor_name, sizeof(rec.cursor_name)).c_str(),
                 sizeof(rec.cursor_name) - 1);
    rec.cursor_state = static_cast<uint8_t>(info.cursor_state);
    rec.has_source_commit_time = info.has_source_commit_time ? 1 : 0;
    rec.has_applied_time = info.has_applied_time ? 1 : 0;
    rec.has_heartbeat_time = info.has_heartbeat_time ? 1 : 0;
    rec.has_last_error_id = info.has_last_error_id ? 1 : 0;
    rec.source_commit_seq = info.source_commit_seq;
    rec.source_commit_time = info.has_source_commit_time ? info.source_commit_time : 0;
    rec.applied_commit_seq = info.applied_commit_seq;
    rec.applied_time = info.has_applied_time ? info.applied_time : 0;
    rec.lag_ms = info.lag_ms;
    rec.heartbeat_time = info.has_heartbeat_time ? info.heartbeat_time : 0;
    rec.last_error_id = info.has_last_error_id ? info.last_error_id : ID{};
    rec.is_valid = info.is_valid ? 1 : 0;

    uint64_t xmin = 0;
    Status status = storeStringInToast(info.cursor_payload, xmin, rec.cursor_payload_oid, ctx);
    if (status != Status::OK)
    {
        return status;
    }

    auto matcher = [&info](const ReplicationCursorRecord& row) {
        return row.replication_cursor_id == info.replication_cursor_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(replication_cursor_table_page_, matcher, rec, ctx);
}

auto CatalogManager::getReplicationCursorCatalogEntry(const ID& replication_cursor_id,
                                                      ReplicationCursorCatalogInfo& info_out,
                                                      ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    auto predicate = [&replication_cursor_id](const ReplicationCursorRecord& rec) {
        return rec.replication_cursor_id == replication_cursor_id && rec.is_valid == 1;
    };
    auto result = findRecordInHeapPage<ReplicationCursorRecord>(replication_cursor_table_page_, predicate, ctx);
    if (result.status != Status::OK)
    {
        return Status::NOT_FOUND;
    }
    if (!isValidReplicationCursorState(static_cast<ReplicationCursorState>(result.record.cursor_state)) ||
        result.record.applied_commit_seq > result.record.source_commit_seq)
    {
        return Status::PAGE_CORRUPT;
    }

    info_out = ReplicationCursorCatalogInfo{};
    info_out.replication_cursor_id = result.record.replication_cursor_id;
    info_out.replication_channel_id = result.record.replication_channel_id;
    info_out.channel_member_id = result.record.channel_member_id;
    info_out.cursor_name = fixedNameFromBuffer(result.record.cursor_name, sizeof(result.record.cursor_name));
    info_out.cursor_state = static_cast<ReplicationCursorState>(result.record.cursor_state);
    info_out.has_source_commit_time = result.record.has_source_commit_time != 0;
    info_out.source_commit_seq = result.record.source_commit_seq;
    info_out.source_commit_time = result.record.source_commit_time;
    info_out.has_applied_time = result.record.has_applied_time != 0;
    info_out.applied_commit_seq = result.record.applied_commit_seq;
    info_out.applied_time = result.record.applied_time;
    info_out.lag_ms = result.record.lag_ms;
    info_out.has_heartbeat_time = result.record.has_heartbeat_time != 0;
    info_out.heartbeat_time = result.record.heartbeat_time;
    info_out.has_last_error_id = result.record.has_last_error_id != 0;
    info_out.last_error_id = result.record.last_error_id;
    info_out.is_valid = result.record.is_valid == 1;

    uint64_t xmin = 0;
    Status status = loadStringFromToast(result.record.cursor_payload_oid, xmin, info_out.cursor_payload, ctx);
    if (status != Status::OK)
    {
        return status;
    }
    return Status::OK;
}

