auto CatalogManager::upsertReplicationTxnBatchCatalogEntry(const ReplicationTxnBatchCatalogInfo& info,
                                                           ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.replication_batch_id) || isZeroUuidLocal(info.replication_channel_id) ||
        isZeroUuidLocal(info.source_member_id) || isZeroUuidLocal(info.origin_id) ||
        info.source_txn_id.empty() || info.source_commit_seq == 0 || info.source_commit_time == 0 ||
        info.received_time == 0 || !isValidReplicationTxnState(info.txn_state))
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.has_applied_time && info.applied_time < info.received_time)
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.has_last_error_id && isZeroUuidLocal(info.last_error_id))
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.txn_state == ReplicationTxnState::FAILED && !info.has_last_error_id)
    {
        return Status::INVALID_ARGUMENT;
    }

    auto channel_predicate = [&info](const ReplicationChannelRecord& rec) {
        return rec.replication_channel_id == info.replication_channel_id && rec.is_valid == 1;
    };
    if (findRecordInHeapPage<ReplicationChannelRecord>(replication_channel_table_page_, channel_predicate, ctx).status != Status::OK)
    {
        return Status::NOT_FOUND;
    }
    auto member_predicate = [&info](const ReplicationChannelMemberRecord& rec) {
        return rec.channel_member_id == info.source_member_id &&
               rec.replication_channel_id == info.replication_channel_id &&
               rec.is_valid == 1;
    };
    if (findRecordInHeapPage<ReplicationChannelMemberRecord>(replication_channel_member_table_page_, member_predicate, ctx).status != Status::OK)
    {
        return Status::NOT_FOUND;
    }
    auto origin_predicate = [&info](const ReplicationOriginRecord& rec) {
        return rec.origin_id == info.origin_id && rec.is_valid == 1;
    };
    if (findRecordInHeapPage<ReplicationOriginRecord>(replication_origin_table_page_, origin_predicate, ctx).status != Status::OK)
    {
        return Status::NOT_FOUND;
    }
    if (info.has_last_error_id)
    {
        auto error_predicate = [&info](const ReplicationErrorRecord& rec) {
            return rec.replication_error_id == info.last_error_id && rec.is_valid == 1;
        };
        if (findRecordInHeapPage<ReplicationErrorRecord>(replication_error_table_page_, error_predicate, ctx).status != Status::OK)
        {
            return Status::NOT_FOUND;
        }
    }

    auto duplicate_predicate = [&info](const ReplicationTxnBatchRecord& row) {
        return row.is_valid == 1 &&
               row.replication_batch_id != info.replication_batch_id &&
               row.replication_channel_id == info.replication_channel_id &&
               row.source_member_id == info.source_member_id &&
               row.source_commit_seq == info.source_commit_seq;
    };
    auto duplicate = findRecordInHeapPage<ReplicationTxnBatchRecord>(
        replication_txn_batch_table_page_, duplicate_predicate, ctx);
    if (duplicate.status == Status::OK)
    {
        return Status::CONSTRAINT_VIOLATION;
    }
    if (duplicate.status != Status::NOT_FOUND)
    {
        return duplicate.status;
    }

    ReplicationTxnBatchRecord rec{};
    rec.replication_batch_id = info.replication_batch_id;
    rec.replication_channel_id = info.replication_channel_id;
    rec.source_member_id = info.source_member_id;
    rec.origin_id = info.origin_id;
    rec.source_commit_seq = info.source_commit_seq;
    rec.source_commit_time = info.source_commit_time;
    rec.txn_state = static_cast<uint8_t>(info.txn_state);
    rec.change_count = info.change_count;
    rec.payload_bytes = info.payload_bytes;
    rec.batch_checksum = info.batch_checksum;
    rec.received_time = info.received_time;
    rec.has_applied_time = info.has_applied_time ? 1 : 0;
    rec.applied_time = info.has_applied_time ? info.applied_time : 0;
    rec.retry_count = info.retry_count;
    rec.has_last_error_id = info.has_last_error_id ? 1 : 0;
    rec.last_error_id = info.has_last_error_id ? info.last_error_id : ID{};
    rec.is_valid = info.is_valid ? 1 : 0;

    uint64_t xmin = 0;
    Status status = storeStringInToast(info.source_txn_id, xmin, rec.source_txn_id_oid, ctx);
    if (status != Status::OK)
    {
        return status;
    }

    auto matcher = [&info](const ReplicationTxnBatchRecord& row) {
        return row.replication_batch_id == info.replication_batch_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(replication_txn_batch_table_page_, matcher, rec, ctx);
}

auto CatalogManager::getReplicationTxnBatchCatalogEntry(const ID& replication_batch_id,
                                                        ReplicationTxnBatchCatalogInfo& info_out,
                                                        ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    auto predicate = [&replication_batch_id](const ReplicationTxnBatchRecord& rec) {
        return rec.replication_batch_id == replication_batch_id && rec.is_valid == 1;
    };
    auto result = findRecordInHeapPage<ReplicationTxnBatchRecord>(replication_txn_batch_table_page_, predicate, ctx);
    if (result.status != Status::OK)
    {
        return Status::NOT_FOUND;
    }
    if (!isValidReplicationTxnState(static_cast<ReplicationTxnState>(result.record.txn_state)))
    {
        return Status::PAGE_CORRUPT;
    }
    if (result.record.txn_state == static_cast<uint8_t>(ReplicationTxnState::FAILED) &&
        result.record.has_last_error_id == 0)
    {
        return Status::PAGE_CORRUPT;
    }

    info_out = ReplicationTxnBatchCatalogInfo{};
    info_out.replication_batch_id = result.record.replication_batch_id;
    info_out.replication_channel_id = result.record.replication_channel_id;
    info_out.source_member_id = result.record.source_member_id;
    info_out.origin_id = result.record.origin_id;
    info_out.source_commit_seq = result.record.source_commit_seq;
    info_out.source_commit_time = result.record.source_commit_time;
    info_out.txn_state = static_cast<ReplicationTxnState>(result.record.txn_state);
    info_out.change_count = result.record.change_count;
    info_out.payload_bytes = result.record.payload_bytes;
    info_out.batch_checksum = result.record.batch_checksum;
    info_out.received_time = result.record.received_time;
    info_out.has_applied_time = result.record.has_applied_time != 0;
    info_out.applied_time = result.record.applied_time;
    info_out.retry_count = result.record.retry_count;
    info_out.has_last_error_id = result.record.has_last_error_id != 0;
    info_out.last_error_id = result.record.last_error_id;
    info_out.is_valid = result.record.is_valid == 1;

    uint64_t xmin = 0;
    Status status = loadStringFromToast(result.record.source_txn_id_oid, xmin, info_out.source_txn_id, ctx);
    if (status != Status::OK)
    {
        return status;
    }
    return Status::OK;
}

auto CatalogManager::listReplicationTxnBatchCatalogEntries(
    const ID& replication_channel_id,
    std::vector<ReplicationTxnBatchCatalogInfo>& rows_out,
    ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    rows_out.clear();
    auto filter = [&replication_channel_id](const ReplicationTxnBatchRecord& rec) {
        return rec.is_valid == 1 &&
               (isZeroUuidLocal(replication_channel_id) || rec.replication_channel_id == replication_channel_id);
    };
    auto converter = [this, ctx](const ReplicationTxnBatchRecord& rec, ReplicationTxnBatchCatalogInfo& info) {
        info = ReplicationTxnBatchCatalogInfo{};
        info.replication_batch_id = rec.replication_batch_id;
        info.replication_channel_id = rec.replication_channel_id;
        info.source_member_id = rec.source_member_id;
        info.origin_id = rec.origin_id;
        info.source_commit_seq = rec.source_commit_seq;
        info.source_commit_time = rec.source_commit_time;
        info.txn_state = static_cast<ReplicationTxnState>(rec.txn_state);
        info.change_count = rec.change_count;
        info.payload_bytes = rec.payload_bytes;
        info.batch_checksum = rec.batch_checksum;
        info.received_time = rec.received_time;
        info.has_applied_time = rec.has_applied_time != 0;
        info.applied_time = rec.applied_time;
        info.retry_count = rec.retry_count;
        info.has_last_error_id = rec.has_last_error_id != 0;
        info.last_error_id = rec.last_error_id;
        info.is_valid = rec.is_valid == 1;
        uint64_t xmin = 0;
        std::string source_txn_id;
        if (loadStringFromToast(rec.source_txn_id_oid, xmin, source_txn_id, ctx) == Status::OK)
        {
            info.source_txn_id = std::move(source_txn_id);
        }
    };
    Status status = readRecordsToVector<ReplicationTxnBatchRecord, ReplicationTxnBatchCatalogInfo>(
        replication_txn_batch_table_page_, rows_out, filter, converter, ctx);
    if (status != Status::OK)
    {
        return status;
    }
    for (const auto& row : rows_out)
    {
        if (!isValidReplicationTxnState(row.txn_state) ||
            (row.txn_state == ReplicationTxnState::FAILED && !row.has_last_error_id))
        {
            return Status::PAGE_CORRUPT;
        }
    }
    return Status::OK;
}

