    if (duplicate.status == Status::OK)
    {
        return Status::CONSTRAINT_VIOLATION;
    }
    if (duplicate.status != Status::NOT_FOUND)
    {
        return duplicate.status;
    }

    ReplicationApplyLogRecord rec{};
    rec.replication_apply_log_id = info.replication_apply_log_id;
    rec.replication_batch_id = info.replication_batch_id;
    rec.target_member_id = info.target_member_id;
    rec.apply_order = info.apply_order;
