    rec.apply_end_time = info.has_apply_end_time ? info.apply_end_time : 0;
    rec.has_applied_commit_seq = info.has_applied_commit_seq ? 1 : 0;
    rec.applied_commit_seq = info.has_applied_commit_seq ? info.applied_commit_seq : 0;
