auto CatalogManager::listReplicationApplyLogCatalogEntries(
    const ID& replication_batch_id,
    std::vector<ReplicationApplyLogCatalogInfo>& rows_out,
    ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    rows_out.clear();
    auto filter = [&replication_batch_id](const ReplicationApplyLogRecord& rec) {
        return rec.is_valid == 1 &&
               (isZeroUuidLocal(replication_batch_id) || rec.replication_batch_id == replication_batch_id);
    };
    auto converter = [](const ReplicationApplyLogRecord& rec, ReplicationApplyLogCatalogInfo& info) {
        info = ReplicationApplyLogCatalogInfo{};
        info.replication_apply_log_id = rec.replication_apply_log_id;
        info.replication_batch_id = rec.replication_batch_id;
        info.target_member_id = rec.target_member_id;
        info.apply_order = rec.apply_order;
        info.txn_state = static_cast<ReplicationTxnState>(rec.txn_state);
        info.apply_start_time = rec.apply_start_time;
        info.has_apply_end_time = rec.has_apply_end_time != 0;
        info.apply_end_time = rec.apply_end_time;
        info.has_applied_commit_seq = rec.has_applied_commit_seq != 0;
        info.applied_commit_seq = rec.applied_commit_seq;
        info.rows_inserted = rec.rows_inserted;
        info.rows_updated = rec.rows_updated;
        info.rows_deleted = rec.rows_deleted;
        info.ddl_count = rec.ddl_count;
        info.has_error_id = rec.has_error_id != 0;
        info.error_id = rec.error_id;
        info.is_valid = rec.is_valid == 1;
    };
    Status status = readRecordsToVector<ReplicationApplyLogRecord, ReplicationApplyLogCatalogInfo>(
        replication_apply_log_table_page_, rows_out, filter, converter, ctx);
    if (status != Status::OK)
    {
        return status;
    }
    for (const auto& row : rows_out)
    {
        if (!isValidReplicationTxnState(row.txn_state) ||
            row.apply_order == 0 ||
            (row.has_apply_end_time && row.apply_end_time < row.apply_start_time))
        {
            return Status::PAGE_CORRUPT;
        }
    }
    return Status::OK;
}

