auto CatalogManager::upsertReplicationRetryQueueCatalogEntry(
    const ReplicationRetryQueueCatalogInfo& info,
    ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.replication_retry_id) || isZeroUuidLocal(info.replication_batch_id) ||
        info.next_retry_time == 0 || !isValidReplicationRetryState(info.retry_state))
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.has_last_error_id && isZeroUuidLocal(info.last_error_id))
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.retry_state == ReplicationRetryState::DEAD_LETTER &&
        (!info.has_dead_letter_reason || info.dead_letter_reason.empty()))
    {
        return Status::INVALID_ARGUMENT;
    }

    auto batch_predicate = [&info](const ReplicationTxnBatchRecord& rec) {
        return rec.replication_batch_id == info.replication_batch_id && rec.is_valid == 1;
    };
    if (findRecordInHeapPage<ReplicationTxnBatchRecord>(replication_txn_batch_table_page_, batch_predicate, ctx).status != Status::OK)
    {
        return Status::NOT_FOUND;
    }
    if (info.has_last_error_id)
    {
        auto error_predicate = [&info](const ReplicationErrorRecord& rec) {
            return rec.replication_error_id == info.last_error_id && rec.is_valid == 1;
        };
        if (findRecordInHeapPage<ReplicationErrorRecord>(replication_error_table_page_, error_predicate, ctx).status != Status::OK)
        {
            return Status::NOT_FOUND;
        }
    }

    auto duplicate_predicate = [&info](const ReplicationRetryQueueRecord& row) {
        return row.is_valid == 1 &&
               row.replication_retry_id != info.replication_retry_id &&
               row.replication_batch_id == info.replication_batch_id;
    };
    auto duplicate = findRecordInHeapPage<ReplicationRetryQueueRecord>(
        replication_retry_queue_table_page_, duplicate_predicate, ctx);
    if (duplicate.status == Status::OK)
    {
        return Status::CONSTRAINT_VIOLATION;
    }
    if (duplicate.status != Status::NOT_FOUND)
    {
        return duplicate.status;
    }

    ReplicationRetryQueueRecord rec{};
    rec.replication_retry_id = info.replication_retry_id;
    rec.replication_batch_id = info.replication_batch_id;
    rec.retry_state = static_cast<uint8_t>(info.retry_state);
    rec.retry_count = info.retry_count;
    rec.next_retry_time = info.next_retry_time;
    rec.has_last_retry_time = info.has_last_retry_time ? 1 : 0;
    rec.last_retry_time = info.has_last_retry_time ? info.last_retry_time : 0;
    rec.has_last_error_id = info.has_last_error_id ? 1 : 0;
    rec.last_error_id = info.has_last_error_id ? info.last_error_id : ID{};
    rec.has_dead_letter_reason = info.has_dead_letter_reason ? 1 : 0;
    rec.is_valid = info.is_valid ? 1 : 0;

    if (rec.has_dead_letter_reason != 0)
    {
        uint64_t xmin = 0;
        Status status = storeStringInToast(info.dead_letter_reason, xmin, rec.dead_letter_reason_oid, ctx);
        if (status != Status::OK)
        {
            return status;
        }
    }

    auto matcher = [&info](const ReplicationRetryQueueRecord& row) {
        return row.replication_retry_id == info.replication_retry_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(replication_retry_queue_table_page_, matcher, rec, ctx);
}

auto CatalogManager::getReplicationRetryQueueCatalogEntry(const ID& replication_retry_id,
                                                          ReplicationRetryQueueCatalogInfo& info_out,
                                                          ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    auto predicate = [&replication_retry_id](const ReplicationRetryQueueRecord& rec) {
        return rec.replication_retry_id == replication_retry_id && rec.is_valid == 1;
    };
    auto result = findRecordInHeapPage<ReplicationRetryQueueRecord>(
        replication_retry_queue_table_page_, predicate, ctx);
    if (result.status != Status::OK)
    {
        return Status::NOT_FOUND;
    }
    if (!isValidReplicationRetryState(static_cast<ReplicationRetryState>(result.record.retry_state)) ||
        (result.record.retry_state == static_cast<uint8_t>(ReplicationRetryState::DEAD_LETTER) &&
         result.record.has_dead_letter_reason == 0))
    {
        return Status::PAGE_CORRUPT;
    }

    info_out = ReplicationRetryQueueCatalogInfo{};
    info_out.replication_retry_id = result.record.replication_retry_id;
    info_out.replication_batch_id = result.record.replication_batch_id;
    info_out.retry_state = static_cast<ReplicationRetryState>(result.record.retry_state);
    info_out.retry_count = result.record.retry_count;
    info_out.next_retry_time = result.record.next_retry_time;
    info_out.has_last_retry_time = result.record.has_last_retry_time != 0;
    info_out.last_retry_time = result.record.last_retry_time;
    info_out.has_last_error_id = result.record.has_last_error_id != 0;
    info_out.last_error_id = result.record.last_error_id;
    info_out.has_dead_letter_reason = result.record.has_dead_letter_reason != 0;
    info_out.is_valid = result.record.is_valid == 1;

    if (info_out.has_dead_letter_reason)
    {
        uint64_t xmin = 0;
        Status status = loadStringFromToast(result.record.dead_letter_reason_oid, xmin, info_out.dead_letter_reason, ctx);
        if (status != Status::OK)
        {
            return status;
        }
    }
    return Status::OK;
}

auto CatalogManager::listReplicationRetryQueueCatalogEntries(
    std::vector<ReplicationRetryQueueCatalogInfo>& rows_out,
    ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    rows_out.clear();
    auto filter = [](const ReplicationRetryQueueRecord& rec) { return rec.is_valid == 1; };
    auto converter = [this, ctx](const ReplicationRetryQueueRecord& rec, ReplicationRetryQueueCatalogInfo& info) {
        info = ReplicationRetryQueueCatalogInfo{};
        info.replication_retry_id = rec.replication_retry_id;
        info.replication_batch_id = rec.replication_batch_id;
        info.retry_state = static_cast<ReplicationRetryState>(rec.retry_state);
        info.retry_count = rec.retry_count;
        info.next_retry_time = rec.next_retry_time;
        info.has_last_retry_time = rec.has_last_retry_time != 0;
        info.last_retry_time = rec.last_retry_time;
        info.has_last_error_id = rec.has_last_error_id != 0;
        info.last_error_id = rec.last_error_id;
        info.has_dead_letter_reason = rec.has_dead_letter_reason != 0;
        info.is_valid = rec.is_valid == 1;
        if (info.has_dead_letter_reason)
        {
            uint64_t xmin = 0;
            std::string reason;
            if (loadStringFromToast(rec.dead_letter_reason_oid, xmin, reason, ctx) == Status::OK)
            {
                info.dead_letter_reason = std::move(reason);
            }
        }
    };
    Status status = readRecordsToVector<ReplicationRetryQueueRecord, ReplicationRetryQueueCatalogInfo>(
        replication_retry_queue_table_page_, rows_out, filter, converter, ctx);
    if (status != Status::OK)
    {
        return status;
    }
    for (const auto& row : rows_out)
    {
        if (!isValidReplicationRetryState(row.retry_state) ||
            (row.retry_state == ReplicationRetryState::DEAD_LETTER && !row.has_dead_letter_reason))
        {
            return Status::PAGE_CORRUPT;
        }
    }
    return Status::OK;
}

