auto CatalogManager::upsertReplicationConflictCatalogEntry(const ReplicationConflictCatalogInfo& info,
                                                           ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.replication_conflict_id) || isZeroUuidLocal(info.replication_channel_id) ||
        isZeroUuidLocal(info.replication_batch_id) || isZeroUuidLocal(info.source_origin_id) ||
        isZeroUuidLocal(info.target_object_id) || !isValidReplicationConflictKind(info.conflict_kind) ||
        !isValidReplicationResolutionState(info.resolution_state) || info.source_commit_seq == 0 ||
        info.source_payload.empty())
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.has_target_origin_id && isZeroUuidLocal(info.target_origin_id))
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.has_target_row_id && isZeroUuidLocal(info.target_row_id))
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.has_target_payload && info.target_payload.empty())
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.has_resolved_by_id && isZeroUuidLocal(info.resolved_by_id))
    {
        return Status::INVALID_ARGUMENT;
    }
    if (isResolvedReplicationState(info.resolution_state) && !info.has_resolved_time)
    {
        return Status::INVALID_ARGUMENT;
    }

    auto channel_predicate = [&info](const ReplicationChannelRecord& rec) {
        return rec.replication_channel_id == info.replication_channel_id && rec.is_valid == 1;
    };
    if (findRecordInHeapPage<ReplicationChannelRecord>(replication_channel_table_page_, channel_predicate, ctx).status != Status::OK)
    {
        return Status::NOT_FOUND;
    }
    auto batch_predicate = [&info](const ReplicationTxnBatchRecord& rec) {
        return rec.replication_batch_id == info.replication_batch_id &&
               rec.replication_channel_id == info.replication_channel_id &&
               rec.is_valid == 1;
    };
    if (findRecordInHeapPage<ReplicationTxnBatchRecord>(replication_txn_batch_table_page_, batch_predicate, ctx).status != Status::OK)
    {
        return Status::NOT_FOUND;
    }
    auto source_origin_predicate = [&info](const ReplicationOriginRecord& rec) {
        return rec.origin_id == info.source_origin_id && rec.is_valid == 1;
    };
    if (findRecordInHeapPage<ReplicationOriginRecord>(replication_origin_table_page_, source_origin_predicate, ctx).status != Status::OK)
    {
        return Status::NOT_FOUND;
    }
    if (info.has_target_origin_id)
    {
        auto target_origin_predicate = [&info](const ReplicationOriginRecord& rec) {
            return rec.origin_id == info.target_origin_id && rec.is_valid == 1;
        };
        if (findRecordInHeapPage<ReplicationOriginRecord>(replication_origin_table_page_, target_origin_predicate, ctx).status != Status::OK)
        {
            return Status::NOT_FOUND;
        }
    }
    auto object_predicate = [&info](const ObjectRecord& rec) {
        return rec.object_id == info.target_object_id && rec.is_valid != 0;
    };
    if (findRecordInHeapPage<ObjectRecord>(object_table_page_, object_predicate, ctx).status != Status::OK)
    {
        return Status::NOT_FOUND;
    }
    if (info.has_resolved_by_id)
    {
        auto resolved_by_predicate = [&info](const UserRecord& rec) {
            return rec.user_id == info.resolved_by_id && rec.is_valid == 1;
        };
        if (findRecordInHeapPage<UserRecord>(users_table_page_, resolved_by_predicate, ctx).status != Status::OK)
        {
            return Status::NOT_FOUND;
        }
    }

    ReplicationConflictRecord rec{};
    rec.replication_conflict_id = info.replication_conflict_id;
    rec.replication_channel_id = info.replication_channel_id;
    rec.replication_batch_id = info.replication_batch_id;
    rec.conflict_kind = static_cast<uint8_t>(info.conflict_kind);
    rec.source_origin_id = info.source_origin_id;
    rec.has_target_origin_id = info.has_target_origin_id ? 1 : 0;
    rec.target_origin_id = info.has_target_origin_id ? info.target_origin_id : ID{};
    rec.target_object_id = info.target_object_id;
    rec.has_target_row_id = info.has_target_row_id ? 1 : 0;
    rec.target_row_id = info.has_target_row_id ? info.target_row_id : ID{};
    rec.source_commit_seq = info.source_commit_seq;
    rec.has_target_commit_seq = info.has_target_commit_seq ? 1 : 0;
    rec.target_commit_seq = info.has_target_commit_seq ? info.target_commit_seq : 0;
    rec.has_target_payload = info.has_target_payload ? 1 : 0;
    rec.resolution_state = static_cast<uint8_t>(info.resolution_state);
    rec.has_resolved_by_id = info.has_resolved_by_id ? 1 : 0;
    rec.resolved_by_id = info.has_resolved_by_id ? info.resolved_by_id : ID{};
    rec.has_resolved_time = info.has_resolved_time ? 1 : 0;
    rec.resolved_time = info.has_resolved_time ? info.resolved_time : 0;
    rec.has_resolution_note = info.has_resolution_note ? 1 : 0;
    rec.is_valid = info.is_valid ? 1 : 0;

    uint64_t xmin = 0;
    Status status = storeStringInToast(info.source_payload, xmin, rec.source_payload_oid, ctx);
    if (status != Status::OK)
    {
        return status;
    }
    if (rec.has_target_payload != 0)
    {
        status = storeStringInToast(info.target_payload, xmin, rec.target_payload_oid, ctx);
        if (status != Status::OK)
        {
            return status;
        }
    }
    if (rec.has_resolution_note != 0)
    {
        status = storeStringInToast(info.resolution_note, xmin, rec.resolution_note_oid, ctx);
        if (status != Status::OK)
        {
            return status;
        }
    }

    auto matcher = [&info](const ReplicationConflictRecord& row) {
        return row.replication_conflict_id == info.replication_conflict_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(replication_conflict_table_page_, matcher, rec, ctx);
}

