        info.replication_channel_id = rec.replication_channel_id;
        info.event_kind = static_cast<ReplicationEventKind>(rec.event_kind);
        info.detected_time = rec.detected_time;
        info.has_resolved_time = rec.has_resolved_time != 0;
        info.resolved_time = rec.resolved_time;
        info.has_resolution_payload = rec.has_resolution_payload != 0;
        info.fence_applied = rec.fence_applied != 0;
        info.fence_cleared = rec.fence_cleared != 0;
        info.has_approved_by_id = rec.has_approved_by_id != 0;
        info.approved_by_id = rec.approved_by_id;
        info.is_valid = rec.is_valid == 1;
        uint64_t xmin = 0;
