auto CatalogManager::upsertClusterFabricSessionCatalogEntry(const ClusterFabricSessionCatalogInfo& info,
                                                            ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.cluster_fabric_session_id) || isZeroUuidLocal(info.cluster_fabric_link_id) ||
        isZeroUuidLocal(info.session_id) || isZeroUuidLocal(info.effective_user_id) ||
        isZeroUuidLocal(info.effective_schema_id) || !isValidFabricSessionState(info.session_state) ||
        info.opened_time == 0)
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.has_effective_role_id && isZeroUuidLocal(info.effective_role_id))
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.has_effective_group_id && isZeroUuidLocal(info.effective_group_id))
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.has_search_path_profile_id && isZeroUuidLocal(info.search_path_profile_id))
    {
        return Status::INVALID_ARGUMENT;
    }
    if (isTerminalFabricSessionState(info.session_state) && !info.has_closed_time)
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.has_closed_time && info.closed_time < info.opened_time)
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.has_last_activity_time && info.last_activity_time < info.opened_time)
    {
        return Status::INVALID_ARGUMENT;
    }

    auto link_predicate = [&info](const ClusterFabricLinkRecord& rec) {
        return rec.cluster_fabric_link_id == info.cluster_fabric_link_id && rec.is_valid == 1;
    };
    if (findRecordInHeapPage<ClusterFabricLinkRecord>(cluster_fabric_link_table_page_, link_predicate, ctx).status !=
        Status::OK)
    {
        return Status::NOT_FOUND;
    }
    auto user_predicate = [&info](const UserRecord& rec) {
        return rec.user_id == info.effective_user_id && rec.is_valid == 1;
    };
    if (findRecordInHeapPage<UserRecord>(users_table_page_, user_predicate, ctx).status != Status::OK)
    {
        return Status::NOT_FOUND;
    }
    auto schema_predicate = [&info](const SchemaRecord& rec) {
        return rec.schema_id == info.effective_schema_id && rec.is_valid == 1;
    };
    if (findRecordInHeapPage<SchemaRecord>(schemas_table_page_, schema_predicate, ctx).status != Status::OK)
    {
        return Status::NOT_FOUND;
    }
    if (info.has_effective_role_id)
    {
        auto role_predicate = [&info](const RoleRecord& rec) {
            return rec.role_id == info.effective_role_id && rec.is_valid == 1;
        };
        if (findRecordInHeapPage<RoleRecord>(roles_table_page_, role_predicate, ctx).status != Status::OK)
        {
            return Status::NOT_FOUND;
        }
    }
    if (info.has_effective_group_id)
    {
        auto group_predicate = [&info](const GroupRecord& rec) {
            return rec.group_id == info.effective_group_id && rec.is_valid == 1;
        };
        if (findRecordInHeapPage<GroupRecord>(groups_table_page_, group_predicate, ctx).status != Status::OK)
        {
            return Status::NOT_FOUND;
        }
    }
    if (info.has_search_path_profile_id)
    {
        auto profile_predicate = [&info](const SearchPathProfileRecord& rec) {
            return rec.profile_id == info.search_path_profile_id && rec.is_valid == 1;
        };
        if (findRecordInHeapPage<SearchPathProfileRecord>(
                search_path_profiles_table_page_, profile_predicate, ctx)
                .status != Status::OK)
        {
            return Status::NOT_FOUND;
        }
    }

    auto duplicate_predicate = [&info](const ClusterFabricSessionRecord& row) {
        return row.is_valid == 1 &&
               row.cluster_fabric_session_id != info.cluster_fabric_session_id &&
               row.cluster_fabric_link_id == info.cluster_fabric_link_id &&
               row.session_id == info.session_id;
    };
    auto duplicate = findRecordInHeapPage<ClusterFabricSessionRecord>(
        cluster_fabric_session_table_page_, duplicate_predicate, ctx);
    if (duplicate.status == Status::OK)
    {
        return Status::CONSTRAINT_VIOLATION;
    }
    if (duplicate.status != Status::NOT_FOUND)
    {
        return duplicate.status;
    }

    ClusterFabricSessionRecord rec{};
    rec.cluster_fabric_session_id = info.cluster_fabric_session_id;
    rec.cluster_fabric_link_id = info.cluster_fabric_link_id;
    rec.session_id = info.session_id;
    rec.effective_user_id = info.effective_user_id;
    rec.has_effective_role_id = info.has_effective_role_id ? 1 : 0;
    rec.has_effective_group_id = info.has_effective_group_id ? 1 : 0;
    rec.has_search_path_profile_id = info.has_search_path_profile_id ? 1 : 0;
    rec.session_state = static_cast<uint8_t>(info.session_state);
    rec.has_closed_time = info.has_closed_time ? 1 : 0;
    rec.has_last_activity_time = info.has_last_activity_time ? 1 : 0;
    rec.is_valid = info.is_valid ? 1 : 0;
    rec.effective_role_id = info.has_effective_role_id ? info.effective_role_id : ID{};
    rec.effective_group_id = info.has_effective_group_id ? info.effective_group_id : ID{};
    rec.effective_schema_id = info.effective_schema_id;
    rec.search_path_profile_id = info.has_search_path_profile_id ? info.search_path_profile_id : ID{};
    rec.opened_time = info.opened_time;
    rec.closed_time = info.has_closed_time ? info.closed_time : 0;
    rec.last_activity_time = info.has_last_activity_time ? info.last_activity_time : 0;

    auto matcher = [&info](const ClusterFabricSessionRecord& row) {
        return row.cluster_fabric_session_id == info.cluster_fabric_session_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(cluster_fabric_session_table_page_, matcher, rec, ctx);
}

auto CatalogManager::getClusterFabricSessionCatalogEntry(const ID& cluster_fabric_session_id,
                                                         ClusterFabricSessionCatalogInfo& info_out,
                                                         ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    auto predicate = [&cluster_fabric_session_id](const ClusterFabricSessionRecord& rec) {
        return rec.cluster_fabric_session_id == cluster_fabric_session_id && rec.is_valid == 1;
    };
    auto result = findRecordInHeapPage<ClusterFabricSessionRecord>(cluster_fabric_session_table_page_, predicate, ctx);
    if (result.status != Status::OK)
    {
        return Status::NOT_FOUND;
    }
    const FabricSessionState state = static_cast<FabricSessionState>(result.record.session_state);
    if (!isValidFabricSessionState(state) ||
        (isTerminalFabricSessionState(state) && result.record.has_closed_time == 0) ||
        (result.record.has_closed_time != 0 && result.record.closed_time < result.record.opened_time) ||
        (result.record.has_last_activity_time != 0 &&
         result.record.last_activity_time < result.record.opened_time))
    {
        return Status::PAGE_CORRUPT;
    }

    info_out = ClusterFabricSessionCatalogInfo{};
    info_out.cluster_fabric_session_id = result.record.cluster_fabric_session_id;
    info_out.cluster_fabric_link_id = result.record.cluster_fabric_link_id;
    info_out.session_id = result.record.session_id;
    info_out.effective_user_id = result.record.effective_user_id;
    info_out.has_effective_role_id = result.record.has_effective_role_id != 0;
    info_out.effective_role_id = result.record.effective_role_id;
    info_out.has_effective_group_id = result.record.has_effective_group_id != 0;
    info_out.effective_group_id = result.record.effective_group_id;
    info_out.effective_schema_id = result.record.effective_schema_id;
    info_out.has_search_path_profile_id = result.record.has_search_path_profile_id != 0;
    info_out.search_path_profile_id = result.record.search_path_profile_id;
    info_out.session_state = state;
    info_out.opened_time = result.record.opened_time;
    info_out.has_closed_time = result.record.has_closed_time != 0;
    info_out.closed_time = result.record.closed_time;
    info_out.has_last_activity_time = result.record.has_last_activity_time != 0;
    info_out.last_activity_time = result.record.last_activity_time;
    info_out.is_valid = result.record.is_valid == 1;
    return Status::OK;
}

