auto CatalogManager::upsertClusterFabricTxnCatalogEntry(const ClusterFabricTxnCatalogInfo& info,
                                                        ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.cluster_fabric_txn_id) || isZeroUuidLocal(info.cluster_fabric_session_id) ||
        isZeroUuidLocal(info.transaction_id) || !isValidFabricTxnState(info.txn_state) ||
        info.begin_time == 0)
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.has_last_error_id && isZeroUuidLocal(info.last_error_id))
    {
        return Status::INVALID_ARGUMENT;
    }
    if (isTerminalFabricTxnState(info.txn_state) && !info.has_terminal_time)
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.has_terminal_time && info.terminal_time < info.begin_time)
    {
        return Status::INVALID_ARGUMENT;
    }

    auto session_predicate = [&info](const ClusterFabricSessionRecord& rec) {
        return rec.cluster_fabric_session_id == info.cluster_fabric_session_id && rec.is_valid == 1;
    };
    if (findRecordInHeapPage<ClusterFabricSessionRecord>(
            cluster_fabric_session_table_page_, session_predicate, ctx)
            .status != Status::OK)
    {
        return Status::NOT_FOUND;
    }
    if (info.has_last_error_id)
    {
        auto error_predicate = [&info](const ClusterFabricErrorRecord& rec) {
            return rec.cluster_fabric_error_id == info.last_error_id && rec.is_valid == 1;
        };
        if (findRecordInHeapPage<ClusterFabricErrorRecord>(cluster_fabric_error_table_page_, error_predicate, ctx)
                .status != Status::OK)
        {
            return Status::NOT_FOUND;
        }
    }

    auto duplicate_predicate = [&info](const ClusterFabricTxnRecord& row) {
        return row.is_valid == 1 &&
               row.cluster_fabric_txn_id != info.cluster_fabric_txn_id &&
               row.cluster_fabric_session_id == info.cluster_fabric_session_id &&
               row.transaction_id == info.transaction_id;
    };
    auto duplicate = findRecordInHeapPage<ClusterFabricTxnRecord>(
        cluster_fabric_txn_table_page_, duplicate_predicate, ctx);
    if (duplicate.status == Status::OK)
    {
        return Status::CONSTRAINT_VIOLATION;
    }
    if (duplicate.status != Status::NOT_FOUND)
    {
        return duplicate.status;
    }

    ClusterFabricTxnRecord rec{};
    rec.cluster_fabric_txn_id = info.cluster_fabric_txn_id;
    rec.cluster_fabric_session_id = info.cluster_fabric_session_id;
    rec.transaction_id = info.transaction_id;
    rec.txn_state = static_cast<uint8_t>(info.txn_state);
    rec.has_terminal_time = info.has_terminal_time ? 1 : 0;
    rec.has_last_error_id = info.has_last_error_id ? 1 : 0;
    rec.is_valid = info.is_valid ? 1 : 0;
    rec.begin_time = info.begin_time;
    rec.terminal_time = info.has_terminal_time ? info.terminal_time : 0;
    rec.last_error_id = info.has_last_error_id ? info.last_error_id : ID{};

    auto matcher = [&info](const ClusterFabricTxnRecord& row) {
        return row.cluster_fabric_txn_id == info.cluster_fabric_txn_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(cluster_fabric_txn_table_page_, matcher, rec, ctx);
}

