auto CatalogManager::upsertClusterFabricTaskChunkCatalogEntry(const ClusterFabricTaskChunkCatalogInfo& info,
                                                              ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.cluster_fabric_task_chunk_id) || isZeroUuidLocal(info.cluster_fabric_task_id) ||
        info.chunk_total == 0 || info.chunk_seq >= info.chunk_total || info.sent_time == 0)
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.has_acked_time && info.acked_time < info.sent_time)
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.is_final_chunk && (info.chunk_seq + 1 != info.chunk_total))
    {
        return Status::INVALID_ARGUMENT;
    }

    auto task_predicate = [&info](const ClusterFabricTaskRecord& rec) {
        return rec.cluster_fabric_task_id == info.cluster_fabric_task_id && rec.is_valid == 1;
    };
    if (findRecordInHeapPage<ClusterFabricTaskRecord>(cluster_fabric_task_table_page_, task_predicate, ctx).status !=
        Status::OK)
    {
        return Status::NOT_FOUND;
    }

    auto duplicate_predicate = [&info](const ClusterFabricTaskChunkRecord& row) {
        return row.is_valid == 1 &&
               row.cluster_fabric_task_chunk_id != info.cluster_fabric_task_chunk_id &&
               row.cluster_fabric_task_id == info.cluster_fabric_task_id &&
               row.chunk_seq == info.chunk_seq;
    };
    auto duplicate = findRecordInHeapPage<ClusterFabricTaskChunkRecord>(
        cluster_fabric_task_chunk_table_page_, duplicate_predicate, ctx);
    if (duplicate.status == Status::OK)
    {
        return Status::CONSTRAINT_VIOLATION;
    }
    if (duplicate.status != Status::NOT_FOUND)
    {
        return duplicate.status;
    }

    ClusterFabricTaskChunkRecord rec{};
    rec.cluster_fabric_task_chunk_id = info.cluster_fabric_task_chunk_id;
    rec.cluster_fabric_task_id = info.cluster_fabric_task_id;
    rec.chunk_seq = info.chunk_seq;
    rec.chunk_total = info.chunk_total;
    rec.chunk_bytes = info.chunk_bytes;
    rec.chunk_checksum = info.chunk_checksum;
    rec.is_final_chunk = info.is_final_chunk ? 1 : 0;
    rec.has_acked_time = info.has_acked_time ? 1 : 0;
    rec.is_valid = info.is_valid ? 1 : 0;
    rec.sent_time = info.sent_time;
    rec.acked_time = info.has_acked_time ? info.acked_time : 0;

    auto matcher = [&info](const ClusterFabricTaskChunkRecord& row) {
        return row.cluster_fabric_task_chunk_id == info.cluster_fabric_task_chunk_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(cluster_fabric_task_chunk_table_page_, matcher, rec, ctx);
}

