auto CatalogManager::upsertClusterFabricErrorCatalogEntry(const ClusterFabricErrorCatalogInfo& info,
                                                          ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.cluster_fabric_error_id) || isZeroUuidLocal(info.cluster_fabric_link_id) ||
        !isValidFabricErrorClass(info.error_class) || info.source_component.empty() ||
        info.source_code.empty() || info.message_text.empty() || info.occurrence_count == 0)
    {
        return Status::INVALID_ARGUMENT;
    }

    auto link_predicate = [&info](const ClusterFabricLinkRecord& rec) {
        return rec.cluster_fabric_link_id == info.cluster_fabric_link_id && rec.is_valid == 1;
    };
    if (findRecordInHeapPage<ClusterFabricLinkRecord>(cluster_fabric_link_table_page_, link_predicate, ctx).status !=
        Status::OK)
    {
        return Status::NOT_FOUND;
    }

    const uint64_t now = catalogNowTicks();
    const uint64_t first_seen = (info.first_seen_time == 0) ? now : info.first_seen_time;
    const uint64_t last_seen = (info.last_seen_time == 0) ? first_seen : info.last_seen_time;
    if (last_seen < first_seen)
    {
        return Status::INVALID_ARGUMENT;
    }

    ClusterFabricErrorRecord rec{};
    rec.cluster_fabric_error_id = info.cluster_fabric_error_id;
    rec.cluster_fabric_link_id = info.cluster_fabric_link_id;
    rec.error_class = static_cast<uint8_t>(info.error_class);
    rec.recoverable = info.recoverable ? 1 : 0;
    rec.is_open = info.is_open ? 1 : 0;
    rec.is_valid = info.is_valid ? 1 : 0;
    std::strncpy(rec.source_component,
                 UTF8Utils::truncateToBytes(info.source_component, sizeof(rec.source_component)).c_str(),
                 sizeof(rec.source_component) - 1);
    std::strncpy(rec.source_code,
                 UTF8Utils::truncateToBytes(info.source_code, sizeof(rec.source_code)).c_str(),
                 sizeof(rec.source_code) - 1);
    rec.first_seen_time = first_seen;
    rec.last_seen_time = last_seen;
    rec.occurrence_count = info.occurrence_count;

    uint64_t xmin = 0;
    const std::string sanitized_message_text = redactSensitiveDiagnosticText(info.message_text);
    Status status = storeStringInToast(sanitized_message_text, xmin, rec.message_text_oid, ctx);
    if (status != Status::OK)
    {
        return status;
    }

    auto existing_predicate = [&info](const ClusterFabricErrorRecord& row) {
        return row.cluster_fabric_error_id == info.cluster_fabric_error_id && row.is_valid == 1;
    };
    auto existing = findRecordInHeapPage<ClusterFabricErrorRecord>(
        cluster_fabric_error_table_page_, existing_predicate, ctx);
    if (existing.status == Status::OK)
    {
        rec.first_seen_time = existing.record.first_seen_time;
    }
    else if (existing.status != Status::NOT_FOUND)
    {
        return existing.status;
    }

    auto matcher = [&info](const ClusterFabricErrorRecord& row) {
        return row.cluster_fabric_error_id == info.cluster_fabric_error_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(cluster_fabric_error_table_page_, matcher, rec, ctx);
}

auto CatalogManager::getClusterFabricErrorCatalogEntry(const ID& cluster_fabric_error_id,
                                                       ClusterFabricErrorCatalogInfo& info_out,
                                                       ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    auto predicate = [&cluster_fabric_error_id](const ClusterFabricErrorRecord& rec) {
        return rec.cluster_fabric_error_id == cluster_fabric_error_id && rec.is_valid == 1;
    };
    auto result = findRecordInHeapPage<ClusterFabricErrorRecord>(cluster_fabric_error_table_page_, predicate, ctx);
    if (result.status != Status::OK)
    {
        return Status::NOT_FOUND;
    }
    if (!isValidFabricErrorClass(static_cast<FabricErrorClass>(result.record.error_class)) ||
        result.record.occurrence_count == 0 ||
        result.record.last_seen_time < result.record.first_seen_time)
    {
        return Status::PAGE_CORRUPT;
    }

    info_out = ClusterFabricErrorCatalogInfo{};
    info_out.cluster_fabric_error_id = result.record.cluster_fabric_error_id;
    info_out.cluster_fabric_link_id = result.record.cluster_fabric_link_id;
    info_out.error_class = static_cast<FabricErrorClass>(result.record.error_class);
    info_out.source_component =
        fixedNameFromBuffer(result.record.source_component, sizeof(result.record.source_component));
    info_out.source_code = fixedNameFromBuffer(result.record.source_code, sizeof(result.record.source_code));
    info_out.recoverable = result.record.recoverable != 0;
    info_out.first_seen_time = result.record.first_seen_time;
    info_out.last_seen_time = result.record.last_seen_time;
    info_out.occurrence_count = result.record.occurrence_count;
    info_out.is_open = result.record.is_open != 0;
    info_out.is_valid = result.record.is_valid == 1;
    uint64_t xmin = 0;
    return loadStringFromToast(result.record.message_text_oid, xmin, info_out.message_text, ctx);
}

auto CatalogManager::listClusterFabricErrorCatalogEntries(
    const ID& cluster_fabric_link_id,
    std::vector<ClusterFabricErrorCatalogInfo>& rows_out,
    ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    rows_out.clear();
    auto filter = [&cluster_fabric_link_id](const ClusterFabricErrorRecord& rec) {
        return rec.is_valid == 1 &&
               (isZeroUuidLocal(cluster_fabric_link_id) || rec.cluster_fabric_link_id == cluster_fabric_link_id);
    };
    auto converter = [this, ctx](const ClusterFabricErrorRecord& rec, ClusterFabricErrorCatalogInfo& info) {
        info = ClusterFabricErrorCatalogInfo{};
        info.cluster_fabric_error_id = rec.cluster_fabric_error_id;
        info.cluster_fabric_link_id = rec.cluster_fabric_link_id;
        info.error_class = static_cast<FabricErrorClass>(rec.error_class);
        info.source_component = fixedNameFromBuffer(rec.source_component, sizeof(rec.source_component));
        info.source_code = fixedNameFromBuffer(rec.source_code, sizeof(rec.source_code));
        info.recoverable = rec.recoverable != 0;
        info.first_seen_time = rec.first_seen_time;
        info.last_seen_time = rec.last_seen_time;
        info.occurrence_count = rec.occurrence_count;
        info.is_open = rec.is_open != 0;
        info.is_valid = rec.is_valid == 1;
        uint64_t xmin = 0;
        std::string msg;
        if (loadStringFromToast(rec.message_text_oid, xmin, msg, ctx) == Status::OK)
        {
            info.message_text = std::move(msg);
        }
    };
    Status status = readRecordsToVector<ClusterFabricErrorRecord, ClusterFabricErrorCatalogInfo>(
        cluster_fabric_error_table_page_, rows_out, filter, converter, ctx);
    if (status != Status::OK)
    {
        return status;
    }
    for (const auto& row : rows_out)
    {
        if (!isValidFabricErrorClass(row.error_class) ||
            row.occurrence_count == 0 ||
            row.last_seen_time < row.first_seen_time)
        {
            return Status::PAGE_CORRUPT;
        }
    }
    return Status::OK;
}

