auto CatalogManager::upsertOlapWatermarkCatalogEntry(const OlapWatermarkCatalogInfo& info,
                                                     ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.watermark_id) || isZeroUuidLocal(info.table_id))
    {
        return Status::INVALID_ARGUMENT;
    }
    auto table_predicate = [&info](const TableRecord& rec) {
        return rec.table_id == info.table_id && rec.is_valid == 1;
    };
    if (findRecordInHeapPage<TableRecord>(tables_table_page_, table_predicate, ctx).status != Status::OK)
    {
        return Status::NOT_FOUND;
    }

    auto duplicate_predicate = [&info](const OlapWatermarkRecord& rec) {
        return rec.is_valid == 1 && rec.watermark_id != info.watermark_id && rec.table_id == info.table_id;
    };
    auto duplicate =
        findRecordInHeapPage<OlapWatermarkRecord>(olap_watermark_table_page_, duplicate_predicate, ctx);
    if (duplicate.status == Status::OK)
    {
        return Status::CONSTRAINT_VIOLATION;
    }
    if (duplicate.status != Status::NOT_FOUND)
    {
        return duplicate.status;
    }

    OlapWatermarkRecord rec{};
    rec.watermark_id = info.watermark_id;
    rec.table_id = info.table_id;
    rec.last_ingested_txid = info.last_ingested_txid;
    rec.last_ingested_time = info.last_ingested_time;
    rec.is_valid = info.is_valid ? 1 : 0;

    auto matcher = [&info](const OlapWatermarkRecord& row) {
        return row.watermark_id == info.watermark_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(olap_watermark_table_page_, matcher, rec, ctx);
}

