auto CatalogManager::upsertOlapSegmentCatalogEntry(const OlapSegmentCatalogInfo& info,
                                                   ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.segment_id) || isZeroUuidLocal(info.partition_id))
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.has_min_key_bytes && info.min_key_bytes.empty())
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.has_max_key_bytes && info.max_key_bytes.empty())
    {
        return Status::INVALID_ARGUMENT;
    }

    auto partition_predicate = [&info](const OlapPartitionRecord& rec) {
        return rec.partition_id == info.partition_id && rec.is_valid == 1;
    };
    if (findRecordInHeapPage<OlapPartitionRecord>(olap_partition_table_page_, partition_predicate, ctx).status !=
        Status::OK)
    {
        return Status::NOT_FOUND;
    }

    auto duplicate_predicate = [&info](const OlapSegmentRecord& rec) {
        return rec.is_valid == 1 && rec.segment_id != info.segment_id &&
               rec.partition_id == info.partition_id && rec.segment_index == info.segment_index;
    };
    auto duplicate = findRecordInHeapPage<OlapSegmentRecord>(olap_segment_table_page_, duplicate_predicate, ctx);
    if (duplicate.status == Status::OK)
    {
        return Status::CONSTRAINT_VIOLATION;
    }
    if (duplicate.status != Status::NOT_FOUND)
    {
        return duplicate.status;
    }

    const uint64_t now = catalogNowTicks();
    OlapSegmentRecord rec{};
    rec.segment_id = info.segment_id;
    rec.partition_id = info.partition_id;
    rec.segment_index = info.segment_index;
    rec.has_min_key_oid = info.has_min_key_bytes ? 1 : 0;
    rec.has_max_key_oid = info.has_max_key_bytes ? 1 : 0;
    rec.is_valid = info.is_valid ? 1 : 0;
    rec.row_count = info.row_count;
    rec.size_bytes = info.size_bytes;
    rec.created_time = (info.created_time == 0) ? now : info.created_time;

    uint64_t xmin = 0;
    if (info.has_min_key_bytes)
    {
        Status status = storeStringInToast(info.min_key_bytes, xmin, rec.min_key_oid, ctx);
        if (status != Status::OK)
        {
            return status;
        }
    }
    if (info.has_max_key_bytes)
    {
        Status status = storeStringInToast(info.max_key_bytes, xmin, rec.max_key_oid, ctx);
        if (status != Status::OK)
        {
            return status;
        }
    }

    auto existing_predicate = [&info](const OlapSegmentRecord& row) {
        return row.segment_id == info.segment_id && row.is_valid == 1;
    };
    auto existing = findRecordInHeapPage<OlapSegmentRecord>(olap_segment_table_page_, existing_predicate, ctx);
    if (existing.status == Status::OK)
    {
        rec.created_time = existing.record.created_time;
    }
    else if (existing.status != Status::NOT_FOUND)
    {
        return existing.status;
    }

    auto matcher = [&info](const OlapSegmentRecord& row) {
        return row.segment_id == info.segment_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(olap_segment_table_page_, matcher, rec, ctx);
}

