auto CatalogManager::upsertOlapIngestLogCatalogEntry(const OlapIngestLogCatalogInfo& info,
                                                     ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.batch_id) || isZeroUuidLocal(info.table_id) ||
        info.min_txid == 0 || info.max_txid < info.min_txid || !isValidOlapIngestState(info.ingest_state))
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.has_completed_time && info.completed_time < info.created_time && info.created_time != 0)
    {
        return Status::INVALID_ARGUMENT;
    }

    auto table_predicate = [&info](const TableRecord& rec) {
        return rec.table_id == info.table_id && rec.is_valid == 1;
    };
    if (findRecordInHeapPage<TableRecord>(tables_table_page_, table_predicate, ctx).status != Status::OK)
    {
        return Status::NOT_FOUND;
    }

    auto duplicate_predicate = [&info](const OlapIngestLogRecord& rec) {
        return rec.is_valid == 1 && rec.batch_id != info.batch_id && rec.table_id == info.table_id &&
               rec.min_txid == info.min_txid && rec.max_txid == info.max_txid;
    };
    auto duplicate = findRecordInHeapPage<OlapIngestLogRecord>(olap_ingest_log_table_page_, duplicate_predicate, ctx);
    if (duplicate.status == Status::OK)
    {
        return Status::CONSTRAINT_VIOLATION;
    }
    if (duplicate.status != Status::NOT_FOUND)
    {
        return duplicate.status;
    }

    const uint64_t now = catalogNowTicks();
    OlapIngestLogRecord rec{};
    rec.batch_id = info.batch_id;
    rec.table_id = info.table_id;
    rec.min_txid = info.min_txid;
    rec.max_txid = info.max_txid;
    rec.row_count = info.row_count;
    rec.size_bytes = info.size_bytes;
    rec.ingest_state = static_cast<uint8_t>(info.ingest_state);
    rec.has_completed_time = info.has_completed_time ? 1 : 0;
    rec.is_valid = info.is_valid ? 1 : 0;
    rec.created_time = (info.created_time == 0) ? now : info.created_time;
    rec.completed_time = info.has_completed_time ? info.completed_time : 0;

    auto existing_predicate = [&info](const OlapIngestLogRecord& row) {
        return row.batch_id == info.batch_id && row.is_valid == 1;
    };
    auto existing = findRecordInHeapPage<OlapIngestLogRecord>(olap_ingest_log_table_page_, existing_predicate, ctx);
    if (existing.status == Status::OK)
    {
        rec.created_time = existing.record.created_time;
    }
    else if (existing.status != Status::NOT_FOUND)
    {
        return existing.status;
    }

    auto matcher = [&info](const OlapIngestLogRecord& row) {
        return row.batch_id == info.batch_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(olap_ingest_log_table_page_, matcher, rec, ctx);
}

auto CatalogManager::getOlapIngestLogCatalogEntry(const ID& batch_id,
                                                  OlapIngestLogCatalogInfo& info_out,
                                                  ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    auto predicate = [&batch_id](const OlapIngestLogRecord& rec) {
        return rec.batch_id == batch_id && rec.is_valid == 1;
    };
    auto result = findRecordInHeapPage<OlapIngestLogRecord>(olap_ingest_log_table_page_, predicate, ctx);
    if (result.status != Status::OK)
    {
        return Status::NOT_FOUND;
    }
    const OlapIngestState ingest_state = static_cast<OlapIngestState>(result.record.ingest_state);
    if (!isValidOlapIngestState(ingest_state) ||
        result.record.max_txid < result.record.min_txid ||
        (result.record.has_completed_time != 0 && result.record.completed_time < result.record.created_time))
    {
        return Status::PAGE_CORRUPT;
    }

    info_out = OlapIngestLogCatalogInfo{};
    info_out.batch_id = result.record.batch_id;
    info_out.table_id = result.record.table_id;
    info_out.min_txid = result.record.min_txid;
    info_out.max_txid = result.record.max_txid;
    info_out.row_count = result.record.row_count;
    info_out.size_bytes = result.record.size_bytes;
    info_out.ingest_state = ingest_state;
    info_out.created_time = result.record.created_time;
    info_out.has_completed_time = result.record.has_completed_time != 0;
    info_out.completed_time = result.record.completed_time;
    info_out.is_valid = result.record.is_valid == 1;
    return Status::OK;
}

auto CatalogManager::listOlapIngestLogCatalogEntries(const ID& table_id,
                                                     std::vector<OlapIngestLogCatalogInfo>& rows_out,
                                                     ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    rows_out.clear();
    auto filter = [&table_id](const OlapIngestLogRecord& rec) {
        return rec.is_valid == 1 && (isZeroUuidLocal(table_id) || rec.table_id == table_id);
    };
    auto converter = [](const OlapIngestLogRecord& rec, OlapIngestLogCatalogInfo& info) {
        info = OlapIngestLogCatalogInfo{};
        info.batch_id = rec.batch_id;
        info.table_id = rec.table_id;
        info.min_txid = rec.min_txid;
        info.max_txid = rec.max_txid;
        info.row_count = rec.row_count;
        info.size_bytes = rec.size_bytes;
        info.ingest_state = static_cast<OlapIngestState>(rec.ingest_state);
        info.created_time = rec.created_time;
        info.has_completed_time = rec.has_completed_time != 0;
        info.completed_time = rec.completed_time;
        info.is_valid = rec.is_valid == 1;
    };
    Status status = readRecordsToVector<OlapIngestLogRecord, OlapIngestLogCatalogInfo>(
        olap_ingest_log_table_page_, rows_out, filter, converter, ctx);
    if (status != Status::OK)
    {
        return status;
    }
    for (const auto& row : rows_out)
    {
        if (!isValidOlapIngestState(row.ingest_state) || row.max_txid < row.min_txid ||
            (row.has_completed_time && row.completed_time < row.created_time))
        {
            return Status::PAGE_CORRUPT;
        }
    }
    return Status::OK;
}

