auto CatalogManager::upsertCubeCatalogEntry(const CubeCatalogInfo& info,
                                            ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.cube_id) || isZeroUuidLocal(info.schema_id) || info.cube_name.empty() ||
        isZeroUuidLocal(info.base_table_id) || isZeroUuidLocal(info.owner_id) || !isValidCubeStatus(info.status))
    {
        return Status::INVALID_ARGUMENT;
    }

    auto schema_predicate = [&info](const SchemaRecord& rec) {
        return rec.schema_id == info.schema_id && rec.is_valid == 1;
    };
    if (findRecordInHeapPage<SchemaRecord>(schemas_table_page_, schema_predicate, ctx).status != Status::OK)
    {
        return Status::NOT_FOUND;
    }
    auto table_predicate = [&info](const TableRecord& rec) {
        return rec.table_id == info.base_table_id && rec.is_valid == 1;
    };
    if (findRecordInHeapPage<TableRecord>(tables_table_page_, table_predicate, ctx).status != Status::OK)
    {
        return Status::NOT_FOUND;
    }
    auto owner_predicate = [&info](const UserRecord& rec) {
        return rec.user_id == info.owner_id && rec.is_valid == 1;
    };
    if (findRecordInHeapPage<UserRecord>(users_table_page_, owner_predicate, ctx).status != Status::OK)
    {
        return Status::NOT_FOUND;
    }

    const std::string folded_name = canonicalIdentifierForLookup(info.cube_name);
    auto duplicate_predicate = [&info, &folded_name](const CubeRecord& rec) {
        return rec.is_valid == 1 && rec.cube_id != info.cube_id && rec.schema_id == info.schema_id &&
               canonicalIdentifierForLookup(fixedNameFromBuffer(rec.cube_name, sizeof(rec.cube_name))) ==
                   folded_name;
    };
    auto duplicate = findRecordInHeapPage<CubeRecord>(cube_table_page_, duplicate_predicate, ctx);
    if (duplicate.status == Status::OK)
    {
        return Status::CONSTRAINT_VIOLATION;
    }
    if (duplicate.status != Status::NOT_FOUND)
    {
        return duplicate.status;
    }

    const uint64_t now = catalogNowTicks();
    CubeRecord rec{};
    rec.cube_id = info.cube_id;
    rec.schema_id = info.schema_id;
    std::strncpy(rec.cube_name, UTF8Utils::truncateToBytes(info.cube_name, sizeof(rec.cube_name)).c_str(),
                 sizeof(rec.cube_name) - 1);
    rec.base_table_id = info.base_table_id;
    rec.status = static_cast<uint8_t>(info.status);
    rec.is_valid = info.is_valid ? 1 : 0;
    rec.owner_id = info.owner_id;
    rec.created_time = (info.created_time == 0) ? now : info.created_time;
    rec.last_modified_time = (info.last_modified_time == 0) ? now : info.last_modified_time;

    auto existing_predicate = [&info](const CubeRecord& row) {
        return row.cube_id == info.cube_id && row.is_valid == 1;
    };
    auto existing = findRecordInHeapPage<CubeRecord>(cube_table_page_, existing_predicate, ctx);
    if (existing.status == Status::OK)
    {
        rec.created_time = existing.record.created_time;
    }
    else if (existing.status != Status::NOT_FOUND)
    {
        return existing.status;
    }

    auto matcher = [&info](const CubeRecord& row) {
        return row.cube_id == info.cube_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(cube_table_page_, matcher, rec, ctx);
}

auto CatalogManager::getCubeCatalogEntry(const ID& cube_id,
                                         CubeCatalogInfo& info_out,
                                         ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    auto predicate = [&cube_id](const CubeRecord& rec) {
        return rec.cube_id == cube_id && rec.is_valid == 1;
    };
    auto result = findRecordInHeapPage<CubeRecord>(cube_table_page_, predicate, ctx);
    if (result.status != Status::OK)
    {
        return Status::NOT_FOUND;
    }
    const CubeStatus status = static_cast<CubeStatus>(result.record.status);
    if (!isValidCubeStatus(status))
    {
        return Status::PAGE_CORRUPT;
    }

    info_out = CubeCatalogInfo{};
    info_out.cube_id = result.record.cube_id;
    info_out.schema_id = result.record.schema_id;
    info_out.cube_name = fixedNameFromBuffer(result.record.cube_name, sizeof(result.record.cube_name));
    info_out.base_table_id = result.record.base_table_id;
    info_out.status = status;
    info_out.owner_id = result.record.owner_id;
    info_out.created_time = result.record.created_time;
    info_out.last_modified_time = result.record.last_modified_time;
    info_out.is_valid = result.record.is_valid == 1;
    return Status::OK;
}

