auto CatalogManager::upsertCubeDimensionCatalogEntry(const CubeDimensionCatalogInfo& info,
                                                     ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.dimension_id) || isZeroUuidLocal(info.cube_id) || info.dimension_name.empty() ||
        isZeroUuidLocal(info.data_type_id) || !isValidCubeSourceKind(info.source_kind))
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.has_source_column_id == info.has_source_expr_sblr_id)
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.has_source_column_id && isZeroUuidLocal(info.source_column_id))
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.has_source_expr_sblr_id && isZeroUuidLocal(info.source_expr_sblr_id))
    {
        return Status::INVALID_ARGUMENT;
    }

    auto cube_predicate = [&info](const CubeRecord& rec) {
        return rec.cube_id == info.cube_id && rec.is_valid == 1;
    };
    if (findRecordInHeapPage<CubeRecord>(cube_table_page_, cube_predicate, ctx).status != Status::OK)
    {
        return Status::NOT_FOUND;
    }
    if (info.has_source_column_id)
    {
        auto column_predicate = [&info](const ColumnRecord& rec) {
            return rec.column_id == info.source_column_id && rec.is_valid == 1;
        };
        if (findRecordInHeapPage<ColumnRecord>(columns_table_page_, column_predicate, ctx).status != Status::OK)
        {
            return Status::NOT_FOUND;
        }
    }

    const uint64_t now = catalogNowTicks();
    CubeDimensionRecord rec{};
    rec.dimension_id = info.dimension_id;
    rec.cube_id = info.cube_id;
    std::strncpy(rec.dimension_name,
                 UTF8Utils::truncateToBytes(info.dimension_name, sizeof(rec.dimension_name)).c_str(),
                 sizeof(rec.dimension_name) - 1);
    rec.source_kind = static_cast<uint8_t>(info.source_kind);
    rec.has_source_column_id = info.has_source_column_id ? 1 : 0;
    rec.has_source_expr_sblr_id = info.has_source_expr_sblr_id ? 1 : 0;
    rec.is_time_dimension = info.is_time_dimension ? 1 : 0;
    rec.is_valid = info.is_valid ? 1 : 0;
    rec.source_column_id = info.has_source_column_id ? info.source_column_id : ID{};
    rec.source_expr_sblr_id = info.has_source_expr_sblr_id ? info.source_expr_sblr_id : ID{};
    rec.data_type_id = info.data_type_id;
    rec.created_time = (info.created_time == 0) ? now : info.created_time;
    rec.last_modified_time = (info.last_modified_time == 0) ? now : info.last_modified_time;

    auto existing_predicate = [&info](const CubeDimensionRecord& row) {
        return row.dimension_id == info.dimension_id && row.is_valid == 1;
    };
    auto existing =
        findRecordInHeapPage<CubeDimensionRecord>(cube_dimension_table_page_, existing_predicate, ctx);
    if (existing.status == Status::OK)
    {
        rec.created_time = existing.record.created_time;
    }
    else if (existing.status != Status::NOT_FOUND)
    {
        return existing.status;
    }

    auto matcher = [&info](const CubeDimensionRecord& row) {
        return row.dimension_id == info.dimension_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(cube_dimension_table_page_, matcher, rec, ctx);
}

auto CatalogManager::getCubeDimensionCatalogEntry(const ID& dimension_id,
                                                  CubeDimensionCatalogInfo& info_out,
                                                  ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    auto predicate = [&dimension_id](const CubeDimensionRecord& rec) {
        return rec.dimension_id == dimension_id && rec.is_valid == 1;
    };
    auto result = findRecordInHeapPage<CubeDimensionRecord>(cube_dimension_table_page_, predicate, ctx);
    if (result.status != Status::OK)
    {
        return Status::NOT_FOUND;
    }
    const CubeSourceKind source_kind = static_cast<CubeSourceKind>(result.record.source_kind);
    if (!isValidCubeSourceKind(source_kind) ||
        ((result.record.has_source_column_id != 0) == (result.record.has_source_expr_sblr_id != 0)))
    {
        return Status::PAGE_CORRUPT;
    }

    info_out = CubeDimensionCatalogInfo{};
    info_out.dimension_id = result.record.dimension_id;
    info_out.cube_id = result.record.cube_id;
    info_out.dimension_name =
        fixedNameFromBuffer(result.record.dimension_name, sizeof(result.record.dimension_name));
    info_out.source_kind = source_kind;
    info_out.has_source_column_id = result.record.has_source_column_id != 0;
    info_out.source_column_id = result.record.source_column_id;
    info_out.has_source_expr_sblr_id = result.record.has_source_expr_sblr_id != 0;
    info_out.source_expr_sblr_id = result.record.source_expr_sblr_id;
    info_out.data_type_id = result.record.data_type_id;
    info_out.is_time_dimension = result.record.is_time_dimension != 0;
    info_out.created_time = result.record.created_time;
    info_out.last_modified_time = result.record.last_modified_time;
    info_out.is_valid = result.record.is_valid == 1;
    return Status::OK;
}

auto CatalogManager::listCubeDimensionCatalogEntries(const ID& cube_id,
                                                     std::vector<CubeDimensionCatalogInfo>& rows_out,
                                                     ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    rows_out.clear();
    auto filter = [&cube_id](const CubeDimensionRecord& rec) {
        return rec.is_valid == 1 && (isZeroUuidLocal(cube_id) || rec.cube_id == cube_id);
    };
    auto converter = [](const CubeDimensionRecord& rec, CubeDimensionCatalogInfo& info) {
        info = CubeDimensionCatalogInfo{};
        info.dimension_id = rec.dimension_id;
        info.cube_id = rec.cube_id;
        info.dimension_name = fixedNameFromBuffer(rec.dimension_name, sizeof(rec.dimension_name));
        info.source_kind = static_cast<CubeSourceKind>(rec.source_kind);
        info.has_source_column_id = rec.has_source_column_id != 0;
        info.source_column_id = rec.source_column_id;
        info.has_source_expr_sblr_id = rec.has_source_expr_sblr_id != 0;
        info.source_expr_sblr_id = rec.source_expr_sblr_id;
        info.data_type_id = rec.data_type_id;
        info.is_time_dimension = rec.is_time_dimension != 0;
        info.created_time = rec.created_time;
        info.last_modified_time = rec.last_modified_time;
        info.is_valid = rec.is_valid == 1;
    };
    Status status = readRecordsToVector<CubeDimensionRecord, CubeDimensionCatalogInfo>(
        cube_dimension_table_page_, rows_out, filter, converter, ctx);
    if (status != Status::OK)
    {
        return status;
    }
    for (const auto& row : rows_out)
    {
        if (!isValidCubeSourceKind(row.source_kind) ||
            (row.has_source_column_id == row.has_source_expr_sblr_id))
        {
            return Status::PAGE_CORRUPT;
        }
    }
    return Status::OK;
}

