auto CatalogManager::upsertCubeLevelCatalogEntry(const CubeLevelCatalogInfo& info,
                                                 ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.level_id) || isZeroUuidLocal(info.dimension_id) || info.level_name.empty() ||
        isZeroUuidLocal(info.key_expr_sblr_id))
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.has_label_expr_sblr_id && isZeroUuidLocal(info.label_expr_sblr_id))
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.has_sort_expr_sblr_id && isZeroUuidLocal(info.sort_expr_sblr_id))
    {
        return Status::INVALID_ARGUMENT;
    }

    auto dimension_predicate = [&info](const CubeDimensionRecord& rec) {
        return rec.dimension_id == info.dimension_id && rec.is_valid == 1;
    };
    if (findRecordInHeapPage<CubeDimensionRecord>(cube_dimension_table_page_, dimension_predicate, ctx).status !=
        Status::OK)
    {
        return Status::NOT_FOUND;
    }

    const std::string folded_name = canonicalIdentifierForLookup(info.level_name);
    auto duplicate_predicate = [&info, &folded_name](const CubeLevelRecord& rec) {
        return rec.is_valid == 1 && rec.level_id != info.level_id && rec.dimension_id == info.dimension_id &&
               canonicalIdentifierForLookup(fixedNameFromBuffer(rec.level_name, sizeof(rec.level_name))) ==
                   folded_name;
    };
    auto duplicate = findRecordInHeapPage<CubeLevelRecord>(cube_level_table_page_, duplicate_predicate, ctx);
    if (duplicate.status == Status::OK)
    {
        return Status::CONSTRAINT_VIOLATION;
    }
    if (duplicate.status != Status::NOT_FOUND)
    {
        return duplicate.status;
    }

    const uint64_t now = catalogNowTicks();
    CubeLevelRecord rec{};
    rec.level_id = info.level_id;
    rec.dimension_id = info.dimension_id;
    std::strncpy(rec.level_name, UTF8Utils::truncateToBytes(info.level_name, sizeof(rec.level_name)).c_str(),
                 sizeof(rec.level_name) - 1);
    rec.has_label_expr_sblr_id = info.has_label_expr_sblr_id ? 1 : 0;
    rec.has_sort_expr_sblr_id = info.has_sort_expr_sblr_id ? 1 : 0;
    rec.is_valid = info.is_valid ? 1 : 0;
    rec.key_expr_sblr_id = info.key_expr_sblr_id;
    rec.label_expr_sblr_id = info.has_label_expr_sblr_id ? info.label_expr_sblr_id : ID{};
    rec.sort_expr_sblr_id = info.has_sort_expr_sblr_id ? info.sort_expr_sblr_id : ID{};
    rec.level_order = info.level_order;
    rec.created_time = (info.created_time == 0) ? now : info.created_time;
    rec.last_modified_time = (info.last_modified_time == 0) ? now : info.last_modified_time;

    auto existing_predicate = [&info](const CubeLevelRecord& row) {
        return row.level_id == info.level_id && row.is_valid == 1;
    };
    auto existing = findRecordInHeapPage<CubeLevelRecord>(cube_level_table_page_, existing_predicate, ctx);
    if (existing.status == Status::OK)
    {
        rec.created_time = existing.record.created_time;
    }
    else if (existing.status != Status::NOT_FOUND)
    {
        return existing.status;
    }

    auto matcher = [&info](const CubeLevelRecord& row) {
        return row.level_id == info.level_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(cube_level_table_page_, matcher, rec, ctx);
}

