auto CatalogManager::upsertCubeMeasureCatalogEntry(const CubeMeasureCatalogInfo& info,
                                                   ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.measure_id) || isZeroUuidLocal(info.cube_id) || info.measure_name.empty() ||
        isZeroUuidLocal(info.source_expr_sblr_id) || isZeroUuidLocal(info.data_type_id) ||
        !isValidCubeAggFunction(info.agg_function) || !isValidCubeNullHandling(info.null_handling))
    {
        return Status::INVALID_ARGUMENT;
    }
    auto cube_predicate = [&info](const CubeRecord& rec) {
        return rec.cube_id == info.cube_id && rec.is_valid == 1;
    };
    if (findRecordInHeapPage<CubeRecord>(cube_table_page_, cube_predicate, ctx).status != Status::OK)
    {
        return Status::NOT_FOUND;
    }

    const std::string folded_name = canonicalIdentifierForLookup(info.measure_name);
    auto duplicate_predicate = [&info, &folded_name](const CubeMeasureRecord& rec) {
        return rec.is_valid == 1 && rec.measure_id != info.measure_id && rec.cube_id == info.cube_id &&
               canonicalIdentifierForLookup(
                   fixedNameFromBuffer(rec.measure_name, sizeof(rec.measure_name))) == folded_name;
    };
    auto duplicate = findRecordInHeapPage<CubeMeasureRecord>(cube_measure_table_page_, duplicate_predicate, ctx);
    if (duplicate.status == Status::OK)
    {
        return Status::CONSTRAINT_VIOLATION;
    }
    if (duplicate.status != Status::NOT_FOUND)
    {
        return duplicate.status;
    }

    const uint64_t now = catalogNowTicks();
    CubeMeasureRecord rec{};
    rec.measure_id = info.measure_id;
    rec.cube_id = info.cube_id;
    std::strncpy(rec.measure_name,
                 UTF8Utils::truncateToBytes(info.measure_name, sizeof(rec.measure_name)).c_str(),
                 sizeof(rec.measure_name) - 1);
    rec.agg_function = static_cast<uint8_t>(info.agg_function);
    rec.null_handling = static_cast<uint8_t>(info.null_handling);
    rec.is_valid = info.is_valid ? 1 : 0;
    rec.source_expr_sblr_id = info.source_expr_sblr_id;
    rec.data_type_id = info.data_type_id;
    rec.created_time = (info.created_time == 0) ? now : info.created_time;
    rec.last_modified_time = (info.last_modified_time == 0) ? now : info.last_modified_time;

    auto existing_predicate = [&info](const CubeMeasureRecord& row) {
        return row.measure_id == info.measure_id && row.is_valid == 1;
    };
    auto existing = findRecordInHeapPage<CubeMeasureRecord>(cube_measure_table_page_, existing_predicate, ctx);
    if (existing.status == Status::OK)
    {
        rec.created_time = existing.record.created_time;
    }
    else if (existing.status != Status::NOT_FOUND)
    {
        return existing.status;
    }

    auto matcher = [&info](const CubeMeasureRecord& row) {
        return row.measure_id == info.measure_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(cube_measure_table_page_, matcher, rec, ctx);
}

auto CatalogManager::getCubeMeasureCatalogEntry(const ID& measure_id,
                                                CubeMeasureCatalogInfo& info_out,
                                                ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    auto predicate = [&measure_id](const CubeMeasureRecord& rec) {
        return rec.measure_id == measure_id && rec.is_valid == 1;
    };
    auto result = findRecordInHeapPage<CubeMeasureRecord>(cube_measure_table_page_, predicate, ctx);
    if (result.status != Status::OK)
    {
        return Status::NOT_FOUND;
    }
    const CubeAggFunction agg = static_cast<CubeAggFunction>(result.record.agg_function);
    const CubeNullHandling nh = static_cast<CubeNullHandling>(result.record.null_handling);
    if (!isValidCubeAggFunction(agg) || !isValidCubeNullHandling(nh))
    {
        return Status::PAGE_CORRUPT;
    }

    info_out = CubeMeasureCatalogInfo{};
    info_out.measure_id = result.record.measure_id;
    info_out.cube_id = result.record.cube_id;
    info_out.measure_name = fixedNameFromBuffer(result.record.measure_name, sizeof(result.record.measure_name));
    info_out.agg_function = agg;
    info_out.source_expr_sblr_id = result.record.source_expr_sblr_id;
    info_out.data_type_id = result.record.data_type_id;
    info_out.null_handling = nh;
    info_out.created_time = result.record.created_time;
    info_out.last_modified_time = result.record.last_modified_time;
    info_out.is_valid = result.record.is_valid == 1;
    return Status::OK;
}

auto CatalogManager::listCubeMeasureCatalogEntries(const ID& cube_id,
                                                   std::vector<CubeMeasureCatalogInfo>& rows_out,
                                                   ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    rows_out.clear();
    auto filter = [&cube_id](const CubeMeasureRecord& rec) {
        return rec.is_valid == 1 && (isZeroUuidLocal(cube_id) || rec.cube_id == cube_id);
    };
    auto converter = [](const CubeMeasureRecord& rec, CubeMeasureCatalogInfo& info) {
        info = CubeMeasureCatalogInfo{};
        info.measure_id = rec.measure_id;
        info.cube_id = rec.cube_id;
        info.measure_name = fixedNameFromBuffer(rec.measure_name, sizeof(rec.measure_name));
        info.agg_function = static_cast<CubeAggFunction>(rec.agg_function);
        info.source_expr_sblr_id = rec.source_expr_sblr_id;
        info.data_type_id = rec.data_type_id;
        info.null_handling = static_cast<CubeNullHandling>(rec.null_handling);
        info.created_time = rec.created_time;
        info.last_modified_time = rec.last_modified_time;
        info.is_valid = rec.is_valid == 1;
    };
    Status status = readRecordsToVector<CubeMeasureRecord, CubeMeasureCatalogInfo>(
        cube_measure_table_page_, rows_out, filter, converter, ctx);
    if (status != Status::OK)
    {
        return status;
    }
    for (const auto& row : rows_out)
    {
        if (!isValidCubeAggFunction(row.agg_function) || !isValidCubeNullHandling(row.null_handling))
        {
            return Status::PAGE_CORRUPT;
        }
    }
    return Status::OK;
}

