auto CatalogManager::upsertCubeRefreshPolicyCatalogEntry(const CubeRefreshPolicyCatalogInfo& info,
                                                         ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.policy_id) || isZeroUuidLocal(info.cube_id) ||
        !isValidCubeRefreshMode(info.refresh_mode))
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.has_interval_ms && info.interval_ms == 0)
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.has_watermark_column_id && isZeroUuidLocal(info.watermark_column_id))
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.has_max_staleness_ms && info.max_staleness_ms == 0)
    {
        return Status::INVALID_ARGUMENT;
    }

    auto cube_predicate = [&info](const CubeRecord& rec) {
        return rec.cube_id == info.cube_id && rec.is_valid == 1;
    };
    if (findRecordInHeapPage<CubeRecord>(cube_table_page_, cube_predicate, ctx).status != Status::OK)
    {
        return Status::NOT_FOUND;
    }
    if (info.has_watermark_column_id)
    {
        auto column_predicate = [&info](const ColumnRecord& rec) {
            return rec.column_id == info.watermark_column_id && rec.is_valid == 1;
        };
        if (findRecordInHeapPage<ColumnRecord>(columns_table_page_, column_predicate, ctx).status != Status::OK)
        {
            return Status::NOT_FOUND;
        }
    }

    auto duplicate_predicate = [&info](const CubeRefreshPolicyRecord& rec) {
        return rec.is_valid == 1 && rec.policy_id != info.policy_id && rec.cube_id == info.cube_id;
    };
    auto duplicate = findRecordInHeapPage<CubeRefreshPolicyRecord>(
        cube_refresh_policy_table_page_, duplicate_predicate, ctx);
    if (duplicate.status == Status::OK)
    {
        return Status::CONSTRAINT_VIOLATION;
    }
    if (duplicate.status != Status::NOT_FOUND)
    {
        return duplicate.status;
    }

    const uint64_t now = catalogNowTicks();
    CubeRefreshPolicyRecord rec{};
    rec.policy_id = info.policy_id;
    rec.cube_id = info.cube_id;
    rec.refresh_mode = static_cast<uint8_t>(info.refresh_mode);
    rec.has_interval_ms = info.has_interval_ms ? 1 : 0;
    rec.has_watermark_column_id = info.has_watermark_column_id ? 1 : 0;
    rec.has_max_staleness_ms = info.has_max_staleness_ms ? 1 : 0;
    rec.is_enabled = info.is_enabled ? 1 : 0;
    rec.is_valid = info.is_valid ? 1 : 0;
    rec.interval_ms = info.has_interval_ms ? info.interval_ms : 0;
    rec.watermark_column_id = info.has_watermark_column_id ? info.watermark_column_id : ID{};
    rec.max_staleness_ms = info.has_max_staleness_ms ? info.max_staleness_ms : 0;
    rec.created_time = (info.created_time == 0) ? now : info.created_time;
    rec.last_modified_time = (info.last_modified_time == 0) ? now : info.last_modified_time;

    auto existing_predicate = [&info](const CubeRefreshPolicyRecord& row) {
        return row.policy_id == info.policy_id && row.is_valid == 1;
    };
    auto existing = findRecordInHeapPage<CubeRefreshPolicyRecord>(
        cube_refresh_policy_table_page_, existing_predicate, ctx);
    if (existing.status == Status::OK)
    {
        rec.created_time = existing.record.created_time;
    }
    else if (existing.status != Status::NOT_FOUND)
    {
        return existing.status;
    }

    auto matcher = [&info](const CubeRefreshPolicyRecord& row) {
        return row.policy_id == info.policy_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(cube_refresh_policy_table_page_, matcher, rec, ctx);
}

