auto CatalogManager::upsertCubeJobCatalogEntry(const CubeJobCatalogInfo& info,
                                               ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.job_id) || isZeroUuidLocal(info.cube_id) || !isValidCubeJobType(info.job_type) ||
        !isValidCubeJobState(info.state))
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.has_started_time && info.started_time == 0)
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.has_completed_time && info.completed_time == 0)
    {
        return Status::INVALID_ARGUMENT;
    }
    if (isTerminalCubeJobState(info.state) && !info.has_completed_time)
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.has_started_time && info.has_completed_time && info.completed_time < info.started_time)
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.has_error_code && info.error_code.empty())
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.has_error_message && info.error_message.empty())
    {
        return Status::INVALID_ARGUMENT;
    }

    auto cube_predicate = [&info](const CubeRecord& rec) {
        return rec.cube_id == info.cube_id && rec.is_valid == 1;
    };
    if (findRecordInHeapPage<CubeRecord>(cube_table_page_, cube_predicate, ctx).status != Status::OK)
    {
        return Status::NOT_FOUND;
    }

    const uint64_t now = catalogNowTicks();
    CubeJobRecord rec{};
    rec.job_id = info.job_id;
    rec.cube_id = info.cube_id;
    rec.job_type = static_cast<uint8_t>(info.job_type);
    rec.state = static_cast<uint8_t>(info.state);
    rec.has_started_time = info.has_started_time ? 1 : 0;
    rec.has_completed_time = info.has_completed_time ? 1 : 0;
    rec.has_error_code = info.has_error_code ? 1 : 0;
    rec.has_error_message = info.has_error_message ? 1 : 0;
    rec.is_valid = info.is_valid ? 1 : 0;
    rec.created_time = (info.created_time == 0) ? now : info.created_time;
    rec.started_time = info.has_started_time ? info.started_time : 0;
    rec.completed_time = info.has_completed_time ? info.completed_time : 0;

    uint64_t xmin = 0;
    if (info.has_error_code)
    {
        Status status = storeStringInToast(info.error_code, xmin, rec.error_code_oid, ctx);
        if (status != Status::OK)
        {
            return status;
        }
    }
    if (info.has_error_message)
    {
        Status status = storeStringInToast(info.error_message, xmin, rec.error_message_oid, ctx);
        if (status != Status::OK)
        {
            return status;
        }
    }

    auto existing_predicate = [&info](const CubeJobRecord& row) {
        return row.job_id == info.job_id && row.is_valid == 1;
    };
    auto existing = findRecordInHeapPage<CubeJobRecord>(cube_job_table_page_, existing_predicate, ctx);
    if (existing.status == Status::OK)
    {
        rec.created_time = existing.record.created_time;
    }
    else if (existing.status != Status::NOT_FOUND)
    {
        return existing.status;
    }

    auto matcher = [&info](const CubeJobRecord& row) {
        return row.job_id == info.job_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(cube_job_table_page_, matcher, rec, ctx);
}

auto CatalogManager::getCubeJobCatalogEntry(const ID& job_id,
                                            CubeJobCatalogInfo& info_out,
                                            ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    auto predicate = [&job_id](const CubeJobRecord& rec) {
        return rec.job_id == job_id && rec.is_valid == 1;
    };
    auto result = findRecordInHeapPage<CubeJobRecord>(cube_job_table_page_, predicate, ctx);
    if (result.status != Status::OK)
    {
        return Status::NOT_FOUND;
    }
    const CubeJobType job_type = static_cast<CubeJobType>(result.record.job_type);
    const CubeJobState state = static_cast<CubeJobState>(result.record.state);
    if (!isValidCubeJobType(job_type) || !isValidCubeJobState(state) ||
        (isTerminalCubeJobState(state) && result.record.has_completed_time == 0) ||
        (result.record.has_started_time != 0 && result.record.started_time < result.record.created_time) ||
        (result.record.has_completed_time != 0 &&
         result.record.completed_time <
             ((result.record.has_started_time != 0) ? result.record.started_time : result.record.created_time)))
    {
        return Status::PAGE_CORRUPT;
    }

    info_out = CubeJobCatalogInfo{};
    info_out.job_id = result.record.job_id;
    info_out.cube_id = result.record.cube_id;
    info_out.job_type = job_type;
    info_out.state = state;
    info_out.created_time = result.record.created_time;
    info_out.has_started_time = result.record.has_started_time != 0;
    info_out.started_time = result.record.started_time;
    info_out.has_completed_time = result.record.has_completed_time != 0;
    info_out.completed_time = result.record.completed_time;
    info_out.has_error_code = result.record.has_error_code != 0;
    info_out.has_error_message = result.record.has_error_message != 0;
    info_out.is_valid = result.record.is_valid == 1;

    uint64_t xmin = 0;
    if (info_out.has_error_code)
    {
        Status status = loadStringFromToast(result.record.error_code_oid, xmin, info_out.error_code, ctx);
        if (status != Status::OK)
        {
            return status;
        }
    }
    if (info_out.has_error_message)
    {
        Status status = loadStringFromToast(result.record.error_message_oid, xmin, info_out.error_message, ctx);
        if (status != Status::OK)
        {
            return status;
        }
    }
    return Status::OK;
}

auto CatalogManager::listCubeJobCatalogEntries(const ID& cube_id,
                                               std::vector<CubeJobCatalogInfo>& rows_out,
                                               ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    rows_out.clear();
    auto filter = [&cube_id](const CubeJobRecord& rec) {
        return rec.is_valid == 1 && (isZeroUuidLocal(cube_id) || rec.cube_id == cube_id);
    };
    auto converter = [this, ctx](const CubeJobRecord& rec, CubeJobCatalogInfo& info) {
        info = CubeJobCatalogInfo{};
        info.job_id = rec.job_id;
        info.cube_id = rec.cube_id;
        info.job_type = static_cast<CubeJobType>(rec.job_type);
        info.state = static_cast<CubeJobState>(rec.state);
        info.created_time = rec.created_time;
        info.has_started_time = rec.has_started_time != 0;
        info.started_time = rec.started_time;
        info.has_completed_time = rec.has_completed_time != 0;
        info.completed_time = rec.completed_time;
        info.has_error_code = rec.has_error_code != 0;
        info.has_error_message = rec.has_error_message != 0;
        info.is_valid = rec.is_valid == 1;
        uint64_t xmin = 0;
        if (info.has_error_code)
        {
            std::string text;
            if (loadStringFromToast(rec.error_code_oid, xmin, text, ctx) == Status::OK)
            {
                info.error_code = std::move(text);
            }
        }
        if (info.has_error_message)
        {
            std::string text;
            if (loadStringFromToast(rec.error_message_oid, xmin, text, ctx) == Status::OK)
            {
                info.error_message = std::move(text);
            }
        }
    };
    Status status = readRecordsToVector<CubeJobRecord, CubeJobCatalogInfo>(
        cube_job_table_page_, rows_out, filter, converter, ctx);
    if (status != Status::OK)
    {
        return status;
    }
    for (const auto& row : rows_out)
    {
        if (!isValidCubeJobType(row.job_type) || !isValidCubeJobState(row.state) ||
            (isTerminalCubeJobState(row.state) && !row.has_completed_time) ||
            (row.has_started_time && row.started_time < row.created_time) ||
            (row.has_completed_time &&
             row.completed_time < (row.has_started_time ? row.started_time : row.created_time)))
        {
            return Status::PAGE_CORRUPT;
        }
    }
    return Status::OK;
}

