auto CatalogManager::upsertCubeStatsCatalogEntry(const CubeStatsCatalogInfo& info,
                                                 ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.cube_id) || info.cache_hit_rate < 0.0f || info.cache_hit_rate > 1.0f)
    {
        return Status::INVALID_ARGUMENT;
    }
    auto cube_predicate = [&info](const CubeRecord& rec) {
        return rec.cube_id == info.cube_id && rec.is_valid == 1;
    };
    if (findRecordInHeapPage<CubeRecord>(cube_table_page_, cube_predicate, ctx).status != Status::OK)
    {
        return Status::NOT_FOUND;
    }

    CubeStatsRecord rec{};
    rec.cube_id = info.cube_id;
    rec.row_count = info.row_count;
    rec.size_bytes = info.size_bytes;
    rec.last_refresh_time = info.last_refresh_time;
    rec.avg_query_latency_ms = info.avg_query_latency_ms;
    rec.cache_hit_rate = info.cache_hit_rate;
    rec.is_valid = info.is_valid ? 1 : 0;

    auto matcher = [&info](const CubeStatsRecord& row) {
        return row.cube_id == info.cube_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(cube_stats_table_page_, matcher, rec, ctx);
}

