auto CatalogManager::upsertTsDictionaryCatalogEntry(const TsDictionaryCatalogInfo& info,
                                                    ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.dictionary_id) || info.dictionary_name.empty() || isZeroUuidLocal(info.template_id))
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.has_init_options && info.init_options_json.empty())
    {
        return Status::INVALID_ARGUMENT;
    }

    Status status = UTF8Utils::validateStorageCapacity(
        info.dictionary_name, sizeof(TsDictionaryRecord{}.dictionary_name), sizeof(TsDictionaryRecord{}.dictionary_name), ctx);
    if (status != Status::OK)
    {
        return status;
    }

    auto template_predicate = [&info](const TsTemplateRecord& rec) {
        return rec.template_id == info.template_id && rec.is_valid == 1;
    };
    if (findRecordInHeapPage<TsTemplateRecord>(ts_template_table_page_, template_predicate, ctx).status != Status::OK)
    {
        return Status::NOT_FOUND;
    }

    const std::string folded_name = canonicalIdentifierForLookup(info.dictionary_name);
    auto duplicate_predicate = [&info, &folded_name](const TsDictionaryRecord& rec) {
        return rec.is_valid == 1 && rec.dictionary_id != info.dictionary_id &&
               canonicalIdentifierForLookup(fixedNameFromBuffer(rec.dictionary_name, sizeof(rec.dictionary_name))) ==
                   folded_name;
    };
    auto duplicate = findRecordInHeapPage<TsDictionaryRecord>(ts_dictionary_table_page_, duplicate_predicate, ctx);
    if (duplicate.status == Status::OK)
    {
        return Status::CONSTRAINT_VIOLATION;
    }
    if (duplicate.status != Status::NOT_FOUND)
    {
        return duplicate.status;
    }

    const uint64_t now = catalogNowTicks();
    TsDictionaryRecord rec{};
    rec.dictionary_id = info.dictionary_id;
    rec.template_id = info.template_id;
    rec.created_time = (info.created_time == 0) ? now : info.created_time;
    rec.last_modified_time = (info.last_modified_time == 0) ? now : info.last_modified_time;
    rec.is_valid = info.is_valid ? 1 : 0;
    std::strncpy(rec.dictionary_name,
                 UTF8Utils::truncateToBytes(info.dictionary_name, sizeof(rec.dictionary_name)).c_str(),
                 sizeof(rec.dictionary_name) - 1);

    if (info.has_init_options)
    {
        uint64_t xmin = 0;
        status = storeStringInToast(info.init_options_json, xmin, rec.init_options_oid, ctx);
        if (status != Status::OK)
        {
            return status;
        }
        rec.has_init_options_oid = 1;
    }

    auto existing_predicate = [&info](const TsDictionaryRecord& row) {
        return row.dictionary_id == info.dictionary_id && row.is_valid == 1;
    };
    auto existing = findRecordInHeapPage<TsDictionaryRecord>(ts_dictionary_table_page_, existing_predicate, ctx);
    if (existing.status == Status::OK)
    {
        rec.created_time = existing.record.created_time;
    }
    else if (existing.status != Status::NOT_FOUND)
    {
        return existing.status;
    }

    auto matcher = [&info](const TsDictionaryRecord& row) {
        return row.dictionary_id == info.dictionary_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(ts_dictionary_table_page_, matcher, rec, ctx);
}

auto CatalogManager::getTsDictionaryCatalogEntry(const ID& dictionary_id,
                                                 TsDictionaryCatalogInfo& info_out,
                                                 ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    auto predicate = [&dictionary_id](const TsDictionaryRecord& rec) {
        return rec.dictionary_id == dictionary_id && rec.is_valid == 1;
    };
    auto result = findRecordInHeapPage<TsDictionaryRecord>(ts_dictionary_table_page_, predicate, ctx);
    if (result.status != Status::OK)
    {
        return Status::NOT_FOUND;
    }

    info_out = TsDictionaryCatalogInfo{};
    info_out.dictionary_id = result.record.dictionary_id;
    info_out.dictionary_name = fixedNameFromBuffer(result.record.dictionary_name, sizeof(result.record.dictionary_name));
    info_out.template_id = result.record.template_id;
    info_out.has_init_options = result.record.has_init_options_oid != 0;
    info_out.init_options_uuid = result.record.init_options_oid;
    info_out.created_time = result.record.created_time;
    info_out.last_modified_time = result.record.last_modified_time;
    info_out.is_valid = result.record.is_valid == 1;
    if (info_out.has_init_options)
    {
        uint64_t xmin = 0;
        Status load_status = loadStringFromToast(result.record.init_options_oid, xmin, info_out.init_options_json, ctx);
        if (load_status != Status::OK)
        {
            return load_status;
        }
    }
    return Status::OK;
}

auto CatalogManager::listTsDictionaryCatalogEntries(const ID& template_id,
                                                    std::vector<TsDictionaryCatalogInfo>& rows_out,
                                                    ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    rows_out.clear();
    auto filter = [&template_id](const TsDictionaryRecord& rec) {
        return rec.is_valid == 1 && (isZeroUuidLocal(template_id) || rec.template_id == template_id);
    };
    auto converter = [](const TsDictionaryRecord& rec, TsDictionaryCatalogInfo& info) {
        info = TsDictionaryCatalogInfo{};
        info.dictionary_id = rec.dictionary_id;
        info.dictionary_name = fixedNameFromBuffer(rec.dictionary_name, sizeof(rec.dictionary_name));
        info.template_id = rec.template_id;
        info.has_init_options = rec.has_init_options_oid != 0;
        info.init_options_uuid = rec.init_options_oid;
        info.created_time = rec.created_time;
        info.last_modified_time = rec.last_modified_time;
        info.is_valid = rec.is_valid == 1;
    };
    Status status = readRecordsToVector<TsDictionaryRecord, TsDictionaryCatalogInfo>(
        ts_dictionary_table_page_, rows_out, filter, converter, ctx);
    if (status != Status::OK)
    {
        return status;
    }
    for (auto& row : rows_out)
    {
        if (row.has_init_options)
        {
            uint64_t xmin = 0;
            status = loadStringFromToast(row.init_options_uuid, xmin, row.init_options_json, ctx);
            if (status != Status::OK)
            {
                return status;
            }
        }
    }
    return Status::OK;
}

