auto CatalogManager::upsertTriggerMessageCatalogEntry(const TriggerMessageCatalogInfo& info,
                                                      ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.message_id) || isZeroUuidLocal(info.trigger_id) || info.message_text.empty())
    {
        return Status::INVALID_ARGUMENT;
    }

    auto trigger_predicate = [&info](const TriggerRecord& rec) {
        return rec.trigger_id == info.trigger_id && rec.is_valid == 1;
    };
    if (findRecordInHeapPage<TriggerRecord>(triggers_table_page_, trigger_predicate, ctx).status != Status::OK)
    {
        return Status::NOT_FOUND;
    }

    auto duplicate_predicate = [&info](const TriggerMessageRecord& rec) {
        return rec.is_valid == 1 && rec.message_id != info.message_id && rec.trigger_id == info.trigger_id &&
               rec.message_number == info.message_number;
    };
    auto duplicate = findRecordInHeapPage<TriggerMessageRecord>(
        trigger_message_table_page_, duplicate_predicate, ctx);
    if (duplicate.status == Status::OK)
    {
        return Status::CONSTRAINT_VIOLATION;
    }
    if (duplicate.status != Status::NOT_FOUND)
    {
        return duplicate.status;
    }

    TriggerMessageRecord rec{};
    rec.message_id = info.message_id;
    rec.trigger_id = info.trigger_id;
    rec.message_number = info.message_number;
    rec.is_valid = info.is_valid ? 1 : 0;
    const uint64_t now = catalogNowTicks();
    rec.created_time = (info.created_time == 0) ? now : info.created_time;
    rec.last_modified_time = (info.last_modified_time == 0) ? now : info.last_modified_time;

    uint64_t xmin = 0;
    const std::string sanitized_message_text = redactSensitiveDiagnosticText(info.message_text);
    Status status = storeStringInToast(sanitized_message_text, xmin, rec.message_text_oid, ctx);
    if (status != Status::OK)
    {
        return status;
    }

    auto existing_predicate = [&info](const TriggerMessageRecord& row) {
        return row.message_id == info.message_id && row.is_valid == 1;
    };
    auto existing = findRecordInHeapPage<TriggerMessageRecord>(
        trigger_message_table_page_, existing_predicate, ctx);
    if (existing.status == Status::OK)
    {
        rec.created_time = existing.record.created_time;
    }
    else if (existing.status != Status::NOT_FOUND)
    {
        return existing.status;
    }

    auto matcher = [&info](const TriggerMessageRecord& row) {
        return row.message_id == info.message_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(trigger_message_table_page_, matcher, rec, ctx);
}

