auto CatalogManager::upsertColumnDropHistoryCatalogEntry(const ColumnDropHistoryCatalogInfo& info,
                                                         ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.history_id) || isZeroUuidLocal(info.table_id) ||
        isZeroUuidLocal(info.column_type_id) || info.column_name.empty())
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.has_dropped_by && isZeroUuidLocal(info.dropped_by_id))
    {
        return Status::INVALID_ARGUMENT;
    }

    Status status = UTF8Utils::validateStorageCapacity(
        info.column_name,
        sizeof(ColumnDropHistoryRecord{}.column_name),
        sizeof(ColumnDropHistoryRecord{}.column_name),
        ctx);
    if (status != Status::OK)
    {
        return status;
    }

    auto table_predicate = [&info](const TableRecord& rec) {
        return rec.table_id == info.table_id && rec.is_valid == 1;
    };
    if (findRecordInHeapPage<TableRecord>(tables_table_page_, table_predicate, ctx).status != Status::OK)
    {
        return Status::NOT_FOUND;
    }

    auto type_predicate = [&info](const TypeRecord& rec) {
        return rec.type_id == info.column_type_id && rec.is_valid == 1;
    };
    if (findRecordInHeapPage<TypeRecord>(type_table_page_, type_predicate, ctx).status != Status::OK)
    {
        return Status::NOT_FOUND;
    }

    if (info.has_dropped_by)
    {
        auto user_predicate = [&info](const UserRecord& rec) {
            return rec.user_id == info.dropped_by_id && rec.is_valid == 1;
        };
        if (findRecordInHeapPage<UserRecord>(users_table_page_, user_predicate, ctx).status != Status::OK)
        {
            return Status::NOT_FOUND;
        }
    }

    const uint64_t dropped_time = (info.dropped_time == 0) ? catalogNowTicks() : info.dropped_time;
    const std::string folded_name = canonicalIdentifierForLookup(info.column_name);
    auto duplicate_predicate = [&info, &folded_name, dropped_time](const ColumnDropHistoryRecord& rec) {
        return rec.is_valid == 1 && rec.history_id != info.history_id && rec.table_id == info.table_id &&
               rec.dropped_time == dropped_time &&
               canonicalIdentifierForLookup(fixedNameFromBuffer(rec.column_name, sizeof(rec.column_name))) ==
                   folded_name;
    };
    auto duplicate = findRecordInHeapPage<ColumnDropHistoryRecord>(
        column_drop_history_table_page_, duplicate_predicate, ctx);
    if (duplicate.status == Status::OK)
    {
        return Status::CONSTRAINT_VIOLATION;
    }
    if (duplicate.status != Status::NOT_FOUND)
    {
        return duplicate.status;
    }

    ColumnDropHistoryRecord rec{};
    rec.history_id = info.history_id;
    rec.table_id = info.table_id;
    rec.column_type_id = info.column_type_id;
    rec.dropped_time = dropped_time;
    rec.has_dropped_by = info.has_dropped_by ? 1 : 0;
    rec.dropped_by_id = info.has_dropped_by ? info.dropped_by_id : ID{};
    rec.is_valid = info.is_valid ? 1 : 0;
    std::strncpy(rec.column_name,
                 UTF8Utils::truncateToBytes(info.column_name, sizeof(rec.column_name)).c_str(),
                 sizeof(rec.column_name) - 1);

    auto matcher = [&info](const ColumnDropHistoryRecord& row) {
        return row.history_id == info.history_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(column_drop_history_table_page_, matcher, rec, ctx);
}

