auto CatalogManager::upsertSblrModuleCatalogEntry(const SblrModuleCatalogInfo& info,
                                                  ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.module_id) || info.feature_key.empty() || info.result_shape_id.empty() ||
        info.payload_schema_id.empty() || isZeroUuidLocal(info.container_blob_id))
    {
        return Status::INVALID_ARGUMENT;
    }

    Status status = UTF8Utils::validateStorageCapacity(
        info.feature_key, sizeof(SblrModuleRecord{}.feature_key), sizeof(SblrModuleRecord{}.feature_key), ctx);
    if (status != Status::OK)
    {
        return status;
    }
    status = UTF8Utils::validateStorageCapacity(
        info.result_shape_id, sizeof(SblrModuleRecord{}.result_shape_id), sizeof(SblrModuleRecord{}.result_shape_id), ctx);
    if (status != Status::OK)
    {
        return status;
    }
    status = UTF8Utils::validateStorageCapacity(
        info.payload_schema_id,
        sizeof(SblrModuleRecord{}.payload_schema_id),
        sizeof(SblrModuleRecord{}.payload_schema_id),
        ctx);
    if (status != Status::OK)
    {
        return status;
    }

    auto duplicate_predicate = [&info](const SblrModuleRecord& rec) {
        return rec.is_valid == 1 && rec.module_id != info.module_id && rec.sblr_checksum == info.sblr_checksum &&
               rec.capability_profile_version == info.capability_profile_version;
    };
    auto duplicate = findRecordInHeapPage<SblrModuleRecord>(sblr_module_table_page_, duplicate_predicate, ctx);
    if (duplicate.status == Status::OK)
    {
        return Status::CONSTRAINT_VIOLATION;
    }
    if (duplicate.status != Status::NOT_FOUND)
    {
        return duplicate.status;
    }

    const uint64_t now = catalogNowTicks();
    SblrModuleRecord rec{};
    rec.module_id = info.module_id;
    rec.sblr_checksum = info.sblr_checksum;
    rec.container_blob_id = info.container_blob_id;
    rec.normalization_evidence_hash = info.normalization_evidence_hash;
    rec.statement_norm_count = info.statement_norm_count;
    rec.capability_profile_version = info.capability_profile_version;
    rec.created_txid = info.created_txid;
    rec.created_at = (info.created_at == 0) ? now : info.created_at;
    rec.is_valid = info.is_valid ? 1 : 0;
    std::strncpy(rec.feature_key,
                 UTF8Utils::truncateToBytes(info.feature_key, sizeof(rec.feature_key)).c_str(),
                 sizeof(rec.feature_key) - 1);
    std::strncpy(rec.result_shape_id,
                 UTF8Utils::truncateToBytes(info.result_shape_id, sizeof(rec.result_shape_id)).c_str(),
                 sizeof(rec.result_shape_id) - 1);
    std::strncpy(rec.payload_schema_id,
                 UTF8Utils::truncateToBytes(info.payload_schema_id, sizeof(rec.payload_schema_id)).c_str(),
                 sizeof(rec.payload_schema_id) - 1);

    auto existing_predicate = [&info](const SblrModuleRecord& row) {
        return row.module_id == info.module_id && row.is_valid == 1;
    };
    auto existing = findRecordInHeapPage<SblrModuleRecord>(sblr_module_table_page_, existing_predicate, ctx);
    if (existing.status == Status::OK)
    {
        rec.created_at = existing.record.created_at;
    }
    else if (existing.status != Status::NOT_FOUND)
    {
        return existing.status;
    }

    auto matcher = [&info](const SblrModuleRecord& row) {
        return row.module_id == info.module_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(sblr_module_table_page_, matcher, rec, ctx);
}

