auto CatalogManager::upsertSblrPlanCatalogEntry(const SblrPlanCatalogInfo& info,
                                                ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.plan_id) || isZeroUuidLocal(info.module_id) || isZeroUuidLocal(info.plan_blob_id))
    {
        return Status::INVALID_ARGUMENT;
    }

    auto module_predicate = [&info](const SblrModuleRecord& rec) {
        return rec.module_id == info.module_id && rec.is_valid == 1;
    };
    auto module_result = findRecordInHeapPage<SblrModuleRecord>(sblr_module_table_page_, module_predicate, ctx);
    if (module_result.status != Status::OK)
    {
        return Status::NOT_FOUND;
    }
    if (info.normalization_evidence_hash != module_result.record.normalization_evidence_hash)
    {
        return Status::CONSTRAINT_VIOLATION;
    }

    std::vector<SblrStatementNormRecord> norm_rows;
    auto norm_filter = [&info](const SblrStatementNormRecord& rec) {
        return rec.is_valid == 1 && rec.module_id == info.module_id;
    };
    auto norm_converter = [](const SblrStatementNormRecord& rec, SblrStatementNormRecord& out) {
        out = rec;
    };
    Status status = readRecordsToVector<SblrStatementNormRecord, SblrStatementNormRecord>(
        sblr_statement_norm_table_page_, norm_rows, norm_filter, norm_converter, ctx);
    if (status != Status::OK)
    {
        return status;
    }
    if (module_result.record.statement_norm_count != norm_rows.size())
    {
        return Status::CONSTRAINT_VIOLATION;
    }

    auto duplicate_predicate = [&info](const SblrPlanRecord& rec) {
        return rec.is_valid == 1 && rec.plan_id != info.plan_id && rec.module_id == info.module_id &&
               rec.catalog_epoch == info.catalog_epoch && rec.security_epoch == info.security_epoch &&
               rec.plan_checksum == info.plan_checksum;
    };
    auto duplicate = findRecordInHeapPage<SblrPlanRecord>(sblr_plan_table_page_, duplicate_predicate, ctx);
    if (duplicate.status == Status::OK)
    {
        return Status::CONSTRAINT_VIOLATION;
    }
    if (duplicate.status != Status::NOT_FOUND)
    {
        return duplicate.status;
    }

    const uint64_t now = catalogNowTicks();
    SblrPlanRecord rec{};
    rec.plan_id = info.plan_id;
    rec.module_id = info.module_id;
    rec.catalog_epoch = info.catalog_epoch;
    rec.security_epoch = info.security_epoch;
    rec.normalization_evidence_hash = info.normalization_evidence_hash;
    rec.plan_checksum = info.plan_checksum;
    rec.dependency_count = info.dependency_count;
    rec.plan_blob_id = info.plan_blob_id;
    rec.created_txid = info.created_txid;
    rec.created_at = (info.created_at == 0) ? now : info.created_at;
    rec.is_valid = info.is_valid ? 1 : 0;

    auto existing_predicate = [&info](const SblrPlanRecord& row) {
        return row.plan_id == info.plan_id && row.is_valid == 1;
    };
    auto existing = findRecordInHeapPage<SblrPlanRecord>(sblr_plan_table_page_, existing_predicate, ctx);
    if (existing.status == Status::OK)
    {
        rec.created_at = existing.record.created_at;
    }
    else if (existing.status != Status::NOT_FOUND)
    {
        return existing.status;
    }

    auto matcher = [&info](const SblrPlanRecord& row) {
        return row.plan_id == info.plan_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(sblr_plan_table_page_, matcher, rec, ctx);
}

