auto CatalogManager::deleteSblrArtifactCatalogEntry(const ID& artifact_id,
                                                    ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    auto predicate = [&artifact_id](const SblrArtifactRecord& rec) {
        return rec.artifact_id == artifact_id && rec.is_valid == 1;
    };
    auto result = findRecordInHeapPage<SblrArtifactRecord>(sblr_artifact_table_page_, predicate, ctx);
    if (result.status != Status::OK)
    {
        return Status::NOT_FOUND;
    }
    SblrArtifactRecord updated = result.record;
    updated.is_valid = 0;
    updated.artifact_state = static_cast<uint8_t>(SblrArtifactState::RETIRED);
    if (updated.has_retired_at == 0)
    {
        updated.has_retired_at = 1;
        updated.retired_at = catalogNowTicks();
    }
    return updateRecordInHeapPage(sblr_artifact_table_page_, result.slot_index, updated, ctx);
}

auto CatalogManager::upsertSblrArtifactStatsCatalogEntry(const SblrArtifactStatsCatalogInfo& info,
                                                         ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.artifact_id))
    {
        return Status::INVALID_ARGUMENT;
    }
    auto artifact_predicate = [&info](const SblrArtifactRecord& rec) {
        return rec.artifact_id == info.artifact_id && rec.is_valid == 1;
    };
    if (findRecordInHeapPage<SblrArtifactRecord>(sblr_artifact_table_page_, artifact_predicate, ctx).status !=
        Status::OK)
    {
        return Status::NOT_FOUND;
    }

    SblrArtifactStatsRecord rec{};
    rec.artifact_id = info.artifact_id;
    rec.execution_count = info.execution_count;
    rec.execution_cpu_us = info.execution_cpu_us;
    rec.last_used_at = info.last_used_at;
    rec.fallback_count = info.fallback_count;
    rec.load_failure_count = info.load_failure_count;
    rec.is_valid = info.is_valid ? 1 : 0;

    auto matcher = [&info](const SblrArtifactStatsRecord& row) {
        return row.artifact_id == info.artifact_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(sblr_artifact_stats_table_page_, matcher, rec, ctx);
}

