auto CatalogManager::upsertSblrCompilerTargetCatalogEntry(const SblrCompilerTargetCatalogInfo& info,
                                                          ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (info.target_name.empty() || info.abi_name.empty() || info.min_compiler_version.empty())
    {
        return Status::INVALID_ARGUMENT;
    }
    Status status = UTF8Utils::validateStorageCapacity(
        info.target_name, sizeof(SblrCompilerTargetRecord{}.target_name), sizeof(SblrCompilerTargetRecord{}.target_name), ctx);
    if (status != Status::OK)
    {
        return status;
    }
    status = UTF8Utils::validateStorageCapacity(
        info.abi_name, sizeof(SblrCompilerTargetRecord{}.abi_name), sizeof(SblrCompilerTargetRecord{}.abi_name), ctx);
    if (status != Status::OK)
    {
        return status;
    }
    status = UTF8Utils::validateStorageCapacity(
        info.min_compiler_version,
        sizeof(SblrCompilerTargetRecord{}.min_compiler_version),
        sizeof(SblrCompilerTargetRecord{}.min_compiler_version),
        ctx);
    if (status != Status::OK)
    {
        return status;
    }

    const std::string folded_target = canonicalIdentifierForLookup(info.target_name);
    const uint64_t now = catalogNowTicks();
    SblrCompilerTargetRecord rec{};
    rec.enabled = info.enabled ? 1 : 0;
    rec.policy_flags = info.policy_flags;
    rec.created_time = (info.created_time == 0) ? now : info.created_time;
    rec.last_modified_time = (info.last_modified_time == 0) ? now : info.last_modified_time;
    rec.is_valid = info.is_valid ? 1 : 0;
    std::strncpy(rec.target_name,
                 UTF8Utils::truncateToBytes(info.target_name, sizeof(rec.target_name)).c_str(),
                 sizeof(rec.target_name) - 1);
    std::strncpy(rec.abi_name,
                 UTF8Utils::truncateToBytes(info.abi_name, sizeof(rec.abi_name)).c_str(),
                 sizeof(rec.abi_name) - 1);
    std::strncpy(rec.min_compiler_version,
                 UTF8Utils::truncateToBytes(info.min_compiler_version, sizeof(rec.min_compiler_version)).c_str(),
                 sizeof(rec.min_compiler_version) - 1);

    auto existing_predicate = [&folded_target](const SblrCompilerTargetRecord& row) {
        return row.is_valid == 1 &&
               canonicalIdentifierForLookup(fixedNameFromBuffer(row.target_name, sizeof(row.target_name))) ==
                   folded_target;
    };
    auto existing =
        findRecordInHeapPage<SblrCompilerTargetRecord>(sblr_compiler_target_table_page_, existing_predicate, ctx);
    if (existing.status == Status::OK)
    {
        rec.created_time = existing.record.created_time;
    }
    else if (existing.status != Status::NOT_FOUND)
    {
        return existing.status;
    }

    auto matcher = [&folded_target](const SblrCompilerTargetRecord& row) {
        return row.is_valid == 1 &&
               canonicalIdentifierForLookup(fixedNameFromBuffer(row.target_name, sizeof(row.target_name))) ==
                   folded_target;
    };
    return updateRecordInHeapPage(sblr_compiler_target_table_page_, matcher, rec, ctx);
}

