auto CatalogManager::upsertSblrCompileQueueCatalogEntry(const SblrCompileQueueCatalogInfo& info,
                                                        ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.queue_id) || isZeroUuidLocal(info.module_id) || info.target_platform.empty())
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.has_last_error_code && info.last_error_code.empty())
    {
        return Status::INVALID_ARGUMENT;
    }
    if (static_cast<uint8_t>(info.queue_state) > static_cast<uint8_t>(SblrQueueState::COMPLETED))
    {
        return Status::INVALID_ARGUMENT;
    }

    Status status = UTF8Utils::validateStorageCapacity(
        info.target_platform,
        sizeof(SblrCompileQueueRecord{}.target_platform),
        sizeof(SblrCompileQueueRecord{}.target_platform),
        ctx);
    if (status != Status::OK)
    {
        return status;
    }
    if (info.has_last_error_code)
    {
        status = UTF8Utils::validateStorageCapacity(
            info.last_error_code,
            sizeof(SblrCompileQueueRecord{}.last_error_code),
            sizeof(SblrCompileQueueRecord{}.last_error_code),
            ctx);
        if (status != Status::OK)
        {
            return status;
        }
    }

    auto module_predicate = [&info](const SblrModuleRecord& rec) {
        return rec.module_id == info.module_id && rec.is_valid == 1;
    };
    if (findRecordInHeapPage<SblrModuleRecord>(sblr_module_table_page_, module_predicate, ctx).status != Status::OK)
    {
        return Status::NOT_FOUND;
    }

    const uint64_t now = catalogNowTicks();
    SblrCompileQueueRecord rec{};
    rec.queue_id = info.queue_id;
    rec.module_id = info.module_id;
    rec.queue_state = static_cast<uint8_t>(info.queue_state);
    rec.priority = info.priority;
    rec.has_last_error_code = info.has_last_error_code ? 1 : 0;
    rec.has_last_attempt_time = info.has_last_attempt_time ? 1 : 0;
    rec.is_valid = info.is_valid ? 1 : 0;
    rec.attempt_count = info.attempt_count;
    rec.created_time = (info.created_time == 0) ? now : info.created_time;
    rec.last_attempt_time = info.has_last_attempt_time ? info.last_attempt_time : 0;
    std::strncpy(rec.target_platform,
                 UTF8Utils::truncateToBytes(info.target_platform, sizeof(rec.target_platform)).c_str(),
                 sizeof(rec.target_platform) - 1);
    if (info.has_last_error_code)
    {
        std::strncpy(rec.last_error_code,
                     UTF8Utils::truncateToBytes(info.last_error_code, sizeof(rec.last_error_code)).c_str(),
                     sizeof(rec.last_error_code) - 1);
    }

    auto existing_predicate = [&info](const SblrCompileQueueRecord& row) {
        return row.queue_id == info.queue_id && row.is_valid == 1;
    };
    auto existing = findRecordInHeapPage<SblrCompileQueueRecord>(
        sblr_compile_queue_table_page_, existing_predicate, ctx);
    if (existing.status == Status::OK)
    {
        rec.created_time = existing.record.created_time;
    }
    else if (existing.status != Status::NOT_FOUND)
    {
        return existing.status;
    }

    auto matcher = [&info](const SblrCompileQueueRecord& row) {
        return row.queue_id == info.queue_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(sblr_compile_queue_table_page_, matcher, rec, ctx);
}

