auto CatalogManager::upsertEncryptionProfileCatalogEntry(const EncryptionProfileCatalogInfo& info,
                                                         ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.profile_id) || isZeroUuidLocal(info.kdf_params_id) ||
        info.profile_name.empty() || info.min_shards_required == 0)
    {
        return Status::INVALID_ARGUMENT;
    }
    if (!isValidEncryptionAlgorithm(info.cipher) ||
        !isValidKdfAlgorithm(info.kdf_algorithm) ||
        !isValidKeyRotationPolicy(info.key_rotation_policy))
    {
        return Status::INVALID_ARGUMENT;
    }
    ErrorContext local_ctx;
    Status status = UTF8Utils::validateStorageCapacity(
        info.profile_name, sizeof(EncryptionProfileRecord{}.profile_name),
        sizeof(EncryptionProfileRecord{}.profile_name), &local_ctx);
    if (status != Status::OK)
    {
        return status;
    }
    auto duplicate_predicate = [&info](const EncryptionProfileRecord& row) {
        return row.is_valid == 1 &&
               row.profile_id != info.profile_id &&
               fixedNameFromBuffer(row.profile_name, sizeof(row.profile_name)) == info.profile_name;
    };
    auto duplicate = findRecordInHeapPage<EncryptionProfileRecord>(
        encryption_profile_table_page_, duplicate_predicate, ctx);
    if (duplicate.status == Status::OK)
    {
        return Status::CONSTRAINT_VIOLATION;
    }
    if (duplicate.status != Status::NOT_FOUND)
    {
        return duplicate.status;
    }

    const uint64_t now = catalogNowTicks();
    EncryptionProfileRecord rec{};
    rec.profile_id = info.profile_id;
    rec.cipher = static_cast<uint8_t>(info.cipher);
    rec.kdf_algorithm = static_cast<uint8_t>(info.kdf_algorithm);
    rec.key_rotation_policy = static_cast<uint8_t>(info.key_rotation_policy);
    rec.is_active = info.is_active ? 1 : 0;
    rec.is_valid = info.is_valid ? 1 : 0;
    rec.kdf_params_id = info.kdf_params_id;
    rec.min_shards_required = info.min_shards_required;
    rec.unlock_timeout_ms = info.unlock_timeout_ms;
    rec.created_time = (info.created_time == 0) ? now : info.created_time;
    rec.last_modified_time = (info.last_modified_time == 0) ? now : info.last_modified_time;
    std::strncpy(rec.profile_name,
                 UTF8Utils::truncateToBytes(info.profile_name, sizeof(rec.profile_name)).c_str(),
                 sizeof(rec.profile_name) - 1);

    auto existing_predicate = [&info](const EncryptionProfileRecord& row) {
        return row.profile_id == info.profile_id && row.is_valid == 1;
    };
    auto existing = findRecordInHeapPage<EncryptionProfileRecord>(
        encryption_profile_table_page_, existing_predicate, ctx);
    if (existing.status == Status::OK)
    {
        rec.created_time = existing.record.created_time;
    }
    else if (existing.status != Status::NOT_FOUND)
    {
        return existing.status;
    }

    auto matcher = [&info](const EncryptionProfileRecord& row) {
        return row.profile_id == info.profile_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(encryption_profile_table_page_, matcher, rec, ctx);
}

