auto CatalogManager::upsertEncryptionKeyCatalogEntry(const EncryptionKeyCatalogInfo& info,
                                                     ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.key_id) ||
        isZeroUuidLocal(info.profile_id) ||
        isZeroUuidLocal(info.key_material_encrypted_id))
    {
        return Status::INVALID_ARGUMENT;
    }
    if (!isValidKeyMaterialKind(info.key_kind) || !isValidEncryptionKeyStatus(info.key_status))
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.key_status == EncryptionKeyStatus::ACTIVE && !info.has_activated_time)
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.key_status == EncryptionKeyStatus::RETIRED && !info.has_retired_time)
    {
        return Status::INVALID_ARGUMENT;
    }

    auto duplicate_predicate = [&info](const EncryptionKeyRecord& row) {
        return row.is_valid == 1 &&
               row.key_id != info.key_id &&
               row.profile_id == info.profile_id &&
               row.key_kind == static_cast<uint8_t>(info.key_kind) &&
               row.key_version == info.key_version;
    };
    auto duplicate = findRecordInHeapPage<EncryptionKeyRecord>(encryption_key_table_page_, duplicate_predicate, ctx);
    if (duplicate.status == Status::OK)
    {
        return Status::CONSTRAINT_VIOLATION;
    }
    if (duplicate.status != Status::NOT_FOUND)
    {
        return duplicate.status;
    }

    const uint64_t now = catalogNowTicks();
    EncryptionKeyRecord rec{};
    rec.key_id = info.key_id;
    rec.profile_id = info.profile_id;
    rec.key_kind = static_cast<uint8_t>(info.key_kind);
    rec.key_status = static_cast<uint8_t>(info.key_status);
    rec.has_activated_time = info.has_activated_time ? 1 : 0;
    rec.has_retired_time = info.has_retired_time ? 1 : 0;
    rec.is_valid = info.is_valid ? 1 : 0;
    rec.key_material_encrypted_id = info.key_material_encrypted_id;
    std::memcpy(rec.key_material_hash, info.key_material_hash.data(), 32);
    rec.key_version = info.key_version;
    rec.created_time = (info.created_time == 0) ? now : info.created_time;
    rec.activated_time = info.has_activated_time ? info.activated_time : 0;
    rec.retired_time = info.has_retired_time ? info.retired_time : 0;

    auto existing_predicate = [&info](const EncryptionKeyRecord& row) {
        return row.key_id == info.key_id && row.is_valid == 1;
    };
    auto existing = findRecordInHeapPage<EncryptionKeyRecord>(
        encryption_key_table_page_, existing_predicate, ctx);
    if (existing.status == Status::OK)
    {
        rec.created_time = existing.record.created_time;
    }
    else if (existing.status != Status::NOT_FOUND)
    {
        return existing.status;
    }

    auto matcher = [&info](const EncryptionKeyRecord& row) {
        return row.key_id == info.key_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(encryption_key_table_page_, matcher, rec, ctx);
}

auto CatalogManager::getEncryptionKeyCatalogEntry(const ID& key_id,
                                                  EncryptionKeyCatalogInfo& info_out,
                                                  ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    auto predicate = [&key_id](const EncryptionKeyRecord& rec) {
        return rec.key_id == key_id && rec.is_valid == 1;
    };
    auto result = findRecordInHeapPage<EncryptionKeyRecord>(encryption_key_table_page_, predicate, ctx);
    if (result.status != Status::OK)
    {
        return Status::NOT_FOUND;
    }
    if (!isValidKeyMaterialKind(static_cast<KeyMaterialKind>(result.record.key_kind)) ||
        !isValidEncryptionKeyStatus(static_cast<EncryptionKeyStatus>(result.record.key_status)))
    {
        return Status::PAGE_CORRUPT;
    }

    info_out = EncryptionKeyCatalogInfo{};
    info_out.key_id = result.record.key_id;
    info_out.profile_id = result.record.profile_id;
    info_out.key_kind = static_cast<KeyMaterialKind>(result.record.key_kind);
    info_out.key_status = static_cast<EncryptionKeyStatus>(result.record.key_status);
    info_out.key_material_encrypted_id = result.record.key_material_encrypted_id;
    std::copy(std::begin(result.record.key_material_hash), std::end(result.record.key_material_hash),
              info_out.key_material_hash.begin());
    info_out.key_version = result.record.key_version;
    info_out.created_time = result.record.created_time;
    info_out.has_activated_time = result.record.has_activated_time != 0;
    info_out.activated_time = result.record.activated_time;
    info_out.has_retired_time = result.record.has_retired_time != 0;
    info_out.retired_time = result.record.retired_time;
    info_out.is_valid = result.record.is_valid == 1;
    return Status::OK;
}

