{
    std::lock_guard<CatalogMutex> lock(mutex_);
    rows_out.clear();
    auto filter = [&profile_id](const EncryptionKeyRecord& rec) {
        if (rec.is_valid != 1)
        {
            return false;
        }
        return isZeroUuidLocal(profile_id) || rec.profile_id == profile_id;
    };
    auto converter = [](const EncryptionKeyRecord& rec, EncryptionKeyCatalogInfo& info) {
        info = EncryptionKeyCatalogInfo{};
        info.key_id = rec.key_id;
        info.profile_id = rec.profile_id;
        info.key_kind = static_cast<KeyMaterialKind>(rec.key_kind);
        info.key_status = static_cast<EncryptionKeyStatus>(rec.key_status);
        info.key_material_encrypted_id = rec.key_material_encrypted_id;
        std::copy(std::begin(rec.key_material_hash), std::end(rec.key_material_hash),
                  info.key_material_hash.begin());
        info.key_version = rec.key_version;
        info.created_time = rec.created_time;
        info.has_activated_time = rec.has_activated_time != 0;
        info.activated_time = rec.activated_time;
        info.has_retired_time = rec.has_retired_time != 0;
        info.retired_time = rec.retired_time;
        info.is_valid = rec.is_valid == 1;
    };
    return readRecordsToVector<EncryptionKeyRecord, EncryptionKeyCatalogInfo>(
        encryption_key_table_page_, rows_out, filter, converter, ctx);
}

auto CatalogManager::deleteEncryptionKeyCatalogEntry(const ID& key_id,
                                                     ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    auto predicate = [&key_id](const EncryptionKeyRecord& rec) {
        return rec.key_id == key_id && rec.is_valid == 1;
    };
    auto result = findRecordInHeapPage<EncryptionKeyRecord>(encryption_key_table_page_, predicate, ctx);
    if (result.status != Status::OK)
    {
        return Status::NOT_FOUND;
    }
    EncryptionKeyRecord updated = result.record;
    updated.is_valid = 0;
    return updateRecordInHeapPage(encryption_key_table_page_, result.slot_index, updated, ctx);
}

auto CatalogManager::upsertEncryptionKeyShardCatalogEntry(const EncryptionKeyShardCatalogInfo& info,
                                                          ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.shard_id) ||
        isZeroUuidLocal(info.key_id) ||
        isZeroUuidLocal(info.shard_material_encrypted_id))
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.shard_total == 0 || info.shard_index >= info.shard_total || info.holder_identity.empty())
    {
        return Status::INVALID_ARGUMENT;
    }
    ErrorContext local_ctx;
    Status status = UTF8Utils::validateStorageCapacity(
        info.holder_identity, sizeof(EncryptionKeyShardRecord{}.holder_identity),
        sizeof(EncryptionKeyShardRecord{}.holder_identity), &local_ctx);
    if (status != Status::OK)
    {
        return status;
    }

    auto duplicate_predicate = [&info](const EncryptionKeyShardRecord& row) {
        return row.is_valid == 1 &&
               row.shard_id != info.shard_id &&
               row.key_id == info.key_id &&
               row.shard_index == info.shard_index;
    };
    auto duplicate = findRecordInHeapPage<EncryptionKeyShardRecord>(
        encryption_key_shard_table_page_, duplicate_predicate, ctx);
    if (duplicate.status == Status::OK)
    {
        return Status::CONSTRAINT_VIOLATION;
    }
    if (duplicate.status != Status::NOT_FOUND)
    {
        return duplicate.status;
    }

    EncryptionKeyShardRecord rec{};
    rec.shard_id = info.shard_id;
    rec.key_id = info.key_id;
    rec.shard_index = info.shard_index;
    rec.shard_total = info.shard_total;
    rec.shard_material_encrypted_id = info.shard_material_encrypted_id;
    rec.has_last_collected_time = info.has_last_collected_time ? 1 : 0;
    rec.last_collected_time = info.has_last_collected_time ? info.last_collected_time : 0;
    rec.created_time = (info.created_time == 0) ? catalogNowTicks() : info.created_time;
    rec.is_valid = info.is_valid ? 1 : 0;
    std::strncpy(rec.holder_identity,
                 UTF8Utils::truncateToBytes(info.holder_identity, sizeof(rec.holder_identity)).c_str(),
                 sizeof(rec.holder_identity) - 1);

    auto existing_predicate = [&info](const EncryptionKeyShardRecord& row) {
        return row.shard_id == info.shard_id && row.is_valid == 1;
    };
    auto existing = findRecordInHeapPage<EncryptionKeyShardRecord>(
        encryption_key_shard_table_page_, existing_predicate, ctx);
    if (existing.status == Status::OK)
    {
        rec.created_time = existing.record.created_time;
    }
    else if (existing.status != Status::NOT_FOUND)
    {
        return existing.status;
    }

    auto matcher = [&info](const EncryptionKeyShardRecord& row) {
        return row.shard_id == info.shard_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(encryption_key_shard_table_page_, matcher, rec, ctx);
}

