        info.shard_total = rec.shard_total;
        info.shard_material_encrypted_id = rec.shard_material_encrypted_id;
        info.holder_identity = fixedNameFromBuffer(rec.holder_identity, sizeof(rec.holder_identity));
        info.created_time = rec.created_time;
        info.has_last_collected_time = rec.has_last_collected_time != 0;
        info.last_collected_time = rec.last_collected_time;
