auto CatalogManager::upsertEncryptionBootstrapInfoCatalogEntry(
    const EncryptionBootstrapInfoCatalogInfo& info,
    ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    if (isZeroUuidLocal(info.database_id) ||
        isZeroUuidLocal(info.profile_id) ||
        isZeroUuidLocal(info.active_key_id) ||
        info.min_shards_required == 0 ||
        info.unlock_policy.empty())
    {
        return Status::INVALID_ARGUMENT;
    }
    if (!isValidUnlockResult(info.last_unlock_result))
    {
        return Status::INVALID_ARGUMENT;
    }
    if (info.has_last_unlock_time && info.last_unlock_time == 0)
    {
        return Status::INVALID_ARGUMENT;
    }
    ErrorContext local_ctx;
    Status status = UTF8Utils::validateStorageCapacity(
        info.unlock_policy, sizeof(EncryptionBootstrapInfoRecord{}.unlock_policy),
        sizeof(EncryptionBootstrapInfoRecord{}.unlock_policy), &local_ctx);
    if (status != Status::OK)
    {
        return status;
    }

    EncryptionBootstrapInfoRecord rec{};
    rec.database_id = info.database_id;
    rec.profile_id = info.profile_id;
    rec.active_key_id = info.active_key_id;
    rec.min_shards_required = info.min_shards_required;
    rec.unlock_timeout_ms = info.unlock_timeout_ms;
    rec.has_last_unlock_time = info.has_last_unlock_time ? 1 : 0;
    rec.last_unlock_time = info.has_last_unlock_time ? info.last_unlock_time : 0;
    rec.last_unlock_result = static_cast<uint8_t>(info.last_unlock_result);
    rec.policy_version = info.policy_version;
    rec.is_valid = info.is_valid ? 1 : 0;
    std::strncpy(rec.unlock_policy,
                 UTF8Utils::truncateToBytes(info.unlock_policy, sizeof(rec.unlock_policy)).c_str(),
                 sizeof(rec.unlock_policy) - 1);

    auto matcher = [&info](const EncryptionBootstrapInfoRecord& row) {
        return row.database_id == info.database_id && row.is_valid == 1;
    };
    return updateRecordInHeapPage(encryption_bootstrap_info_table_page_, matcher, rec, ctx);
}

